window.HS_LOAD(3,{"intro":[[["حضورؐ اور آپؐ کے صحابہ کرامؓ کس طرح علم الٰہی حاصل کرنے کا شوق رکھتے تھے اور دوسروں کو اس کی ترغیب دیتے تھے اور علم الٰہی میں جو ایمان و عمل ہیں ان کو کس طرح خود سیکھتے اور دوسروں کو سکھاتے تھے اور سفر و حضر، خوش حالی اور بد حالی، ہر حال میں کس طرح علم الٰہی کے سیکھنے سکھانے میں لگتے تھے اور کس طرح مدینہ منورہ علی صاحبہا الف الف صلوٰۃ و تحیۃ میں آنے والے مہمانوں کو سکھانے کا اہتمام کرتے تھے اور کس طرح علم، جہاد اور کمائی ان تینوں کاموں کو جمع کرتے تھے اور مختلف شہروں میں علم پھیلانے کے لیے آدمیوں کو بھیجا کرتے تھے اور کس طرح اپنے اندر ان صفات کے پیدا کرنے کا اہتمام کرتے تھے جن کی وجہ سے علم ",""],["ٱللَّٰه","a"],[" کے ہاں قبول ہوتا ہے۔",""]]],"topics":{"46":{"lead":[],"stories":[{"b":[["n",[["حضرت صفوان بن عسال مرادیؓ","b"],[" فرماتے ہیں میں حضورؐ کی خدمت میں حاضر ہوا۔ حضورؐ اس وقت اپنی دھاری دار سرخ چادر پر تکیہ لگا کر بیٹھے ہوئے تھے۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں علم حاصل کرنے آیا ہوں۔ حضورؐ نے فرمایا خوش آمدید ہو طالب علم کو۔ طالب علم کو فرشتے اپنے پروں سے گھیر لیتے ہیں اور پھر ایک دوسرے پر سوار ہوتے رہتے ہیں یہاں تک کہ وہ آسمان دنیا تک پہنچ جاتے ہیں اور وہ اس علم سے محبت کی وجہ سے ایسا کرتے ہیں جسے یہ طالب علم حاصل کر رہا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, Tabraani, Ibn Hibbaan and Haakim, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.59)."]]},{"b":[["n",[["حضرت قبیصہ بن مخارقؓ","b"],[" فرماتے ہیں میں حضورؐ کی خدمت میں حاضر ہوا۔ حضورؐ نے پوچھا کیوں آئے ہو؟ میں نے عرض کیا میری عمر زیادہ ہو گئی ہے، میری ہڈیاں کمزور ہو گئی ہیں یعنی میں بوڑھا ہو گیا ہوں۔ میں آپؐ کی خدمت میں اس لیے حاضر ہوا ہوں تا کہ آپؐ مجھے وہ چیز سکھائیں جس سے ",""],["ٱللَّٰه","a"],[" تعالیٰ مجھے نفع دے۔ حضورؐ نے فرمایا تم جس پتھر، درخت اور ڈھیلے کے پاس سے گزرے ہو اس نے تمہارے لیے دعائے مغفرت کی ہے۔ اے قبیصہ! صبح کی نماز کے بعد تین دفعہ سُبْحَانَ ٱللَّهِ ٱلْعَظِيمِ وَبِحَمْدِهِ کہو، اس سے تم اندھے پن، کوڑھی پن اور فالج سے محفوظ رہو گے۔ اے قبیصہ! یہ دعا بھی پڑھا کرو:",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَسْأَلُكَ مِمَّا عِنْدَكَ، وَأَفِضْ عَلَيَّ مِنْ فَضْلِكَ، وَٱنْشُرْ عَلَيَّ مِنْ رَحْمَتِكَ، وَأَنْزِلْ عَلَيَّ مِنْ بَرَكَتِكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں ان نعمتوں میں سے مانگتا ہوں جو تیرے پاس ہیں اور اپنے فضل کی مجھ پر بارش کر اور اپنی رحمت مجھ پر پھیلا دے اور اپنی برکت مجھ پر نازل کر دے۔\"",""],[" (2)","s"]]]],"f":[["(2)","Ahmad, as quoted in Jam'ul Fawaa'id (Vol.1 Pg.21). Mundhiri and Haythami have commented on the chain of narrators."]]},{"b":[["n",[["حضرت سخبرہؓ","b"],[" فرماتے ہیں حضورؐ ایک مرتبہ بیان فرما رہے تھے، آپؐ کے پاس سے دو آدمی گزرے۔ حضورؐ نے ان سے فرمایا تم دونوں بیٹھ جاؤ، تم خیر پر ہو۔ جب حضورؐ کھڑے ہوئے اور صحابہؓ سب حضورؐ کے پاس سے ادھر ادھر چلے گئے تو ان دونوں نے کھڑے ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ نے ہم سے فرمایا تھا تم دونوں بیٹھ جاؤ، تم خیر پر ہو، یہ صرف ہم دونوں کے لیے ہے یا تمام لوگوں کے لیے ہے؟ حضورؐ نے فرمایا جو بندہ بھی علم حاصل کرتا ہے تو یہ علم کا حاصل کرنا اس کے پچھلے تمام گناہوں کا کفارہ بن جاتا ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Tirmidhi and Tabraani, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.60)."]]},{"b":[["n",[["حضرت ابوامامہ باہلیؓ","b"],[" فرماتے ہیں حضورؐ کے سامنے دو آدمیوں کا تذکرہ ہوا جن میں سے ایک عابد تھا اور دوسرا عالم۔ حضورؐ نے فرمایا عالم کو عابد پر ایسی فضیلت حاصل ہے جیسی مجھے تمہارے ادنیٰ آدمی پر۔ پھر حضورؐ نے فرمایا جو آدمی لوگوں کو خیر سکھاتا ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس پر رحمت بھیجتے ہیں اور ",""],["ٱللَّٰه","a"],[" کے فرشتے اور تمام آسمانوں والے یہاں تک کہ چیونٹیاں اپنے بلوں میں اور مچھلیاں اس کے لیے دعائے رحمت کرتی ہیں۔ دوسری روایت میں دو آدمیوں کا ذکر نہیں ہے، البتہ یہ ہے کہ حضورؐ نے فرمایا عالم کو عابد پر ایسی فضیلت حاصل ہے جیسی مجھے ادنیٰ آدمی پر۔ پھر حضورؐ نے یہ آیت پڑھی:",""],[" (4)","s"]]],["q",[["إِنَّمَا يَخْشَى ٱللَّهَ مِنْ عِبَادِهِ ٱلْعُلَمَٰٓؤُا۟  (سورۃ فاطر: ۲۸)","a"]]],["p",[["ترجمہ: \"خدا سے اس کے وہی بندے ڈرتے ہیں جو (اس کی عظمت کا) علم رکھتے ہیں۔\" اور آگے پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (5)","s"]]]],"f":[["(4)","Tirmidhi."],["(5)","Daarmi."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں حضورؐ سے ان دو آدمیوں کے بارے میں پوچھا گیا جو بنی اسرائیل میں سے تھے، ان میں سے ایک عالم تھا اور فرض نماز پڑھ کر بیٹھ جاتا اور لوگوں کو خیر کی باتیں سکھاتا رہتا اور دوسرا دن بھر روزہ رکھتا اور رات بھر عبادت کرتا۔ ان دونوں میں سے کون افضل ہے؟ حضورؐ نے فرمایا یہ عالم جو فرض نماز پڑھ کر بیٹھ جاتا اور لوگوں کو خیر کی باتیں سکھاتا رہتا تھا، اسے اس عابد پر جو دن بھر روزہ رکھتا تھا اور رات بھر عبادت کرتا تھا ایسی فضیلت حاصل ہے جیسی مجھے تمہارے ادنیٰ آدمی پر۔",""],[" (6)","s"]]]],"f":[["(6)","Daarmi, as quoted in Mishkaatul Masaabeeh (Pg.26,28)."]]},{"b":[["n",[["حضرت عقبہ بن عامرؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ باہر تشریف لائے۔ ہم لوگ صفہ میں بیٹھے ہوئے تھے۔ آپؐ نے فرمایا تم میں سے کون شخص اس کو پسند کرتا ہے کہ علی الصبح بازار بطحان یا عقیق میں جائے اور وہاں سے دو عمدہ اونٹنیاں کسی قسم کے گناہ اور قطع رحمی کے بغیر پکڑ لائے؟ ہم نے عرض کیا ہم سب اسے پسند کرتے ہیں۔ حضورؐ نے فرمایا کہ مسجد میں جا کر دو آیتوں کا پڑھنا یا پڑھا دینا دو اونٹنیوں سے اور تین آیات کا تین اونٹنیوں سے اسی طرح چار کا چار سے افضل ہے اور ان کے برابر اونٹوں سے افضل ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Muslim, as quoted in Mishkaatul Masaabeeh (Pg.175). Abu Nu'aym has reported a similar narration in his Hilya (Vol.1 Pg.341)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں حضورؐ کے زمانے میں دو بھائی تھے۔ ان میں سے ایک کمائی کرتا تھا اور دوسرا ہر وقت حضورؐ کے ساتھ رہتا تھا اور حضورؐ سے سیکھتا تھا۔ کمانے والے بھائی نے حضورؐ سے اپنے بھائی کی (نہ کمانے کی) شکایت کی۔ حضورؐ نے فرمایا شاید تمہیں اس (نہ کمانے والے) بھائی کی برکت سے روزی ملتی ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Tirmidhi, as quoted in Jam'ul Fawaa'id (Vol.1 Pg.20)."]]}]},"47":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوالطفیلؒ","b"],[" کہتے ہیں حضرت علیؓ فرمایا کرتے تھے انبیاء علیہم الصلوٰۃ والسلام کے سب سے زیادہ قریب وہ شخص ہے جو ان کے لائے ہوئے دین کو سب سے زیادہ جاننے والا ہو۔ پھر یہ آیت پڑھا کرتے تھے:",""]]],["q",[["إِنَّ أَوْلَى ٱلنَّاسِ بِإِبْرَٰهِيمَ لَلَّذِينَ ٱتَّبَعُوهُ وَهَٰذَا ٱلنَّبِىُّ  (سورۃ آل عمران: ۶۸)","a"]]],["p",[["ترجمہ: \"بلاشبہ سب آدمیوں میں زیادہ خصوصیت رکھنے والے (حضرت) ابراہیم کے ساتھ البتہ وہ لوگ تھے جنہوں نے ان کا اتباع کیا تھا اور یہ نبی (",""],["ﷺ","a"],[") ہیں\" یعنی حضرت محمدؐ اور ان کا اتباع کرنے والے صحابہؓ۔ اس لیے تم اس کو تبدیل نہ کرو، لہٰذا محمدؐ کا دوست وہ ہے جو ",""],["ٱللَّٰه","a"],[" کی اطاعت کرے اور محمدؐ کا دشمن وہ ہے جو ",""],["ٱللَّٰه","a"],[" کی نافرمانی کرے اگرچہ وہ حضورؐ کا قریبی رشتہ دار ہی کیوں نہ ہو۔",""],[" (1)","s"]]]],"f":[["(1)","Lalkala'ee, as quoted in Kanzul Ummaal (Vol.1 Pg.96)."]]},{"b":[["n",[["حضرت کمیل بن زیادؒ","b"],[" کہتے ہیں حضرت علیؓ میرا ہاتھ پکڑ کر مجھے صحرا کی طرف لے چلے۔ جب ہم صحرا میں پہنچ گئے تو حضرت علیؓ بیٹھ گئے اور ایک لمبا سانس لے کر فرمایا اے کمیل بن زیاد! دل برتن ہیں، ان میں سے بہترین برتن وہ ہے جو (اپنے اندر کی چیز کو) زیادہ محفوظ رکھنے والا ہو۔ میں تمہیں جو بات کہہ رہا ہوں وہ یاد رکھنا۔ انسان تین قسم کے ہیں: ایک عالم ربانی، دوسرے وہ علم حاصل کرنے والا جو نجات کے راستے پر چل رہا ہے، تیسرے وہ کمینے اور رذیل لوگ جو ہر شور مچانے والے کے پیچھے چل پڑتے ہیں اور جدھر کی ہوا چلے ادھر کو ہی رخ کر لیتے ہیں، نہ تو علم کے نور سے کچھ روشنی حاصل کی اور نہ کسی مضبوط مددگار کی پناہ حاصل کی۔ علم مال سے بہتر ہے۔ علم تمہاری حفاظت کرتا ہے اور مال کی حفاظت تمہیں کرنی پڑتی ہے۔ علم عمل کرنے سے بڑھتا ہے اور مال خرچ کرنے سے گھٹتا ہے۔ عالم کی محبت دین ہے جس کا ",""],["ٱللَّٰه","a"],[" کے ہاں اس سے بدلہ ملے گا۔ علم کی وجہ سے عالم کی زندگی میں اس کی بات مانی جاتی ہے اور اس کے مرنے کے بعد اس کا اچھائی سے تذکرہ کیا جاتا ہے۔ جب مال چلا جاتا ہے تو مال کی کارگیری اور مال کی بنیاد پر چلنے والے کام بھی ختم ہو جاتے ہیں۔ مال کے خزانے جمع کرنے والے زندہ بھی ہوں تو بھی وہ (روح اور دل کے اعتبار سے) مردہ شمار ہوتے ہیں اور علماء (مرنے کے بعد بھی) جب تک زمانہ رہے گا باقی رہیں گے۔ (ان کا ذکر خیر ہوتا رہے گا) ان کے جسم دنیا سے چلے جائیں گے لیکن ان کی عظمت کے نقوش دلوں میں باقی رہیں گے۔ اور یہ بات غور سے سنو! اور سینے کی طرف اشارہ کر کے حضرت علیؓ نے فرمایا اس جگہ ایک زبردست علم ہے، کاش! اس علم کو اٹھانے والے مجھے مل جاتے۔ اب یا تو ایسے لوگ ملتے ہیں جن کی سمجھ تو تیز ہے لیکن (تقویٰ اور طہارت کے نہ ہونے کی وجہ سے) ان پر اطمینان نہیں۔ یہ دین کے اسباب کو دنیا کے لیے استعمال کرتے ہیں اور قرآن میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جو دلائل بیان کیے ہیں ان سے قرآن کے خلاف ہی ثابت کرتے ہیں (کیونکہ علم کا نور انہیں حاصل نہیں ہے) اور ",""],["ٱللَّٰه","a"],[" کی نعمتوں کو اس کے بندوں کے خلاف استعمال کرتے ہیں۔ یا پھر ایسے لوگ ملتے ہیں جو اہل حق کے فرمانبردار تو ہیں لیکن انہیں دین کے زندہ کرنے کی کوئی سمجھ نہیں ہے اور معمولی سا شبہ پیش آتے ہی ان کے دل میں شک پیدا ہو جاتا ہے۔ نہ اس طرف طبیعت جمتی ہے اور نہ اس طرف۔ یا پھر ایسے لوگ ملتے ہیں جو لذتوں میں پڑے ہوئے ہیں اور آسانی سے خواہشات کی بات مان لیتے ہیں یا پھر ایسے لوگ ملتے ہیں جو مال جمع کرنے اور ذخیرہ کرنے کا ہی جذبہ رکھتے ہیں اور یہ آخری دو قسم کے انسان دین کے داعی بھی نہیں ہیں (پہلے دو دین کے داعی تو تھے لیکن ان میں اور خرابیاں تھیں) اور چرنے والے جانور ان دونوں کے زیادہ مشابہ ہیں۔ اور علم والوں کے مرنے سے علم بھی ختم ہو جائے گا لیکن یہ بات بھی ہے کہ زمین کبھی بھی ",""],["ٱللَّٰه","a"],[" کے ایسے بندوں سے خالی نہیں ہوتی جو اس لیے دلائل لے کر کھڑے ہوتے ہیں تا کہ ",""],["ٱللَّٰه","a"],[" کے دلائل اور واضح احکام بیکار اور معطل نہ قرار دیے جائیں۔ ان بندوں کی تعداد چاہے بہت کم ہو لیکن ",""],["ٱللَّٰه","a"],[" کے ہاں ان کا درجہ سب سے بڑا ہے۔ اور ",""],["ٱللَّٰه","a"],[" کی حجتوں یعنی قرآنی آیات پر جو غلط اعتراضات کیے جاتے ہیں ان کو ",""],["ٱللَّٰه","a"],[" تعالیٰ ان بندوں کے ذریعے دور فرماتے ہیں یہاں تک کہ وہ ان حجتوں کو اپنے جیسے بندوں تک پہنچا کر ان کے دلوں میں اتار دیتے ہیں اور کمال علم کی وجہ سے ہر امر کی حقیقت ان پر واضح ہو جاتی ہے اور جس امر کی حقیقت عیش و عشرت والوں کو دشوار نظر آتی ہے، وہ ان کے لیے بہت آسان ہوتی ہے۔ اور جن کاموں سے جاہل لوگ گھبراتے ہیں اور وحشت محسوس کرتے ہیں ان میں ان کا دل لگتا ہے۔ یہ لوگ اپنے بدن سے تو دنیا میں رہتے ہیں لیکن ان کی روحوں کا تعلق منظر اعلیٰ یعنی آخرت سے ہوتا ہے۔ یہی لوگ ",""],["ٱللَّٰه","a"],[" کی زمین پر اس کے خلیفہ ہیں اور اس کے دین کے داعی ہیں۔ ہائے ہائے! مجھے ان لوگوں کو دیکھنے کا کتنا شوق ہے۔ میں اپنے لیے اور تمہارے لیے ",""],["ٱللَّٰه","a"],[" سے استغفار کرتا ہوں۔ اب اگر تم چاہو تو جا سکتے ہو۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilya (Vol.1 Pg.79)."]]},{"b":[["n",[["حضرت معاذ بن جبلؓ","b"],[" فرماتے ہیں علم سیکھو کیونکہ ",""],["ٱللَّٰه","a"],[" کے لیے علم سیکھنا ",""],["ٱللَّٰه","a"],[" سے ڈرنا ہے۔ علم کو تلاش کرنا عبادت ہے اور اس کا آپس میں مذاکرہ کرنا تسبیح (کا ثواب دلاتا) ہے اور (سمجھنے کے لیے) اس میں بحث کرنا جہاد ہے اور نہ جاننے والے کو سکھانا صدقہ ہے اور جو لوگ علم کے اہل ہیں ان پر علم خرچ کرنا ",""],["ٱللَّٰه","a"],[" کے تقرب کا ذریعہ ہے کیونکہ علم کے ذریعہ سے حلال و حرام معلوم ہوتا ہے اور علم جنت والوں کے لیے (جنت کے راستے کا) مینار ہے اور وحشت میں انس کا ذریعہ ہے، مسافری میں ساتھی، تنہائی میں بات کرنے والا، نفع و خوشی کے نقصان اور غم کے کاموں کو بتانے والا، دشمنوں کے خلاف ہتھیار اور دوستوں کے نزدیک انسان کی زینت کا ذریعہ ہے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے ذریعے کچھ لوگوں کو بلند مرتبہ کرتے ہیں اور ان کو خیر کے کاموں میں پیشوا اور امام بناتے ہیں۔ ان کے طریقوں کو لوگ اختیار کرتے ہیں اور ان کے کاموں میں ان کی اتباع کرتے ہیں اور ان کی رائے اور فیصلہ پر سب مطمئن ہو جاتے ہیں۔ فرشتے ان کی دوستی اور ان کے ساتھ رہنے کا شوق رکھتے ہیں اور اپنے پروں کو ان پر ملتے ہیں اور ہر طرح کی مخلوق ان کے لیے دعائے مغفرت کرتی ہے یہاں تک کہ سمندر کی مچھلیاں اور دوسرے جانور اور خشکی کے درندے اور جانور بھی ان کے لیے دعائے مغفرت کرتے ہیں کیونکہ علم دلوں کو جہالت سے نکال کر زندگی بخشتا ہے اور اندھیرے میں انسان کو بصیرت عطا کرتا ہے۔ انسان علم کے ذریعہ سے بہترین لوگوں کے مرتبے کو اور دنیا و آخرت کے بلند درجوں کو پا لیتا ہے۔ اس میں غور و فکر کرنے سے روزہ رکھنے کا اور اسے پڑھنے پڑھانے سے راتوں کو عبادت کرنے کا ثواب ملتا ہے۔ علم کی وجہ سے انسان صلہ رحمی کرتا ہے اور حلال اور حرام کا فرق جانتا ہے۔ علم عمل کا امام ہے، عمل اس کے تابع ہے۔ خوش قسمت لوگوں کے دلوں میں علم کا الہام ہوتا ہے اور بدقسمت لوگ علم سے محروم رہتے ہیں۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilya (Vol.1 Pg.239). Ibn Abdul Birr has reported a similar narration in his Jaami Bayaanil Ilm (Vol.1 Pg.55)."]]},{"b":[["n",[["حضرت ہارون بن رئابؒ","b"],[" کہتے ہیں کہ حضرت ابن مسعودؓ فرمایا کرتے تھے تم صبح اس حال میں کرو کہ یا تو (سکھانے والے) عالم ہو یا سیکھنے والے ہو، اس کے علاوہ کچھ اور نہ ہو کیونکہ اس کے علاوہ تو آدمی جاہل ہوتا ہے اور جو آدمی علم حاصل کرنے کی حالت میں صبح کرتا ہے اس کے اس عمل کو پسندیدہ سمجھنے کی وجہ سے فرشتے اس کے لیے اپنے پر کھول دیتے ہیں۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.1 Pg.29)."]]},{"b":[["n",[["حضرت زیدؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا تم اس حال میں صبح کرو کہ یا تو تم (سکھانے والے) عالم ہو یا سیکھنے والے ہو اور ایسے آدمی نہ بنو جس کی اپنی کوئی رائے نہ ہو اور وہ ہر ایک کے پیچھے چل پڑے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abdul Birr has also reported the narration in his Jaami Bayaanil Ilm (Vol.1 Pg.29)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں اے لوگو! علم اٹھنے سے پہلے علم حاصل کرو اور اس کے اٹھنے کی صورت یہ ہوگی کہ علم والے دنیا سے چلے جائیں گے اور تم لوگ علم حاصل کرو کیونکہ تمہیں معلوم نہیں ہے کہ تمہیں اپنے علم کی کب ضرورت پڑ جائے اور علم حاصل کرنے میں مبالغہ اور غلو سے بچو اور پرانا طرز اختیار کرو (جو صحابہ کرامؓ کا تھا) کیونکہ عنقریب ایسے لوگ آئیں گے جو ",""],["ٱللَّٰه","a"],[" کی کتاب کو تو پڑھیں گے لیکن اسے اپنی پشت کے پیچھے پھینک دیں گے (اس پر عمل نہیں کریں گے)۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani. Haythami (Vol.1 Pg.126) has commented on the chain of narrators. Abdur Razzaaq has reported part of the narration, as quoted in the Jaami of Ibn Abdul Birr (Vol.1 Pg.78)."]]},{"b":[["n",[["حضرت ابوالاحوصؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا آدمی عالم بن کر پیدا نہیں ہوتا بلکہ علم تو سیکھنے سے آتا ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Abdul Birr has also reported the narration in his Jaami Bayaanil Ilm (Vol.1 Pg.100)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں تم عالم بنو یا علم سیکھنے والے بنو۔ ان دو کے علاوہ کچھ اور نہ بنو۔ اگر ایسا نہیں کر سکتے تو علماء سے محبت کرو، ان سے بغض نہ رکھو۔",""],[" (8)","s"]]]],"f":[["(8)","Tabraani. Haythami (Vol.1 Pg.122) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ نے فرمایا تو (سکھانے والے) عالم بنو یا طالب علم بنو یا علماء سے محبت کرنے والے اور ان کا اتباع کرنے والے بنو، (ان چار کے علاوہ) پانچویں قسم کے مت بنو ورنہ ہلاک ہو جاؤ گے۔ راوی حضرت حمیدؒ کہتے ہیں میں نے حضرت حسنؒ سے پوچھا پانچویں قسم سے کون مراد ہے؟ انہوں نے کہا اپنی طرف سے دین میں نئی باتیں ایجاد کرنے والا۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.1 Pg.28)."]]},{"b":[["n",[["حضرت ضحاکؒ","b"],[" کہتے ہیں کہ حضرت ابوالدرداءؓ نے فرمایا اے دمشق والو! تم لوگ میرے دینی بھائی ہو اور علاقے کے پڑوسی ہو اور دشمنوں کے خلاف میرے مددگار ہو لیکن تم مجھ سے دوستی کیوں نہیں رکھتے؟ حالانکہ میرا خرچہ بھی تمہارے ذمہ نہیں ہے، دوسروں پر ہے۔ میں دیکھ رہا ہوں کہ تمہارے علماء جا رہے ہیں اور تمہارے جاہل لوگ ان سے علم نہیں سیکھ رہے ہیں اور میں دیکھ رہا ہوں کہ ",""],["ٱللَّٰه","a"],[" نے جس روزی کی ذمہ داری لے رکھی ہے تم اس کے پیچھے پڑے ہوئے ہو اور ",""],["ٱللَّٰه","a"],[" نے تمہیں جن کاموں کا حکم دیا ہے انہیں چھوڑ رکھا ہے۔ غور سے سنو! کچھ لوگوں نے بڑی مضبوط عمارتیں بنائیں اور بہت مال جمع کیا اور بڑی دور کی امیدیں لگائیں لیکن پھر ان کی عمارتیں گر کر قبرستان بن گئیں اور ان کی امیدیں دھوکہ ثابت ہوئیں اور ایسے لوگ خود ہی ہلاک ہو گئے۔ غور سے سنو! علم سیکھو اور سکھاؤ کیونکہ علم سیکھنے والا اور سکھانے والا دونوں اجر میں برابر ہیں۔ اگر یہ دونوں نہ ہوں تو پھر لوگوں میں کوئی خیر نہیں ہے۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Nu'aym in his Hilya (Vol.1 Pg.213)."]]},{"b":[["n",[["حضرت حسانؒ","b"],[" کہتے ہیں کہ حضرت ابوالدرداءؓ نے دمشق والوں سے فرمایا کیا تم اس بات پر راضی ہو گئے کہ سالہا سال گندم کی روٹی پیٹ بھر کر کھاتے رہو؟ تمہاری مجلسوں میں ",""],["ٱللَّٰه","a"],[" کا نام نہیں لیا جاتا۔ تمہیں کیا ہو گیا؟ تمہارے علماء جا رہے ہیں لیکن تمہارے جاہل علم حاصل نہیں کر رہے ہیں؟ اگر تمہارے علماء چاہتے تو ان کی تعداد میں اضافہ ہو سکتا تھا، اگر تمہارے جاہل علم کو تلاش کرتے تو وہ اسے ضرور پا لیتے۔ نقصان دینے والی چیزوں کے بجائے اپنے فائدے والی چیزیں اختیار کرو۔ اس ذات کی قسم جس کے قبضہ میں میری جان ہے! جو امت بھی ہلاک ہوئی ہے اس کی ہلاکت کے دو ہی اسباب تھے، ایک تو وہ اپنی خواہشات پر چل رہے تھے اور دوسرے وہ اپنی تعریف کیا کرتے تھے۔ ",""],["حضرت ابوالدرداءؓ","b"],[" فرماتے ہیں علم کے اٹھنے سے پہلے اسے حاصل کر لو اور علم کے اٹھنے کی صورت یہ ہوگی کہ علماء دنیا سے چلے جائیں گے اور علم سکھانے والے اور سیکھنے والے دونوں اجر میں برابر ہیں۔ انسان کہلانے کے مستحق دو ہی آدمی ہیں: علم سکھانے والا عالم اور سیکھنے والا۔ ان دو کے علاوہ باقی انسانوں میں کوئی خیر نہیں۔",""],[" (11)","s"],[" (12)","s"]]]],"f":[["(11)","Abu Nu'aym in his Hilya (Vol.1 Pg.222)."],["(12)","Abu Nu'aym in his Hilya (Vol.1 Pg.222)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" فرماتے ہیں جو بھی صبح سویرے مسجد کو کوئی خیر کی بات سیکھنے یا سکھانے جاتا ہے اس کے لیے اس مجاہد کا اجر لکھا جاتا ہے جو مال غنیمت لے کر واپس آتا ہے۔",""],[" (13)","s"]]]],"f":[["(13)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.1 Pg.32)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" فرماتے ہیں کہ جو آدمی یہ سمجھے کہ صبح اور شام علم کے لیے جانا جہاد نہیں ہے وہ کم عقل اور ناقص رائے والا ہے۔ ",""],["حضرت ابوالدرداءؓ","b"],[" فرماتے ہیں کہ علم سیکھنے سے ہی حاصل ہوتا ہے۔",""],[" (14)","s"],[" (15)","s"]]]],"f":[["(14)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.1 Pg.31)."],["(15)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.1 Pg.100)."]]},{"b":[["n",[["حضرت ابوذرؓ","b"],[" اور ",""],["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ آدمی کا علم کا ایک باب سیکھ لینا ہمیں اس کے ہزار رکعت نفل پڑھنے سے زیادہ محبوب ہے اور حضورؐ نے ارشاد فرمایا ہے جو طالب علم طالب علمی کی حالت میں مرے گا وہ شہید ہوگا۔ ایک روایت میں ان دونوں حضرات کا یہ ارشاد نقل ہے کہ علم کا ایک باب سکھانا ہمیں سو رکعت نفل سے زیادہ محبوب ہے چاہے اس پر عمل ہو رہا ہو یا نہ ہو رہا ہو۔",""],[" (16)","s"],[" (17)","s"]]]],"f":[["(16)","Bazzaar and Tabraani, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.61)."],["(17)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.1 Pg.25)."]]},{"b":[["n",[["حضرت علی ازدیؒ","b"],[" کہتے ہیں میں نے حضرت ابن عباسؓ سے جہاد کے بارے میں پوچھا تو انہوں نے فرمایا کیا میں تمہیں ایسا عمل نہ بتاؤں جو تمہارے لیے جہاد سے بہتر ہے؟ تم کسی مسجد میں جا کر قرآن، فقہ یا سنت سکھاؤ۔ ",""],["حضرت ازدیؒ","b"],[" کہتے ہیں میں نے حضرت ابن عباسؓ سے جہاد کے بارے میں پوچھا تو انہوں نے فرمایا کیا میں تمہیں وہ عمل نہ بتاؤں جو تمہارے لیے جہاد سے بہتر ہے؟ تم کسی مسجد میں جا کر قرآن، نبی کریمؐ کی سنتیں اور دین کے فقہی مسائل سکھاؤ۔",""],[" (18)","s"],[" (19)","s"]]]],"f":[["(18)","Ibn Zanjway, as quoted in Kanzul Ummaal (Vol.5 Pg.230)."],["(19)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.1 Pg.62)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں لوگوں کو خیر سکھانے والے کے لیے ہر چیز دعائے مغفرت کرتی ہے حتیٰ کہ سمندر میں مچھلیاں بھی اس کے لیے دعائے مغفرت کرتی ہیں۔",""],[" (20)","s"]]]],"f":[["(20)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.1 Pg.124)."]]},{"b":[["n",[["حضرت زر بن حبیشؒ","b"],[" کہتے ہیں میں حضرت صفوان بن عسال مرادیؓ کی خدمت میں صبح صبح گیا تو انہوں نے پوچھا اے زر! تم صبح صبح کس لیے آئے ہو؟ میں نے کہا علم حاصل کرنے آیا ہوں۔ فرمایا تو علم سکھانے والے عالم بنو یا سیکھنے والے بنو۔ ان دو کے علاوہ اور کچھ نہ بنو۔",""],[" (21)","s"]]]],"f":[["(21)","Tabraani in his Awsat. Haythami (Vol.1 Pg.122) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت صفوانؓ","b"],[" فرماتے ہیں جو اپنے گھر سے علم حاصل کرنے نکلتا ہے تو فرشتے اس علم سیکھنے والے اور اس علم سکھانے والے کے لیے اپنے پر بچھاتے ہیں۔",""],[" (22)","s"]]]],"f":[["(22)","Tabraani in his Kabeer. Haythami (Vol.1 Pg.123) has commented on the chain of narrators."]]}]},"48":{"lead":[],"stories":[{"b":[["n",[["جب ",""],["حضرت معاذ بن جبلؓ","b"],[" کی وفات کا وقت قریب آیا تو فرمایا دیکھو کیا صبح صادق ہو گئی ہے؟ ایک آدمی نے آ کر بتایا کہ ابھی نہیں ہوئی۔ پھر فرمایا دیکھو کیا صبح صادق ہو گئی ہے؟ پھر کسی نے آ کر بتایا کہ ابھی نہیں ہوئی۔ بالآخر ایک آدمی نے آ کر بتایا کہ صبح صادق ہو گئی ہے تو فرمایا میں اس رات سے ",""],["ٱللَّٰه","a"],[" کی پناہ مانگتا ہوں جس کی صبح دوزخ کی آگ کی طرف لے جائے۔ خوش آمدید ہو موت کو، خوش آمدید ہو اس مہمان کو جو بہت لمبے عرصے کے بعد ملنے آیا ہے، جس سے مجھے بہت محبت ہے لیکن وہ ایسے وقت آیا ہے جبکہ میرے ہاں فاقہ ہے۔ اے ",""],["ٱللَّٰه","a"],["! میں زندگی بھر تجھ سے ڈرتا رہا لیکن آج تیری رحمت کا امید وار ہوں۔ اے ",""],["ٱللَّٰه","a"],["! تجھے اچھی طرح معلوم ہے کہ مجھے دنیا سے اور اس میں زیادہ عرصہ تک رہنے سے اس وجہ سے محبت نہیں ہے کہ میں نہریں کھودوں اور درخت لگاؤں بلکہ اس وجہ سے ہے تا کہ میں سخت گرمی کی دوپہر میں پیاس برداشت کروں یعنی گرمیوں میں روزے رکھوں اور مشقت کے مواقع پر مشقت اٹھاؤں اور علم کے حلقوں میں علماء کی خدمت میں دوزانو بیٹھوں۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilya (Vol.1 Pg.239). Ibn Abdul Birr has also reported the narration in his Jaami Bayaanil Ilm (Vol.1 Pg.51)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" نے فرمایا اگر تین کام نہ ہوتے تو میں اسے پسند کرتا کہ دنیا میں اور نہ رہوں۔ راوی کہتے ہیں کہ میں نے پوچھا کہ وہ تین کام کون سے ہیں؟ انھوں نے فرمایا ایک تو دن اور رات میں اپنے خالق کے سامنے سر زمین پر رکھنا جو میری آخرت کی زندگی میں آگے جمع ہو رہا ہے۔ دوسرے سخت گرمیوں کی دوپہر میں (روزہ رکھ کر) پیاسا رہنا۔ تیسرے ایسے لوگوں کے ساتھ بیٹھنا جو عمدہ کلام کو ایسے چنتے ہیں جیسے کہ پھل چنا جاتا ہے۔ آگے اور بھی حدیث ہے۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں جب حضورؐ کا انتقال ہوا تو میں نے ایک انصاری آدمی سے کہا آج صحابہ بہت بڑی تعداد میں موجود ہیں، آؤ ان سے پوچھ پوچھ کر قرآن و حدیث جمع کر لیں۔ انھوں نے کہا اے ابن عباس! آپ پر بڑا تعجب ہے، کیا آپ یہ سمجھتے ہیں کہ حضورؐ کے اتنے بڑے بڑے صحابہؓ کے ہوتے ہوئے بھی لوگوں کو آپ کی ضرورت پڑے گی؟ (انھوں نے میری بات نہ مانی اور اس کے لیے تیار نہ ہوئے تو) میں نے انہیں چھوڑ دیا اور حضورؐ کے صحابہؓ سے پوچھنے لگا اور مجھے پتہ چلتا کہ فلاں صحابی فلاں حدیث بیان کرتے ہیں تو میں ان کے دروازے پر جا تا، وہ دوپہر کو آرام کر رہے ہوتے۔ میں ان کے دروازے پر چادر پر ٹیک لگا کر بیٹھ جاتا اور ہوا کی وجہ سے مٹی مجھ پر پڑتی رہتی، وہ صحابی (آرام سے فارغ ہو کر) باہر آتے تو مجھے دیکھتے اور کہتے اے حضورؐ کے چچا زاد بھائی! آپ کا کیسے آنا ہوا؟ آپ خود کیوں آئے؟ آپ کسی کو میرے پاس بھیج دیتے میں آپ کے پاس آ جاتا۔ میں کہتا نہیں (مجھے آپ سے علم حاصل کرنا ہے، اس لیے) میرا حق بنتا ہے کہ میں آپ کی خدمت میں آؤں، پھر میں ان سے اس حدیث کے بارے پوچھتا (اس طرح میں نے تفسیر اور احادیث کا بہت بڑا ذخیرہ جمع کر لیا یہاں تک کہ جنہیں حاصل کرنے کے لیے لوگ میرے پاس آنے لگے) وہ انصاری بھی بہت عرصہ تک زندہ رہے اور انھوں نے دیکھا کہ لوگ میرے ارد گرد جمع ہیں اور مجھ سے قرآن و حدیث کے بارے میں پوچھ رہے ہیں۔ اس پر انہوں نے کہا یہ نوجوان واقعی مجھ سے زیادہ سمجھ دار نکلا۔",""],[" (2)","s"]]]],"f":[["(2)","Haakim in his Mustadrak (Vol.1 Pg.106), reporting from reliable sources as confirmed by Dhahabi. Daarimi and Haarith in his Masaaneed have reported a similar narration, as quoted in Isaabah (Vol.2 Pg.331). Tabraani has also reported the narration from reliable sources as confirmed by Haythami (Vol.9 Pg.277). A similar narration has also been reported by Ibn Abdul Birr in his Jaami (Vol.1 Pg.85) and by Ibn Sa'd (Vol.4 Pg.182)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" نے فرمایا جب دنیا کے مختلف شہر فتح ہوئے تو لوگ دنیا کی طرف متوجہ ہو گئے اور میں نے اپنی ساری توجہ حضرت عمرؓ (سے قرآن و حدیث لینے) کی طرف لگا دی۔ راوی کہتے ہیں کہ حضرت ابن عباسؓ کی اکثر حدیثیں حضرت عمرؓ ہی سے منقول ہیں۔",""],[" (3)","s"]]]],"f":[["(3)","Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.161)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ نے مجھ سے فرمایا جس طرح تیرے ساتھی مجھ سے مال غنیمت مانگتے ہیں تم نہیں مانگتے۔ میں نے عرض کیا میں تو آپؐ سے یہ مانگتا ہوں کہ جو علم ",""],["ٱللَّٰه","a"],[" نے آپؐ کو عطا فرمایا ہے آپؐ اس میں سے مجھے بھی سکھائیں۔ اس کے بعد میں نے کمر سے دھاری دار چادر اتار کر اپنے اور حضورؐ کے درمیان بچھا دی اور یہ منظر مجھے ایسا یاد ہے کہ اب بھی مجھ کو اس پر جوئیں چلتی ہوئی نظر آ رہی ہیں۔ پھر آپؐ نے مجھے حدیث سنائی، جب میں نے وہ حدیث پوری سن لی تو حضورؐ نے فرمایا اب اس چادر کو سمیٹ کر اپنے جسم سے باندھ لو۔ (میں نے ایسے ہی کیا) اس کے بعد حضورؐ جو بھی ارشاد فرماتے مجھے اس میں سے ایک حرف بھی نہیں بھولتا تھا۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilya (Vol.1 Pg.381)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں لوگ یہ کہتے ہیں کہ ابوہریرہ بہت زیادہ حدیثیں بیان کرتا ہے، ہم سب نے ",""],["ٱللَّٰه","a"],[" کے پاس جانا ہے (اگر میں غلط حدیث بیان کروں گا تو ",""],["ٱللَّٰه","a"],[" میری پکڑ فرمائیں گے اور جو میرے بارے میں غلط گمان رکھتے ہیں ",""],["ٱللَّٰه","a"],[" ان سے بھی پوچھیں گے) اور لوگ یہ بھی کہتے ہیں دوسرے مہاجرین اور انصار صحابہؓ ابوہریرہ جتنی حدیثیں بیان نہیں کرتے۔ میرے مہاجر بھائی تو بازاروں میں خرید و فروخت میں مشغول رہتے تھے اور میرے انصاری بھائیوں کو اپنی زمینوں اور مویشیوں کی مشغولی تھی اور میں ایک مسکین نادار آدمی تھا اور ہر وقت حضورؐ کی خدمت میں پیٹ بھر کھانے پر قناعت کر کے حاضر رہتا تھا۔ انصار و مہاجرین جب حضورؐ کی خدمت سے چلے جاتے تو میں پھر بھی حاضر خدمت رہتا۔ وہ حضورؐ سے سن کر اپنے کاموں میں لگ کر بھول جاتے، میں سب کچھ یاد رکھتا۔ ایک دن حضورؐ نے فرمایا تم میں سے جو آدمی بھی اپنا کپڑا میرے سامنے پھیلائے گا اور جب میں اپنی بات پوری کر لوں تو وہ اسے سمیٹ کر اپنے سینے سے لگائے گا تو وہ کبھی بھی میری کوئی بات نہیں بھولے گا۔ میں نے فوراً اپنی دھاری دار چادر بچھا دی۔ میری کمر پر اس کے علاوہ اور کوئی کپڑا نہیں تھا۔ پھر جب حضورؐ نے اپنی وہ بات پوری فرما لی تو میں نے چادر سمیٹ کر اپنے سینے سے لگا لی۔ اس ذات کی قسم جس نے آپؐ کو حق دے کر بھیجا ہے! مجھے اس میں سے ایک بات بھی آج تک نہیں بھولی۔ ",""],["ٱللَّٰه","a"],[" کی کتاب (قرآن) میں اگر یہ دو آیتیں نہ ہوتیں (جن میں علم کو چھپانے کی ممانعت ہے) تو میں آپ لوگوں کو بھی کوئی حدیث بیان نہ کرتا:",""]]],["q",[["إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِى ٱلْكِتَٰبِ ۙ أُو۟لَٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّٰعِنُونَ ۝ إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَٰٓئِكَ أَتُوبُ عَلَيْهِمْ ۚ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ  (سورۃ بقرہ: ۱۵۹-۱۶۰)","a"]]],["p",[["ترجمہ: \"جو لوگ اخفاء کرتے ہیں ان مضامین کا جن کو ہم نے نازل کیا ہے جو کہ (اپنی ذات میں) واضح ہیں اور (دوسروں کو) ہادی ہیں بعد اس کے کہ ہم ان کو کتاب الٰہی (تورات و انجیل) میں عام لوگوں پر ظاہر کر چکے ہوں، ایسے لوگوں پر ",""],["ٱللَّٰه","a"],[" تعالیٰ بھی لعنت فرماتے ہیں اور (دوسرے بہتیرے) لعنت کرنے والے بھی ان پر لعنت بھیجتے ہیں۔ مگر جو لوگ توبہ کر لیں اور اصلاح کر دیں اور (ان مضامین کو) ظاہر کر دیں تو ایسے لوگوں پر میں متوجہ ہو جاتا ہوں اور میری تو بکثرت عادت ہے توبہ قبول کر لینا اور مہربانی فرمانا۔\"",""],[" (5)","s"]]]],"f":[["(5)","Bukhaari (Vol.1 Pg.316)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں لوگ کہتے تھے کہ ابوہریرہ بہت زیادہ حدیثیں بیان کرتا ہے۔ اصل بات یہ ہے کہ میں ہر وقت حضورؐ کے ساتھ رہتا تھا اور صرف پیٹ بھر کھانے پر گزارہ کر لیتا تھا۔ ان دنوں نہ خمیری روٹی مجھے ملتی تھی اور نہ پہننے کو ریشم اور نہ خدمت کرنے والا کوئی مرد میرے پاس تھا اور نہ کوئی عورت۔ اور بعض دفعہ بھوک کی شدت کی وجہ سے اپنا پیٹ کنکریوں کے ساتھ چمٹا دیتا تھا (تا کہ کنکریوں کی ٹھنڈک سے بھوک کی گرمی میں کمی آ جائے) اور کبھی ایسا بھی ہوتا تھا کہ قرآن کی آیت مجھے معلوم ہوتی تھی لیکن میں کسی آدمی سے وہ آیت اس لیے پڑھاتا تھا تا کہ وہ مجھے اپنے ساتھ گھر لے جائے اور مجھے کچھ کھلا دے اور مساکین کے حق میں سب سے بہتر حضرت جعفر بن ابی طالبؓ تھے۔ وہ ہمیں گھر لے جاتے اور جو کچھ گھر میں ہوتا وہ سب کچھ ہمیں کھلا دیتے یہاں تک کہ بعض دفعہ وہ شہد یا گھی کی کپی ہی ہمارے پاس باہر لے آتے۔ اس کپی میں کچھ ہوتا نہیں تھا تو ہم اسے پھاڑ کر اس کے اندر جو ہوتا اسے چاٹ لیتے۔",""],[" (6)","s"]]]],"f":[["(6)","Bukhaari, as quoted in Targheeb wat Tarheeb (Vol.5 Pg.175)."]]}]},"49":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوموسیٰؓ","b"],[" فرماتے ہیں حضورؐ نے ارشاد فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے مجھے جو ہدایت اور علم دے کر بھیجا ہے اس کی مثال اس بارش جیسی ہے جو بہت زیادہ ہوئی اور ایک زمین پر برسی ہو جس کا ایک ٹکڑا بہت عمدہ اور زرخیز تھا، اس ٹکڑے نے بارش کے پانی کو اپنے اندر جذب کر لیا جس سے گھاس اور چارہ خوب اگا۔ اس زمین میں ایک بنجر اور سخت ٹکڑا تھا جس نے اس پانی کو روک لیا (نہ اپنے اندر جذب کیا اور ڈھلان نہ ہونے کی وجہ سے نہ جانے دیا) تو ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس پانی سے لوگوں کو نفع پہنچایا، چنانچہ انھوں نے اسے پیا اور اپنے جانوروں کو پلایا اور اس سے کاشت کی۔ اور اس زمین کا تیسرا ٹکڑا چٹیل میدان تھا جس میں پانی بھی (ڈھلان کی وجہ سے) نہ رکا اور گھاس وغیرہ بھی نہ اگا۔ یہ مثال اس شخص کی ہے جس نے ",""],["ٱللَّٰه","a"],[" کے دین میں سمجھ حاصل کی اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جو مجھے دے کر بھیجا ہے اس سے اس کو نفع ہوا، اس نے خود سیکھا اور دوسروں کو سکھایا۔ اور اس آدمی کی مثال ہے جس نے تکبر کی وجہ سے اس علم و ہدایت کی طرف بالکل توجہ نہ کی اور ",""],["ٱللَّٰه","a"],[" تعالیٰ کی جو ہدایت دے کر مجھے بھیجا گیا ہے اسے بالکل قبول نہ کیا۔",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari and Muslim, as quoted in Mishkaatul Masaabeeh (Pg.20)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا مجھ سے پہلے ",""],["ٱللَّٰه","a"],[" نے جس نبی کو بھی اس امت میں بھیجا تو اس امت میں اس کے حواری اور خاص صحابی ضرور ہوتے تھے جو اس کی ہر سنت کو مضبوطی سے پکڑتے اور ٹھیک ٹھیک اس کی پیروی کرتے اور اس کے دین کو بعینہ محفوظ رکھتے لیکن بعد میں ایسے نالائق لوگ پیدا ہو جاتے جو ان کاموں کا دعویٰ کرتے جو انھوں نے کیے نہیں ہوتے تھے اور جن کاموں کا حکم نہیں دیا گیا تھا ان کاموں کو کرتے تھے (میری امت میں بھی ایسے لوگ آئندہ ہوں گے) جو ان لوگوں کے خلاف اپنے ہاتھ سے جہاد کرے وہ بھی مومن ہے اور جو اپنی زبان سے جہاد کرے وہ بھی مومن ہے اور جو اپنے دل سے جہاد کرے وہ بھی مومن ہے، اس کے بعد رائی کے دانے کے برابر بھی ایمان نہیں ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Muslim, as quoted in Mishkaatul Masaabeeh (Pg.21)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا اصل علم تین چیزیں ہیں: محکم آیت (یعنی قرآن مجید)، قائم دائم سنت یعنی حضورؐ کی وہ حدیث جو قابل اعتماد سند سے ثابت ہو اور قرآن و حدیث کے برابر درجہ رکھنے والے فرائض یعنی اجماع اور قیاس۔ ان کے علاوہ جو کچھ ہے وہ زائد علم ہے (اسے حاصل کرنا ضروری نہیں ہے)۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Dawood and Ibn Maajah, as quoted in Mishkaatul Masaabeeh (Pg.27). Ibn Abdul Birr has reported a similar narration in his Jaami Bayaanil Ilm (Vol.2 Pg.23)."]]},{"b":[["n",[["حضرت عمرو بن عوفؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا میں تم میں ایسی دو چیزوں کو چھوڑ کر جا رہا ہوں کہ جب تک تم ان دونوں کو مضبوطی سے تھامے رکھو گے کبھی گمراہ نہیں ہو گے۔ ایک ",""],["ٱللَّٰه","a"],[" کی کتاب اور دوسری اس کے نبیؐ کی سنت۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.23)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ نبی کریمؐ ایک دن مسجد میں تشریف لائے تو دیکھا کہ بہت سارے لوگ ایک آدمی پر جمع ہیں۔ حضورؐ نے پوچھا یہ کون ہے؟ لوگوں نے کہا یہ ایک علامہ ہے۔ حضورؐ نے پوچھا اس کے علامہ ہونے کا کیا مطلب ہے؟ لوگوں نے کہا یہ عربوں کے نسب، عربی زبان، اشعار اور عربوں کا جن چیزوں میں اختلاف ہے ان سب کو تمام لوگوں سے زیادہ جاننے والا ہے۔ حضورؐ نے فرمایا یہ ایسا علم ہے جس کے جاننے میں کوئی فائدہ نہیں اور اس کے معلوم نہ ہونے میں کوئی نقصان نہیں۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.23)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ علم تین چیزیں ہیں: حق بولنے والی کتاب یعنی قرآن مجید، وہ سنت جو قیامت تک چلے گی اور جو بات نہ آتی ہو اس کے بارے میں یہ کہہ دینا کہ میں اسے نہیں جانتا۔ ",""],["حضرت ابن عباسؓ","b"],[" فرماتے ہیں اصل علم ",""],["ٱللَّٰه","a"],[" کی کتاب اور اس کے رسولؐ کی سنت ہے۔ ان دونوں کو چھوڑ کر جو بھی اپنی رائے سے کچھ کہے گا اس کا پتہ نہیں کہ وہ اسے اپنی نیکیوں میں پائے گا یا اپنی برائیوں میں۔",""],[" (6)","s"],[" (7)","s"]]]],"f":[["(6)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.24)."],["(7)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.26)."]]},{"b":[["n",[["حضرت مجاہدؒ","b"],[" کہتے ہیں کہ ایک مرتبہ ہم حضرت ابن عباسؓ کے شاگرد حضرت عطاء، حضرت طاؤس اور حضرت عکرمہ بیٹھے ہوئے تھے اور حضرت ابن عباسؓ کھڑے ہو کر نماز پڑھ رہے تھے کہ اتنے میں ایک آدمی آیا اور اس نے کہا کیا یہاں کوئی مفتی ہے؟ میں نے کہا پوچھو کیا پوچھتے ہو؟ اس نے کہا میں جب بھی پیشاب کرتا ہوں تو اس کے بعد منی نکل آتی ہے۔ ہم نے کہا وہی منی جس سے بچہ بنتا ہے؟ اس نے کہا جی ہاں! ہم نے کہا اس سے تمہیں غسل کرنا پڑے گا۔ وہ آدمی اِنَّا لِلّٰہِ پڑھتا ہوا پشت پھیر کر واپس چلا گیا۔ حضرت ابن عباسؓ نے جلدی جلدی نماز پوری کی اور سلام پھیرتے ہی عکرمہ سے کہا اے عکرمہ! اس آدمی کو میرے پاس لاؤ۔ چنانچہ حضرت عکرمہؒ اسے لے آئے تو حضرت ابن عباسؓ ہماری طرف متوجہ ہوئے اور فرمایا تم نے جو اس آدمی کو مسئلہ بتایا ہے وہ تم نے ",""],["ٱللَّٰه","a"],[" کی کتاب سے لیا ہے؟ ہم نے کہا نہیں۔ انھوں نے فرمایا کیا تم نے یہ مسئلہ حضورؐ کی سنت سے لیا ہے؟ ہم نے کہا نہیں۔ انھوں نے فرمایا کیا تم نے حضورؐ کے صحابہؓ سے لیا ہے؟ ہم نے کہا نہیں۔ انھوں نے فرمایا پھر کس سے لیا ہے؟ ہم نے کہا ہم نے اپنی رائے سے اسے بتایا ہے۔ انھوں نے فرمایا اسی وجہ سے حضورؐ فرماتے ہیں کہ ایک فقیہ شیطان پر ہزار عابدوں سے زیادہ بھاری ہے۔ پھر اس آدمی کی طرف متوجہ ہو کر فرمایا ذرا یہ بتاؤ پیشاب کے بعد جب منی نکلتی ہے تو کیا اس وقت تمہارے دل میں شہوت ہوتی ہے؟ اس نے کہا نہیں۔ فرمایا کیا اس کے نکلنے کے بعد تم اپنے جسم میں سستی محسوس کرتے ہو؟ اس نے کہا نہیں تو فرمایا یہ منی معدہ کی خرابی کی وجہ سے نکلتی ہے، لہٰذا تمہارے لیے وضو کافی ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.26)."]]}]},"50":{"lead":[],"stories":[{"b":[["n",[["حضرت عمرو بن یحییٰ بن جعدہؒ","b"],[" فرماتے ہیں حضورؐ کی خدمت میں ایک کتاب لائی گئی جو کسی جانور کے کندھے کی ہڈی پر لکھی ہوئی تھی۔ اس پر حضورؐ نے فرمایا کسی قوم کے بے وقوف اور گمراہ ہونے کے لیے یہ کافی ہے کہ اپنے نبی کے لائے ہوئے علم کو چھوڑ کر دوسرے نبی کے علم کی طرف متوجہ ہوں یا اپنے نبی کی کتاب کے علاوہ کسی اور کتاب کی طرف متوجہ ہوں۔ اس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ آیت نازل فرمائی:",""]]],["q",[["أَوَلَمْ يَكْفِهِمْ أَنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ يُتْلَىٰ عَلَيْهِمْ  (سورۃ عنکبوت: ۵۱)","a"]]],["p",[["ترجمہ: \"کیا ان لوگوں کو یہ بات کافی نہیں ہوئی کہ ہم نے آپ پر یہ کتاب نازل فرمائی جو ان کو سنائی جاتی رہتی ہے۔\"",""],[" (1)","s"]]]],"f":[["(1)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.5 Pg.118)."]]},{"b":[["n",[["حضرت خالد بن عرفطہؒ","b"],[" کہتے ہیں کہ ایک مرتبہ میں حضرت عمرؓ کے پاس بیٹھا ہوا تھا کہ اتنے میں قبیلہ عبدالقیس کا ایک آدمی ان کے پاس لایا گیا جس کی رہائش سوس شہر میں تھی (یہ خوزستان کا ایک شہر ہے جس میں حضرت دانیال علیہ السلام کی قبر ہے)۔ حضرت عمرؓ نے فرمایا تم فلاں بن فلاں عبدی ہو؟ اس نے کہا جی ہاں۔ حضرت عمرؓ کے پاس ایک لاٹھی تھی وہ انھوں نے اسے ماری۔ اس نے کہا اے امیر المومنین! میرا کیا قصور؟ حضرت عمرؓ نے فرمایا بیٹھ جاؤ۔ وہ بیٹھ گیا۔ حضرت عمرؓ نے یہ آیات تین دفعہ پڑھیں:",""]]],["q",[["بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ۝ الٓر ۚ تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ ۝ إِنَّآ أَنزَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ ۝ نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ بِمَآ أَوْحَيْنَآ إِلَيْكَ هَٰذَا ٱلْقُرْءَانَ وَإِن كُنتَ مِن قَبْلِهِۦ لَمِنَ ٱلْغَٰفِلِينَ  (سورۃ یوسف: ۱-۳)","a"]]],["p",[["ترجمہ: \"الر۔ یہ آیتیں ہیں ایک کتاب واضح کی۔ ہم نے اس کو اتارا ہے قرآن عربی زبان کا کہ تم سمجھو۔ ہم نے جو یہ قرآن آپ کے پاس بھیجا ہے اس کے ذریعہ سے ہم آپ سے ایک بڑا عمدہ قصہ بیان کرتے ہیں اور اس کے قبل آپ محض بے خبر تھے۔\" اور اسے تین دفعہ لاٹھی ماری۔ اس آدمی نے کہا اے امیر المومنین! میرا قصور؟ حضرت عمرؓ نے فرمایا تم نے ہی حضرت دانیال علیہ السلام کی کتابیں لکھی ہیں۔ اس آدمی نے کہا اس بارے میں آپ مجھے جو فرمائیں گے میں وہی کروں گا۔ حضرت عمرؓ نے فرمایا جاؤ اور جا کر ان پر گرم گرم پانی ڈال کر سفیدی ان کو مٹا دو اور نہ کسی کو پڑھاؤ نہ خود پڑھو۔ اگر مجھے پتہ چلا کہ تم نے خود پڑھی ہیں یا کسی کو پڑھائی ہیں تو میں تمہیں سخت سزا دوں گا۔ پھر اس سے فرمایا یہاں بیٹھو۔ وہ حضرت عمرؓ کے سامنے آ کر بیٹھ گیا۔ حضرت عمرؓ نے فرمایا ایک دفعہ میں گیا اور اہل کتاب کی ایک کتاب نقل کی اور اسے ایک کھال پر لکھ کر حضورؐ کی خدمت میں لایا۔ حضورؐ نے فرمایا اے عمر! یہ تمہارے ہاتھ میں کیا ہے؟ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! یہ کتاب میں نے اس لیے لکھ کر لایا ہوں تا کہ ہمارے علم میں اضافہ ہو جائے۔ یہ سنتے ہی حضورؐ کو اتنا غصہ آیا کہ آپؐ کے دونوں رخسار سرخ ہو گئے، پھر (حضورؐ کے ارشاد پر لوگوں کو جمع کرنے کے لیے) الصلوٰۃ جامعۃ کہہ کر اعلان کیا گیا۔ انصار نے کہا تمہارے نبی ",""],["ﷺ","a"],[" کو کسی وجہ سے سخت غصہ آیا ہوا ہے، اس لیے تم ہتھیار لگا کر چلو۔ چنانچہ انصار تیار ہو کر آئے اور آ کر حضورؐ کے منبر کو چاروں طرف سے گھیر لیا۔ حضورؐ نے فرمایا اے لوگو! مجھے ایسے کلمات دیے گئے ہیں جن کے الفاظ کم اور معانی بہت زیادہ ہیں اور وہ مہر کی طرح آخری درجے کے اور فیصلہ کن نوعیت کے کلمات ہیں اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے بہت مختصر کر کے مجھے عطا فرمائے ہیں۔ اور میں تمہارے پاس ایسی ملت لے کر آیا ہوں جو بالکل واضح اور صاف ستھری ہے، لہٰذا تم حیرت اور پریشانی میں مت پڑو اور نہ حیرت میں پڑنے والوں یعنی اہل کتاب سے دھوکہ کھاؤ۔ حضرت عمرؓ فرماتے ہیں میں فوراً کھڑے ہو کر عرض کیا میں ",""],["ٱللَّٰه","a"],[" کے رب ہونے پر، اسلام کے دین ہونے پر اور آپؐ کے رسول ہونے پر بالکل راضی ہوں۔ پھر حضورؐ منبر سے نیچے تشریف لے آئے۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Ya'la. Haythami (Vol.1 Pg.182) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں حضرت عمر بن خطابؓ کو اہل کتاب سے ایک کتاب ملی، وہ اسے لے کر نبی کریمؐ کی خدمت میں حاضر ہوئے اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مجھے اہل کتاب سے ایک بہت اچھی کتاب ملی ہے۔ یہ سنتے ہی حضورؐ کو غصہ آ گیا اور فرمایا اے ابن الخطاب! کیا تم ابھی تک اسلام کے امور کے بارے میں حیران و پریشان ہو؟ اس ذات کی قسم جس کے قبضہ میں میری جان ہے! میں تمہارے پاس ایسی ملت لے کر آیا ہوں جو بالکل واضح اور صاف ستھری ہے۔ تم اہل کتاب سے کچھ نہ پوچھو کیونکہ ہو سکتا ہے کہ وہ جواب میں تمہیں حق بات کہہ دیں اور تم اسے جھٹلا دو یا وہ غلط بات کہہ دیں اور تم اسے سچا مان لو (ان کے ہاں حق اور باطل آپس میں ملا ہوا ہے)۔ اس ذات کی قسم جس کے قبضہ میں میری جان ہے! اگر حضرت موسیٰ علیہ السلام زندہ ہوتے تو ان کو بھی میرا ہی اتباع کرنا پڑتا (اس کے علاوہ ان کے لیے بھی کامیابی کا اور کوئی راستہ نہ ہوتا)۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.42). Ahmad, Abu Ya'la and Bazzaar have reported a similar narration."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن ثابتؓ","b"],[" فرماتے ہیں حضرت عمر بن خطابؓ نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرا اپنے ایک بھائی کے پاس سے گزر ہوا جو قبیلہ بنو قریظہ میں سے ہے۔ اس نے مجھے تورات میں سے جامع باتیں لکھ کر دی ہیں، کیا میں انہیں آپؐ کے سامنے پیش کروں؟ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ فرماتے ہیں یہ سنتے ہی غصہ کی وجہ سے حضورؐ کا چہرہ بدل گیا تو میں نے کہا (اے عمر!) کیا تم حضورؐ کے چہرے پر غصہ کے آثار نہیں دیکھ رہے ہو؟ انھوں نے فوراً عرض کیا ہم ",""],["ٱللَّٰه","a"],[" کے رب ہونے پر، اسلام کے دین ہونے پر اور محمدؐ کے رسول ہونے پر راضی ہیں۔ اس پر حضورؐ کا غصہ زائل ہو گیا اور فرمایا اس ذات کی قسم جس کے قبضہ میں میری جان ہے! اگر تم میں حضرت موسیٰؑ ہوتے اور تم مجھے چھوڑ کر ان کا اتباع کر لیتے تو تم گمراہ ہو جاتے۔ دوسری امتوں میں سے تم میرے حصے میں آئے ہو اور دوسرے نبیوں میں سے میں تمہارے حصے میں آیا ہوں۔",""],[" (4)","s"]]]],"f":[["(4)","Ahmad and Tabraani. Haythami (Vol.1 Pg.174) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت میمون بن مہرانؒ","b"],[" کہتے ہیں کہ ایک آدمی حضرت عمر بن خطابؓ کے پاس آیا اور اس نے کہا اے امیر المومنین! ہم نے جب مدائن شہر فتح کیا تو مجھے ایک کتاب ملی جس کی باتیں مجھے بہت پسند آئیں۔ حضرت عمرؓ نے پوچھا کیا اس کی باتیں ",""],["ٱللَّٰه","a"],[" کی کتاب سے ملی ہوئی ہیں؟ اس آدمی نے کہا نہیں۔ حضرت عمرؓ نے کوڑا منگا کر اسے مارنا شروع کر دیا اور یہ آیتیں پڑھ کر سنانی شروع کیں:",""]]],["q",[["الٓر ۚ تِلْكَ ءَايَٰتُ ٱلْكِتَٰبِ ٱلْمُبِينِ ۝ إِنَّآ أَنزَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ ۝ نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ ٱلْقَصَصِ ... لَمِنَ ٱلْغَٰفِلِينَ  (سورۃ یوسف: ۱-۳)","a"]]],["p",[["ترجمہ اسی باب کے شروع میں گزر چکا ہے۔ پھر حضرت عمرؓ نے فرمایا تم سے پہلے لوگ صرف اسی وجہ سے ہلاک ہوئے کہ وہ اپنے علماء اور پادریوں کی کتابوں کی طرف متوجہ ہو گئے اور انھوں نے تورات اور انجیل کو چھوڑ دیا یہاں تک کہ یہ دونوں کتابیں بوسیدہ ہو گئیں اور دونوں میں جو علم الٰہی تھا وہ سب جاتا رہا۔",""],[" (5)","s"]]]],"f":[["(5)","Nasr Maqdasi, as quoted in Kanzul Ummaal (Vol.1 Pg.95)."]]},{"b":[["n",[["حضرت حریث بن ظہیرؒ","b"],[" کہتے ہیں کہ حضرت ابن مسعودؓ نے فرمایا اہل کتاب سے کچھ بھی نہ پوچھا کرو کیونکہ وہ خود تمہیں کبھی بھی ہدایت کی بات نہیں بتائیں گے بلکہ ہو سکتا ہے کہ وہ حق بات بیان کریں اور تم اسے جھٹلا دو اور وہ غلط بات بیان کریں اور تم اس کی تصدیق کر دو۔ عبدالرزاق کی روایت میں یہ بھی ہے کہ حضرت ابن مسعودؓ نے فرمایا اگر تم نے ان سے ضرور پوچھنا ہے تو پھر یہ دیکھو کہ جو ",""],["ٱللَّٰه","a"],[" کی کتاب کے مطابق ہو وہ لے لو اور جو اس کے خلاف ہو اسے چھوڑ دو۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.40). Abdur Razzaaq has reported a similar narration."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ تم اہل کتاب سے کوئی بات کیسے پوچھتے ہو جبکہ تمہاری یہ کتاب جو ",""],["ٱللَّٰه","a"],[" نے اپنے نبی کریمؐ پر نازل فرمائی ہے تمہارے سامنے موجود ہے۔ تمام کتابیں بہت زمانہ پہلے ",""],["ٱللَّٰه","a"],[" کے پاس سے آئی ہیں اور یہ ابھی ابھی ",""],["ٱللَّٰه","a"],[" کے ہاں سے آئی ہے، بالکل تر و تازہ ہے۔ اس میں باہر کی کوئی چیز ملائی نہیں جا سکی۔ کیا ",""],["ٱللَّٰه","a"],[" نے تمہیں اپنی کتاب میں یہ نہیں بتایا کہ ان اہل کتاب نے ",""],["ٱللَّٰه","a"],[" کی کتاب (تورات اور انجیل) کو بدل دیا ہے اور اس میں تحریف کی ہے اور بہت سی باتیں اپنے پاس سے لکھ کر اس میں شامل کر کے یوں کہنے لگے کہ یہ ",""],["ٱللَّٰه","a"],[" کے پاس سے آئی ہیں۔ یہ اس لیے کیا تا کہ کچھ تھوڑا سا دنیاوی فائدہ حاصل ہو جائے۔ وہ علم الٰہی جو تمہارے پاس آیا ہے کیا وہ تمہیں ان سے پوچھنے سے روکتا نہیں؟ (قرآن و حدیث کے ہوتے ہوئے اہل کتاب سے پوچھنے کی ضرورت نہیں ہے) ",""],["ٱللَّٰه","a"],[" کی قسم! ہم نے تو کبھی نہیں دیکھا کہ اہل کتاب کا کوئی آدمی اس علم کے بارے میں پوچھ رہا ہو جو ",""],["ٱللَّٰه","a"],[" نے تمہارے پاس نازل فرمایا ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.42). Tabraani has reported a similar narration from reliable sources."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں تم اہل کتاب سے ان کی کتابوں کے بارے میں پوچھتے ہو حالانکہ تمہارے پاس ",""],["ٱللَّٰه","a"],[" کی کتاب ہے جو تمام کتابوں کے بعد سب سے آخر میں ابھی ابھی ",""],["ٱللَّٰه","a"],[" کے پاس سے آئی ہے۔ تم اسے پڑھتے بھی ہو اور وہ بالکل تر و تازہ ہے اور اس میں کوئی اور چیز بھی تک ملائی بھی نہیں جا سکتی۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.42)."]]}]},"51":{"lead":[],"stories":[{"b":[["n",[["حضرت ولید بن ابی ولید ابوعثمان مدنیؒ","b"],[" کہتے ہیں کہ حضرت عقبہ بن مسلمؒ نے ان سے بیان کیا کہ حضرت شفی اصبحیؒ نے ان سے بیان کیا کہ میں مدینہ منورہ گیا تو میں نے دیکھا کہ ایک آدمی کے ارد گرد بہت لوگ جمع ہیں۔ میں نے پوچھا یہ صاحب کون ہیں؟ لوگوں نے بتایا کہ یہ حضرت ابوہریرہؓ ہیں۔ اب لوگوں کو حدیثیں سنا رہے تھے۔ جب وہ خاموش ہو گئے اور سب لوگ چلے گئے اور وہ اکیلے رہ گئے تو میں نے عرض کیا کہ میرے آپ پر جتنے حق بنتے ہیں (کہ میں مسلمان ہوں، مسافر ہوں اور طالب علم ہوں وغیرہ) ان سب کا واسطہ دے کر میں درخواست کرتا ہوں کہ آپ مجھے وہ حدیث سنائیں جو آپ نے حضورؐ سے سنی ہے اور خوب اچھی طرح سمجھی ہے۔ حضرت ابوہریرہؓ نے فرمایا ضرور، میں تمہیں وہ حدیث ضرور سناؤں گا جو حضورؐ نے مجھ سے بیان فرمائی اور میں نے اسے خوب اچھی طرح سمجھا ہے۔ پھر حضرت ابوہریرہؓ نے ایسے زور سے سسکی لی کہ بے ہوش ہو گئے۔ ہم کچھ دیر ٹھہرے رہے پھر انہیں افاقہ ہوا تو فرمایا میں تمہیں وہ حدیث ضرور سناؤں گا جو حضورؐ نے مجھ سے اس گھر میں بیان فرمائی اور اس وقت میرے اور حضورؐ کے علاوہ اور کوئی نہیں تھا، پھر اتنے زور سے سسکی لی کہ بے ہوش ہی ہو گئے۔ پھر انہیں افاقہ ہوا اور انھوں نے اپنا چہرہ پونچھا اور فرمایا میں تمہیں وہ حدیث ضرور سناؤں گا جو حضورؐ نے اس وقت مجھ سے بیان فرمائی تھی جبکہ ہم دونوں اس گھر میں تھے اور ہم دونوں کے علاوہ اور کوئی نہیں تھا۔ اس کے بعد پھر حضرت ابوہریرہؓ نے اتنے زور سے سسکی لی کہ بے ہوش ہو گئے اور منہ کے بل زمین پر گرنے لگے لیکن میں نے انہیں سنبھال لیا اور بہت دیر تک انہیں سہارا دے کر سنبھالے رکھا۔ پھر انہیں افاقہ ہوا تو فرمایا کہ مجھ سے حضورؐ نے یہ بیان فرمایا کہ قیامت کے دن ",""],["ٱللَّٰه","a"],[" تعالیٰ بندوں کے درمیان فیصلہ کرنے کے لیے متوجہ ہوں گے اور اس وقت کسی میں بھی ",""],["ٱللَّٰه","a"],[" کے سامنے کھڑے ہونے کی طاقت نہ ہوگی بلکہ ہر جماعت گھٹنوں کے بل سر جھکائے ہوئے ہوگی اور ",""],["ٱللَّٰه","a"],[" تعالیٰ پہلے تین آدمیوں کو بلائیں گے۔ ایک وہ آدمی جس نے سارا قرآن یاد کیا اور دوسرا وہ آدمی جسے ",""],["ٱللَّٰه","a"],[" کے راستے میں شہید کیا گیا اور تیسرا مالدار آدمی۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ قرآن کے قاری کو فرمائیں گے کہ جو وحی میں نے اپنے رسول پر نازل کی تھی کیا میں نے تجھے نہیں سکھائی تھی؟ وہ کہے گا اے میرے رب! سکھائی تھی۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرمائیں گے تو نے جو کچھ سیکھا تھا اس پر کیا عمل کیا؟ وہ کہے گا میں رات دن اس کی تلاوت کرتا تھا۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ اس سے فرمائیں گے تو نے یہ سب کچھ اس لیے کیا تھا تا کہ لوگ تجھے قاری کہیں، سو یہ کہا جا چکا (اور تیرا مقصد حاصل ہو چکا)۔ پھر مالدار کو لایا جائے گا اور ",""],["ٱللَّٰه","a"],[" تعالیٰ اس سے فرمائیں گے کیا میں نے تجھے اس قدر زیادہ وسعت نہیں دی تھی کہ تو کسی کا محتاج نہیں تھا؟ وہ کہے گا جی ہاں بہت وسعت دی تھی۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرمائیں گے جب میں نے تجھے اتنا زیادہ دیا تو تو نے اس کے مقابلہ میں کیا عمل کیے؟ وہ کہے گا میں صلہ رحمی کرتا تھا اور صدقہ و خیرات دیتا تھا۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرمائیں گے تو غلط کہتا ہے اور فرشتے بھی کہیں گے تو غلط کہتا ہے۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ کہیں گے تو نے سب کچھ اس لیے کیا تھا تا کہ لوگ کہیں کہ فلاں بہت سخی ہے اور یہ کہا جا چکا۔ اور پھر ",""],["ٱللَّٰه","a"],[" کے راستے میں شہید ہونے والے کو لایا جائے گا اور ",""],["ٱللَّٰه","a"],[" تعالیٰ اس سے فرمائیں گے تمہیں کس وجہ سے قتل کیا گیا؟ وہ کہے گا تو نے اپنے راستہ میں جہاد کرنے کا حکم دیا تھا اس وجہ سے میں نے کفار سے جنگ کی یہاں تک کہ مجھے قتل کر دیا گیا۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرمائیں گے تو نے یہ سب کچھ اس لیے کیا تھا تا کہ یہ کہا جائے کہ فلاں بہت بہادر ہے اور یہ کہا جا چکا۔ پھر حضورؐ نے میرے گھٹنوں پر ہاتھ مار کر فرمایا اے ابوہریرہ! ",""],["ٱللَّٰه","a"],[" کی مخلوق میں یہی تین آدمی ہیں جن کے ذریعہ قیامت کے دن سب سے پہلے آگ کو بھڑکایا جائے گا۔ یہ حدیث حضرت ابوہریرہؓ سے سن کر حضرت شفیؒ حضرت معاویہؓ کی خدمت میں گئے اور انہیں یہ حدیث سنائی۔ حضرت ابوعثمانؒ کہتے ہیں کہ حضرت علاء بن ابی حکیمؒ حضرت معاویہؓ کے تلوار بردار تھے۔ انھوں نے مجھے یہ واقعہ سنایا کہ ایک آدمی نے حضرت معاویہؓ کے پاس آ کر حضرت ابوہریرہؓ کی طرف سے یہ حدیث سنائی۔ اسے سن کر حضرت معاویہؓ نے فرمایا جب ان تینوں کے ساتھ یہ کیا جائے گا تو باقی لوگوں کے ساتھ کیا ہوگا؟ پھر حضرت معاویہؓ نے رونا شروع کیا اور اتنا زیادہ روئے کہ ہمیں گمان ہونے لگا کہ شاید وہ ہلاک ہو جائیں گے اور ہم نے کہا یہ آدمی تو ہمارے پاس بہت خطرناک خبر لے کر آیا ہے۔ پھر حضرت معاویہؓ کو افاقہ ہوا اور انھوں نے اپنا چہرہ صاف کیا اور فرمایا ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ نے سچ فرمایا ہے:",""]]],["q",[["مَن كَانَ يُرِيدُ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا نُوَفِّ إِلَيْهِمْ أَعْمَٰلَهُمْ فِيهَا وَهُمْ فِيهَا لَا يُبْخَسُونَ ۝ أُو۟لَٰٓئِكَ ٱلَّذِينَ لَيْسَ لَهُمْ فِى ٱلْءَاخِرَةِ إِلَّا ٱلنَّارُ ۖ وَحَبِطَ مَا صَنَعُوا۟ فِيهَا وَبَٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ  (سورۃ ہود: ۱۵-۱۶)","a"]]],["p",[["ترجمہ: \"جو شخص (اپنے اعمال خیر سے) محض حیات دنیوی (کی منفعت) اور اس کی رونق (کا حاصل کرنا) چاہتا ہو تو ہم ان لوگوں کے (ان) اعمال (کی جزا) ان کو دنیا ہی میں پورے طور سے بھگتا دیتے ہیں اور ان کے لیے دنیا میں کچھ کمی نہیں ہوتی۔ یہ ایسے لوگ ہیں کہ ان کے لیے آخرت میں بجز دوزخ کے اور کچھ (ثواب وغیرہ) نہیں اور انھوں نے جو کچھ کیا تھا آخرت میں سب ناکارہ (ثابت) ہوگا اور (واقع میں تو) جو کچھ کر رہے ہیں وہ اب بھی بے اثر ہے۔\"",""],[" (1)","s"]]]],"f":[["(1)","Tirmidhi (Vol.2 Pg.61)."]]},{"b":[["n",[["حضرت ابوسلمہ بن عبدالرحمن بن عوفؒ","b"],[" فرماتے ہیں کہ مروہ پر حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرؓ اور حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرو بن العاصؓ کی آپس میں ملاقات ہوئی، وہ دونوں کچھ دیر آپس میں بات کرتے رہے پھر حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمروؓ چلے گئے اور حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرؓ وہاں روتے ہوئے رہ گئے تو ایک آدمی نے ان سے پوچھا اے ابوعبدالرحمن! آپ کیوں رو رہے ہیں؟ حضرت ابن عمرؓ نے فرمایا یہ صاحب یعنی حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمروؓ ابھی بتا کر گئے ہیں کہ انھوں نے حضورؐ کو یہ فرماتے ہوئے سنا کہ جس کے دل میں رائی کے دانے کے برابر بھی تکبر ہوگا ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے چہرے کے بل آگ میں ڈال دیں گے۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad, as quoted in Targheeb wat Tarheeb (Vol.4 Pg.345)."]]},{"b":[["n",[["حضرت ابوالحسنؒ","b"],[" (بنو نوفل کے آزاد کردہ غلام) کہتے ہیں کہ جب سورت شعراء نازل ہوئی تو حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ اور حضرت حسان بن ثابتؓ روتے ہوئے حضورؐ کی خدمت میں حاضر ہوئے۔ حضورؐ یہ آیت پڑھ رہے تھے:",""]]],["q",[["وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلْغَاوُۥنَ  (سورۃ شعراء: ۲۲۴)","a"]]],["p",[["ترجمہ: \"اور شاعروں کی راہ تو بے راہ لوگ چلا کرتے ہیں۔\" پھر حضورؐ اس آیت پر پہنچے:",""]]],["q",[["إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ","a"]]],["p",[["ترجمہ: \"ہاں مگر جو لوگ ایمان لائے اور اچھے کام کیے۔\" تو آپؐ نے فرمایا تم ہو یہ لوگ۔ پھر پڑھا:",""]]],["q",[["وَذَكَرُوا۟ ٱللَّهَ كَثِيرًا","a"]]],["p",[["ترجمہ: \"اور انھوں نے (اپنے اشعار میں) کثرت سے ",""],["ٱللَّٰه","a"],[" کا ذکر کیا۔\" آپؐ نے فرمایا تم ہو یہ لوگ۔ پھر پڑھا:",""]]],["q",[["وَٱنتَصَرُوا۟ مِنۢ بَعْدِ مَا ظُلِمُوا۟  (سورۃ شعراء: ۲۲۴-۲۲۷)","a"]]],["p",[["ترجمہ: \"اور انھوں نے بعد اس کے کہ ان پر ظلم ہو چکا ہے (اس کا) بدلہ لیا۔\" پھر فرمایا تم ہو یہ لوگ۔",""],[" (3)","s"]]]],"f":[["(3)","Haakim (Vol.3 Pg.488)."]]},{"b":[["n",[["حضرت ابوصالحؒ","b"],[" کہتے ہیں جب حضرت ابوبکرؓ کے زمانے میں یمن والے آئے اور انھوں نے قرآن سنا تو رونے لگے۔ حضرت ابوبکرؓ نے (تواضعاً) فرمایا ہم بھی ایسے تھے، پھر دل سخت ہو گئے۔ ابونعیم صاحب کتاب کہتے ہیں دل سخت ہو جانے کا مطلب یہ ہے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ کو پہچان کر دل طاقتور اور مطمئن ہو گئے۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilya, as quoted in Kanzul Ummaal (Vol.1 Pg.224)."]]}]},"52":{"lead":[],"stories":[{"b":[["n",[["حضرت ابزی خزاعی ابوعبدالرحمنؓ","b"],[" فرماتے ہیں کہ ایک دن حضورؐ نے بیان فرمایا اور مسلمانوں کی چند جماعتوں کی خوب تعریف کی، پھر آپؐ نے فرمایا کیا بات ہے کچھ لوگ ایسے ہیں جو اپنے پڑوسیوں میں دین کی سمجھ پیدا کرتے ہیں اور نہ ان کو سکھاتے ہیں اور نہ انہیں سمجھدار بناتے ہیں اور نہ ان کو بھلائی کا حکم دیتے ہیں اور نہ انہیں برائی سے روکتے ہیں۔ اور کیا بات ہے کچھ لوگ ایسے ہیں جو اپنے پڑوسیوں سے دین کی سمجھ حاصل نہیں کرتے اور ان سے سیکھتے نہیں اور سمجھ و عقل کی باتیں حاصل نہیں کرتے؟ ",""],["ٱللَّٰه","a"],[" کی قسم! یا تو یہ لوگ اپنے پڑوسیوں کو سکھانے لگ جائیں اور انہیں سمجھدار بنانے لگ جائیں اور ان میں دین کی سمجھ پیدا کرنے لگ جائیں اور انہیں بھلائی کا حکم دینے اور برائی سے روکنے لگ جائیں اور دوسرے لوگ اپنے پڑوسیوں سے سیکھنے لگ جائیں اور ان سے سمجھ و عقل کی باتیں حاصل کرنے لگ جائیں اور دین کی سمجھ حاصل کرنے لگ جائیں ورنہ میں انہیں اس دنیا میں جلد سزا دوں گا۔ پھر منبر سے نیچے تشریف لائے اور اپنے گھر تشریف لے گئے۔ لوگ ایک دوسرے سے کہنے لگے کہ کیا خیال ہے حضورؐ نے کن لوگوں کی طرف اشارہ فرمایا ہے؟ کچھ لوگوں نے کہا ہمارے خیال میں تو قبیلہ اشعر کے لوگوں کی طرف اشارہ فرمایا ہے کیونکہ وہ خود دین کی سمجھ رکھتے ہیں اور ان کے کچھ پڑوسی ہیں جو چشموں پر زندگی گزارنے والے، دیہاتی اور اجڈ لوگ ہیں۔ جب یہ خبر اشعری لوگوں تک پہنچی تو انھوں نے حضورؐ کی خدمت میں آ کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ نے بہت سے لوگوں کی تو تعریف فرمائی لیکن ہمارے بارے میں آپؐ نے کچھ نہیں فرمایا ہے، تو ہماری کیا خامی ہے؟ حضورؐ نے فرمایا لوگوں کو چاہیے کہ وہ اپنے پڑوسیوں کو سکھائیں، ان میں دین کی سمجھ پیدا کریں اور انہیں سمجھدار بنائیں اور انہیں نیکی کا حکم کریں اور انہیں برائی سے روکیں اور اسی طرح دوسرے لوگوں کو چاہیے کہ وہ اپنے پڑوسیوں سے سیکھیں اور ان سے سمجھ و عقل کی باتیں حاصل کریں اور دین کی سمجھ حاصل کریں، ورنہ میں ان سب کو دنیا ہی میں جلد سزا دوں گا۔ ان اشعری لوگوں نے عرض کیا کیا دوسروں کی غلطی پر ہم پکڑے جائیں گے؟ حضورؐ نے اپنی وہی بات دوبارہ ارشاد فرمائی تو انھوں نے پھر عرض کیا کیا ہم دوسروں کی غلطی پر پکڑے جائیں گے؟ حضورؐ نے پھر وہی ارشاد فرمایا تو انھوں نے عرض کیا ہمیں ایک سال کی مہلت دے دیں۔ چنانچہ حضورؐ نے انہیں ایک سال کی مہلت دی تا کہ وہ اپنے پڑوسیوں کو سکھائیں، ان میں دین کی سمجھ پیدا کریں اور انہیں سمجھدار بنائیں۔ پھر حضورؐ نے یہ آیت تلاوت فرمائی:",""]]],["q",[["لُعِنَ ٱلَّذِينَ كَفَرُوا۟ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبْنِ مَرْيَمَ ۚ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ ۝ كَانُوا۟ لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ ۚ لَبِئْسَ مَا كَانُوا۟ يَفْعَلُونَ  (سورۃ مائدہ: ۷۸-۷۹)","a"]]],["p",[["ترجمہ: \"بنی اسرائیل میں جو لوگ کافر تھے ان پر لعنت کی گئی تھی داؤد اور عیسیٰ بن مریم کی زبان سے۔ یہ لعنت اس سبب سے ہوئی کہ انھوں نے حکم کی مخالفت کی اور حد سے نکل گئے۔ جو برا کام انھوں نے کر رکھا تھا اس سے باز نہ آتے تھے، واقعی ان کا فعل بے شک برا تھا۔\"",""],[" (1)","s"]]]],"f":[["(1)","Ibn Raahway, Bukhaari in his Wahdaan, Ibnus Sakan, Ibn Mandah, Tabraani, Abu Nu'aym, Ibn Asaakir, Baawardi and Ibn Mardway, as quoted in Kanzul Ummaal (Vol.2 Pg.139)."]]}]},"53":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن سلمہؒ","b"],[" کہتے ہیں کہ ایک آدمی حضرت معاذؓ کے پاس آیا اور رونے لگا۔ حضرت معاذؓ نے فرمایا کیوں روتے ہو؟ اس آدمی نے کہا نہ تو میں اس وجہ سے روتا ہوں کہ میرے اور آپ کے درمیان کوئی رشتہ داری ہے اور نہ اس وجہ سے روتا ہوں کہ مجھے آپ سے کچھ دنیا ملا کرتی تھی (جو آپ کے انتقال کے بعد مجھے نہیں ملے گی) بلکہ اس وجہ سے روتا ہوں کہ میں آپ سے علم حاصل کیا کرتا تھا اور اب مجھے ڈر ہے کہ یہ علم حاصل کرنے کا سلسلہ ختم ہو جائے گا۔ حضرت معاذؓ نے فرمایا مت رو کیونکہ جو بھی علم اور ایمان حاصل کرنا چاہے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے ضرور عطا فرمائے گا جیسے کہ حضرت ابراہیم علیہ السلام کو عطا فرمایا تھا، حالانکہ اس وقت علم اور ایمان نہ تھا۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilya (Vol.1 Pg.234)."]]},{"b":[["n",[["حضرت یزید بن عمیرہؒ","b"],[" کہتے ہیں کہ جب حضرت معاذؓ کی وفات کا وقت قریب آیا تو ان کے ارد گرد بیٹھے ہوئے لوگ رونے لگے۔ حضرت معاذؓ نے فرمایا کیوں رو رہے ہو؟ انھوں نے کہا ہم اس علم کی وجہ سے روتے ہیں جس کے حاصل کرنے کا سلسلہ آپ کے انتقال پر ٹوٹ جائے گا۔ حضرت معاذؓ نے فرمایا نہیں۔ علم و ایمان قیامت تک اپنی جگہ رہیں گے، جو ان دونوں کو تلاش کرے گا وہ انہیں قرآن و سنت رسول میں سے ضرور پا لے گا (چونکہ قرآن مجید معیار ہے اس لیے) ہر کلام کو قرآن پر پیش کرو اور قرآن کو کسی کلام پر پیش مت کرو اور حضرت عمرؓ، حضرت عثمانؓ اور حضرت علیؓ سے علم حاصل کرو اور اگر یہ حضرات نہ ملیں تو پھر ان چار سے حاصل کرو: حضرت عویمر (ابوالدرداءؓ)، حضرت ابن مسعودؓ، حضرت سلمانؓ اور حضرت ابن سلامؓ۔ یہ ابن سلام وہی ہیں جو یہودی تھے پھر مسلمان ہو گئے، کیونکہ میں نے حضورؐ سے سنا ہے کہ یہ جنت میں بلا حساب جانے والے دس آدمیوں میں سے ہیں۔ اور عالم کی لغزش سے بچو اور جو بھی حق بات لے کر آئے اسے قبول کر لو اور جو غلط بات لے کر آئے اسے قبول نہ کرو چاہے وہ کوئی بھی ہو۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Asaakir and Sayf, as quoted in Kanzul Ummaal (Vol.7 Pg.87)."]]},{"b":[["n",[["حضرت یزید بن عمیرہؒ","b"],[" کہتے ہیں جب حضرت معاذ بن جبلؓ کا مرض الوفات شروع ہوا تو بھی وہ بے ہوش ہو جاتے تھے اور کبھی انہیں افاقہ ہو جاتا تھا۔ ایک دفعہ تو ایسی بے ہوشی طاری ہوئی کہ ہم سمجھے کہ ان کا انتقال ہو گیا ہے، پھر انہیں افاقہ ہوا تو میں ان کے سامنے بیٹھا ہوا رو رہا تھا۔ انھوں نے فرمایا کیوں رو رہے ہو؟ میں نے کہا میں نہ تو اس وجہ سے رو رہا ہوں کہ مجھے آپ سے کوئی دنیا ملا کرتی تھی جو آپ کے بعد مجھے نہیں ملا کرے گی اور نہ اس وجہ سے رو رہا ہوں کہ میرے اور آپ کے درمیان کوئی رشتہ داری ہے، بلکہ اس وجہ سے رو رہا ہوں کہ آپ سے علم کی باتیں اور صحیح فیصلے سنا کرتا تھا اور وہ سب اب جاتا رہے گا۔ حضرت معاذؓ نے فرمایا مت رو کیونکہ علم اور ایمان اپنی جگہ رہیں گے، جو انہیں تلاش کرے گا وہ انہیں ضرور پا لے گا۔ لہٰذا علم کو وہاں تلاش کرو جہاں حضرت ابراہیم علیہ السلام نے تلاش کیا تھا کیونکہ وہ جانتے نہیں تھے تو انھوں نے ",""],["ٱللَّٰه","a"],[" تعالیٰ سے سوال کیا تھا جیسے کہ قرآن میں ہے:",""]]],["q",[["إِنِّى ذَاهِبٌ إِلَىٰ رَبِّى سَيَهْدِينِ  (سورۃ الصافات: ۹۹)","a"]]],["p",[["ترجمہ: \"میں تو اپنے رب کی طرف چلا جاتا ہوں وہ مجھ کو (اچھی جگہ) پہنچا ہی دے گا۔\" میرے بعد ان چار آدمیوں میں سے علم حاصل کرنا، اگر ان میں سے کسی سے نہ ملے تو پھر ممتاز اور عمدہ لوگوں سے علم کے بارے میں پوچھنا۔ وہ چار یہ ہیں: حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ، حضرت عبد",""],["ٱللَّٰه","a"],[" بن سلامؓ، حضرت سلمانؓ اور حضرت عویمر ابوالدرداءؓ۔ اور حکیم آدمی کی لغزش سے اور منافق کے فیصلے سے بچ کر رہنا۔ میں نے پوچھا مجھے کس طرح حکیم آدمی کی لغزش کا پتہ چل سکتا ہے؟ حضرت معاذؓ نے فرمایا وہ گمراہی کا کلمہ شیطان کسی آدمی کی زبان پر اس طرح جاری کر دیتا ہے کہ وہ بے سوچے سمجھے فوراً بول دیتا ہے اور منافق بھی کبھی حق بات کہہ دیتا ہے، لہٰذا علم جہاں سے بھی آئے تم اسے لے لو کیونکہ حق بات میں نور ہوتا ہے اور جن باتوں کا حق اور باطل ہونا واضح نہ ہو ان سے بچو۔",""],[" (3)","s"]]]],"f":[["(3)","Haakim (Vol.4 Pg.466)."]]},{"b":[["n",[["حضرت عمرو بن میمونؒ","b"],[" کہتے ہیں کہ ہم لوگ یمن میں رہا کرتے تھے۔ وہاں حضرت معاذ بن جبلؓ آئے اور فرمایا اے یمن والو! اسلام لے آؤ سلامتی پا لو گے۔ میں ",""],["ٱللَّٰه","a"],[" کے رسولؐ کی طرف سے تمہاری طرف قاصد بن کر آیا ہوں۔ حضرت عمروؒ کہتے ہیں کہ میرے دل میں ان کی محبت ایسی بیٹھی کہ میں ان کے انتقال تک ان سے جدا نہیں ہوا، ان کے ساتھ ہی رہا۔ جب ان کے انتقال کا وقت آیا تو میں رونے لگا۔ حضرت معاذؓ نے فرمایا کیوں روتے ہو؟ میں نے کہا اس علم کی وجہ سے رو رہا ہوں جو آپ کے ساتھ چلا جائے گا۔ حضرت معاذؓ نے فرمایا نہیں، علم اور ایمان قیامت تک دنیا میں رہے گا۔ آگے اور حدیث ذکر کی ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.7 Pg.87)."]]}]},"54":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں میں نے اپنی زندگی کا بڑا عرصہ اس طرح گزارا ہے کہ ہم میں سے ہر ایک قرآن سے پہلے ایمان سیکھتا تھا اور جب بھی کوئی سورت حضرت محمدؐ پر نازل ہوتی تھی ہر ایک اس کے حلال و حرام ایسے سیکھتا تھا جیسے تم قرآن کو سیکھتے ہو اور جہاں وقف کرنا مناسب ہوتا تھا اس کو بھی سیکھتا تھا۔ پھر اب میں ایسے لوگوں کو دیکھ رہا ہوں جو ایمان سے پہلے قرآن حاصل کر لیتے ہیں اور سورت فاتحہ شروع سے آخر تک ساری پڑھ لیتے ہیں اور انہیں پتہ نہیں چلتا کہ سورت فاتحہ کن کاموں کا حکم دے رہی ہے اور کن کاموں سے روک رہی ہے اور اس سورت میں کون سی آیت ایسی ہے جہاں جا کر رک جانا چاہیے، اور سورت فاتحہ کو ردی کھجور کی طرح بکھیر دیتا ہے یعنی جلدی جلدی پڑھتا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.165)."]]},{"b":[["n",[["حضرت جندب بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرمایا کرتے تھے ہم نوعمر لڑکے حضورؐ کے ساتھ ہوا کرتے تھے، پہلے ہم نے ایمان سیکھا پھر ہم نے قرآن سیکھا جس سے ہمارا ایمان اور زیادہ ہو گیا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Maajah (Pg.11)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ جب حضورؐ کے زمانے میں ایک آیت یا چند آیتیں یا پوری سورت نازل ہوتی تو اس سے مسلمانوں کا ایمان اور خشوع اور بڑھ جاتا اور وہ آیت یا سورت جس کام سے روکتی سارے مسلمان اس سے رک جاتے۔",""],[" (3)","s"]]]],"f":[["(3)","Askari and Ibn Mardway, as quoted in Kanzul Ummaal (Vol.1 Pg.232)."]]},{"b":[["n",[["حضرت ابوعبدالرحمن سلمیؒ","b"],[" کہتے ہیں کہ نبی کریمؐ کے جو صحابہؓ ہمیں پڑھاتے تھے انھوں نے ہمیں بتایا کہ وہ حضورؐ سے دس آیتیں پڑھتے اور اگلی دس آیتیں تب شروع کرتے جب پہلی دس آیتوں میں جو علم و عمل ہے اسے اچھی طرح جان لیتے۔ چنانچہ یوں ہم علم و عمل دونوں سیکھتے۔ ",""],["حضرت ابوعبدالرحمنؒ","b"],[" سے اسی جیسی دوسری روایت میں یہ مضمون بھی منقول ہے کہ ہم قرآن کو اور اس پر عمل کو سیکھتے تھے اور ہمارے بعد ایسے لوگ قرآن کے وارث بنیں گے جو پانی کی طرح سارا قرآن پی جائیں گے لیکن یہ قرآن ان کی ہنسلی کی ہڈی سے نیچے نہیں اترے گا اور حلق کی طرف اشارہ کر کے فرمایا بلکہ اس سے بھی نیچے نہیں جائے گا۔",""],[" (4)","s"],[" (5)","s"]]]],"f":[["(4)","Ahmad (Vol.5 Pg.410). Haythami (Vol.1 Pg.232) has commented on the chain of narrators."],["(5)","Ibn Sa'd (Vol.6 Pg.172)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ جب ہم نبی کریمؐ سے قرآن کی دس آیتیں سیکھتے تو بعد والی آیتیں تب سیکھتے جب پہلی آیتوں میں جو کچھ ہوتا اسے اچھی طرح سیکھ لیتے۔ حضرت شریکؒ راوی سے پوچھا گیا اس سے مراد یہ ہے کہ پہلی آیتوں میں جو عمل ہوتا اسے سیکھ لیتے؟ حضرت شریکؒ نے کہا جی ہاں۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.232)."]]}]},"55":{"lead":[],"stories":[{"b":[["n",[["حضرت سلمانؓ نے ",""],["حضرت حذیفہؓ","b"],[" سے فرمایا اے قبیلہ بنو عبس والے! علم تو بہت زیادہ ہے اور عمر بڑی تھوڑی ہے، لہٰذا دین پر عمل کرنے کے لیے جتنے علم کی ضرورت پڑتی جائے اتنا علم حاصل کرتے جاؤ اور جس کی ضرورت نہیں اسے چھوڑ دو اور اس کے حاصل کرنے کی مشقت میں نہ پڑو۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilya (Vol.1 Pg.189)."]]},{"b":[["n",[["حضرت ابوالبختریؒ","b"],[" کہتے ہیں کہ قبیلہ بنو عبس کا ایک آدمی حضرت سلمانؓ کے ساتھ سفر میں تھا، اس آدمی نے دریائے دجلہ سے پانی پیا۔ حضرت سلمانؓ نے اس سے فرمایا اور پی لو۔ اس نے کہا نہیں، میں سیر ہو چکا ہوں۔ حضرت سلمانؓ نے فرمایا تمہارا کیا خیال ہے تمہارے پانی پینے سے دریائے دجلہ میں کوئی کمی آئی ہے؟ اس آدمی نے کہا میں نے جتنا پانی پیا ہے اس سے اس دریا میں کیا کمی آئے گی؟ حضرت سلمانؓ نے فرمایا علم بھی اسی دریا کی طرح ہے، لہٰذا جتنا علم تمہیں فائدہ دے اتنا حاصل کر لو۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilya (Vol.1 Pg.188)."]]},{"b":[["n",[["حضرت محمد بن ابی قبیلہؒ","b"],[" کہتے ہیں کہ ایک آدمی نے حضرت ابن عمرؓ کو خط لکھ کر علم کے بارے میں پوچھا۔ حضرت ابن عمرؓ نے اسے یہ جواب لکھا کہ تم نے مجھے خط لکھ کر علم کے بارے میں پوچھا ہے۔ علم تو بہت زیادہ ہے، میں سارا لکھ کر تمہیں نہیں بھیج سکتا۔ البتہ تم اس بات کی پوری کوشش کرو کہ تم ",""],["ٱللَّٰه","a"],[" سے ملاقات اس حال میں ہو کہ تمہاری زبان مسلمانوں کی آبرو سے رکی ہوئی ہو اور تمہاری کمر ان کے ناحق خون کا بوجھ نہ ہو اور تمہارا پیٹ ان کے مال سے خالی ہو اور تم مسلمانوں کی جماعت سے چمٹے ہوئے ہو۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.5 Pg.230)."]]}]},"56":{"lead":[],"stories":[{"b":[["n",[["حضرت ابورفاعہؓ","b"],[" فرماتے ہیں کہ میں حضورؐ کی خدمت میں پہنچا تو آپؐ بیان فرما رہے تھے، میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ایک اجنبی پردیسی آدمی اپنے دین کے بارے میں پوچھنے آیا ہے، جسے کچھ معلوم نہیں ہے کہ اس کا دین کیا ہے؟ حضورؐ بیان چھوڑ کر میرے پاس تشریف لائے، پھر ایک کرسی لائی گئی۔ میرا خیال ہے کہ اس کے پائے لوہے کے تھے اور اس پر حضورؐ بیٹھ کر مجھے ",""],["ٱللَّٰه","a"],[" کا علم سکھانے لگے، پھر منبر پر واپس جا کر اپنا بیان پورا فرمایا۔",""],[" (1)","s"]]]],"f":[["(1)","Muslim (Vol.1 Pg.287). Bukhaari has reported a similar narration in his Adab (Pg.171), as have Nasa'ee in his Zeenah, Tabraani and Abu Nu'aym, as quoted in Kanzul Ummaal (Vol.5 Pg.242)."]]},{"b":[["n",[["حضرت جریرؓ","b"],[" فرماتے ہیں کہ ایک دیہاتی آدمی نبی کریمؐ کی خدمت میں آیا اور عرض کیا مجھے اسلام سکھا دیں۔ حضورؐ نے فرمایا تم اس بات کی گواہی دو کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں اور محمدؐ اس کے بندے اور رسول ہیں اور نماز قائم کرو اور زکوٰۃ ادا کرو اور رمضان کے روزے رکھو اور حج بیت ",""],["ٱللَّٰه","a"],[" کرو اور لوگوں کے لیے وہی پسند کرو جو تم اپنے لیے پسند کرتے ہو اور ان کے لیے وہی چیز ناپسند کرو جو اپنے لیے ناپسند کرتے ہو۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.1 Pg.70)."]]},{"b":[["n",[["حضرت محمد بن ثابتؒ","b"],[" کہتے ہیں حضرت فروہ بن مسیک مرادیؓ کندہ کے بادشاہوں کو چھوڑ کر نبی کریمؐ کا اتباع کرنے کے لیے اپنی قوم کے نمائندے بن کر حضورؐ کی خدمت میں آئے اور حضرت سعد بن عبادہؓ کے مہمان بنے اور وہ قرآن، اسلام کے فرائض اور شرعی احکام سیکھتے تھے۔ آگے اور حدیث ذکر کی ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Sa'd (Vol.1 Pg.327)."]]},{"b":[["n",[["حضرت ضباعہ بنت زبیر بن عبدالمطلبؓ","b"],[" فرماتی ہیں کہ یمن سے قبیلہ بہراء کا وفد آیا جو کہ تیرہ آدمی تھے، وہ اپنے اونٹوں کی نکیل پکڑ کر چلتے رہے یہاں تک کہ بنو جدیلہ قبیلہ کے محلہ میں حضرت مقداد بن عمروؓ کے دروازے پر پہنچ گئے۔ حضرت مقدادؓ نے باہر آ کر انہیں خوش آمدید کہا اور انہیں اپنے گھر کے ایک حصے میں ٹھہرایا۔ وہ لوگ حضورؐ کی خدمت میں حاضر ہو کر مسلمان ہوئے اور فرائض سیکھے اور چند دن قیام فرمایا اور پھر حضورؐ کی خدمت میں الوداع کہنے کے لیے حاضر ہوئے۔ حضورؐ نے صحابہؓ کو حکم دیا کہ انہیں اب جاتے ہوئے ہدیے دیے جائیں، پھر وہ لوگ اپنے علاقے کو واپس چلے گئے۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Sa'd (Vol.1 Pg.331)."]]},{"b":[["n",[["حضرت ابن سیرینؒ","b"],[" کہتے ہیں کہ حضرت ابوبکرؓ اور حضرت عمرؓ لوگوں کو اسلام سکھایا کرتے تھے اور یہ فرمایا کرتے تھے کہ ",""],["ٱللَّٰه","a"],[" کی عبادت کرو اور اس کے ساتھ کسی چیز کو شریک نہ کرو اور جو نماز ",""],["ٱللَّٰه","a"],[" نے تم پر فرض کی ہے اسے وقت پر ادا کرو کیونکہ نماز میں کوتاہی کرنا ہلاکت ہے اور دل کی خوشی کے ساتھ زکوٰۃ ادا کرو اور رمضان کے روزے رکھو اور جسے امیر بنایا جائے اس کی بات سنو اور مانو۔",""],[" (5)","s"]]]],"f":[["(5)","Abdur Razzaaq, Ibn Abi Shaybah, Ibn Jareer and Rustah in his Imaan, as quoted in Kanzul Ummaal (Vol.1 Pg.69)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" فرماتے ہیں کہ ایک دیہاتی حضرت عمرؓ کے پاس آیا اور عرض کیا اے امیر المومنین! مجھے دین سکھا دیں۔ حضرت عمرؓ نے فرمایا تم اس بات کی گواہی دو کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں، حضرت محمدؐ ",""],["ٱللَّٰه","a"],[" کے رسول ہیں، نماز قائم کرو، زکوٰۃ ادا کرو، حج بیت ",""],["ٱللَّٰه","a"],[" کرو، رمضان کے روزے رکھو، لوگوں کے ظاہری اعمال دیکھو، ان کے پوشیدہ اور چھپے ہوئے اعمال کو مت تلاش کرو اور ہر اس کام سے بچو جس کو کرنے سے شرم آتی ہو (اور یہ تمام کام بالکل حق اور سچ ہیں، اس لیے) جب ",""],["ٱللَّٰه","a"],[" سے ملاقات ہو تو کہہ دینا کہ عمرؓ نے مجھے ان کاموں کا حکم دیا تھا۔",""],[" (6)","s"]]]],"f":[["(6)","Bayhaqi and Isfahaani in his Hujjah."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں کہ ایک دیہاتی آدمی حضرت عمرؓ کے پاس آیا اور عرض کیا اے امیر المومنین! مجھے دین سکھائیں۔ اس کے بعد پچھلی حدیث جیسا مضمون ذکر کیا اور آخر میں یہ مضمون بھی ہے کہ پھر حضرت عمرؓ نے فرمایا اے ",""],["ٱللَّٰه","a"],[" کے بندے! ان تمام کاموں کو مضبوطی سے تھام لو اور جب ",""],["ٱللَّٰه","a"],[" سے ملو تو جو دل میں آئے کہہ دینا۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Adi and Bayhaqi, as quoted in Kanzul Ummaal (Vol.1 Pg.70)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ کے پاس ایک آدمی آیا اور اس نے کہا اے امیر المومنین! میں دیہات کا رہنے والا ہوں اور مجھے بہت کام ہوتے ہیں، اس لیے مجھے ایسے عمل بتائیں جن پر پوری طرح اعتماد کر سکوں اور جن کے ذریعے میں منزل مقصود یعنی ",""],["ٱللَّٰه","a"],[" تک یا جنت تک پہنچ سکوں۔ حضرت عمرؓ نے فرمایا اچھی طرح سمجھ لو اور اپنا ہاتھ مجھے دکھاؤ۔ اس نے اپنا ہاتھ حضرت عمرؓ کے ہاتھ میں دے دیا۔ حضرت عمرؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی عبادت کرو اور اس کے ساتھ کسی چیز کو شریک نہ کرو، نماز قائم کرو، فرض زکوٰۃ ادا کرو، حج اور عمرہ کرو اور (امیر کی) فرمانبرداری کرو، لوگوں کے ظاہری اعمال اور حالات دیکھو، ان کے پوشیدہ اور چھپے ہوئے اعمال اور حالات مت تلاش کرو، ہر وہ کام کرو کہ جس کی خبر لوگوں میں پھیل جائے تو تمہیں نہ شرم اٹھانی پڑے اور نہ رسوائی برداشت کرنی پڑے اور ہر اس کام سے بچو کہ جس کی خبر لوگوں میں پھیل جائے تو تمہیں شرم بھی اٹھانی پڑے اور رسوا بھی ہونا پڑے۔ اس آدمی نے کہا اے امیر المومنین! میں ان تمام باتوں پر عمل کروں گا اور جب اپنے رب سے ملوں گا تو کہہ دوں گا کہ عمر بن خطاب نے مجھے یہ کام بتائے تھے۔ حضرت عمرؓ نے فرمایا ان تمام کاموں کو لے جاؤ اور جب اپنے رب سے ملو تو جو دل چاہے کہہ دینا۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.208)."]]}]},"57":{"lead":[],"stories":[{"b":[["n",[["حضرت ابو مالک اشجعیؒ","b"],[" کے والد فرماتے ہیں کہ جب کوئی آدمی مسلمان ہوتا تو حضورؐ اسے سب سے پہلے نماز سکھاتے تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani and Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.293)."]]},{"b":[["n",[["حضرت حکم بن عمیرؒ","b"],[" کہتے ہیں کہ حضورؐ ہمیں نماز سکھاتے تھے اور فرماتے تھے کہ جب تم نماز کے لیے کھڑے ہونے لگو تو پہلے ",""],["ٱللَّٰه","a"],[" اکبر کہو اور اپنے ہاتھوں کو اٹھاؤ لیکن کانوں سے اوپر نہ لے جاؤ اور پھر یہ پڑھو:",""]]],["q",[["سُبْحَانَكَ ٱللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ ٱسْمُكَ وَتَعَالَىٰ جَدُّكَ وَلَآ إِلَٰهَ غَيْرُكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تو پاک ہے، ہم تیری تعریف کرتے ہیں، تیرا نام برکت والا ہے اور تیری بزرگی بلند ہے اور تیرے سوا کوئی معبود نہیں ہے۔\"",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym, as quoted in Kanzul Ummaal (Vol.4 Pg.203)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ ہمیں حضرت ابوبکرؓ منبر پر اس طرح التحیات سکھاتے تھے جیسے کہ استاد مکتب میں بچوں کو سکھاتا ہے۔ ",""],["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ حضرت عمر بن خطابؓ نے میرا ہاتھ پکڑا اور مجھے التحیات سکھائی اور ارشاد فرمایا کہ حضورؐ نے بھی ان کا ہاتھ پکڑ کر انہیں التحیات سکھائی تھی:",""]]],["q",[["ٱلتَّحِيَّاتُ لِلَّهِ، ٱلصَّلَوَاتُ ٱلطَّيِّبَاتُ لِلَّهِ","a"]]],["p",[["(ٱلتَّحِيَّاتُ لِلَّهِ ... سے لے کر آخر تک۔)",""],[" (3)","s"]]]],"f":[["(3)","Musaddad and Tahaawi, as quoted in Kanzul Ummaal (Vol.4 Pg.217)."]]},{"b":[["n",[["حضرت عبدالرحمن بن عبدالقاریؒ","b"],[" کہتے ہیں کہ انھوں نے حضرت عمر بن خطابؓ کو منبر پر لوگوں کو التحیات سکھاتے ہوئے سنا۔ فرما رہے تھے اے لوگو! کہو ٱلتَّحِيَّاتُ لِلَّهِ سے لے کر آخر تک۔",""],[" (4)","s"]]]],"f":[["(4)","Maalik, Shaafi'ee, Tahaawi, Abdur Razzaaq and others."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ حضورؐ ہمیں التحیات اس طرح سکھاتے تھے جیسے ہمیں قرآن کی کوئی سورت سکھاتے تھے۔ ",""],["حضرت ابن مسعودؓ","b"],[" سے بھی ایسی ہی حدیث منقول ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abi Shaybah. Another similar report has been narrated from Hadhrat Abdullaah bin Mas'ood."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں حضورؐ نے مجھے التحیات اس طرح سکھائی جس طرح مجھے آپؐ قرآن کی کوئی سورت سکھایا کرتے تھے اور اس وقت میرا ہاتھ حضورؐ کے ہاتھوں میں تھا، پھر اس کے بعد التحیات کا ذکر کیا۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abi Shaybah."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ حضورؐ ہمیں سورتوں کا شروع والا حصہ اور قرآن سکھاتے تھے، چنانچہ ہمیں حضورؐ نے نماز کا خطبہ اور نکاح وغیرہ کسی ضرورت کا خطبہ بھی سکھایا، پھر التحیات کا ذکر کیا۔",""],[" (7)","s"]]]],"f":[["(7)","Askari in his Amthaal."]]},{"b":[["n",[["حضرت اسودؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ ہمیں التحیات اس طرح سکھاتے تھے جس طرح ہمیں قرآن کی کوئی سورت سکھاتے تھے، اس میں ہماری الف اور واؤ کی غلطی بھی پکڑتے تھے۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Najjaar. The above narrations have been quoted in Kanzul Ummaal (Vol.4 Pg.218-219)."]]},{"b":[["n",[["حضرت زید بن وہبؒ","b"],[" فرماتے ہیں کہ ایک دفعہ حضرت حذیفہؓ مسجد میں تشریف لے گئے تو دیکھا کہ ایک آدمی نماز پڑھ رہا ہے لیکن رکوع سجدہ پورا نہیں کر رہا۔ جب وہ نماز سے فارغ ہوا تو حضرت حذیفہؓ نے اس سے پوچھا کتنے عرصہ سے تم ایسی نماز پڑھ رہے ہو؟ اس نے کہا چالیس سال سے۔ حضرت حذیفہؓ نے فرمایا تم نے چالیس سال سے ٹھیک نماز نہیں پڑھی اور اگر تم ایسی نماز پڑھتے ہوئے مر گئے تو تم اس حالت پر نہیں مرو گے جس پر حضرت محمدؐ پیدا کیے گئے تھے۔ پھر اس کی طرف متوجہ ہو کر اسے سکھانے لگے۔ پھر فرمایا آدمی کو چاہیے کہ وہ نماز میں قیام مختصر کرے لیکن رکوع سجدہ پورا کرے۔",""],[" (9)","s"]]]],"f":[["(9)","Abdur Razzaaq, Ibn Abi Shaybah, Bukhaari and Nasa'ee, as quoted in Kanzul Ummaal (Vol.4 Pg.230)."]]}]},"58":{"lead":[],"stories":[{"b":[["n",[["حضرت علی بن ابی طالبؓ","b"],[" فرماتے ہیں کہ نبی کریمؐ نے مجھ سے فرمایا میں تمہیں پانچ ہزار بکریاں دے دوں یا ایسے پانچ کلمات سکھا دوں جن سے تمہارا دین اور دنیا دونوں ٹھیک ہو جائیں؟ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! پانچ ہزار بکریاں تو بہت زیادہ ہیں لیکن آپؐ مجھے وہ کلمات ہی سکھا دیں۔ حضورؐ نے فرمایا کہو:",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لِي ذَنْبِي، وَوَسِّعْ لِي خُلُقِي، وَطَيِّبْ لِي كَسْبِي، وَقَنِّعْنِي بِمَا رَزَقْتَنِي، وَلَا تُذْهِبْ قَلْبِي إِلَىٰ شَيْءٍ صَرَفْتَهُ عَنِّي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میرے گناہ معاف فرما اور میرے اخلاق وسیع فرما اور میری کمائی کو پاک فرما اور جو روزی تو مجھے عطا فرمائے اس پر مجھے قناعت نصیب فرما اور جو چیز تو مجھ سے ہٹا لے اس کی طلب مجھ میں باقی نہ رہنے دے۔\"",""],[" (1)","s"]]]],"f":[["(1)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.4 Pg.230)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن جعفرؓ","b"],[" اپنی بیٹیوں کو یہ کلمات سکھاتے اور انہیں ان کے پڑھنے کی تاکید کرتے اور فرماتے میں نے یہ کلمات حضرت علیؓ سے سیکھے ہیں اور حضرت علیؓ نے فرمایا تھا کہ جب حضورؐ کو کوئی پریشانی یا مشکل کام پیش آتا تو آپؐ یہ کلمات پڑھتے:",""]]],["q",[["لَا إِلَٰهَ إِلَّا ٱللَّهُ ٱلْحَلِيمُ ٱلْكَرِيمُ، سُبْحَانَهُ، تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ، وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَالَمِينَ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں جو بڑا بردبار، بڑے کرم والا ہے۔ وہ تمام عیبوں سے پاک ہے۔ ",""],["ٱللَّٰه","a"],[" برکت والا ہے جو بڑے عرش کا رب ہے اور تمام تعریفیں ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جو تمام جہانوں کا رب ہے۔\"",""],[" (2)","s"]]]],"f":[["(2)","Nasa'ee and Abu Nu'aym, as quoted in Kanzul Ummaal (Vol.1 Pg.298)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن جعفرؓ","b"],[" فرماتے ہیں کہ حضرت علیؓ نے مجھ سے فرمایا اے میرے بیٹے! میں تمہیں ایسے کلمات سکھاؤں گا جو میں نے حضورؐ سے سنے ہیں۔ موت کے وقت جو ان کلمات کو کہے گا وہ جنت میں ضرور داخل ہوگا:",""]]],["q",[["لَا إِلَٰهَ إِلَّا ٱللَّهُ ٱلْحَلِيمُ ٱلْكَرِيمُ (تین مرتبہ)، ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَالَمِينَ (تین مرتبہ)، تَبَارَكَ ٱلَّذِي بِيَدِهِ ٱلْمُلْكُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں جو بڑا بردبار، بڑے کرم والا ہے۔ (تین مرتبہ) تمام تعریفیں ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جو تمام جہانوں کا رب ہے۔ (تین مرتبہ) وہ ذات بابرکت ہے جس کے قبضے میں تمام بادشاہی ہے۔ وہ زندہ کرتا ہے اور مارتا ہے اور وہ ہر چیز پر قادر ہے۔\"",""],[" (3)","s"]]]],"f":[["(3)","Kharaa'iti in his Makaarimul Akhlaaq, as quoted in Kanzul Ummaal (Vol.8 Pg.111)."]]},{"b":[["n",[["حضرت سعد بن جنادہؓ","b"],[" فرماتے ہیں کہ طائف والوں میں سے سب سے پہلے نبی کریمؐ کی خدمت میں حاضر ہوا اور طائف کے جنوب میں واقع پہاڑی سلسلے کے بالائی حصہ سے صبح صبح چلا اور عصر کے وقت منی میں پہنچا پھر پہاڑ پر چڑھا اور اتر کر حضورؐ کی خدمت میں حاضر ہوا اور مسلمان ہوا۔ حضورؐ نے مجھے قُلْ هُوَ ٱللَّهُ أَحَدٌ اور إِذَا زُلْزِلَتِ سکھائی اور یہ کلمات بھی سکھائے: سُبْحَانَ ٱللَّهِ وَٱلْحَمْدُ لِلَّهِ وَلَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱللَّهُ أَكْبَرُ اور فرمایا یہی وہ نیک کلمات ہیں جو باقی رہنے والے ہیں۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.86)."]]},{"b":[["n",[["حضرت ابی بن کعبؓ","b"],[" فرماتے ہیں کہ حضرت محمدؐ ہمیں سکھاتے کہ صبح کو ہم یہ دعا پڑھیں:",""]]],["q",[["أَصْبَحْنَا عَلَىٰ فِطْرَةِ ٱلْإِسْلَامِ، وَكَلِمَةِ ٱلْإِخْلَاصِ، وَسُنَّةِ نَبِيِّنَا مُحَمَّدٍ ﷺ، وَمِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ","a"]]],["p",[["ترجمہ: \"ہم نے فطرت اسلام، کلمہ اخلاص، اپنے نبی حضرت محمدؐ کی سنت اور ابراہیم علیہ السلام کی ملت پر صبح کی، جو سب سے یکسو ہو کر ایک ",""],["ٱللَّٰه","a"],[" کے ہو گئے تھے اور وہ مشرکوں میں سے نہیں تھے۔\" اور شام کو بھی یہ دعا پڑھیں (صرف أَصْبَحْنَا کی جگہ أَمْسَيْنَا کہہ لیں)۔",""],[" (5)","s"]]]],"f":[["(5)","Abdullaah bin Ahmad in his Zawaa'id, as quoted in Kanzul Ummaal (Vol.1 Pg.294)."]]},{"b":[["n",[["حضرت سعدؓ","b"],[" فرماتے ہیں کہ حضورؐ ہمیں یہ کلمات اس طرح سکھاتے تھے جس طرح استاد بچوں کو لکھنا سکھاتا ہے:",""]]],["q",[["ٱللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ ٱلْبُخْلِ، وَأَعُوذُ بِكَ مِنَ ٱلْجُبْنِ، وَأَعُوذُ بِكَ أَنْ أُرَدَّ إِلَىٰ أَرْذَلِ ٱلْعُمُرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ ٱلدُّنْيَا وَعَذَابِ ٱلْقَبْرِ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں بخل سے تیری پناہ مانگتا ہوں اور بزدلی سے تیری پناہ مانگتا ہوں اور میں اس بات سے تیری پناہ مانگتا ہوں کہ مجھے ناکارہ عمر کی طرف پہنچا دیا جائے اور دنیا کے فتنوں سے اور عذاب قبر سے تیری پناہ مانگتا ہوں۔\"",""],[" (6)","s"]]]],"f":[["(6)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.1 Pg.307)."]]},{"b":[["n",[["حضرت حارث بن نوفلؓ","b"],[" فرماتے ہیں کہ نبی کریمؐ نے ہمیں مرجانے والے کے لیے یہ دعا سکھائی:",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لِإِخْوَانِنَا وَأَخَوَاتِنَا، وَأَصْلِحْ ذَاتَ بَيْنِنَا، وَأَلِّفْ بَيْنَ قُلُوبِنَا، ٱللَّهُمَّ هَٰذَا عَبْدُكَ فُلَانُ بْنُ فُلَانٍ، لَا نَعْلَمُ إِلَّا خَيْرًا، وَأَنْتَ أَعْلَمُ بِهِ مِنَّا، فَٱغْفِرْ لَنَا وَلَهُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ہمارے بھائیوں اور بہنوں کی مغفرت فرما اور ہمارے آپس کے تعلقات کو ٹھیک فرما اور ہمارے دلوں میں ایک دوسرے کی محبت پیدا فرما۔ اے ",""],["ٱللَّٰه","a"],["! یہ تیرا بندہ فلاں بن فلاں ہے، ہمیں تو یہی معلوم ہے کہ یہ بہت نیک تھا اور آپ اسے ہم سے زیادہ جانتے ہیں، تو آپ ہماری اور اس کی مغفرت فرما دیں۔\" اپنی جماعت میں میں سب سے چھوٹا تھا، میں نے عرض کیا اگر مجھے اس کی کوئی نیکی معلوم نہ ہو تو؟ حضورؐ نے فرمایا تو تم وہی کہو جو تمہیں معلوم ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Nu'aym, as quoted in Kanzul Ummaal (Vol.8 Pg.114)."]]},{"b":[["n",[["حضرت عبادہ بن صامتؓ","b"],[" فرماتے ہیں کہ جب رمضان شریف آتا تو حضورؐ ہمیں دعا کے طور پر یہ کلمات سکھاتے تھے:",""]]],["q",[["ٱللَّهُمَّ سَلِّمْنِي لِرَمَضَانَ، وَسَلِّمْ رَمَضَانَ لِي، وَسَلِّمْهُ لِي مُتَقَبَّلًا","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! مجھے رمضان کے لیے صحیح سالم رکھ اور رمضان کو میرے لیے صحیح سالم رکھ (یعنی چاند وقت پر نظر آئے، بادل وغیرہ نہ ہوں) اور پھر اسے قبول بھی فرما۔\"",""],[" (8)","s"]]]],"f":[["(8)","Tabraani in his Du'aa and Daylami, as quoted in Kanzul Ummaal (Vol.4 Pg.232)."]]},{"b":[["n",[["حضرت سلامہ کندیؒ","b"],[" کہتے ہیں حضرت علیؓ لوگوں کو نبی کریمؐ پر درود پڑھنے کے لیے یہ کلمات سکھاتے تھے:",""]]],["q",[["ٱللَّهُمَّ دَاحِيَ ٱلْمَدْحُوَّاتِ، وَبَارِئَ ٱلْمَسْمُوكَاتِ، وَجَبَّارَ ٱلْقُلُوبِ عَلَىٰ فِطْرَتِهَا شَقِيِّهَا وَسَعِيدِهَا، ٱجْعَلْ شَرَائِفَ صَلَوَاتِكَ، وَنَوَامِيَ بَرَكَاتِكَ، وَرَأْفَةَ تَحَنُّنِكَ، عَلَىٰ مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ، ٱلْخَاتِمِ لِمَا سَبَقَ، وَٱلْفَاتِحِ لِمَا أُغْلِقَ، وَٱلْمُعْلِنِ ٱلْحَقَّ بِٱلْحَقِّ، وَٱلدَّامِغِ لِجَيْشَاتِ ٱلْأَبَاطِيلِ، كَمَا حُمِّلَ فَٱضْطَلَعَ بِأَمْرِكَ بِطَاعَتِكَ، مُسْتَوْفِزًا فِي مَرْضَاتِكَ، غَيْرَ نَكِلٍ عَنْ قَدَمٍ، وَلَا وَاهٍ فِي عَزْمٍ، وَاعِيًا لِوَحْيِكَ، حَافِظًا لِعَهْدِكَ، مَاضِيًا عَلَىٰ نَفَاذِ أَمْرِكَ، حَتَّىٰ أَوْرَىٰ قَبَسًا لِقَابِسٍ، آلَاءَ ٱللَّهِ تَصِلُ بِأَهْلِهِ أَسْبَابَهُ، بِهِ هُدِيَتِ ٱلْقُلُوبُ بَعْدَ خَوْضَاتِ ٱلْفِتَنِ وَٱلْإِثْمِ، وَأَبْهَجَ مُوضِحَاتِ ٱلْأَعْلَامِ، وَمُنِيرَاتِ ٱلْإِسْلَامِ، وَنَائِرَاتِ ٱلْأَحْكَامِ، فَهُوَ أَمِينُكَ ٱلْمَأْمُونُ، وَخَازِنُ عِلْمِكَ ٱلْمَخْزُونِ، وَشَهِيدُكَ يَوْمَ ٱلدِّينِ، وَبَعِيثُكَ نِعْمَةً، وَرَسُولُكَ بِٱلْحَقِّ رَحْمَةً. ٱللَّهُمَّ ٱفْسَحْ لَهُ مَفْسَحًا فِي عَدْنِكَ، وَٱجْزِهِ مُضَاعَفَاتِ ٱلْخَيْرِ مِنْ فَضْلِكَ، مُهَنَّآتٍ غَيْرَ مُكَدَّرَاتٍ، مِنْ فَوْزِ ثَوَابِكَ ٱلْمَحْلُولِ، وَجَزِيلِ عَطَائِكَ ٱلْمَعْلُولِ. ٱللَّهُمَّ أَعْلِ عَلَىٰ بِنَاءِ ٱلنَّاسِ بِنَاءَهُ، وَأَكْرِمْ مَثْوَاهُ لَدَيْكَ وَنُزُلَهُ، وَأَتْمِمْ لَهُ نُورَهُ، وَٱجْزِهِ مِنِ ٱبْتِعَاثِكَ لَهُ مَقْبُولَ ٱلشَّهَادَةِ، مَرْضِيَّ ٱلْمَقَالَةِ، ذَا مَنْطِقٍ عَدْلٍ، وَخُطَّةٍ فَصْلٍ، وَحُجَّةٍ وَبُرْهَانٍ عَظِيمٍ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اے بچھی ہوئی زمینوں کے بچھانے والے! بلند آسمانوں کے پیدا کرنے والے! بدبخت اور نیک بخت دلوں کو ان کی فطرت پر پیدا کرنے والے! اپنی معظم رحمتیں، بڑھنے والی برکتیں اور اپنی خاص مہربانی اور شفقت حضرت محمدؐ پر نازل فرما جو کہ تیرے بندے اور رسول ہیں اور جو نبوتیں پہلے گزر چکی ہیں ان کے لیے مہر ہیں اور بند سعادتوں کو کھولنے والے ہیں اور صحیح طریقے سے حق کی مدد کرنے والے ہیں اور جس طرح انہیں ذمہ داری دی گئی اس طرح انھوں نے باطل کے لشکروں کو نیست و نابود کر دیا اور تیری اطاعت کے لیے تیرے حکم کو لے کر کھڑے ہو گئے اور تجھے خوش کرنے کے لیے ہر دم مستعد رہے۔ انھوں نے آگے بڑھنے میں بالکل سستی نہ کی اور نہ عزم و ارادہ میں کچھ کمزوری ظاہر کی، تیری وحی کو خوب یاد کیا اور تیرے عہد کی حفاظت کی اور تیرے ہر حکم کو نافذ کیا یہاں تک کہ روشنی لینے والوں کے لیے نور اسلام کا شعلہ روشن کر دیا۔ آپؐ ہی کے ذریعہ دلوں کو فتنوں اور گناہوں میں غوطے کھانے کے بعد ہدایت ملی اور آپؐ نے کھلی اور واضح نشانیوں کو، اسلام کے روشن دلائل کو اور منور احکام کو خوب اچھی طرح واضح کر دیا۔ وہ تیرے معصوم اور محفوظ امین ہیں اور تیرے علمی خزانے کے خزانچی اور محافظ ہیں اور قیامت کے دن تیرے گواہ ہیں، تو نے انہیں نعمت بنا کر بھیجا ہے اور وہ تیرے سچے رسول ہیں جو رحمت بن کر آئے ہیں۔ اے ",""],["ٱللَّٰه","a"],["! اپنی جنت عدن میں ان کو خوب کشادہ جگہ عطا فرما اور اپنے بار بار دیے جانے والے ثواب میں سے اور اپنی بڑی عطا کے خزانوں میں سے خوب بڑھا کر صاف ستھری جزا انہیں عطا فرما۔ اے ",""],["ٱللَّٰه","a"],["! ان کی عمارت کو تمام لوگوں کی عمارت سے اونچا فرما اور اپنے ہاں ان کے ٹھکانے اور مہمانی کو خوب عمدہ فرما اور اپنے نور کو ان کے لیے پورا فرما اور تو ان کو یہ بدلہ دے کہ جب ان کو قیامت کے دن اٹھایا جائے تو ان کی گواہی قبول ہو اور ان کی بات تیری پسند کے مطابق ہو اور عدل و انصاف والی ہو اور ان کا کلام صحیح اور حق و غلط میں تمیز کرنے والا ہو اور وہ مضبوط حجت اور بڑی دلیل والے ہوں۔\"",""],[" (9)","s"]]]],"f":[["(9)","Tabraani in his Awsat and Abu Nu'aym in the Awaali of Sa'eed bin Mansoor, as quoted in Kanzul Ummaal (Vol.1 Pg.214). In his Tafseer (Vol.3 Pg.509) Haafidh Ibn Katheer has commented on the narration."]]}]},"59":{"lead":[],"stories":[{"b":[["n",[["حضرت شہاب بن عبادؒ","b"],[" کہتے ہیں قبیلہ عبدالقیس کا جو وفد حضورؐ کی خدمت میں گیا تھا ان میں سے ایک صاحب کو اپنے سفر کی تفصیل بتاتے ہوئے اس طرح سنا کہ ہم لوگ حضورؐ کی خدمت میں پہنچے۔ آپؐ ہمارے آنے سے بہت زیادہ خوش ہوئے۔ جب ہم حضورؐ کی مجلس والوں تک پہنچ گئے تو انھوں نے ہمارے لیے کشادہ جگہ بنا دی۔ ہم وہاں بیٹھ گئے۔ حضورؐ نے ہمیں خوش آمدید کہا اور ہمیں دعا دی، پھر ہماری طرف دیکھ کر فرمایا تمہارا سردار اور ذمہ دار کون ہے؟ ہم سب نے منذر بن عائذ کی طرف اشارہ کیا۔ حضورؐ نے فرمایا کیا یہ اشج سردار ہے؟ (اشج اسے کہتے ہیں جس کے سر یا چہرے پر کسی زخم کا نشان ہو) ان کے چہرے پر گدھے کے کھر لگنے کے زخم کا نشان تھا اور یہ سب سے پہلا دن تھا جس میں ان کا نام اشج پڑا۔ یہ باقی لوگوں سے پیچھے رہ گئے تھے۔ انھوں نے اپنے وفد کی سواریوں کو باندھا اور ان کا سامان سنبھالا، پھر اپنا بیگ نکالا اور سفر کے کپڑے اتار کر نئے کپڑے پہنے، پھر وہ حضورؐ کی طرف آئے۔ اس وقت حضورؐ نے پاؤں پھیلا کر تکیہ لگا رکھا تھا، جب حضرت اشجؓ حضورؐ کے قریب پہنچے تو لوگوں نے ان کے لیے جگہ بنا دی اور یوں کہا اے اشج! یہاں بیٹھ جاؤ۔ حضورؐ پاؤں سمیٹ کر سیدھے بیٹھ گئے اور فرمایا اے اشج! یہاں آ جاؤ۔ چنانچہ وہ حضورؐ کے دائیں طرف آرام سے بیٹھ گئے۔ حضورؐ نے انہیں خوش آمدید کہا اور بہت شفقت اور مہربانی کا معاملہ کیا، پھر حضورؐ نے ان سے ان کے علاقے کے بارے میں پوچھا اور ہجر کی ایک ایک بستی صفا، مشقر وغیرہ کا نام لیا۔ حضرت اشجؓ نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! میرے ماں باپ آپؐ پر قربان ہوں، آپؐ تو ہماری بستیوں کے نام ہم سے زیادہ جانتے ہیں۔ حضورؐ نے فرمایا تمہارے علاقے میں گیا ہوں اور میں نے خوب گھوم پھر کر دیکھا ہے۔ پھر حضورؐ نے انصار کی طرف متوجہ ہو کر فرمایا اپنے ان بھائیوں کا اکرام کرو کیونکہ یہ تمہاری طرح مسلمان بھی ہیں لیکن ان کے بالوں اور کھال کی رنگت تم سے بہت زیادہ ملتی جلتی ہے۔ اپنی خوشی سے اسلام لائے ہیں، ان پر زبردستی نہیں کرنی پڑی اور یہ بھی نہیں کہ مسلمانوں کے لشکر نے ان پر حملہ کر کے ان پر غلبہ پا لیا ہو اور ان کا تمام مال غنیمت بنا لیا ہو یا انھوں نے اسلام سے انکار کیا ہو اور انہیں قتل کیا گیا ہو (وہ وفد انصار کے ہاں رہا)۔ پھر حضورؐ نے اس وفد سے پوچھا تم نے اپنے بھائیوں کے اکرام اور مہمانی کو کیسا پایا؟ انھوں نے کہا یہ بہت اچھے بھائی ہیں، انھوں نے رات کو ہمیں نرم نرم بستروں پر سلایا اور عمدہ کھانے کھلائے اور صبح کو ہمیں ہمارے رب کی کتاب اور ہمارے نبیؐ کی سنتیں سکھائیں۔ حضورؐ کو انصار کا یہ رویہ بہت پسند آیا اور آپؐ اس سے بہت خوش ہوئے اور پھر آپؐ نے ہم میں سے ہر ایک کی طرف توجہ فرمائی اور ہم نے جو کچھ سیکھا تھا اس کا اندازہ لگایا تو ہم میں سے کسی نے التحیات سیکھ لی تھی، کسی نے سورت فاتحہ، کسی نے ایک سورت، کسی نے دو سورتیں، کسی نے ایک سنت اور کسی نے دو سنتیں۔ آگے لمبی حدیث ذکر کی۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad (Vol.4 Pg.206), reporting from reliable sources as confirmed by Haythami (Vol.8 Pg.178) and by Mundhirri in his Targheeb wat Tarheeb (Vol.4 Pg.152)."]]},{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں کہ ہم لوگ حضورؐ کے پاس بیٹھے ہوئے تھے کہ اتنے میں آپؐ نے فرمایا تمہارے پاس عبدالقیس کا وفد آ رہا ہے لیکن ہمیں کوئی نظر نہیں آ رہا تھا۔ تھوڑی ہی دیر گزری تھی کہ واقعی وہ وفد پہنچ گیا۔ انھوں نے آ کر حضورؐ کو سلام کیا۔ حضورؐ نے ان سے پوچھا کہ تمہارے توشہ کی کھجوروں میں سے کچھ باقی ہے؟ انھوں نے کہا جی ہاں۔ پھر حضورؐ کے ارشاد فرمانے پر چمڑے کا ایک دستر خوان بچھا دیا گیا اور انھوں نے اپنی بچی ہوئی کھجوریں اس پر ڈال دیں۔ پھر حضورؐ نے اپنے صحابہؓ کو جمع فرمایا اور اس وفد سے مختلف کھجوروں کے بارے میں فرمانے لگے تم اس کھجور کو برنی کہتے ہو اور اس کو یہ اور اس کو یہ۔ انھوں نے کہا جی ہاں۔ پھر آپؐ نے اس وفد کو تقسیم کر دیا کہ (مدینے کے رہنے والے) مسلمان ان میں سے ایک ایک کو لے جائیں اور اپنے ہاں ٹھہرائیں اور انہیں قرآن و حدیث پڑھائیں اور نماز سکھائیں۔ ایک ہفتہ وہ یوں ہی سیکھتے رہے، پھر حضورؐ نے سارے وفد کو بلایا (اور ان کا امتحان لیا) تو آپؐ نے دیکھا کہ ابھی پورا سیکھے اور سمجھے نہیں ہیں، کچھ کمی ہے، پھر انہیں دوسرے مسلمانوں کے حوالے کر دیا اور ایک ہفتہ ان کے ہاں رہنے دیا، پھر انہیں بلایا (اور ان کا امتحان لیا) تو دیکھا کہ انھوں نے سب کچھ پڑھ لیا ہے اور پوری طرح سمجھ لیا ہے، پھر اس وفد نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" نے ہمیں بڑی خیر سکھا دی ہے اور دین کی سمجھ عطا فرما دی ہے۔ اب ہم اپنے علاقے کو جانا چاہتے ہیں۔ حضورؐ نے فرمایا ہاں ضرور چلے جاؤ۔ پھر ان لوگوں نے کہا کہ ہم اپنے علاقے میں جو شراب پیتے ہیں اگر ہم اس کے بارے میں حضورؐ سے پوچھ لیں۔ اس کے بعد آگے حدیث میں اس بات کا ذکر ہے کہ حضورؐ نے کدو کے تونبے اور درخت کی کھوکھلی جڑ سے بنائے ہوئے برتن اور روغنی مرتبان میں نبیذ بنانے سے منع فرمایا۔",""]]]],"f":[]}]},"60":{"lead":[],"stories":[{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں کہ حضورؐ نو سال مدینہ منورہ میں رہے اور اس عرصہ میں آپؐ نے کوئی حج نہیں کیا۔ پھر آپؐ نے لوگوں میں اعلان کروایا کہ ",""],["ٱللَّٰه","a"],[" کے رسول ",""],["ﷺ","a"],[" اس سال حج کریں گے تو بہت سارے لوگ مدینہ منورہ آ گئے۔ ہر شخص یہ چاہتا تھا کہ حضورؐ کی اقتداء کرے اور وہی کام کرے جو حضورؐ کریں۔ جب ذیقعدہ میں پانچ دن باقی رہ گئے تو آپؐ حج کے لیے تشریف لے چلے۔ ہم بھی آپؐ کے ساتھ تھے۔ جب آپؐ ذوالحلیفہ پہنچے تو حضرت اسماء بنت عمیسؓ کے ہاں حضرت محمد بن ابی بکرؓ پیدا ہوئے۔ انھوں نے حضورؐ کی خدمت میں پیغام بھیجا کہ میں اب کیا کروں؟ حضورؐ نے فرمایا پہلے غسل کرو پھر کسی کپڑے کی لنگوٹی باندھ لو پھر احرام باندھ لو اور اونچی آواز سے لبیک کہو۔ پھر حضورؐ وہاں سے تشریف لے چلے یہاں تک کہ جب آپؐ کی اونٹنی آپؐ کو لے کر بیدا نامی اونچے مقام پر پہنچی تو آپؐ نے ان الفاظ سے لبیک پڑھی:",""]]],["q",[["لَبَّيْكَ ٱللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ ٱلْحَمْدَ وَٱلنِّعْمَةَ لَكَ وَٱلْمُلْكَ، لَا شَرِيكَ لَكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! حاضر ہوں، حاضر ہوں، حاضر ہوں، تیرا کوئی شریک نہیں، حاضر ہوں۔ تمام تعریفیں، تمام نعمتیں اور ساری بادشاہت تیرے لیے ہے، تیرا کوئی شریک نہیں۔\" اور لوگوں نے بھی لبیک پڑھی اور کچھ لوگ ذَا ٱلْمَعَارِجِ جیسے کلمات پڑھ رہے تھے اور نبی کریمؐ سن رہے تھے لیکن آپؐ نے ان سے کچھ نہ فرمایا۔ پھر میں نے حضورؐ کے سامنے نگاہ ڈالی تو مجھے حد نگاہ تک آدمی ہی آدمی نظر آئے، کوئی سوار تھا کوئی پیدل اور یہی حال آپؐ کے دائیں بائیں اور پیچھے تھا۔ حضرت جابرؓ فرماتے ہیں کہ حضورؐ ہمارے درمیان تھے، آپؐ پر قرآن نازل ہوتا تھا، آپؐ اس کی تفسیر بھی جانتے تھے اور قرآن پر جیسا عمل آپؐ کرتے تھے ویسا ہم بھی کرتے تھے۔ آگے اور حدیث بھی ذکر کی ہے۔ آئندہ حضورؐ کے خطبات حج کے عنوان کے ذیل میں حضورؐ کے صحابہ کرامؓ کے سفر حج میں سیکھنے سکھانے کے واقعات آئیں گے اور جہاد میں نکل کر سیکھنے سکھانے کے باب میں اس باب کے کچھ واقعات گزر چکے ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.146)."]]},{"b":[["n",[["حضرت جابر بن ازرق غاضریؓ","b"],[" فرماتے ہیں کہ میں حضورؐ کی خدمت میں سواری پر اپنا سامان لے کر حاضر ہوا۔ میں آپؐ کے ساتھ ساتھ چلتا رہا یہاں تک کہ ہم منزل پر پہنچ گئے۔ حضورؐ نے سواری سے اتر کر چمڑے کے ایک خیمے میں قیام فرمایا اور آپؐ کے خیمے کے دروازے پر تیس کوڑے بردار آدمی کھڑے ہو گئے، ایک آدمی مجھے دھکے دینے لگا۔ میں نے کہا اگر تم مجھے دھکے دو گے تو میں بھی تمہیں دھکے دوں گا اور اگر تم مجھے مارو گے تو میں بھی تمہیں ماروں گا۔ اس آدمی نے کہا او سب سے برے آدمی! میں نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! تم مجھ سے زیادہ برے ہو۔ اس نے کہا کیسے؟ میں نے کہا میں اطراف یمن سے اس لیے آیا ہوں تا کہ نبی کریمؐ سے حدیثیں سنوں اور واپس جا کر اپنے پیچھے والوں کو وہ ساری حدیثیں سناؤں اور تم مجھے روکتے ہو۔ اس آدمی نے کہا تم نے ٹھیک کہا، ",""],["ٱللَّٰه","a"],[" کی قسم! واقعی میں تم سے زیادہ برا ہوں۔ پھر حضورؐ سواری پر سوار ہوئے اور منی میں جمرہ عقبہ کے پاس لوگ آپؐ کے ساتھ چمٹنے لگے اور ان کی تعداد بڑھتی گئی۔ یہ سب لوگ حضورؐ سے مختلف باتیں پوچھنا چاہتے تھے لیکن تعداد زیادہ ہونے کی وجہ سے کوئی بھی آپؐ تک پہنچ نہیں سکتا تھا۔ اتنے میں ایک آدمی آیا جس نے اپنے بال کٹوا رکھے تھے۔ اس نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرے لیے دعائے رحمت فرما دیں۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" بال منڈوانے والوں پر رحمت نازل فرمائے۔ اس آدمی نے پھر کہا میرے لیے دعائے رحمت فرما دیں۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" بال منڈوانے والوں پر رحمت نازل فرمائے۔ اس آدمی نے پھر کہا میرے لیے دعائے رحمت فرما دیں۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" بال منڈوانے والوں پر رحمت نازل فرمائے۔ یہ دعا آپؐ نے تین مرتبہ فرمائی تو وہ آدمی گیا اور جا کر اس نے اپنے بال منڈوا دیے۔ اس کے بعد مجھے جو بھی نظر آیا اس کے بال منڈے ہوئے تھے۔",""]]],["p",[["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے:",""]]],["q",[["وَمَا كَانَ ٱلْمُؤْمِنُونَ لِيَنفِرُوا۟ كَآفَّةً ۚ فَلَوْلَا نَفَرَ مِن كُلِّ فِرْقَةٍ مِّنْهُمْ طَآئِفَةٌ لِّيَتَفَقَّهُوا۟ فِى ٱلدِّينِ وَلِيُنذِرُوا۟ قَوْمَهُمْ إِذَا رَجَعُوٓا۟ إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ  (سورۃ التوبہ: ۱۲۲)","a"]]],["p",[["ترجمہ: \"اور (ہمیشہ کے لیے) مسلمانوں کو یہ (بھی) نہ چاہیے کہ (جہاد کے واسطے) سب کے سب (ہی) نکل کھڑے ہوں، سو ایسا کیوں نہ کیا جائے کہ ان کی ہر بڑی جماعت میں سے ایک چھوٹی جماعت (جہاد میں) جایا کرے تا کہ باقی ماندہ لوگ دین کی سمجھ بوجھ حاصل کرتے رہیں اور تا کہ یہ لوگ اپنی (اس) قوم کو جبکہ وہ ان کے پاس واپس آویں ڈراویں تا کہ وہ (ان سے دین کی باتیں سن کر برے کاموں سے) احتیاط رکھیں۔\" اس کی تفسیر کے بارے میں علامہ ابن جریر فرماتے ہیں کہ اس آیت کی تفسیر میں علمائے کرام کے مختلف اقوال ہیں لیکن ان میں سب سے زیادہ ٹھیک قول ان علماء کا ہے جو فرماتے ہیں کہ جہاد کے لیے نکلنے والی چھوٹی جماعت سفر جہاد میں دین کی سمجھ بوجھ حاصل کر کے آئیں گے، کیونکہ وہ اپنی آنکھوں سے دیکھیں گے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ دشمنوں اور کفار کے خلاف اپنے دین والوں کی اور اپنے رسولؐ کے صحابہؓ کی مدد فرماتے ہیں تو اس طرح حقیقت اسلام اور اس کے تمام دینوں پر غلبہ پانے کا علم ان نکلنے والوں کو بھی حاصل ہو جائے گا جن کو پہلے سے یہ علم حاصل نہیں تھا۔ اور جب یہ لوگ اپنی قوم میں جا کر ان کو ",""],["ٱللَّٰه","a"],[" کی اس غیبی مدد کے واقعات سنائیں گے جس کی وجہ سے مسلمانوں کا مشرکوں پر غالب آنا ہوا اور ",""],["ٱللَّٰه","a"],[" کی نافرمانی کی وجہ سے کافروں پر ",""],["ٱللَّٰه","a"],[" کے عذاب اترنے کے عینی مشاہدہ کے واقعات سنائیں گے تو باقی ماندہ لوگ ان واقعات کو سن کر برے کاموں سے اور زیادہ احتیاط کرنے لگیں گے اور ان کا ",""],["ٱللَّٰه","a"],[" اور رسولؐ پر ایمان اور زیادہ بڑھ جائے گا۔",""],[" (2)","s"],[" (3)","s"]]]],"f":[["(2)","Abu Nu'aym, as quoted in Kanzul Ummaal (Vol.3 Pg.49). Ibn Mandah has also reported the narration, as quoted in Isaabah (Vol.1 Pg.211)."],["(3)","Ibn Jareer (Vol.11 Pg.51)."]]}]},"61":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوسعیدؓ","b"],[" فرماتے ہیں کہ ہم لوگ غزوے میں جایا کرتے تھے اور ایک دو آدمی حضورؐ کی حدیثیں سننے اور یاد رکھنے کے لیے چھوڑ جاتے تھے۔ جب ہم غزوے سے واپس آتے تو وہ حضورؐ کی بیان کردہ تمام حدیثیں ہمیں سنا دیتے اور ان سے سننے کی بنیاد پر ہم حدیث آگے بیان کرتے وقت یوں کہہ دیتے کہ حضورؐ نے فرمایا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Khaythama and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.5 Pg.240)."]]}]},"62":{"lead":[],"stories":[{"b":[["n",[["حضرت ثابت بنانیؒ","b"],[" کہتے ہیں حضرت انس بن مالکؓ نے بیان کیا کہ انصار کے ستر آدمی ایسے تھے جو رات ہوتے ہی اپنے ایک معلم کے پاس مدینہ میں چلے جاتے اور رات بھر اس سے قرآن پڑھتے رہتے اور صبح کو ان میں سے جو طاقتور اور صحت مند ہوتے وہ جنگل سے لکڑیاں کاٹ لاتے اور پینے کا میٹھا پانی بھر لاتے اور جن کے پاس مال کی گنجائش ہوتی وہ بکری ذبح کر کے اس کا گوشت بناتے اور گوشت کے ٹکڑے حضورؐ کے حجروں پر ٹانک دیتے۔ جب حضرت خبیبؓ کو (مکہ میں) شہید کر دیا گیا تو ان ستر آدمیوں کو حضورؐ نے بھیجا، ان میں میرے ماموں حضرت حرام بن ملحانؓ بھی تھے۔ یہ قبیلہ بنو سلیم کے ایک قبیلے کے پاس آئے۔ حضرت حرامؓ نے اس جماعت کے امیر سے کہا کیا میں جا کر ان لوگوں کو یہ نہ بتا دوں کہ ہم ان سے لڑنے کے ارادے سے نہیں آئے، اس طرح وہ ہمیں چھوڑ دیں گے۔ جماعت والوں نے کہا ٹھیک ہے، چنانچہ حضرت حرامؓ نے جا کر ان لوگوں کو یہ بات کہی۔ اس پر ایک آدمی نے انہیں ایسا نیزہ مارا جو پار نکل گیا۔ جب حضرت حرامؓ نے دیکھا کہ نیزہ پیٹ میں پہنچ گیا ہے تو انھوں نے کہا ",""],["ٱللَّٰه","a"],[" اکبر، کعبہ کے رب کی قسم! میں تو کامیاب ہو گیا۔ اس کے بعد وہ قبیلہ والے ان تمام حضرات پر ٹوٹ پڑے اور سب کو قتل کر دیا اور ایک بھی باقی نہ رہا جو واپس جا کر حضورؐ کو خبر کر سکے۔ اس جماعت کی شہادت پر میں نے حضورؐ کو جتنا غمگین دیکھا اتنا کسی جماعت پر نہیں دیکھا، چنانچہ میں نے دیکھا کہ حضورؐ جب بھی فجر کی نماز پڑھتے تو ہاتھ اٹھا کر اس قبیلے کے لیے بددعا کرتے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilya (Vol.1 Pg.123)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ چند لوگوں نے نبی کریمؐ کی خدمت میں آ کر کہا ہمارے ساتھ چند آدمی بھیج دیں جو ہمیں قرآن و سنت سکھائیں۔ چنانچہ حضورؐ نے ان کے ساتھ انصار کے ستر آدمی بھیج دیے جن کو (حافظ قرآن ہونے کی وجہ سے) قراء کہا جاتا تھا، ان میں میرے ماموں حضرت حرامؓ بھی تھے۔ یہ لوگ قرآن پڑھتے تھے اور رات کو ایک دوسرے سے سنتے سناتے تھے اور علم حاصل کرتے تھے اور دن میں پانی لا کر مسجد میں رکھ دیتے تھے اور جنگل سے لکڑیاں کاٹ کر لاتے تھے اور انہیں بیچ کر اہل صفہ اور فقراء صحابہؓ کے لیے کھانا خرید کر لاتے۔ حضورؐ نے ان حضرات کو ان لوگوں کے پاس بھیج دیا، وہ لوگ ان کے آڑے آئے اور انہیں اس جگہ پہنچنے سے پہلے ہی قتل کر دیا، تو ان لوگوں نے کہا اے ",""],["ٱللَّٰه","a"],["! ہماری طرف سے ہمارے نبی کو یہ پیغام پہنچا دے کہ ہم تیرے پاس پہنچ گئے ہیں اور ہم تجھ سے راضی ہیں اور تو ہم سے راضی ہے۔ اور پیچھے سے آ کر میرے ماموں حضرت حرامؓ کو ایک آدمی نے ایسا نیزہ مارا جو پار نکل گیا۔ حضرت حرامؓ نے کہا رب کعبہ کی قسم! میں تو کامیاب ہو گیا۔ حضورؐ نے اپنے بھائیوں سے فرمایا تمہارے بھائی شہید کر دیے گئے ہیں اور انھوں نے یہ دعا مانگی ہے کہ اے ",""],["ٱللَّٰه","a"],["! ہماری طرف سے ہمارے نبی کو یہ پیغام پہنچا دے کہ ہم تیرے پاس پہنچ گئے ہیں اور ہم تجھ سے راضی ہیں اور تو ہم سے راضی ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.3 Pg.514)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ حضرت عمرؓ نے فرمایا میں اور میرا ایک انصاری پڑوسی ہم دونوں قبیلہ بنوامیہ بن زید کے محلہ میں رہتے تھے جو کہ مدینہ کے علاقہ عوالی میں تھا اور ہم دونوں باری باری حضورؐ کی خدمت میں جاتے تھے۔ ایک دن وہ جاتا اور ایک دن میں۔ جب میں جاتا تو اس دن کی وحی وغیرہ کی تمام خبریں لا کر میں اس انصاری کو سنا دیتا۔ جب وہ جاتا تو وہ آ کر اس دن کی تمام خبریں مجھے سنا دیتا۔ چنانچہ میرا انصاری ساتھی اپنی باری والے دن حضورؐ کی خدمت میں گیا اور واپس آ کر اس نے بہت زور سے میرا دروازہ کھٹکھٹایا اور زور سے کہا کیا عمر اندر ہیں؟ میں گھبرا کر اس کے پاس باہر آیا۔ اس نے کہا بہت بڑی بات پیش آ گئی ہے (کہ حضورؐ نے اپنی بیویوں کو طلاق دے دی ہے)۔ میں حضرت حفصہؓ کے پاس گیا تو وہ رو رہی تھیں۔ میں نے پوچھا کیا تم سب کو حضورؐ نے طلاق دے دی ہے؟ انھوں نے کہا مجھے معلوم نہیں۔ پھر میں حضورؐ کی خدمت میں گیا اور میں نے کھڑے کھڑے عرض کیا کیا آپؐ نے اپنی عورتوں کو طلاق دے دی ہے؟ حضورؐ نے فرمایا نہیں۔ میں نے (خوشی سے) کہا ",""],["ٱللَّٰه","a"],[" اکبر۔",""],[" (3)","s"]]]],"f":[["(3)","Bukhaari (Vol.1 Pg.19)."]]},{"b":[["n",[["حضرت براءؓ","b"],[" فرماتے ہیں ہم سب نے حضورؐ کی ہر حدیث نہیں سنی کیونکہ ہماری جائیداد اور دنیاوی مشاغل بھی تھے (جن کو وقت دینا پڑتا تھا) اور اس زمانے میں لوگ جھوٹ نہیں بولتے تھے، اس لیے جو مجلس میں حاضر ہو کر حضورؐ سے حدیث سن لیتا وہ غائب کو سنا دیتا۔ ",""],["حضرت براءؓ","b"],[" فرماتے ہیں ہم نے ہر حدیث حضورؐ سے نہیں سنی (کچھ سنی ہیں اور کچھ نہیں سنی ہیں) ہم لوگ اونٹ چرانے میں مشغول رہتے تھے، ہمارے ساتھی حضورؐ سے حدیث سنتے تھے پھر وہ ہمیں سنایا کرتے تھے۔",""],[" (4)","s"],[" (5)","s"]]]],"f":[["(4)","Haakim (Vol.1 Pg.127), reporting from reliable sources as confirmed by Dhahabi."],["(5)","Haakim in his Ma'rifa Uloomil Hadith (Pg.14) and Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.154). Abu Nu'aym has reported a similar narration, as quoted in Kanzul Ummaal (Vol.5 Pg.238)."]]},{"b":[["n",[["حضرت ابوانس مالک بن ابی عامر اصبحیؒ","b"],[" کہتے ہیں میں حضرت طلحہ بن عبید",""],["ٱللَّٰه","a"],["ؓ کے پاس تھا کہ اتنے میں ایک آدمی ان کے پاس اندر آیا اور اس نے کہا اے ابومحمد! ",""],["ٱللَّٰه","a"],[" کی قسم ہمیں معلوم نہیں کہ یہ یمنی آدمی حضورؐ کو زیادہ جانتا ہے یا آپ لوگ؟ یہ تو حضورؐ کی طرف سے ایسی باتیں نقل کرتے ہیں جو حضورؐ نے نہیں فرمائی ہیں۔ وہ آدمی یہ بات حضرت ابوہریرہؓ کے بارے میں کہہ رہا تھا۔ حضرت طلحہؓ نے فرمایا اس بات میں کوئی شک نہیں ہے کہ انھوں نے (یعنی حضرت ابوہریرہؓ نے) حضورؐ سے وہ حدیثیں سنی ہیں جو ہم نے نہیں سنیں اور انہیں حضورؐ کے وہ حالات معلوم ہیں جو ہمیں معلوم نہیں ہیں۔ اس کی وجہ یہ ہے کہ ہم مالدار لوگ تھے، ہمارے گھر اور بال بچے تھے۔ ہم حضورؐ کی خدمت میں صبح و شام حاضری دیتے تھے اور پھر واپس چلے جاتے۔ حضرت ابوہریرہؓ مسکین آدمی تھے، نہ ان کے پاس مال تھا اور نہ اہل و عیال۔ انھوں نے اپنا ہاتھ نبی کریمؐ کے ہاتھ میں دے رکھا تھا۔ جہاں حضورؐ تشریف لے جاتے یہ ساتھ جاتے، اس لیے ہمیں اس بات میں کوئی شک نہیں ہے کہ انہیں وہ کچھ معلوم ہے جو ہمیں معلوم نہیں ہے اور انھوں نے وہ کچھ سن رکھا ہے جو ہم نے نہیں سنا اور ہم میں سے کوئی بھی ان پر یہ الزام نہیں لگا سکتا کہ انھوں نے اپنے پاس سے بنا کر وہ باتیں حضورؐ کی طرف سے بیان کی ہیں جو حضورؐ نے نہیں فرمائی۔",""],[" (6)","s"]]]],"f":[["(6)","Haakim (Vol.3 Pg.512)."]]}]},"63":{"lead":[],"stories":[{"b":[["n",[["حضرت عمرؓ نے فرمایا ہمارے اس بازار میں وہی کاروبار کرے جس نے دین کی سمجھ حاصل کر لی ہو۔",""],[" (1)","s"]]]],"f":[["(1)","Tirmidhi, as quoted in Kanzul Ummaal (Vol.2 Pg.218)."]]}]},"64":{"lead":[],"stories":[{"b":[["n",[["حضرت علیؓ","b"],[" نے ",""],["ٱللَّٰه","a"],[" تعالیٰ کے فرمان:",""]]],["q",[["قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا  (سورۃ تحریم: ۶)","a"]]],["p",[["ترجمہ: \"تم اپنے کو اور اپنے گھر والوں کو (دوزخ کی) آگ سے بچاؤ\" کے بارے میں فرمایا اپنے آپ کو اور اپنے گھر والوں کو خیر والے اعمال سکھاؤ۔ ایک روایت میں یہ ہے کہ انہیں تعلیم اور ادب سکھاؤ۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Haakim, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.85)."],["(2)","Tabari in his Tafseer (Vol.28 Pg.107)."]]},{"b":[["n",[["حضرت مالک بن حویرثؓ","b"],[" فرماتے ہیں کہ ہم چند ہم عمر نوجوان حضورؐ کی خدمت میں حاضر ہوئے اور ہم آپؐ کے ہاں بیس دن ٹھہرے، پھر آپؐ کو اندازہ ہوا کہ ہمارے دلوں میں گھر جانے کا شوق پیدا ہو گیا ہے تو آپؐ نے ہم سے پوچھا کہ گھر کن کو چھوڑ آئے ہو؟ آپؐ بہت شفیق، نرم اور رحم دل تھے، اس لیے آپؐ نے فرمایا اپنے گھر واپس چلے جاؤ اور انہیں (جو سیکھا ہے وہ) سکھاؤ اور انہیں (نیک اعمال کا) حکم دو اور جیسے مجھے نماز پڑھتے ہوئے دیکھا ہے ویسے نماز پڑھو اور جب نماز کا وقت آئے تو تم میں سے کوئی ایک اذان دے دیا کرے اور جو تم میں سب سے بڑا ہو وہ تمہاری امامت کیا کرے۔",""],[" (3)","s"]]]],"f":[["(3)","Bukhaari in his Adab (Pg.33)."]]}]},"65":{"lead":[],"stories":[{"b":[["n",[["حضرت زید بن ثابتؓ","b"],[" فرماتے ہیں جب حضورؐ مدینہ منورہ تشریف لائے تو مجھے حضورؐ کی خدمت میں پیش کیا گیا اور لوگوں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! یہ لڑکا قبیلہ بنو نجار کا ہے اور جتنا قرآن آپؐ پر نازل ہو چکا ہے اس میں سے سترہ سورتیں پڑھ چکا ہے۔ چنانچہ میں نے حضورؐ کو قرآن پڑھ کر سنایا جو حضورؐ کو بہت پسند آیا تو آپؐ نے فرمایا اے زید! تم میرے لیے یہود کی لکھائی سیکھ لو کیونکہ ",""],["ٱللَّٰه","a"],[" کی قسم! مجھے لکھائی کے بارے میں یہود پر کوئی اطمینان نہیں ہے۔ چنانچہ میں نے یہود کی زبان کو اور ان کی لکھائی کو سیکھنا شروع کر دیا، مجھے آدھا مہینہ نہیں گزرا تھا کہ میں ان کی زبان کا ماہر ہو گیا۔ چنانچہ پھر میں حضورؐ کی طرف سے یہود کے نام خطوط لکھا کرتا اور جب یہود حضورؐ کے نام خط لکھ کر بھیجتے تو میں حضورؐ کو پڑھ کر سنایا کرتا۔ ",""],["حضرت زیدؓ","b"],[" فرماتے ہیں کہ حضورؐ نے مجھ سے فرمایا کیا تم سریانی زبان اچھی طرح جانتے ہو؟ کیونکہ میرے پاس سریانی زبان میں خط آتے ہیں۔ میں نے کہا نہیں۔ آپؐ نے فرمایا اسے سیکھ لو۔ چنانچہ میں نے سترہ دنوں میں سریانی زبان اچھی طرح سیکھ لی۔",""],[" (1)","s"],[" (2)","s"],[" (3)","s"]]]],"f":[["(1)","Abu Ya'la and Ibn Asaakir."],["(2)","Abu Ya'la, Ibn Asaakir and Ibn Abi Dawood."],["(3)","Ibn Abi Dawood and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.185). Ibn Sa'd (Vol.4 Pg.174) has reported a similar narration."]]},{"b":[["n",[["حضرت زیدؓ","b"],[" فرماتے ہیں کہ حضورؐ نے مجھ سے فرمایا میرے پاس (یہود کے) خطوط آتے ہیں، میں نہیں چاہتا کہ ہر آدمی انہیں پڑھے، کیا تم عبرانی یا سریانی زبان کی لکھائی سیکھ سکتے ہو؟ میں نے کہا جی ہاں۔ چنانچہ میں نے وہ زبان سترہ دنوں میں اچھی طرح سیکھ لی۔",""]]]],"f":[]},{"b":[["n",[["حضرت عمر بن قیسؒ","b"],[" کہتے ہیں حضرت ابن زبیرؓ کے سو غلام تھے۔ ان میں سے ہر غلام الگ زبان میں بات کرتا تھا اور حضرت ابن زبیرؓ ان میں سے ہر ایک سے اسی کی زبان میں بات کرتے تھے۔ میں جب ان کے دنیاوی مشاغل پر نگاہ ڈالتا تو ایسے لگتا کہ جیسے ان کا پلک جھپکنے کے بقدر بھی آخرت کا ارادہ نہیں ہے اور میں جب ان کی آخرت والے اعمال کی مشغولی پر نگاہ ڈالتا تو ایسے لگتا کہ جیسے ان کا پلک جھپکنے کے بقدر بھی دنیا کا ارادہ نہیں ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Haakim (Vol.3 Pg.549) and Abu Nu'aym in his Hilya (Vol.1 Pg.334)."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" نے فرمایا ستاروں کا اتنا علم حاصل کرو جس سے تم خشکی اور سمندر میں صحیح راستہ معلوم کر سکو، اس سے زیادہ نہ حاصل کرو۔ ",""],["حضرت عمرؓ","b"],[" نے فرمایا ستاروں کا اتنا علم حاصل کرو جس سے تم راستہ معلوم کر سکو اور نسب بھی اتنے معلوم کرو جس سے تم صلہ رحمی کر سکو۔",""],[" (5)","s"],[" (6)","s"]]]],"f":[["(5)","Ibn Abdul Birr in his Ilm."],["(6)","Hannaad, as quoted in Kanzul Ummaal (Vol.5 Pg.234)."]]},{"b":[["n",[["حضرت صعصعہ بن صوحانؒ","b"],[" کہتے ہیں کہ ایک دیہاتی آدمی حضرت علی بن ابی طالبؓ کی خدمت میں آیا اور اس نے کہا اے امیر المومنین! آپ یہ آیت کس طرح پڑھتے ہیں:",""]]],["q",[["لَّا يَأْكُلُهُۥٓ إِلَّا ٱلْخَٰطِـُٔونَ  (سورۃ الحاقہ: ۳۷)","a"]]],["p",[["(دیہاتی نے اسے \"الخاطون\" کے معنی میں پڑھا اور کہا) اس کا ترجمہ یہ ہوا کہ اسے صرف قدم اٹھانے والے کھائیں گے۔ اشکال یہ ہوتا ہے کہ ",""],["ٱللَّٰه","a"],[" کی قسم! قدم تو ہر آدمی اٹھاتا ہے۔ یہ سن کر حضرت علیؓ مسکرائے اور فرمایا یہ آیت اس طرح ہے: لَّا يَأْكُلُهُۥٓ إِلَّا ٱلْخَٰطِـُٔونَ۔ ترجمہ: \"اسے صرف نافرمان لوگ ہی کھائیں گے۔\" اس دیہاتی نے کہا آپ نے ٹھیک فرمایا اے امیر المومنین! ",""],["ٱللَّٰه","a"],[" تعالیٰ ایسے نہیں ہیں کہ اپنے بندے کو یونہی (دوزخ میں) جانے دیں۔ حضرت علیؓ نے حضرت ابوالاسود دؤلیؒ کی طرف متوجہ ہو کر فرمایا اب تو تمام عجمی لوگ ",""],["ٱللَّٰه","a"],[" کے دین میں داخل ہو گئے ہیں، اس لیے تم ان کے لیے ایسی علامتیں مقرر کرو جن سے وہ اپنی زبان پر صحیح قراءت کر سکیں۔ چنانچہ انھوں نے اس کے لیے رفع، نصب اور جر کی اصطلاحات مقرر کیں (جو علم نحو میں پڑھائی جاتی ہیں)۔ اس طرح عربی کے علم نحو کی ابتداء ہوئی۔",""],[" (7)","s"]]]],"f":[["(7)","Bayhaqi, Ibn Asaakir and Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.5 Pg.237)."]]}]},"66":{"lead":[],"stories":[{"b":[["n",[["حضرت عروہؓ","b"],[" فرماتے ہیں کہ جب حضورؐ مکہ سے حنین تشریف لے گئے تو اپنے پیچھے حضرت معاذ بن جبلؓ کو مکہ والوں پر امیر بنا کر چھوڑ گئے اور انہیں حکم دیا کہ وہ لوگوں کو قرآن سکھائیں اور ان میں دین کی سمجھ پیدا کریں، پھر جب وہاں سے مدینہ واپس جانے لگے تو دوبارہ حضرت معاذ بن جبلؓ کو مکہ والوں پر مقرر فرمایا۔ ",""],["حضرت مجاہدؒ","b"],[" کہتے ہیں حضورؐ جب مکہ سے حنین کی طرف تشریف لے گئے تو اپنے پیچھے حضرت معاذ بن جبلؓ کو چھوڑ گئے تا کہ وہ مکہ والوں میں دین کی سمجھ پیدا کریں اور انہیں قرآن پڑھائیں۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Haakim (Vol.3 Pg.270)."],["(2)","Ibn Sa'd (Vol.4 Pg.164)."]]}]},"67":{"lead":[],"stories":[{"b":[["n",[["حضرت قاسمؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ جس سفر میں تشریف لے جاتے تو اپنے پیچھے حضرت زید بن ثابتؓ کو اپنی جگہ ذمہ دار بنا جاتے۔ حضرت عمرؓ نے اور لوگوں کو تمام علاقوں میں تقسیم کر دیا تھا (حضرت زیدؓ کو اپنے پاس رکھا ہوا تھا)۔ حضرت زیدؓ کو بہت ہی ضروری کام کی وجہ سے ہی بھیجتے۔ حضرت عمرؓ سے نام لے کر آدمیوں کے بھیجنے کا مطالبہ ہوتا اور یوں کہا جاتا کہ حضرت زید بن ثابتؓ کو بھیج دیں تو فرماتے کہ میں حضرت زیدؓ کے مرتبہ سے ناواقف نہیں ہوں لیکن اس شہر (مدینہ) والوں کو حضرت زیدؓ کی ضرورت ہے کیونکہ مدینہ والوں کو پیش آنے والے مسائل میں جیسا عمدہ جواب حضرت زیدؓ سے ملتا ہے ایسا کسی اور سے نہیں ملتا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.4 Pg.174)."]]},{"b":[["n",[["حضرت سالم بن عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں کہ جس دن حضرت زید بن ثابتؓ کا انتقال ہوا اس دن ہم لوگ حضرت ابن عمرؓ کے ساتھ تھے۔ میں نے کہا آج لوگوں کے بہت بڑے عالم کا انتقال ہو گیا ہے۔ حضرت ابن عمرؓ نے کہا ",""],["ٱللَّٰه","a"],[" آج ان پر رحمت نازل فرمائے، یہ تو حضرت عمرؓ کے زمانہ خلافت میں بھی لوگوں کے بہت بڑے عالم تھے۔ حضرت عمرؓ نے لوگوں کو تمام علاقوں میں بکھیر دیا تھا اور انہیں اپنی رائے سے فتویٰ دینے سے منع کر دیا تھا لیکن حضرت زید بن ثابتؓ مدینہ ہی میں رہے اور مدینہ والوں کو اور باہر سے آنے والوں کو فتویٰ دیا کرتے تھے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.4 Pg.176)."]]},{"b":[["n",[["حضرت ابو عبدالرحمن سلمیؒ","b"],[" کہتے ہیں کہ میں نے حضرت عثمانؓ کو قرآن پڑھ کر سنایا۔ اس پر انہوں نے مجھ سے فرمایا اس طرح تم مجھے لوگوں کے کاموں کے بارے میں غور و فکر کرنے سے ہٹا دو گے، اس لیے تم حضرت زید بن ثابتؓ کے پاس چلے جاؤ کیونکہ انہیں اس کام کے لیے مجھ سے زیادہ فرصت ہے اور انہیں پڑھ کر سناؤ، میری اور ان کی قراءت ایک جیسی ہے، اس میں کوئی فرق نہیں ہے۔",""]]],["p",[["اور جلد اول صفحہ نمبر ۳۶۰ پر ابن سعد کی یہ روایت گزر چکی ہے کہ حضرت کعب بن مالکؓ فرماتے ہیں کہ جب حضرت معاذؓ ملک شام کی طرف روانہ ہونے لگے تو حضرت عمرؓ فرمایا کرتے تھے کہ حضرت معاذؓ کے شام جانے سے مدینہ والوں کو فقہی مسائل میں اور فتویٰ لینے میں بڑی دقت پیش آ رہی ہے کیونکہ حضرت معاذؓ مدینہ میں لوگوں کو فتویٰ دیا کرتے تھے۔ میں نے حضرت ابوبکرؓ سے، ",""],["ٱللَّٰه","a"],[" ان پر رحمت نازل فرمائے، یہ بات کی تھی کہ وہ حضرت معاذؓ کو مدینہ میں روک لیں کیونکہ لوگوں کو (فتویٰ میں) ان کی ضرورت ہے لیکن انھوں نے مجھے انکار کر دیا اور فرمایا کہ ایک آدمی اس راستہ میں جا کر شہید ہونا چاہتا ہے تو میں اسے نہیں روک سکتا۔ آگے اور حدیث بھی ذکر کی ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Ambaari, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.184)."]]}]},"68":{"lead":[],"stories":[{"b":[["n",[["حضرت عاصم بن عمر بن قتادہؒ","b"],[" کہتے ہیں قبیلہ جدیلہ کی دو شاخوں عضل اور قارہ کے کچھ لوگ غزوہ احد کے بعد حضورؐ کی خدمت میں آئے اور کہنے لگے ہمارے علاقے میں لوگ مسلمان ہو چکے ہیں، آپؐ ہمارے ساتھ اپنے چند ساتھی بھیج دیں جو ہمیں قرآن پڑھائیں اور ہم میں دین کی سمجھ پیدا کریں۔ چنانچہ حضورؐ نے ان کے ساتھ چھ آدمی بھیج دیے جن میں حضرت حمزہ بن عبدالمطلبؓ کے حلیف حضرت مرثد بن ابی مرثدؓ بھی تھے اور یہی ان کے امیر تھے۔ پھر اس کے بعد غزوہ رجیع کا مختصر قصہ ذکر کیا۔",""],[" (1)","s"]]]],"f":[["(1)","Haakim (Vol.3 Pg.222)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ یمن کے کچھ لوگ حضورؐ کے پاس آئے اور کہنے لگے ہم میں ایسا آدمی بھیج دیں جو ہم میں دین کی سمجھ پیدا کرے اور ہمیں سنتیں سکھائے اور ",""],["ٱللَّٰه","a"],[" کی کتاب کے مطابق ہمارے جھگڑوں کے فیصلے کرے۔ حضورؐ نے فرمایا اے علی! یمن چلے جاؤ اور ان میں دین کی سمجھ پیدا کیا کرو اور ان کو سنتیں سکھاؤ اور ان کے جھگڑوں کے فیصلے ",""],["ٱللَّٰه","a"],[" کی کتاب کے مطابق کرو۔ میں نے عرض کیا یمن والے تو اجڈ لوگ ہیں اور وہ ایسے مقدمات میرے پاس لائیں گے جن کا صحیح فیصلہ مجھے معلوم نہیں ہوگا تو پھر میں کیا کروں گا؟ حضورؐ نے میرے سینے پر ہاتھ مارا اور فرمایا جاؤ ",""],["ٱللَّٰه","a"],[" تمہارے دل کو (صحیح فیصلے کی) ہدایت دے دے گا اور تمہاری زبان کو (صحیح فیصلہ پر) جما دے گا۔ چنانچہ (حضورؐ کی اس دعا کا یہ اثر ہوا کہ) اس دن سے لے کر آج تک مجھے بھی دو آدمیوں کے درمیان فیصلہ کرنے میں کوئی شک یا تردد نہیں ہوا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Jareer, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.37)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ یمن والے حضورؐ کی خدمت میں آئے اور عرض کیا ہمارے ساتھ ایسا آدمی بھیج دیں جو ہمیں قرآن سکھائے۔ حضورؐ نے حضرت ابوعبیدہؓ کا ہاتھ پکڑ کر انہیں یمن والوں کے ساتھ بھیج دیا اور فرمایا یہ اس امت کے امین ہیں۔ ابن سعد کی روایت میں یہ ہے کہ یمن والوں نے حضورؐ سے یہ مطالبہ کیا کہ حضورؐ ان کے ساتھ ایک آدمی ایسا بھیج دیں جو انہیں سنت اور اسلام سکھائے۔",""],[" (3)","s"],[" (4)","s"]]]],"f":[["(3)","Haakim (Vol.3 Pg.267)."],["(4)","Ibn Sa'd (Vol.3 Pg.299)."]]},{"b":[["n",[["حضرت ابوبکر بن محمد بن عمرو بن حزمؒ","b"],[" کہتے ہیں کہ ہمارے پاس حضورؐ کی تحریر ہے جو حضورؐ نے لکھ کر حضرت عمرو بن حزمؓ کو اس وقت عطا فرمائی تھی جب حضورؐ نے انہیں یمن اس لیے بھیجا تھا تا کہ وہاں والوں میں دین کی سمجھ پیدا کریں اور انہیں سنت سکھائیں اور ان سے صدقات وصول کریں اور انہیں تحریر لکھ کر دی اور انہیں ہدایات بھی دیں۔ تحریر میں یہ تھا بسم ",""],["ٱللَّٰه","a"],[" الرحمن الرحیم، یہ ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ کی طرف سے تحریر ہے:",""]]],["q",[["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَوْفُوا۟ بِٱلْعُقُودِ  (سورۃ مائدہ: ۱)","a"]]],["p",[["ترجمہ: \"اے ایمان والو! عہدوں کو پورا کرو۔\" (حضرت) محمد رسول ",""],["ٱللَّٰه","a"],["ؐ عمرو بن حزمؓ کو یمن بھیج رہے ہیں اور ان سے یہ عہد لے رہے ہیں کہ وہ اپنی تمام باتوں میں ",""],["ٱللَّٰه","a"],[" سے تقویٰ اختیار کریں گے کیونکہ ",""],["ٱللَّٰه","a"],[" ان لوگوں کے ساتھ ہے جو تقویٰ اختیار کریں اور نیک کردار ہوں۔",""]]],["p",[["حضورؐ نے حضرت معاذؓ اور حضرت ابوموسیٰؓ کو یمن بھیجا اور دونوں کو حکم دیا کہ وہ لوگوں کو قرآن سکھائیں۔",""],[" (5)","s"],[" (6)","s"]]]],"f":[["(5)","Ibn Abi Haatim, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.3)."],["(6)","Abu Nu'aym in his Hilya (Vol.1 Pg.256)."]]},{"b":[["n",[["حضرت عمار بن یاسرؓ","b"],[" فرماتے ہیں مجھے حضورؐ نے قیس کے ایک قبیلے کی طرف بھیجا تا کہ میں انہیں اسلام کے احکام سکھاؤں۔ میں نے وہاں جا کر دیکھا تو وہ بدکے ہوئے اونٹوں کی طرح تھے۔ ان کی نگاہیں ہر وقت اوپر اٹھی رہتی تھیں اور ان کو بکری اور اونٹوں کے علاوہ اور کوئی فکر نہیں تھی، اس لیے میں حضورؐ کی خدمت میں واپس آ گیا تو حضورؐ نے فرمایا اے عمار! کیا کر کے آئے ہو؟ (اپنی کارگزاری سناؤ) میں نے ان کے تمام حالات سنائے اور ان میں جو لا پرواہی اور غفلت تھی وہ بھی بتائی۔ حضورؐ نے فرمایا اے عمار! کیا میں تمہیں اس سے بھی زیادہ عجیب لوگ نہ بتاؤں جو کہ ان باتوں سے واقف ہیں جن سے یہ ناواقف تھے لیکن پھر بھی وہ ان کی طرح غفلت میں پڑے ہوئے ہیں۔",""],[" (7)","s"]]]],"f":[["(7)","Bazzaar and Tabraani in his Kabeer, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.91)."]]},{"b":[["n",[["حضرت حارثہ بن مضربؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ نے جو خط کوفہ والوں کو بھیجا تھا وہ میں نے پڑھا تھا، اس میں لکھا ہوا تھا امابعد! میں تمہارے پاس حضرت عمارؓ کو امیر بنا کر اور حضرت عبد",""],["ٱللَّٰه","a"],["ؓ کو استاد اور وزیر بنا کر بھیج رہا ہوں۔ یہ دونوں حضورؐ کے چیدہ اور برگزیدہ صحابہ میں سے ہیں، ان دونوں کی بات سنو اور ان دونوں کی اقتداء کرو۔ اور حضرت عبد",""],["ٱللَّٰه","a"],["ؓ کو بھیجنے میں انہوں نے بڑی قربانی دی ہے کیونکہ مجھے ان کی یہاں ضرورت تھی لیکن میں نے تمہاری ضرورت کو مقدم رکھا۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Sa'd (Vol.6 Pg.7)."]]},{"b":[["n",[["حضرت ابوالاسود دؤلیؒ","b"],[" کہتے ہیں میں بصرہ گیا تو وہاں حضرت عمران بن حصین ابو نجیدؓ تشریف فرما تھے، انہیں حضرت عمر بن خطابؓ نے بصرہ اس لیے بھیجا تھا تا کہ وہ بصرہ والوں میں دین کی سمجھ پیدا کریں۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Sa'd (Vol.7 Pg.10)."]]},{"b":[["n",[["حضرت محمد بن کعب قرظیؒ","b"],[" کہتے ہیں کہ نبی کریمؐ کے زمانے میں انصار میں سے صرف پانچ آدمیوں نے سارے قرآن کو یاد کیا تھا: حضرت معاذ بن جبل، حضرت عبادہ بن صامت، حضرت ابی بن کعب، حضرت ابوایوب اور حضرت ابوالدرداءؓ۔ حضرت عمر بن خطابؓ کے زمانے میں حضرت یزید بن ابی سفیانؓ نے انہیں خط لکھا کہ شام والے بہت زیادہ مسلمان ہو گئے ہیں اور سارے شہر ان سے بھر گئے ہیں اور انہیں ایسے آدمیوں کی شدید ضرورت ہے جو انہیں قرآن سکھائیں اور ان میں دین کی سمجھ پیدا کریں۔ اے امیر المومنین! سکھانے والے آدمی بھیج کر آپ میری مدد کریں۔ پھر حضرت عمرؓ نے ان پانچوں حضرات کو بلایا اور ان سے فرمایا تمہارے شامی بھائیوں نے مجھ سے مدد مانگی ہے کہ میں ان کے پاس ایسے آدمی بھیجوں جو انہیں قرآن سکھائیں اور ان میں دین کی سمجھ پیدا کریں۔ ",""],["ٱللَّٰه","a"],[" آپ لوگوں پر رحم فرمائے۔ آپ لوگ اپنے میں سے تین آدمی اس کام کے لیے دے کر میری مدد کریں۔ اب اگر آپ لوگ چاہیں تو قرعہ اندازی کر لیں یا پھر جو اپنا نام از خود پیش کر دے وہ چلا جائے۔ ان حضرات نے کہا نہیں، قرعہ اندازی کی ضرورت نہیں ہے۔ یہ حضرت ابوایوبؓ تو بہت بوڑھے ہیں اور یہ حضرت ابی بن کعبؓ بیمار ہیں، چنانچہ حضرت معاذ بن جبلؓ، حضرت عبادہؓ، حضرت ابوالدرداءؓ ملک شام گئے۔ ان سے حضرت عمرؓ نے فرمایا حمص شہر سے شروع کرو کیونکہ تم لوگوں کو مختلف استعداد والا پاؤ گے۔ بعض ایسے بھی ہوں گے جو جلدی سیکھ جائیں گے۔ جب تمہیں کوئی ایسا آدمی نظر آئے تو دوسرے لوگوں کو اس کی طرف متوجہ کر دو (کہ وہ اس سے علم حاصل کریں)۔ جب تم حمص والوں کے بارے میں مطمئن ہو جاؤ تو پھر تم میں سے ایک وہاں ہی ٹھہر جائے اور ایک دمشق چلا جائے اور ایک فلسطین۔ چنانچہ یہ حضرات حمص تشریف لے گئے اور وہاں ٹھہر کر انہیں سکھاتے رہے۔ جب ان کے بارے میں اطمینان ہو گیا تو حضرت عبادہؓ وہاں ٹھہر گئے اور حضرت ابوالدرداءؓ دمشق اور حضرت معاذؓ فلسطین چلے گئے۔ حضرت معاذؓ کا تو طاعون عمواس میں انتقال ہو گیا، بعد میں حضرت عبادہؓ فلسطین چلے گئے، ان کا بھی وہاں ہی انتقال ہوا، البتہ حضرت ابوالدرداءؓ دمشق ہی رہے اور ان کا وہاں ہی انتقال ہوا۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Sa'd (Vol.4 Pg.172) and Haakim, as quoted in Kanzul Ummaal (Vol.1 Pg.281). Bukhaari has reported a similar narration in his Taareekh Sagheer (Pg.22)."]]}]},"69":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن محمد بن عقیلؒ","b"],[" کہتے ہیں کہ میں نے حضرت جابر بن عبد",""],["ٱللَّٰه","a"],["ؓ کو یہ فرماتے ہوئے سنا کہ مجھے خبر پہنچی کہ ایک آدمی نے حضورؐ سے ایک حدیث سنی ہے (اور میں نے وہ حدیث حضورؐ سے نہیں سنی تھی) اور پتہ چلا کہ وہ صحابی شام میں رہتے ہیں، اس لیے میں نے اونٹ خریدا اور اس پر کجاوہ کسا اور ایک ماہ کا سفر کر کے ملک شام پہنچا۔ وہاں جا کر معلوم ہوا کہ وہ صحابی حضرت عبد",""],["ٱللَّٰه","a"],[" بن انیسؓ ہیں۔ میں نے ان کے دربان سے کہا کہ جا کر کہو کہ دروازے پر جابر آیا ہے۔ انہوں نے کہا کیا عبد",""],["ٱللَّٰه","a"],[" کے بیٹے؟ میں نے کہا جی ہاں۔ وہ یہ سنتے ہی ایک دم اپنا کپڑا گھسیٹتے باہر آئے اور میرے گلے لگ گئے اور میں نے بھی انہیں گلے لگا لیا۔ پھر میں نے کہا مجھے یہ خبر ملی ہے کہ آپ نے قصاص کے بارے میں حضورؐ سے ایک حدیث سنی ہے تو مجھے یہ ڈر ہوا کہ کہیں اس کے سننے سے پہلے آپ کا یا میرا انتقال نہ ہو جائے (اس لیے میں اتنا لمبا سفر کر کے صرف اسی حدیث کو سننے آیا ہوں)۔ انہوں نے کہا میں نے حضورؐ کو یہ ارشاد فرماتے ہوئے سنا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ قیامت کے دن تمام لوگوں کو اس حال میں جمع کریں گے کہ سب ننگے بدن، بغیر ختنے کے اور خالی ہاتھ ہوں گے۔ ہم نے پوچھا خالی ہاتھ ہونے کا کیا مطلب ہے؟ حضورؐ نے فرمایا ان کے ساتھ دنیا کی کوئی چیز نہ ہوگی۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ ان میں ایسی آواز سے اعلان فرمائیں گے جسے دور والا بھی اسی طرح سن لے گا جیسے نزدیک والا: میں بدلہ لینے والا ہوں اور میں (ہر چیز کا) مالک ہوں۔ جس دوزخی پر کسی جنتی کا کوئی حق ہے وہ اس وقت تک دوزخ میں نہیں جا سکتا جب تک میں اس دوزخی سے اس جنتی کا بدلہ نہ لے لوں اور جس جنتی پر کسی دوزخی کا کوئی حق ہے وہ اس وقت تک جنت میں نہیں جا سکتا جب تک میں اس سے اس دوزخی کا بدلہ نہ لے لوں اور اس میں کسی کی رعایت بالکل نہیں کروں گا، اگر صرف تھپڑ ظلماً مارا ہوگا تو بھی اس سے تھپڑ کا بدلہ لوں گا۔ ہم نے پوچھا ",""],["ٱللَّٰه","a"],[" تعالیٰ بدلہ کس طرح لے کر دیں گے جب کہ ہم اس حال میں آئیں گے کہ ہم ننگے بدن، بغیر ختنے کے اور خالی ہاتھ ہوں گے؟ حضورؐ نے فرمایا یہ بدلہ نیکیوں اور برائیوں کے ذریعہ ہوگا (مظلوم کو ظالم کی نیکیاں مل جائیں گی اور مظلوم کے گناہ ظالم پر ڈال دیے جائیں گے)۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad and Tabraani. Haythami (Vol.1 Pg.133) has commented on the chain of narrators. Bukhaari in his Adab and Abu Ya'la have reported a similar narration, as quoted in Fat'hul Baari (Vol.1 Pg.127), as have Ibn Abdul Birr in his Jaami (Vol.1 Pg.93) and Haakim (Vol.4 Pg.574)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں کہ مجھے قصاص کے بارے میں نبی کریمؐ سے ایک حدیث پہنچی اور لوگوں میں حدیث بیان کرنے والے صحابی مصر میں تھے، چنانچہ میں نے ایک اونٹ خریدا اور سفر کر کے مصر پہنچا اور اس صحابی کے دروازے پر گیا۔ آگے پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani in Masnadush Shaami'een and Tammaam in his Fawaa'id, as quoted in Fat'hul Baari."]]},{"b":[["n",[["حضرت مسلمہ بن مخلدؓ","b"],[" فرماتے ہیں کہ جس زمانے میں میں مصر کا امیر تھا ایک دن دربان نے آ کر کہا کہ دروازے پر ایک دیہاتی آدمی اونٹ پر آیا ہے اور اندر آنے کی اجازت طلب کر رہا ہے۔ میں نے پوچھا آپ کون ہیں؟ انہوں نے کہا جابر بن عبد",""],["ٱللَّٰه","a"],[" انصاریؓ۔ میں نے بالا خانے سے جھانک کر کہا میں نیچے آ جاؤں یا آپ اوپر آئیں گے؟ انہوں نے کہا نہ آپ نیچے اتریں اور نہ مجھے اوپر چڑھنے کی ضرورت ہے، مجھے یہ خبر ملی ہے کہ آپ مسلمان کے عیب چھپانے کے بارے میں ایک حدیث حضورؐ سے روایت کرتے ہیں، میں اسے سننے آیا ہوں۔ میں نے کہا میں نے حضورؐ کو یہ فرماتے ہوئے سنا کہ جو کسی مسلمان کے عیب پر پردہ ڈالے گا گویا اس نے زندہ درگور لڑکی کو زندہ کر دیا۔ یہ حدیث سن کر حضرت جابرؓ نے واپس جانے کے لیے سواری کو ہانکا۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani in his Awsat. Haythami has commented on the chain of narrators."]]},{"b":[["n",[["حضرت منیبؒ","b"],[" کہتے ہیں کہ میرے چچا نے فرمایا کہ نبی کریمؐ کے ایک صحابی کو یہ خبر ملی کہ حضورؐ کے ایک اور صحابی حضورؐ سے یہ روایت بیان کرتے ہیں کہ جو آدمی اپنے مسلمان بھائی کے (عیب) پر دنیا میں پردہ ڈالے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ قیامت کے دن اس (کے گناہوں) پر پردہ ڈالیں گے، وہ روایت بیان کرنے والے صحابی مصر میں تھے تو پہلے صحابی سفر کر کے ان کے پاس مصر گئے اور ان سے اس حدیث کے بارے میں پوچھا۔ انہوں نے کہا جی ہاں، میں نے حضورؐ کو یہ فرماتے ہوئے سنا کہ جو آدمی اپنے مسلمان بھائی (کے عیب) پر دنیا میں پردہ ڈالے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ قیامت کے دن اس (کے گناہوں) پر پردہ ڈالیں گے۔ پہلے صحابی نے کہا میں نے بھی یہ حدیث حضورؐ سے سنی ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Ahmad. Haythami (Vol.1 Pg.134) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن جریجؒ","b"],[" کہتے ہیں کہ حضرت ابوایوبؓ سواری پر سفر کر کے مصر حضرت عقبہ بن عامرؓ کے پاس گئے اور فرمایا میں آپ سے ایک ایسی حدیث کے بارے میں پوچھنا چاہتا ہوں کہ اس حدیث کے موقع پر جتنے صحابہؓ حضورؐ کی خدمت میں حاضر تھے اب ان میں صرف میں اور آپ باقی رہ گئے ہیں۔ آپ نے مسلمانوں کی پردہ پوشی کے بارے میں حضورؐ کو یہ فرماتے ہوئے سنا؟ حضرت عقبہؓ نے کہا میں نے حضورؐ کو یہ فرماتے ہوئے سنا کہ جو دنیا میں کسی مسلمان کے (عیب) پر پردہ ڈالے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ قیامت کے دن اس (کے گناہوں) پر پردہ ڈالیں گے۔ یہ سن کر حضرت ابوایوبؓ مدینہ واپس لوٹ گئے اور جب تک یہ حدیث بیان نہ کر دی اس وقت تک اپنا کجاوہ نہ کھولا۔ ",""],["حضرت ابن جریجؒ","b"],[" کہتے ہیں کہ میں نے مدینہ کے ایک بڑے میاں حضرت ابوسعید اعمیؒ کو سنا کہ وہ حضرت عطاءؒ سے یہ واقعہ بیان کر رہے تھے کہ حضرت ابوایوبؓ نے حضرت عقبہ بن عامرؓ سے ملنے کے لیے (مصر کا) سفر کیا۔ جب وہ مصر پہنچ گئے تو لوگوں نے ان کے آنے کا تذکرہ حضرت عقبہؓ سے کیا۔ حضرت عقبہؓ ان کے پاس باہر آئے، پھر اس کے بعد پچھلی حدیث جیسا مضمون ذکر کیا، اس کے بعد یہ ہے کہ یہ حدیث سن کر حضرت ابوایوبؓ اپنی سواری کے پاس آئے اور اس پر سوار ہو کر مدینہ واپس لوٹ گئے اور اپنا کجاوہ بھی نہیں کھولا۔",""],[" (5)","s"]]]],"f":[["(5)","Ahmad. A similar narration has been reported by Ibn Abdul Birr in his Isti'aab (Vol.1 Pg.93)."]]},{"b":[["n",[["حضرت عقبہ بن عامرؓ","b"],[" حضرت مسلمہ بن مخلدؓ سے ملنے گئے تو ان کے اور دربان کے درمیان کچھ جھگڑا ہو گیا۔ حضرت مسلمہؓ نے اندر سے ان کی آواز سن لی اور اندر آنے کی اجازت دے دی۔ حضرت عقبہؓ نے کہا میں آپ کو ملنے نہیں آیا بلکہ کسی ضرورت سے آیا ہوں اور وہ یہ ہے کہ کیا آپ کو وہ دن یاد ہے کہ جس دن حضورؐ نے فرمایا تھا کہ جسے اپنے بھائی کی کسی برائی کا پتہ چلے اور وہ اس پر پردہ ڈال دے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ قیامت کے دن اس پر پردہ ڈالیں گے۔ حضرت مسلمہؓ نے کہا جی ہاں۔ حضرت عقبہؓ نے کہا بس میں اسی لیے آیا تھا۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani in his Kabeer and Awsat, as quoted by Haythami (Vol.1 Pg.134)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن بریدہؒ","b"],[" کہتے ہیں کہ ایک صحابی نے صرف ایک حدیث سننے کے لیے حضرت فضالہ بن عبیدؓ کے پاس مصر کا سفر کیا۔ دارمی میں اس کے بعد یہ مضمون ہے کہ وہ صحابی جب حضرت فضالہؓ کے پاس پہنچے تو وہ اپنی اونٹنی کو جو ملا ہوا پانی پلا رہے تھے، انہیں آتا ہوا دیکھ کر حضرت فضالہؓ نے خوش آمدید کہا۔ انہوں نے کہا میں آپ سے ملنے نہیں آیا بلکہ اس وجہ سے آیا ہوں کہ میں نے اور آپ نے حضورؐ کی ایک حدیث سنی تھی، مجھے امید ہے کہ وہ آپ کو اب بھی یاد ہوگی۔ حضرت فضالہؓ نے پوچھا وہ کون سی حدیث ہے؟ انہوں نے کہا کہ اس حدیث میں یہ اور یہ مضمون ہے۔",""],[" (7)","s"],[" (8)","s"]]]],"f":[["(7)","Abu Dawood, as quoted in Fat'hul Baari (Vol.1 Pg.128)."],["(8)","Daarimi (Pg.55)."]]},{"b":[["n",[["حضرت عبید","b"],["ٱللَّٰه","a"],[" بن عدیؒ","b"],[" فرماتے ہیں کہ مجھے پتہ چلا کہ حضرت علیؓ کے پاس ایک حدیث ہے تو مجھے اس بات کا ڈر ہوا کہ کہیں اگر حضرت علیؓ کا انتقال ہو گیا تو پھر شاید مجھے یہ حدیث کسی اور کے پاس نہ مل سکے، اس وجہ سے میں سفر کر کے ان کے پاس عراق گیا۔ ابن عساکر میں اس کے بعد یہ مضمون ہے کہ میں نے اس حدیث کے بارے میں پوچھا، انہوں نے مجھے وہ حدیث سنائی اور مجھ سے یہ عہد لیا کہ میں یہ حدیث کسی اور سے بیان نہ کروں، اگر وہ ایسا نہ کرتے تو میں آپ لوگوں کو وہ حدیث ضرور سنا دیتا۔ حضرت ابن مسعودؓ کا فرمان آگے آ رہا ہے جو بخاری میں منقول ہے کہ اگر مجھے کسی کے بارے میں پتہ چل جائے کہ وہ مجھ سے زیادہ ",""],["ٱللَّٰه","a"],[" کی کتاب کو جانتا ہے تو میں ضرور سفر کر کے اس کے پاس جاؤں، اور ابن عساکر میں ان کا یہ فرمان منقول ہے کہ اگر مجھے کسی کے بارے میں یہ پتہ چلے کہ اونٹ مجھے اس تک پہنچا سکتے ہیں اور وہ حضرت محمدؐ پر نازل ہونے والے علوم کو مجھ سے زیادہ جانتا ہے تو میں ضرور اس کے پاس جاؤں گا تا کہ میرے علم میں اور اضافہ ہو سکے۔",""],[" (9)","s"],[" (10)","s"],[" (11)","s"],[" (12)","s"]]]],"f":[["(9)","Khateeb, as quoted in Fat'hul Baari (Vol.1 Pg.128). Ibn Asaakir has reported a similar narration, as quoted in Kanzul Ummaal (Vol.5 Pg.239)."],["(10)","Ibn Asaakir has reported a similar narration, as quoted in Kanzul Ummaal (Vol.5 Pg.239)."],["(11)","Bukhaari."],["(12)","Ibn Asaakir."]]}]},"70":{"lead":[],"stories":[{"b":[["n",[["حضرت ابو ثعلبہؓ","b"],[" فرماتے ہیں کہ میں حضورؐ سے ملا، میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مجھے ایسے آدمی کے حوالے فرما دیں جو اچھی طرح سکھانے والا ہو۔ آپؐ نے مجھے حضرت ابوعبیدہ بن جراحؓ کے حوالے فرما دیا اور ارشاد فرمایا میں نے تمہیں ایسے آدمی کے حوالے کیا ہے جو تمہیں اچھی طرح تعلیم دے گا اور اچھی طرح ادب سکھائے گا۔ طبرانی میں اس کے بعد یہ مضمون ہے کہ جب میں حضرت ابوعبیدہؓ کی خدمت میں پہنچا تو وہ اور حضرت بشیر بن سعد ابو نعمانؓ آپس میں باتیں کر رہے تھے۔ مجھے دیکھ کر وہ دونوں حضرات خاموش ہو گئے۔ میں نے کہا اے ابو عبیدہ! ",""],["ٱللَّٰه","a"],[" کی قسم! حضورؐ نے تو اس طرح مجھے بیان نہیں کیا تھا، یعنی وہ تو مجھے دیکھ کر خاموش نہیں ہوئے تھے۔ انھوں نے کہا بیٹھ جاؤ، ہم تمہیں حدیث سنائیں گے۔ پھر فرمایا حضورؐ نے ارشاد فرمایا تم میں تو اس وقت نبوت کا دور ہے، پھر نبوت کے طرز پر خلافت ہوگی، پھر بادشاہت اور جبر ہوگا۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.7 Pg.95)."],["(2)","Tabraani. Haythami (Vol.5 Pg.189) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! امر بالمعروف اور نہی عن المنکر کب چھوڑا جائے گا؟ آپؐ نے فرمایا جب تم میں وہ باتیں ظاہر ہو جائیں گی جو تم سے پہلے بنی اسرائیل میں ظاہر ہوئی تھیں۔ میں نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! وہ باتیں کیا ہیں؟ آپؐ نے فرمایا جب تمہارے نیک اور بہترین آدمیوں میں سستی اور تمہارے برے لوگوں میں بے حیائی ظاہر ہو جائے گی اور بادشاہت تمہارے چھوٹوں میں اور دینی علم تمہارے کمینوں میں منتقل ہو جائے گا۔ ",""],["حضرت ابوامیہ جمحیؒ","b"],[" فرماتے ہیں حضورؐ سے قیامت کی نشانیوں کے بارے میں پوچھا گیا، آپؐ نے فرمایا قیامت کی ایک نشانی یہ ہے کہ علم چھوٹوں کے پاس تلاش کیا جانے لگے گا۔",""],[" (3)","s"],[" (4)","s"]]]],"f":[["(3)","Ibn Asaakir and Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.2 Pg.139). Ibn Abdul Birr has also reported the narration in his Jaami (Vol.1 Pg.157)."],["(4)","Ibn Abdul Birr in his Jaami. Tabraani has also reported the narration but Haythami (Vol.1 Pg.135) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عکیمؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ فرمایا کرتے تھے غور سے سنو! سب سے سچی بات ",""],["ٱللَّٰه","a"],[" تعالیٰ کی ہے اور سب سے اچھا طریقہ حضرت محمدؐ کا ہے اور سب سے برے کام وہ ہیں جو نئے ایجاد کیے جائیں۔ غور سے سنو! لوگ اس وقت تک خیر پر رہیں گے جب تک ان کے پاس علم ان کے بڑوں کی طرف سے آئے گا۔ ",""],["حضرت بلال بن یحییٰؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ نے فرمایا مجھے معلوم ہے کہ لوگ کب سدھرتے ہیں اور کب بگڑتے ہیں؟ جب علم چھوٹے کی طرف سے آئے گا تو بڑا اس کی نافرمانی کرے گا اور جب علم بڑے کی طرف سے آئے گا تو چھوٹا اس کی اتباع کرے گا اور دونوں ہدایت پا جائیں گے۔",""],[" (5)","s"],[" (6)","s"]]]],"f":[["(5)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.158)."],["(6)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.158)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ لوگ اس وقت تک نیکو کار اور اپنے دین پر پختہ رہیں گے جب تک ان کے پاس علم حضرت محمدؐ کے صحابہؓ کی طرف سے اور ان کے اپنے بڑوں کی طرف سے آئے گا اور جب ان کے پاس علم ان کے چھوٹوں کی طرف سے آنے لگے گا تو پھر لوگ ہلاک ہو جائیں گے۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani in his Kabeer and Awsat, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.135). Ibn Abdul Birr has also reported the narration in his Jaami (Vol.1 Pg.159)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں لوگ اس وقت تک خیر پر رہیں گے جب تک وہ علم اپنے بڑوں سے حاصل کریں گے اور جب علم اپنے چھوٹوں اور اپنے بروں سے حاصل کرنے لگیں گے تو ہلاک ہو جائیں گے۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.159)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں تم لوگ اس وقت تک خیر پر رہو گے جب تک علم تمہارے بڑوں میں رہے گا۔ اور جب علم تمہارے چھوٹوں میں آ جائے گا تو چھوٹے بڑے کو بیوقوف بنائیں گے۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.159)."]]},{"b":[["n",[["حضرت معاویہؓ","b"],[" فرماتے ہیں کہ سب سے زیادہ گمراہ کرنے والا انسان وہ ہے جو قرآن پڑھے اور اس کے معنی اور مطلب کو نہ سمجھے، پھر وہ بچے، غلام، عورت اور باندی کو قرآن سکھائے، پھر یہ سب مل کر قرآن کے ذریعے علم والوں سے جھگڑا کریں۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.194)."]]},{"b":[["n",[["حضرت ابوحازمؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ نے فرمایا اس امت پر مجھے کسی مومن کی طرف سے کوئی خطرہ نہیں ہے کیونکہ اسے اس کا ایمان برے کام سے روک لے گا اور اس فاسق کی طرف سے بھی کوئی خطرہ نہیں ہے جس کا فاسق ہونا کھلا اور واضح ہو۔ مجھے تو اس امت پر اس آدمی کی طرف سے خطرہ ہے جس نے قرآن تو پڑھا ہے لیکن زبان سے اچھی طرح پڑھ کر وہ صحیح راستے سے پھسل گیا، یعنی زبان سے پڑھنے کو ہی اصل سمجھ لیا اور قرآن کی صحیح تفسیر چھوڑ کر اس سے اپنی طرف سے اس کا مطلب بنا لیا۔",""],[" (11)","s"]]]],"f":[["(11)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.194)."]]},{"b":[["n",[["حضرت عقبہ بن عامرؓ","b"],[" کے انتقال کا وقت جب قریب آیا تو انہوں نے فرمایا اے میرے بیٹو! میں تمہیں تین باتوں سے روکتا ہوں، انہیں اچھی طرح یاد رکھنا۔ حضورؐ کی طرف سے حدیث صرف معتبر اور قابل اعتماد آدمی سے ہی لینا اور کسی اور سے نہ لینا اور قرضہ لینے کی عادت نہ بنا لینا چاہے تمہیں چغہ پہن کر ہی گزارا کرنا پڑے اور اشعار لکھنے میں نہ لگ جانا ورنہ ان میں تمہارے دل ایسے مشغول ہو جائیں گے کہ قرآن سے رہ جاؤ گے۔",""],[" (12)","s"]]]],"f":[["(12)","Tabraani. Haythami (Vol.1 Pg.140) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضرت عمر بن خطابؓ نے جابیہ مقام میں لوگوں میں بیان فرمایا اور ارشاد فرمایا اے لوگو! تم میں سے جو قرآن کے بارے میں کچھ پوچھنا چاہتا ہے وہ حضرت ابی بن کعبؓ کے پاس جائے اور جو میراث کے بارے میں پوچھنا چاہتا ہے وہ حضرت زید بن ثابتؓ کے پاس جائے اور جو کوئی فقہی مسائل پوچھنا چاہتا ہے وہ حضرت معاذ بن جبلؓ کے پاس جائے اور جو مال لینا چاہتا ہے وہ میرے پاس آ جائے کیونکہ ",""],["ٱللَّٰه","a"],[" نے مجھے مال کا والی اور اس کی تقسیم کرنے والا بنایا ہے۔",""],[" (13)","s"]]]],"f":[["(13)","Tabraani in his Awsat. Haythami (Vol.1 Pg.135) has commented on the chain of narrators."]]}]},"71":{"lead":[],"stories":[{"b":[["n",[["حضرت صفوان بن عسال مرادیؓ","b"],[" فرماتے ہیں کہ میں نبی کریمؐ کی خدمت میں حاضر ہوا، آپؐ اس وقت مسجد میں اپنی سرخ دھاریوں والی چادر پر ٹیک لگائے ہوئے تھے، میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں علم حاصل کرنے آیا ہوں۔ آپؐ نے فرمایا طالب علم کو خوش آمدید ہو۔ آگے اور حدیث ذکر کی جیسے کہ باب کے شروع میں گزر چکی ہے۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابوہارونؒ","b"],[" کہتے ہیں کہ جب ہم حضرت ابوسعیدؓ کی خدمت میں جاتے تو فرماتے خوش آمدید ہو ان لوگوں کو جن کے بارے میں حضورؐ نے ہمیں وصیت فرمائی تھی۔ حضورؐ نے فرمایا تھا لوگ تمہارے تابع ہوں گے اور زمین کے آخری کناروں سے تمہارے پاس دین کی سمجھ حاصل کرنے کے لیے آئیں گے۔ جب وہ تمہارے پاس آئیں تو ان کے ساتھ اچھا سلوک کرنے کی وصیت مجھ سے قبول کر لو۔ ",""],["حضرت ابوسعیدؓ","b"],[" حضورؐ کا یہ ارشاد نقل کرتے ہیں کہ تمہارے پاس مشرق کی طرف سے لوگ علم حاصل کرنے آئیں گے۔ جب وہ تمہارے پاس آئیں تو تم ان کے ساتھ اچھا سلوک کرنا۔ راوی کہتے ہیں چنانچہ حضرت ابوسعیدؓ جب ہمیں دیکھتے تو فرماتے خوش آمدید ہو ان لوگوں کو جن کے بارے میں حضورؐ نے ہمیں وصیت فرمائی تھی۔ ترمذی کی ایک روایت میں مزید یہ بھی ہے کہ ",""],["ٱللَّٰه","a"],[" نے تمہیں جو علم عطا فرما رکھا ہے وہ انہیں بھی سکھاؤ۔ ایک روایت میں یہ ہے کہ مختلف دور دراز علاقوں سے لوگ آئیں گے جو تم سے دین کے بارے میں پوچھیں گے۔ جب وہ تمہارے پاس آئیں تو ان کے لیے جگہ میں گنجائش پیدا کرو اور ان کے ساتھ اچھا سلوک کرنے کی وصیت قبول کرو اور ان کو سکھاؤ۔ ابن عساکر کی روایت میں یہ ہے کہ انہیں سکھاؤ اور انہیں کہو خوش آمدید، خوش آمدید، قریب ہو جاؤ۔",""],[" (1)","s"],[" (2)","s"],[" (3)","s"],[" (4)","s"]]]],"f":[["(1)","Tirmidhi."],["(2)","Tirmidhi and Ibn Maajah (Pg.37). Haakim (Vol.1 Pg.88) has reported a similar narration from reliable sources as confirmed by Dhahabi."],["(3)","Ibn Jareer and Ibn Asaakir."],["(4)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.5 Pg.243)."]]},{"b":[["n",[["حضرت ابوسعیدؓ","b"],[" کے پاس جب یہ نوعمر جوان آتے تو فرماتے خوش آمدید ہو ان لوگوں کو جن کے بارے میں حضورؐ نے ہمیں وصیت فرمائی تھی۔ ہمیں حضورؐ نے حکم دیا تھا کہ ہم ان کے لیے مجلس میں گنجائش پیدا کریں اور ان کو حدیث سمجھائیں کیونکہ آپ لوگ ہی ہمارے بعد جگہ سنبھالنے والے ہیں اور احادیث دوسروں کو سنانے والے ہیں۔ اور ان نوجوانوں سے فرمایا کرتے تھے اگر تمہیں کوئی بات سمجھ میں نہ آئے تو مجھ سے سمجھ لینا کیونکہ تم سمجھ کر اٹھو یہ مجھے اس سے زیادہ محبوب ہے کہ تم بے سمجھے اٹھ جاؤ۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.5 Pg.243)."]]},{"b":[["n",[["حضرت اسماعیلؒ","b"],[" کہتے ہیں کہ ہم لوگ حضرت حسنؒ کے پاس عیادت کے لیے گئے۔ ہماری تعداد اتنی زیادہ تھی کہ سارا گھر بھر گیا تو انہوں نے اپنے پاؤں سمیٹ کر فرمایا ہم لوگ حضرت ابوہریرہؓ کی عیادت کرنے کے لیے گئے، ہماری تعداد اتنی زیادہ تھی کہ سارا گھر بھر گیا۔ انہوں نے اپنے پاؤں سمیٹ کر فرمایا ہم لوگ حضورؐ کی عیادت کرنے گئے اور ہماری تعداد اتنی زیادہ تھی کہ سارا گھر بھر گیا، آپؐ پہلو کے بل لیٹے ہوئے تھے، جب آپؐ نے ہمیں دیکھا تو اپنے پاؤں سمیٹ لیے اور فرمایا میرے بعد تمہارے پاس بہت لوگ علم حاصل کرنے کے لیے آئیں گے، تم انہیں خوش آمدید کہنا اور ان سے سلام اور مصافحہ کرنا اور انہیں خوب سکھانا۔ حضرت حسنؒ کہتے ہیں ",""],["ٱللَّٰه","a"],[" کی قسم! ہمیں تو ایسے لوگ ملے جنہوں نے نہ تو ہمیں خوش آمدید کہا اور نہ ہم سے سلام اور مصافحہ کیا اور نہ ہمیں سکھایا بلکہ جب ہم ان کے پاس گئے تو ہمارے ساتھ جفا کا معاملہ کیا (حضرت حسن بصریؒ صحابہؓ کے بعد والے لوگوں کی شکایت کر رہے ہیں)۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Maajah (Pg.37)."]]},{"b":[["n",[["حضرت ام درداءؓ","b"],[" فرماتی ہیں کہ جب بھی حضرت ابودرداءؓ کوئی حدیث بیان کرتے تو ضرور مسکراتے، تو میں نے ان سے کہا مجھے اس بات کا ڈر ہے کہ اس طرح لوگ آپ کو بے وقوف سمجھنے لگیں گے۔ انھوں نے فرمایا حضورؐ جب بھی بات فرماتے تو ضرور مسکراتے۔",""],[" (7)","s"]]]],"f":[["(7)","Ahmad and Tabraani in his Kabeer. Haythami (Vol.1 Pg.131) has commented on the chain of narrators."]]}]},"72":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ ایک آدمی نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! ہمارے ساتھ بیٹھنے والوں میں کون سب سے بہترین ہے؟ آپؐ نے فرمایا جس کے دیکھنے سے تمہیں ",""],["ٱللَّٰه","a"],[" یاد آئے اور جس کی گفتگو سے تمہارے علم میں اضافہ ہو اور جس کے عمل سے تمہیں آخرت یاد آئے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Ya'la. Mundhiri (Vol.1 Pg.76) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت قرہؓ","b"],[" فرماتے ہیں کہ جب حضورؐ مجلس میں تشریف فرما ہوتے تو آپؐ کے صحابہؓ آپؐ کے پاس کئی حلقے بنا کر بیٹھ جاتے (اور آپس میں سیکھنے سکھانے لگ جاتے اور جب ضرورت پڑتی تو حضورؐ سے پوچھ لیتے)۔",""],[" (2)","s"]]]],"f":[["(2)","Bazzaar."]]},{"b":[["n",[["حضرت یزید رقاشیؒ","b"],[" کہتے ہیں کہ جب حضرت انسؓ ہمیں حدیث سناتے تو یہ بھی فرماتے یہ حدیث ایسے نہیں سیکھی جاتی تھی جس طرح تم اور تمہارے ساتھی کرتے ہیں کہ ایک آدمی بیٹھ جاتا ہے اور سب اس کے گرد جمع ہو جاتے ہیں اور وہ ان میں بیان کرتا ہے، بلکہ صحابہ کرامؓ فجر کی نماز سے فارغ ہو کر کئی حلقے بنا لیتے اور ان حلقوں میں قرآن پڑھتے اور فرائض اور سنتیں سیکھتے۔",""],[" (3)","s"]]]],"f":[["(3)","Majma'uz Zawaa'id (Vol.1 Pg.132)."]]},{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں میں مہاجرین کی ایک جماعت میں ان کے ساتھ بیٹھا ہوا تھا اور ہمارے پاس کپڑے بہت کم تھے جس کی وجہ سے ہم ایک دوسرے کی اوٹ میں بیٹھے ہوئے تھے اور ہمارے ایک قاری قرآن پڑھ رہے تھے اور ہم سب ",""],["ٱللَّٰه","a"],[" کی کتاب سن رہے تھے۔ حضورؐ نے فرمایا تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے میری امت میں ایسے لوگ بھی بنائے ہیں کہ مجھے حکم دیا گیا ہے کہ میں اپنے آپ کو ان کے پاس بٹھاؤں۔ حضورؐ کے تشریف لانے پر گول حلقہ بن گیا اور سب نے چہرے حضورؐ کی طرف کر لیے لیکن آپؐ نے میرے علاوہ اور کسی کو نہیں پہچانا۔ پھر حضورؐ نے فرمایا اے فقراء مہاجرین! تمہیں خوشخبری ہو کہ تمہیں قیامت کے دن پورا نور حاصل ہوگا اور تم مالداروں سے آدھا دن پہلے جنت میں داخل ہو جاؤ گے اور یہ آدھا دن پانچ سو برس کا ہوگا۔",""],[" (4)","s"]]]],"f":[["(4)","Bayhaqi, as quoted in Al Bidaayah wan Nihaayah (Vol.6 Pg.57). Abu Nu'aym has reported the narration at greater length in his Hilya (Vol.1 Pg.342)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں کہ حضورؐ کا اپنی مسجد میں دو حلقوں پر گزر ہوا۔ ایک حلقہ والے دعا میں اور ",""],["ٱللَّٰه","a"],[" سے راز و نیاز کی باتوں میں لگے ہوئے تھے اور دوسرے حلقہ والے دینی علم سیکھ سکھا رہے تھے۔ حضورؐ نے فرمایا دونوں حلقے والے خیر پر ہیں لیکن ایک حلقہ والے دوسرے سے بہتر ہیں۔ یہ تو ",""],["ٱللَّٰه","a"],[" سے دعا کر رہے ہیں اور اس سے راز و نیاز میں لگے ہوئے ہیں، اگر ",""],["ٱللَّٰه","a"],[" چاہے گا تو ان کو دے گا اور اگر چاہے گا تو نہیں دے گا۔ یہ دوسرے حلقے والے سیکھ رہے ہیں اور جسے نہیں آتا اسے سکھا رہے ہیں اور مجھے تو سکھانے والا بنا کر ہی بھیجا گیا ہے۔ پھر آپؐ آ کر ان کے پاس بیٹھ گئے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.50). Daarimi has reported a similar narration."]]},{"b":[["n",[["حضرت ابوبکر بن ابی موسیٰؒ","b"],[" کہتے ہیں کہ حضرت ابوموسیٰؓ عشاء کے بعد حضرت عمر بن خطابؓ کے پاس آئے۔ حضرت عمرؓ نے پوچھا کیسے آنا ہوا؟ حضرت ابوموسیٰؓ نے کہا آپ سے کچھ بات کرنا چاہتا ہوں۔ حضرت عمرؓ نے فرمایا اس وقت؟ حضرت ابو موسیٰؓ نے کہا ہاں ایک ضروری دینی مسئلہ ہے، چنانچہ حضرت عمرؓ ان کے پاس بیٹھ گئے اور دونوں بہت دیر تک باتیں کرتے رہے۔ جب باتوں سے فارغ ہوئے تو حضرت ابوموسیٰؓ نے کہا اے امیر المومنین! تہجد کی نماز پڑھ لیں۔ حضرت عمرؓ نے فرمایا ہم تو نماز میں ہی تھے۔",""],[" (6)","s"]]]],"f":[["(6)","Abdur Razzaaq and Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.5 Pg.228)."]]},{"b":[["n",[["حضرت جندب بن عبد","b"],["ٱللَّٰه","a"],[" بجلیؒ","b"],[" کہتے ہیں میں علم حاصل کرنے مدینہ آیا۔ میں حضورؐ کی مسجد میں داخل ہوا تو میں نے دیکھا کہ لوگ حلقے بنا کر بیٹھے ہوئے ہیں اور باتیں کر رہے ہیں۔ میں حلقوں کے پاس سے گزرتا رہا اور چلتے چلتے ایک حلقہ کے پاس پہنچا تو اس میں ایک صاحب تھے جن کا رنگ بدلا ہوا تھا اور ان کے جسم پر دو کپڑے تھے، ایسے لگ رہا تھا کہ جیسے ابھی سفر سے آئے ہوں۔ میں نے انہیں فرماتے ہوئے سنا رب کعبہ کی قسم! لوگوں سے بیعت لینے والے بادشاہ ہلاک ہو گئے اور مجھے ان کا غم نہیں، اور یہ بات انھوں نے کئی مرتبہ کہی۔ میں ان کے پاس بیٹھ گیا۔ وہ کافی دیر تک حدیثیں بیان فرماتے رہے۔ ان کے بعد وہ کھڑے ہو گئے۔ ان کے کھڑے ہونے کے بعد میں نے ان کے بارے میں پوچھا کہ یہ کون ہیں؟ لوگوں نے بتایا یہ مسلمانوں کے سردار حضرت ابی بن کعبؓ ہیں۔ میں ان کے پیچھے ہو لیا یہاں تک کہ وہ اپنے گھر میں داخل ہو گئے۔ ان کا گھر بالکل پرانا سا تھا۔ اس کی شکل و صورت بوسیدہ تھی اور ان میں دنیا کی رغبت بالکل نہ تھی، بالکل دنیا سے الگ تھلگ تھے۔ ان کی تمام باتیں آپس میں ملتی جلتی تھیں۔ میں نے انہیں سلام کیا، انھوں نے سلام کا جواب دیا پھر مجھ سے پوچھا تم کن لوگوں میں سے ہو؟ میں نے کہا عراق والوں میں سے۔ انھوں نے فرمایا عراق والے تو مجھ سے بہت زیادہ سوالات کرتے ہیں۔ جب انھوں نے یہ فرمایا تو مجھے غصہ آ گیا اور میں نے گھٹنے کے بل بیٹھ کر اپنے ہاتھ چہرے تک اٹھائے اور قبلہ کی طرف منہ کر لیا اور میں نے دعا کرنی شروع کی۔ اے ",""],["ٱللَّٰه","a"],["! ہم تجھ ہی سے ان لوگوں کی شکایت کرتے ہیں کہ ہم نے بہت مال خرچ کیا اور اپنے جسموں کو خوب تھکایا اور اپنی سواریوں کو چلایا۔ یہ سب کچھ ہم نے علم حاصل کرنے کے لیے کیا۔ جب ہماری ان سے ملاقات ہوئی تو یہ ہمیں ترش روئی سے ملے اور ہمیں ایسے سخت کلمات کہہ دیے۔ یہ سن کر حضرت ابیؓ رونے لگے اور مجھے راضی کرنے لگے اور فرمانے لگے تیرا بھلا ہو! میرا مطلب یہ ہرگز نہیں تھا۔ پھر فرمانے لگے اے ",""],["ٱللَّٰه","a"],["! اگر تو نے مجھے آئندہ جمعہ تک زندہ رکھا تو میں نے جو کچھ حضورؐ سے سن رکھا ہے وہ سب ضرور بیان کر دوں گا اور کسی کی ملامت کی پرواہ نہیں کروں گا۔ اس کے بعد میں ان کے پاس سے واپس آ گیا اور اگلے جمعہ کا انتظار کرنے لگا۔ لیکن جمعرات کو میں کسی کام سے باہر آیا تو میں نے دیکھا کہ تمام گلیاں لوگوں سے بھری ہوئی ہیں۔ جس گلی میں جاتا ہوں وہاں لوگ ہی لوگ نظر آتے ہیں۔ میں نے پوچھا ان لوگوں کو کیا ہوا؟ لوگوں نے کہا ہمارا خیال ہے آپ اجنبی مسافر ہیں۔ میں نے کہا جی ہاں۔ لوگوں نے کہا مسلمانوں کے سردار حضرت ابی بن کعبؓ کا انتقال ہو گیا ہے۔ حضرت جندبؒ کہتے ہیں کہ میں عراق واپس آیا تو میری ملاقات حضرت ابوموسیٰؓ سے ہوئی اور میں نے انہیں حضرت ابیؓ کی ساری بات بتائی۔ انھوں نے فرمایا ہائے افسوس! کاش وہ زندہ رہ جاتے تا کہ ہمیں ان کی وہ خاص بات پہنچ جاتی۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Sa'd (Vol.3 Pg.501)."]]},{"b":[["n",[["حضرت ہلال بن یسافؒ","b"],[" کہتے ہیں کہ میں بصرہ آیا اور ایک مسجد میں داخل ہوا تو میں نے دیکھا ایک بڑے میاں جن کے سر اور داڑھی کے بال سفید ہیں ایک ستون سے ٹیک لگا کر لوگوں میں حدیث بیان کر رہے ہیں۔ میں نے پوچھا یہ کون ہیں؟ لوگوں نے بتایا یہ حضرت عمران بن حصینؓ ہیں۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Sa'd (Vol.4 Pg.291)."]]},{"b":[["n",[["حضرت ابوصالحؒ","b"],[" کہتے ہیں میں نے حضرت ابن عباسؓ کی ایسی زبردست مجلس دیکھی ہے کہ یہ سارے قریش والے اس پر فخر کریں تو بجا ہے۔ یہ واقعی قابل فخر مجلس ہے۔ میں نے ایک دن دیکھا کہ بہت سے لوگ ان کے گھر کے باہر راستہ پر جمع ہیں اور اتنے زیادہ ہیں کہ آنے جانے کی بالکل جگہ نہیں ہے۔ میں نے اندر جا کر حضرت ابن عباسؓ کو بتایا کہ دروازے پر بہت سے لوگ آئے ہوئے ہیں۔ انھوں نے فرمایا میرے لیے وضو کا پانی رکھو، چنانچہ وہ وضو کر کے بیٹھ گئے اور فرمایا باہر جاؤ اور لوگوں میں اعلان کرو کہ جو قرآن اور اس کے حروف اور اس کی کسی چیز کے بارے میں کچھ پوچھنا چاہتا ہے وہ اندر آ جائے۔ چنانچہ میں نے باہر جا کر یہ اعلان کیا تو ایک بہت بڑی تعداد اندر آئی جس سے سارا گھر اور حجرہ بھر گیا اور انھوں نے جو بات بھی پوچھی حضرت ابن عباسؓ نے اس کا جواب دیا اور جتنا انھوں نے پوچھا تھا بلکہ اس سے کہیں اور زیادہ اپنے پاس سے انہیں بتایا۔ پھر فرمایا اب اپنے دوسرے بھائیوں کو اندر آنے کا موقع دے دو۔ چنانچہ وہ لوگ باہر چلے گئے۔ پھر مجھ سے فرمایا باہر جا کر اب یہ اعلان کر دو کہ جو قرآن کی تفسیر اور شرح کے بارے میں کچھ پوچھنا چاہتا ہے وہ اندر آ جائے۔ چنانچہ میں نے باہر جا کر یہ اعلان کیا تو ایک بہت بڑی تعداد اندر آئی جس سے سارا گھر اور حجرہ بھر گیا اور انھوں نے جو بات بھی پوچھی حضرت ابن عباسؓ نے اس کا جواب دیا اور جتنا ان لوگوں نے پوچھا تھا اتنا بلکہ اس سے بھی زیادہ اپنے پاس سے بیان کر دیا، پھر فرمایا اب اپنے دوسرے بھائیوں کو اندر آنے کا موقع دے دو۔ چنانچہ وہ لوگ چلے گئے۔ پھر مجھ سے فرمایا باہر جا کر اعلان کر دو کہ جو حلال حرام اور فقہی مسائل پوچھنا چاہتا ہے وہ اندر آ جائے۔ چنانچہ میں نے باہر جا کر یہ اعلان کر دیا تو بہت بڑی تعداد اندر آئی جس سے سارا گھر اور حجرہ بھر گیا اور ان لوگوں نے جو بھی پوچھا اس کا انہیں جواب دیا اور اتنا ہی اور اپنے پاس سے بیان کر دیا، پھر ان سے فرمایا اپنے دوسرے بھائیوں کو موقع دے دو۔ چنانچہ وہ لوگ باہر چلے گئے۔ پھر مجھ سے فرمایا باہر جا کر اعلان کر دو کہ جو میراث وغیرہ جیسے مسائل پوچھنا چاہتا ہے وہ اندر آ جائے۔ چنانچہ میں نے باہر جا کر یہ اعلان کر دیا تو بہت بڑی تعداد اندر آئی جس سے سارا گھر اور حجرہ بھر گیا اور ان لوگوں نے جو بھی پوچھا حضرت ابن عباسؓ نے اس کا جواب دیا اور اتنا ہی اپنے پاس سے بیان کر دیا، پھر فرمایا اب اپنے دوسرے بھائیوں کو موقع دے دو۔ چنانچہ وہ لوگ باہر چلے گئے۔ پھر مجھ سے فرمایا باہر جا کر یہ اعلان کر دو کہ جو عربی لغت، اشعار اور انوکھے کلام کے بارے میں پوچھنا چاہتا ہے وہ اندر آ جائے۔ میں نے باہر جا کر یہ اعلان کر دیا جس پر ایک بہت بڑی تعداد داخل ہوئی جس سے سارا گھر اور حجرہ بھر گیا اور ان لوگوں نے جو بات بھی پوچھی اس کا حضرت ابن عباسؓ نے جواب دیا اور اتنا ہی اور اپنے پاس سے بیان کر دیا۔ اگر سارے قریش حضرت ابن عباسؓ کی اس مجلس پر فخر کریں تو انہیں فخر کرنے کا حق پہنچتا ہے اور میں نے اس جیسا منظر اور کسی کے ہاں نہیں دیکھا۔",""],[" (9)","s"]]]],"f":[["(9)","Abu Nu'aym in his Hilya (Vol.1 Pg.320). Haakim (Vol.3 Pg.538) has reported a similar narration."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا بہترین مجلس وہ ہے جس میں حکمت کی باتیں بیان کی جائیں۔ دوسری روایت میں یہ الفاظ ہیں کہ بہترین مجلس وہ ہے جس میں خوب حکمت کے موتی بکھیرے جائیں اور رحمت خداوندی کی پوری امید ہو (کیونکہ اس میں ایسے اعمال کیے جاتے ہیں جن کی وجہ سے ",""],["ٱللَّٰه","a"],[" کی رحمت نازل ہوتی ہے)۔",""],[" (10)","s"],[" (11)","s"]]]],"f":[["(10)","Tabraani in his Kabeer, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.167)."],["(11)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.50)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں متقی لوگ سردار ہیں اور فقیہ لوگ امت کے رہنما ہیں اور ان کے ساتھ بیٹھنے سے (ایمان و علم میں) اضافہ ہوتا ہے۔",""],[" (12)","s"]]]],"f":[["(12)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.126)."]]},{"b":[["n",[["حضرت ابوجحیفہؓ","b"],[" نے فرمایا کہ قیمتی اور کارآمد نصیحت کے طور پر یہ کہا جاتا تھا کہ بڑی عمر والوں کے پاس بیٹھا کرو اور علماء سے دوستی لگاؤ اور حکمت والے سمجھدار لوگوں سے میل جول رکھو۔ ",""],["حضرت ابودرداءؓ","b"],[" فرماتے ہیں کہ آدمی کے دینی سمجھ رکھنے کی ایک نشانی یہ بھی ہے کہ اس کا چلنا اور آنا جانا علم والوں کے پاس ہو۔ ایک روایت میں مزید یہ الفاظ بھی ہیں اور اس کا بیٹھنا بھی ان کے ساتھ ہو۔",""],[" (13)","s"],[" (14)","s"],[" (15)","s"]]]],"f":[["(13)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.126)."],["(14)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.127)."],["(15)","Abu Nu'aym in his Hilya (Vol.1 Pg.211)."]]}]},"73":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوحازمؒ","b"],[" کہتے ہیں کہ حضرت سہلؓ اپنی قوم کی مجلس میں حضورؐ کی حدیثیں بیان کر رہے تھے کہ کچھ لوگ آپس میں ایک دوسرے کی طرف متوجہ ہو کر باتیں کرنے لگے۔ انہیں غصہ آ گیا اور فرمایا میں انہیں حضورؐ کی وہ حدیثیں سنا رہا ہوں جنہیں میری آنکھوں نے دیکھا ہے اور میرے کانوں نے سنا ہے اور میں یہ دیکھ رہا ہوں کہ یہ لوگ آپس میں ایک دوسرے کی طرف متوجہ ہیں (اور حدیث نہیں سن رہے ہیں)۔ غور سے سنو ",""],["ٱللَّٰه","a"],[" کی قسم! اب میں تمہارے درمیان میں سے چلا جاؤں گا اور کبھی بھی تمہارے پاس واپس نہیں آؤں گا۔ میں نے ان سے پوچھا آپ کہاں چلے جائیں گے؟ انھوں نے کہا میں ",""],["ٱللَّٰه","a"],[" کے راستے میں جہاد کرنے چلا جاؤں گا۔ میں نے کہا اب جہاد کرنا آپ کے بس میں نہیں ہے کیونکہ نہ آپ گھوڑے پر بیٹھ سکتے ہیں نہ تلوار چلا سکتے ہیں اور نہ نیزہ مار سکتے ہیں (آپ بہت بوڑھے اور کمزور ہو چکے ہیں)۔ انھوں نے فرمایا اے ابوحازم! میں جا کر جہاد کی صف میں کھڑا ہو جاؤں گا، کوئی نامعلوم تیر یا پتھر آ کر مجھے لگے گا اور اس طرح ",""],["ٱللَّٰه","a"],[" تعالیٰ مجھے شہادت کا درجہ عطا فرما دیں گے۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani in his Kabeer. Haythami (Vol.1 Pg.155) has commented on the chain of narrators."]]}]},"74":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوامامہؓ","b"],[" فرماتے ہیں کہ قریش کا ایک جوان حضورؐ کی خدمت میں آ کر کہنے لگا یا رسول ",""],["ٱللَّٰه","a"],["! مجھے زنا کی اجازت دے دیں۔ تمام لوگ اس کی طرف متوجہ ہو گئے اور اسے ڈانٹنے لگے اور کہنے لگے ایسی بات نہ کہو۔ حضورؐ نے فرمایا ذرا قریب آ جاؤ۔ وہ حضورؐ کے قریب آ گیا۔ حضورؐ نے فرمایا کیا تم زنا کو اپنی ماں کے لیے پسند کرتے ہو؟ اس نے کہا بالکل نہیں، ",""],["ٱللَّٰه","a"],[" کی قسم! ",""],["ٱللَّٰه","a"],[" مجھے آپؐ پر قربان کرے۔ حضورؐ نے فرمایا نہ ہی دوسرے لوگ اسے اپنی ماں کے لیے پسند کرتے ہیں۔ پھر آپؐ نے فرمایا کیا تم اسے اپنی بیٹی کے لیے پسند کرتے ہو؟ اس نے کہا بالکل نہیں، یا رسول ",""],["ٱللَّٰه","a"],[" کی قسم! ",""],["ٱللَّٰه","a"],[" مجھے آپؐ پر قربان کرے۔ حضورؐ نے فرمایا اور نہ ہی اور لوگ اسے اپنی بیٹیوں کے لیے پسند کرتے ہیں۔ پھر آپؐ نے فرمایا کیا تم اسے اپنی بہن کے لیے پسند کرتے ہو؟ اس نے کہا بالکل نہیں، ",""],["ٱللَّٰه","a"],[" کی قسم! یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" مجھے آپؐ پر قربان کرے۔ حضورؐ نے فرمایا نہ ہی دوسرے لوگ اسے اپنی بہنوں کے لیے پسند کرتے ہیں۔ پھر آپؐ نے فرمایا کیا تم اسے اپنی پھوپھی کے لیے پسند کرتے ہو؟ اس نے کہا بالکل نہیں، ",""],["ٱللَّٰه","a"],[" کی قسم! یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" مجھے آپؐ پر قربان کرے۔ حضورؐ نے فرمایا اور نہ ہی دوسرے لوگ اسے اپنی پھوپھیوں کے لیے پسند کرتے ہیں۔ پھر آپؐ نے فرمایا کیا تم اسے اپنی خالہ کے لیے پسند کرتے ہو؟ اس نے کہا بالکل نہیں، ",""],["ٱللَّٰه","a"],[" کی قسم! یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" مجھے آپؐ پر قربان کرے۔ حضورؐ نے فرمایا اور نہ ہی دوسرے لوگ اسے اپنی خالاؤں کے لیے پسند کرتے ہیں۔ پھر حضورؐ نے اپنا ہاتھ اس پر رکھ کر یہ دعا مانگی اے ",""],["ٱللَّٰه","a"],["! اس کے گناہ معاف فرما اور اس کے دل کو پاک فرما اور اس کی شرمگاہ کی حفاظت فرما۔ حضرت ابوامامہؓ فرماتے ہیں حضورؐ کے سمجھانے اور دعا فرمانے کے بعد اس جوان کی توجہ اس طرف سے بالکل ہٹ گئی۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani and Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.129)."]]},{"b":[["n",[["حضرت ابوامامہؓ","b"],[" فرماتے ہیں کہ نبی کریمؐ جب کوئی بات ارشاد فرماتے تو اسے تین مرتبہ کہتے تا کہ سننے والے اچھی طرح سمجھ لیں۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani in his Kabeer, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.129)."]]},{"b":[["n",[["حضرت شعبیؒ","b"],[" کہتے ہیں حضرت عائشہؓ نے مدینہ والوں کے واعظ حضرت ابن ابی سائبؒ سے فرمایا تین کاموں میں میری بات مانو ورنہ میں تم سے سخت لڑائی کروں گی۔ حضرت ابن ابی سائبؒ نے عرض کیا وہ تین کام کیا ہیں؟ اے ام المومنین! میں آپ کی بات ضرور مانوں گا۔ حضرت عائشہؓ نے فرمایا پہلی بات یہ ہے کہ تم دعا میں بتکلف قافیہ بندی سے بچو کیونکہ حضورؐ اور آپؐ کے صحابہؓ اس طرح قصداً نہیں کیا کرتے تھے اور دوسری بات یہ ہے کہ ہفتہ میں ایک دفعہ لوگوں میں بیان کیا کرو اور زیادہ کرنا چاہو تو دو دفعہ ورنہ زیادہ سے زیادہ تین دفعہ کیا کرو، اس سے زیادہ نہ کرو ورنہ لوگ (",""],["ٱللَّٰه","a"],[" کی) اس کتاب سے اکتا جائیں گے اور تیسری بات یہ ہے کہ ایسا ہرگز نہ کرنا کہ تم کسی گروہ کے پاس جاؤ اور وہاں والے آپس میں بات کر رہے ہوں اور تم ان کی بات کاٹ کر اپنا بیان شروع کر دو بلکہ انہیں اپنی بات کرنے دو اور جب وہ تمہیں موقع دیں اور کہیں تو پھر ان میں بیان کرو۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.191). Abu Ya'la has reported a similar narration."]]},{"b":[["n",[["حضرت شقیق بن سلمہؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ ایک دن ہمارے پاس باہر تشریف لائے اور فرمایا مجھے خبر پہنچ جاتی ہے کہ آپ لوگ باہر بیٹھے ہیں لیکن بعض دفعہ میں جان بوجھ کر آپ لوگوں کے پاس باہر نہیں آتا تا کہ میرے زیادہ بیانات اور زیادہ حدیثیں سنانے کی وجہ سے آپ لوگ اکتا نہ جائیں، کیونکہ حضورؐ وعظ اور بیان میں ہمارا خیال فرماتے تھے تا کہ ہم اکتا نہ جائیں۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.105)."]]},{"b":[["n",[["حضرت اعمشؒ","b"],[" کہتے ہیں کہ حضرت ابن مسعودؓ کا ایک آدمی پر گزر ہوا جو ایک قوم میں وعظ کہہ رہا تھا۔ حضرت ابن مسعودؓ نے فرمایا اے وعظ و نصیحت کرنے والے! لوگوں کو (",""],["ٱللَّٰه","a"],[" کی رحمت سے) نا امید نہ کرنا۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani in his Kabeer. Haythami (Vol.1 Pg.191) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت علیؓ نے فرمایا کیا میں تمہیں دین کی سمجھ رکھنے والا حقیقی عالم نہ بتاؤں؟ یہ وہ عالم ہے جو لوگوں کو ",""],["ٱللَّٰه","a"],[" کی رحمت سے نا امید نہ کرے اور نہ ",""],["ٱللَّٰه","a"],[" تعالیٰ کی نافرمانی کی انہیں کھلی چھٹی دے اور نہ انہیں ",""],["ٱللَّٰه","a"],[" کی پکڑ سے بے خوف اور بے فکر ہونے دے اور نہ انہیں قرآن کو چھوڑ کر کسی اور چیز میں ایسا لگنے دے کہ قرآن چھوٹ جائے۔ اس عبادت میں خیر نہیں ہے جس میں دینی علم نہ ہو اور اس دینی علم میں خیر نہیں ہے جسے آدمی سمجھا نہ ہو یا جس کے ساتھ پرہیزگاری نہ ہو اور قرآن کی اس تلاوت میں کوئی خیر نہیں جس میں انسان قرآن کے معنی اور مطلب میں غور و فکر نہ کرے۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Dharees, Abu Nu'aym in his Hilya (Vol.1 Pg.77), Ibn Asaakir and others, as quoted in Kanzul Ummaal (Vol.5 Pg.231). In his Isti'aab (Vol.2 Pg.44), Ibn Abdul Birr has reported the words from Rasulullaah."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ جب حضورؐ نے حضرت معاذ بن جبل اور حضرت ابوموسیٰؓ کو یمن بھیجا تو ان دونوں کو یہ ہدایات دیں کہ آپس میں ایک دوسرے سے تعاون کرنا اور ایک دوسرے کی بات ماننا اور لوگوں کو خوشخبریاں سنانا اور لوگوں کو مت بھگانا۔ چنانچہ (یمن جا کر) حضرت معاذؓ نے لوگوں میں بیان فرمایا اور انہیں اسلام لانے کی اور دینی سمجھ حاصل کرنے کی اور قرآن پڑھنے پڑھانے کی ترغیب دی اور فرمایا میں تمہیں جنت والے اور دوزخ والے بتا دیتا ہوں۔ جب کسی آدمی کا بھلائی کے ساتھ ذکر ہو تو سمجھ لو کہ وہ جنت والوں میں سے ہے اور جب کسی کا برائی کے ساتھ ذکر ہو تو سمجھ لو کہ وہ دوزخ والوں میں سے ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.166)."]]},{"b":[["n",[["حضرت ابوسعیدؓ","b"],[" فرماتے ہیں کہ نبی کریمؐ کے صحابہ کرامؓ جب آپس میں بیٹھا کرتے تھے تو ان کی باتیں دینی امور کے بارے میں ہی ہوتی تھیں یا پھر خود کوئی سورت پڑھتے یا کسی کو پڑھاتے۔",""],[" (8)","s"]]]],"f":[["(8)","Haakim (Vol.1 Pg.94), reporting from reliable sources as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں آدمی علم کے اعلیٰ مرتبہ پر اس وقت ہوگا جب اپنے سے اوپر والے سے حسد نہ کرے اور اپنے سے نیچے والے کو حقیر نہ سمجھے اور علم کے بدلے میں کوئی قیمت نہ چاہے۔",""],[" (9)","s"]]]],"f":[["(9)","Abu Nu'aym in his Hilya (Vol.1 Pg.306)."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" فرماتے ہیں خود علم سیکھو اور لوگوں کو سکھاؤ اور علم کے لیے وقار اور سکون و اطمینان سیکھو اور جس سے علم سیکھو اس کے سامنے بھی تواضع اختیار کرو اور جسے علم سکھاؤ اس کے سامنے بھی تواضع اختیار کرو اور متکبر عالم نہ بنو۔ اس طرح تمہارا جہل تمہارے علم کے سامنے نہیں ٹھہر سکے گا بلکہ ختم ہو جائے گا۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.135). Ahmad in his Zuhd, Bayhaqi, Ibn Abi Shaybah and others have reported a similar narration."]]},{"b":[["n",[["حضرت علیؓ","b"],[" نے فرمایا (تمہیں سکھانے والے) عالم کا یہ حق ہے کہ تم اس سے سوال زیادہ نہ کرو اور اسے جواب دینے کی مشقت میں نہ ڈالو یعنی اسے مجبور نہ کرو اور جب وہ تم سے منہ دوسری طرف پھیر لے تو پھر اس پر اصرار نہ کرو اور جب وہ تھک جائے تو اس کے کپڑے نہ پکڑو اور نہ ہاتھ سے اس کی طرف اشارہ کرو اور نہ آنکھوں سے۔ اور اس کی مجلس کا کچھ نہ پوچھو اور اس کی لغزشیں تلاش نہ کرو اور اگر اس سے کوئی لغزش ہو جائے تو تم اس کی لغزش سے رجوع کا انتظار کرو اور جب وہ رجوع کر لے تو تم اسے قبول کر لو اور یہ بھی نہ کہو کہ فلاں نے آپ کی بات کے خلاف بات کہی ہے اور اس کے کسی راز کا افشاء نہ کرو اور اس کے پاس کسی کی غیبت نہ کرو اور اس کے سامنے اور اس کے پیٹھ پیچھے دونوں حالتوں میں اس کے حق کا خیال کرو اور تمام لوگوں کو سلام کرو لیکن اسے بھی خاص طور سے کرو اور اس کے سامنے بیٹھو، اگر اسے کوئی ضرورت ہو تو دوسروں سے آگے بڑھ کر اس کی خدمت کرو اور اس کے پاس جتنا وقت بھی تمہارا گزر جائے تنگدل نہ ہونا کیونکہ یہ عالم کھجور کے درخت کی طرح ہے جس سے ہر وقت کسی نہ کسی فائدے کے حاصل ہونے کا انتظار رہتا ہے اور یہ عالم اس روزہ دار کے درجہ میں ہے جو ",""],["ٱللَّٰه","a"],[" کے راستہ میں جہاد کر رہا ہو۔ جب ایسا عالم مر جاتا ہے تو اسلام میں ایسا شگاف پڑ جاتا ہے جو قیامت تک پر نہیں ہو سکتا اور آسمان کے ستر ہزار مقرب فرشتے طالب علم کے ساتھ (اکرام کے لیے) چلتے ہیں۔",""],[" (11)","s"]]]],"f":[["(11)","Murhibi and Ibn Abdul Birr in his Jaami, as quoted in Kanzul Ummaal (Vol.5 Pg.242). Muntakhab Kanzul Ummaal (Vol.4 Pg.73) and Khateeb in his Jaami, as quoted in Kanzul Ummaal (Vol.5 Pg.229)."]]},{"b":[["n",[["حضرت جمیلہؒ","b"],[" (حضرت انس بن مالکؓ کی ام ولد باندی) کہتی ہیں کہ جب حضرت ثابت بنانیؒ حضرت انسؓ کی خدمت میں آتے تو حضرت انسؓ فرماتے اے لونڈی! ذرا خوشبو لانا تا کہ میں اپنے ہاتھوں کو لگا لوں، یہ ثابت کی ماں کا بیٹا یعنی خود حضرت ثابت، جب تک میرے دونوں ہاتھوں کو چوم نہیں لے گا اس وقت تک راضی نہیں ہوگا۔",""],[" (12)","s"]]]],"f":[["(12)","Abu Ya'la. Haythami (Vol.1 Pg.130) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ میں حضرت عمر بن خطابؓ سے ایک بات پوچھنا چاہتا تھا لیکن ان کے رعب اور ہیبت کی وجہ سے میں ان سے دو سال تک نہ پوچھ سکا یہاں تک کہ کسی سفر حج یا سفر عمرہ میں حضرت عمرؓ کسی ضرورت کے لیے مرالظہران کی وادی میں اراک مقام پر اپنے ساتھیوں سے پیچھے رہ گئے اور مجھے تنہائی کا موقع مل گیا تو میں نے کہا اے امیر المومنین! میں آپ سے دو سال سے ایک بات پوچھنا چاہتا ہوں لیکن صرف آپ کی ہیبت کی وجہ سے نہ پوچھ سکا۔ حضرت عمرؓ نے فرمایا ایسا مت کرو۔ جب کسی بات کے مجھ سے پوچھنے کا ارادہ ہوا کرے تو فوراً پوچھ لیا کرو، اگر مجھے وہ بات معلوم ہوگی تو میں تمہیں بتا دوں گا ورنہ کہہ دوں گا مجھے معلوم نہیں۔ پھر تم اس آدمی سے پوچھ لینا جو اسے جانتا ہو۔ میں نے کہا وہ دو عورتیں کون ہیں جن کے بارے میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے (سورت تحریم میں) فرمایا ہے کہ وہ دونوں حضورؐ کے مقابلہ میں ایک دوسرے کی مددگار بنی تھیں؟ حضرت عمرؓ نے فرمایا وہ حضرت عائشہؓ اور حضرت حفصہؓ تھیں۔ اس کے بعد اور لمبی حدیث ذکر کی ہے۔",""],[" (13)","s"]]]],"f":[["(13)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.112)."]]},{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں میں نے حضرت سعد بن مالکؓ سے کہا میں آپ سے کچھ پوچھنا چاہتا ہوں لیکن آپ سے ڈر بھی لگتا ہے۔ حضرت سعدؓ نے کہا اے میرے بھتیجے! مجھ سے نہ ڈرو، جب تمہیں معلوم ہو کہ وہ چیز مجھے معلوم ہے تو تم مجھ سے ضرور پوچھ لو۔ میں نے عرض کیا جب غزوہ تبوک میں حضورؐ اپنے پیچھے حضرت علیؓ کو چھوڑ کر گئے تھے تو ان سے کیا فرمایا تھا؟ حضرت سعدؓ نے کہا حضورؐ نے فرمایا تھا اے علی! کیا تم اس بات پر راضی نہیں ہو کہ تم میرے لیے ایسے ہو جاؤ جیسے کہ حضرت ہارون علیہ السلام حضرت موسیٰ علیہ السلام کے لیے تھے (کوہ طور پر جاتے وقت حضرت موسیٰؑ حضرت ہارونؑ کو پیچھے چھوڑ گئے تھے)۔",""],[" (14)","s"]]]],"f":[["(14)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.112). Ibn Sa'd (Vol.3 Pg.24) has also reported the narration with some additions."]]},{"b":[["n",[["حضرت عثمان بن عبد","b"],["ٱللَّٰه","a"],[" بن موہبؒ","b"],[" کہتے ہیں حضرت جبیر بن مطعمؓ کا پانی کے ایک چشمہ پر گزر ہوا۔ اس چشمہ والوں نے ان سے میراث کے بارے میں پوچھا تو حضرت جبیرؓ نے فرمایا مجھے معلوم نہیں لیکن تم لوگ میرے ساتھ کسی کو بھیج دو، میں معلوم کر کے اسے جواب بتا دوں گا۔ چنانچہ چشمہ والوں نے ان کے ساتھ ایک آدمی بھیج دیا۔ حضرت جبیرؓ نے جا کر حضرت عمرؓ سے اس کے بارے میں پوچھا۔ حضرت عمرؓ نے فرمایا جو عالم اور فقیہ بننا چاہتا ہے اسے ایسے ہی کرنا چاہیے جیسے کہ حضرت جبیر بن مطعمؓ نے کیا۔ ان سے ایسی بات پوچھی گئی جو انہیں معلوم نہیں تھی تو کہہ دیا ",""],["ٱللَّٰه","a"],[" علم ",""],["ٱللَّٰه","a"],[" جانتے ہیں (میں نہیں جانتا)۔",""],[" (15)","s"]]]],"f":[["(15)","Ibn Sa'd, as quoted in Kanzul Ummaal (Vol.5 Pg.241)."]]},{"b":[["n",[["حضرت مجاہدؒ","b"],[" کہتے ہیں کہ کسی نے حضرت ابن عمرؓ سے اولاد کی میراث کے بارے میں پوچھا۔ حضرت ابن عمرؓ نے فرمایا مجھے معلوم نہیں۔ کسی نے ان سے کہا آپ اس کا جواب کیوں نہیں دیتے؟ انھوں نے فرمایا ابن عمر سے وہ چیز پوچھی گئی جو اسے معلوم نہیں، اس نے کہہ دیا میں نہیں جانتا (ٹھیک تو کیا)۔ ",""],["حضرت عروہؒ","b"],[" کہتے ہیں حضرت ابن عمرؓ سے کسی چیز کے بارے میں پوچھا گیا تو انھوں نے فرمایا مجھے معلوم نہیں۔ جب وہ پوچھنے والا پشت پھیر کر چل پڑا تو حضرت ابن عمرؓ نے اپنے آپ سے کہا ابن عمر سے ایسی چیز پوچھی گئی جو اسے معلوم نہیں تو اس نے کہہ دیا مجھے معلوم نہیں۔",""],[" (16)","s"],[" (17)","s"]]]],"f":[["(16)","Ibn Abdul Birr in his Isti'aab (Vol.2 Pg.52)."],["(17)","Ibn Sa'd (Vol.4 Pg.144)."]]},{"b":[["n",[["حضرت عقبہ بن مسلمؒ","b"],[" کہتے ہیں کہ میں مسلسل چونتیس مہینے حضرت ابن عمرؓ کی صحبت میں رہا۔ کئی دفعہ ایسا ہوا کہ آپ سے کوئی چیز پوچھی جاتی تو آپ کہہ دیتے میں نہیں جانتا اور پھر میری طرف متوجہ ہو کر فرماتے کیا تم جانتے ہو یہ لوگ کیا چاہتے ہیں؟ یہ لوگ ہماری پشتوں کو جہنم تک جانے کے لیے پل بنانا چاہتے ہیں۔",""],[" (18)","s"]]]],"f":[["(18)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.54)."]]},{"b":[["n",[["حضرت نافعؒ","b"],[" کہتے ہیں کہ حضرت ابن عمرؓ سے کسی نے ایک مسئلہ پوچھا۔ حضرت ابن عمرؓ نے اپنا سر جھکا لیا اور کوئی جواب نہ دیا یہاں تک کہ لوگ یہ سمجھے کہ حضرت ابن عمرؓ نے اس کا سوال ہی نہیں سنا۔ اس لیے اس آدمی نے کہا ",""],["ٱللَّٰه","a"],[" آپ پر رحم فرمائے کیا آپ نے میرا سوال نہیں سنا؟ انھوں نے فرمایا سنا ہے لیکن شاید آپ لوگ یہ سمجھتے ہیں کہ جو کچھ ہم سے آپ لوگ پوچھ رہے ہیں ",""],["ٱللَّٰه","a"],[" تعالیٰ ہم سے اس کے بارے میں باز پرس نہیں کرے گا۔ ",""],["ٱللَّٰه","a"],[" تم پر رحم کرے ہمیں ذرا مہلت دو تا کہ ہم تمہارے سوال کے بارے میں سوچ لیں۔ اگر ہمیں اس کا کوئی جواب سمجھ میں آگیا تو ہم تمہیں بتا دیں گے اور اگر نہ آیا تو تمہیں بتا دیں گے کہ ہمیں معلوم نہیں۔",""],[" (19)","s"]]]],"f":[["(19)","Ibn Sa'd (Vol.4 Pg.168)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا اے لوگو! جس آدمی سے ایسی بات پوچھی جائے جو اسے معلوم ہے تو وہ بتا دے اور جسے معلوم نہیں ہے وہ کہہ دے ",""],["ٱللَّٰه","a"],[" زیادہ جانتا ہے (میں نہیں جانتا) کیونکہ یہ بھی علم میں سے ہے کہ جس بات کو آدمی نہیں جانتا اس کے بارے میں کہہ دے کہ ",""],["ٱللَّٰه","a"],[" زیادہ جانتا ہے۔ خود ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اپنے نبی کریمؐ کو ارشاد فرمایا ہے",""]]],["q",[["قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَآ أَنَا۠ مِنَ ٱلْمُتَكَلِّفِينَ  (سورۃ ص: ۸۶)","a"]]],["p",[["ترجمہ: \"آپ کہہ دیجیے کہ میں تم سے اس قرآن (کی تبلیغ) پر کچھ معاوضہ چاہتا ہوں اور نہ میں بناوٹ کرنے والوں میں سے ہوں۔\"",""],[" (20)","s"]]]],"f":[["(20)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.51)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن بشرؒ","b"],[" کہتے ہیں کہ حضرت علی بن ابی طالبؓ سے ایک مسئلہ پوچھا گیا تو انھوں نے فرمایا مجھے معلوم نہیں پھر فرمایا اس بول سے میرے جگر کو بہت زیادہ ٹھنڈک پہنچی ہے کہ مجھ سے ایسی بات پوچھی گئی جو مجھے معلوم نہیں اور میں نے کہہ دیا مجھے معلوم نہیں۔",""],[" (21)","s"]]]],"f":[["(21)","Sa'd bin Nasr, as quoted in Kanzul Ummaal (Vol.5 Pg.241). Daarimi has reported a similar narration in brief, as quoted in Kanzul Ummaal (Vol.5 Pg.243)."]]},{"b":[["n",[["حضرت یحییٰ بن سعیدؒ","b"],[" کہتے ہیں کہ حضرت ابن عباسؓ نے فرمایا جب کوئی عالم میں نہیں جانتا کہنا چھوڑ دیتا ہے تو سمجھ لو کہ وہ اپنی ہلاکت کی جگہ پر پہنچ گیا ہے۔ ",""],["حضرت مالکؒ","b"],[" کہتے ہیں کہ حضرت ابن عباسؓ فرمایا کرتے تھے کہ جب کوئی عالم میں نہیں جانتا کہنے سے چوک جائے تو سمجھ لو کہ وہ اپنی ہلاکت کی جگہ پر پہنچ گیا ہے۔",""],[" (22)","s"]]]],"f":[["(22)","Abu Dawood and Maalik, as quoted in Jaami Bayaanil Ilm (Vol.2 Pg.54)."]]},{"b":[["n",[["حضرت مکحولؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ لوگوں کو حدیثیں سناتے اور جب دیکھتے کہ یہ تھک گئے ہیں اور اکتا گئے ہیں تو انہیں پودے لگانے میں مشغول کر دیتے۔",""],[" (23)","s"]]]],"f":[["(23)","Ibn Sam'aani, as quoted in Kanzul Ummaal (Vol.5 Pg.131)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مصعبؒ","b"],[" کہتے ہیں کہ ایک دفعہ حضرت عمر بن خطابؓ نے فرمایا عورتوں کا مہر چالیس اوقیہ (ایک اوقیہ چالیس درہم کا ہوتا ہے) سے زیادہ مقرر نہ کرو چاہے ذی الغصہ قیس بن حصین حارثی (جیسے سردار) کی بیٹی کیوں نہ ہو جو اس سے زیادہ مقرر کرے گا میں وہ زائد رقم لے کر بیت المال میں جمع کر دوں گا۔ اس پر عورتوں کی صف میں سے ایک عورت کھڑی ہوئی جس کا قد لمبا تھا اور ناک چپٹی تھی اور اس نے کہا آپ کو ایسا کرنے کا اختیار نہیں ہے۔ حضرت عمرؓ نے فرمایا کیوں؟ اس عورت نے کہا کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["وَءَاتَيْتُمْ إِحْدَىٰهُنَّ قِنطَارًا فَلَا تَأْخُذُوا۟ مِنْهُ شَيْـًٔا  (سورۃ نساء: ۲۰)","a"]]],["p",[["ترجمہ: \"اور تم اس ایک کو انبار کا انبار مال دے چکے ہو تو تم اس میں سے کچھ بھی مت لو۔\" تو حضرت عمرؓ نے فوراً کہا عورت نے ٹھیک کہا مرد نے غلطی کی (یعنی عمرؓ نے)۔",""],[" (24)","s"]]]],"f":[["(24)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.131)."]]},{"b":[["n",[["حضرت محمد بن کعب قرظیؒ","b"],[" کہتے ہیں کہ ایک آدمی نے حضرت علیؓ سے کوئی مسئلہ پوچھا۔ حضرت علیؓ نے اس کا کچھ جواب دیا۔ اس آدمی نے کہا اے امیر المومنین! مسئلہ اس طرح نہیں ہے بلکہ اس طرح ہے۔ حضرت علیؓ نے فوراً کہا تم نے ٹھیک کہا میری بات غلط تھی",""]]],["q",[["وَفَوْقَ كُلِّ ذِى عِلْمٍ عَلِيمٌ  (سورۃ یوسف: ۷۶)","a"]]],["p",[["ترجمہ: \"اور ہر جاننے والے کے اوپر اس سے زیادہ جاننے والا ہوتا ہے۔\"",""],[" (25)","s"]]]],"f":[["(25)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.131). Ibn Jareer has reported a similar narration, as quoted in Kanzul Ummaal (Vol.5 Pg.241)."]]},{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں کہ بعض دفعہ حضرت عمر بن خطابؓ اور حضرت عثمان بن عفانؓ کا آپس میں کسی مسئلہ میں اتنا جھگڑا ہو جاتا تھا کہ دیکھنے والا یوں سمجھتا تھا کہ اب شاید یہ دونوں کبھی آپس میں اکٹھے نہیں ہوں گے لیکن وہ دونوں جب اس مجلس سے اٹھتے تو ایسے لگتا کہ کوئی بات ہوئی ہی نہیں تھی بالکل ٹھیک ٹھاک ہوتے۔",""],[" (26)","s"]]]],"f":[["(26)","Khateeb, as quoted in Kanzul Ummaal (Vol.5 Pg.241)."]]}]},"75":{"lead":[],"stories":[{"b":[["n",[["حضرت عقبہ بن عامرؓ","b"],[" فرماتے ہیں کہ میں بارہ سواروں کی جماعت میں (اپنی بستی سے) چلا اور سفر کر کے مدینہ حضورؐ کی خدمت میں پہنچا۔ ہم آپؐ کے ہاں ٹھہر گئے۔ میرے ساتھیوں نے کہا ہمارے اونٹ کون چرائے گا تا کہ (وہ تو ہمارے اونٹ لے کر چلا جائے اور فارغ ہو کر) ہم جا کر حضورؐ سے علم کی روشنی حاصل کر سکیں اور شام کو جب وہ اونٹ چرا کر واپس آئے گا تو ہم نے جو کچھ دن بھر میں حضورؐ سے سنا ہوگا وہ سب اسے بتا دیں گے۔ میں اونٹ چرانے کے لیے تیار ہو گیا اور چند دن اونٹ چراتا رہا پھر میں نے دل میں سوچا کہیں میرا نقصان تو نہیں ہو رہا کیونکہ میرے ساتھی حضورؐ سے وہ حدیثیں سنتے ہیں جو میں نہیں سنتا اور آپؐ سے وہ کچھ سیکھ رہے ہیں جو میں نہیں سیکھ رہا۔ چنانچہ ایک دن (میں اونٹ لے کر نہ گیا اور دوسرے ساتھی اپنے اپنے اونٹ لے کر گئے اور) میں مجلس میں حاضر ہوا تو میں نے ایک آدمی کو یہ کہتے ہوئے سنا کہ حضورؐ نے فرمایا جو پورا وضو کرے گا وہ اپنے گناہوں سے ایسے پاک صاف ہو جائے گا جیسے آج ہی اس کی ماں نے اسے جنا ہو۔ میں یہ فضیلت سن کر بہت خوش ہوا اور واہ واہ کرنے لگا۔ حضرت عمر بن خطابؓ نے کہا ارے میاں اگر تم اس سے پہلے والا کلام سن لیتے تو اور زیادہ حیران ہوتے میں نے کہا ",""],["ٱللَّٰه","a"],[" مجھے آپ پر قربان کرے ذرا مجھے وہ کلام تو سنا دیں۔ انھوں نے فرمایا کہ حضورؐ نے فرمایا کہ جو اس حال میں مرے کہ ",""],["ٱللَّٰه","a"],[" کے ساتھ کسی چیز کو شریک نہ ٹھہراتا ہو تو ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے لیے جنت کے سارے دروازے کھول دیں گے کہ جس سے چاہے داخل ہو جائے اور جنت کے آٹھ دروازے ہیں۔ اس کے بعد حضورؐ ہمارے پاس باہر تشریف لائے۔ میں آپؐ کے سامنے بیٹھ گیا لیکن آپؐ نے مجھ سے منہ پھیر لیا اور تین مرتبہ حضورؐ نے ایسے ہی فرمایا۔ جب آپؐ نے چوتھی مرتبہ بھی ایسے ہی کیا تو میں نے عرض کیا یا نبی ",""],["ٱللَّٰه","a"],["! میرے ماں باپ آپ پر قربان ہوں آپ مجھ سے کیوں منہ پھیر رہے ہیں؟ اس پر آپؐ نے میری طرف متوجہ ہو کر فرمایا کہیں ایک آدمی (کا مجلس میں آنا) زیادہ پسند ہے یا بارہ (کا)۔ جب میں نے یہ منظر دیکھا تو میں اسی وقت اپنے ساتھیوں کے پاس واپس چلا گیا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.77). Abu Nu'aym has also reported the narration in his Hilya (Vol.9 Pg.307)."]]},{"b":[["n",[["حضرت عثمان بن ابی العاصؓ","b"],[" فرماتے ہیں کہ میں ثقیف کے وفد کے ساتھ حضورؐ کی خدمت میں حاضر ہوا۔ ہم نے نبی کریمؐ کے دروازے پر اپنے نئے جوڑے پہنے ہوئے تھے اور ہم اس میں سب سے چھوٹا تھا۔ میرے ساتھیوں نے کہا ہماری سواریوں کو کون تھام کر رکھے گا؟ لیکن سب کو حضورؐ کی خدمت میں فوراً حاضری دینے کا شوق تھا اور کوئی بھی اس کام کے لیے ٹھہرنا نہیں چاہتا تھا۔ میں ان سب میں چھوٹا تھا میں نے کہا اگر آپ لوگ چاہیں تو میں سواریوں کے لیے یہاں ٹھہرنے کے لیے تیار ہوں لیکن شرط یہ ہے کہ جب آپ لوگ اندر سے باہر آ جائیں تو پھر آپ لوگوں کو میری سواری کی وجہ سے یہاں رکنا ہوگا۔ انھوں نے کہا ٹھیک ہے اور وہ سب اندر حضورؐ کی خدمت میں چلے گئے اور وہاں سے فارغ ہو کر باہر واپس آئے اور کہنے لگے آؤ چلیں میں نے کہا کہاں؟ تمہارے گھر، میں نے اپنے گھر سے اتنا سفر کیا لیکن جب نبی کریمؐ کے دروازے پر پہنچا تو حضورؐ کی خدمت میں حاضری دیے بغیر واپس چلا جاؤں حالانکہ آپ لوگوں نے مجھ سے وعدہ کیا تھا جیسے کہ آپ لوگوں کو معلوم ہے۔ اس پر ساتھیوں نے کہا اچھا جلدی کرو ہم حضورؐ سے ہر بات پوچھ آئے ہیں تمہیں اب کچھ پوچھنے کی ضرورت نہیں۔ چنانچہ میں حضورؐ کی خدمت میں حاضر ہوا اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپ میرے لیے ",""],["ٱللَّٰه","a"],[" سے دعا فرما دیں کہ مجھے علم اور دین کی سمجھ عطا فرمائے۔ حضورؐ نے فرمایا تم نے کیا کہا؟ میں نے اپنی درخواست دوبارہ پیش کی تو حضورؐ نے فرمایا تم نے ایسی فرمائش کی ہے کہ ویسی تمہارے ساتھیوں میں سے کسی نے نہیں کی۔ جاؤ اب تم ہی اپنے ان ساتھیوں کے بھی امیر ہوا اور تمہاری قوم میں سے جو بھی تمہارے پاس آئے تم اس کے امیر ہو۔ آگے اور حدیث بھی ذکر کی ہے۔ دوسری مختصر روایت میں یہ ہے کہ میں حضورؐ کی خدمت میں حاضر ہوا۔ حضورؐ کے پاس ایک قرآن رکھا ہوا تھا وہ میں نے حضورؐ سے مانگا حضورؐ نے مجھے عطا فرما دیا۔",""],[" (2)","s"],[" (3)","s"]]]],"f":[["(2)","Tabraani. Haythami (Vol.9 Pg.371) has commented on the chain of narrators."],["(3)","Tabraani."]]}]},"76":{"lead":[],"stories":[{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ ہم لوگ نبی کریمؐ کے پاس بیٹھے ہوتے تھے اور کبھی ہماری تعداد ساٹھ تک بھی ہو جاتی تھی۔ حضورؐ ہم لوگوں میں حدیث بیان فرماتے پھر اپنی کسی ضرورت سے اندر تشریف لے جاتے ہم لوگ بیٹھ کر اسے آپس میں اتنا دہراتے کہ جب وہاں سے اٹھتے تو وہ حدیث ہمارے دل میں پختہ ہو چکی ہوتی۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Ya'la. Haythami (Vol.1 Pg.161) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوموسیٰؓ","b"],[" فرماتے ہیں کہ نبی کریمؐ جب فجر کی نماز پڑھ لیتے تو ہم سب آپؐ کی طرف متوجہ ہو جاتے۔ ہم میں سے کوئی آپؐ سے قرآن کے بارے میں کوئی فرائض کے بارے میں اور کوئی خواب کی تعبیر پوچھتا۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani in his Kabeer. Haythami (Vol.1 Pg.159) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت فضالہ بن عبیدؓ","b"],[" کے پاس جب ان کے ساتھی آیا کرتے تو ان سے فرمایا کرتے کہ مل کر پڑھا کرو، بشارتیں سنایا کرو اور (علم کو) بڑھاؤ ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہاری خیر کو بڑھائے اور تم سے محبت کرے اور جو تم سے بھی محبت کرتا ہے اس سے بھی محبت کرے اور مسائل کو ہمارے سامنے دہراتے رہا کرو کیونکہ مسائل کے آخری حصے کا ثواب پہلے حصے کی طرح ہے اور اپنی گفتگو میں استغفار شامل کر لیا کرو۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani in his Kabeer, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.161)."]]},{"b":[["n",[["حضرت ابونضرہؒ","b"],[" کہتے ہیں کہ میں نے حضرت ابوسعیدؓ کی خدمت میں عرض کیا کہ آپ ہمیں حدیثیں لکھ کر دے دیں۔ فرمایا ہرگز لکھ کر نہیں دیں گے، ہم ہرگز حدیث کو قرآن نہیں بنائیں گے بلکہ تم ہم سے حدیثیں ایسے لو جیسے ہم نے نبی کریمؐ سے (بغیر لکھے ہوئے زبانی) لی تھیں اور حضرت ابوسعیدؓ یہ بھی فرمایا کرتے تھے کہ حدیثیں آپس میں دہرایا کرو کیونکہ حدیثیں اس طرح پختہ یاد ہو جاتی ہیں۔ حضرت ابوسعیدؓ نے فرمایا حدیثوں کا آپس میں مذاکرہ کرتے رہا کرو اس سے حدیثیں اچھی طرح یاد ہو جاتی ہیں۔ حضرت علیؓ نے فرمایا حدیثوں کا آپس میں مذاکرہ کرتے رہا کرو کیونکہ اگر تم ایسا نہیں کرو گے تو تمام حدیثیں بھول جاؤ گے۔ ابن عبدالبر کی روایت کے شروع میں یہ بھی ہے کہ آپس میں ایک دوسرے سے ملتے رہا کرو۔",""],[" (4)","s"],[" (5)","s"],[" (6)","s"],[" (7)","s"]]]],"f":[["(4)","Tabraani in his Awsat, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.161)."],["(5)","Haakim (Vol.1 Pg.94) and Ibn Abdul Birr in his Jaami (Vol.1 Pg.111)."],["(6)","Haakim (Vol.1 Pg.95)."],["(7)","Ibn Abi Shaybah, as quoted by Ibn Abdul Birr in his Jaami (Vol.1 Pg.101)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا حدیثوں کا آپس میں مذاکرہ کرتے رہو کیونکہ مذاکرہ کرنے سے حدیثیں زندہ رہتی ہیں یعنی یاد رہتی ہیں۔ حضرت ابن مسعودؓ نے فرمایا علم کا پڑھنا پڑھانا نفل نماز کا ثواب دلاتا ہے اور حضرت ابن عباسؓ نے فرمایا راتوں کے کچھ حصے میں علم کا آپس میں مذاکرہ کرنا مجھے رات بھر عبادت کرنے سے زیادہ محبوب ہے۔",""],[" (8)","s"],[" (9)","s"],[" (10)","s"]]]],"f":[["(8)","Haakim (Vol.1 Pg.95)."],["(9)","Ibn Abdul Birr in his Isti'aab (Vol.1 Pg.22)."],["(10)","Ibn Abdul Birr in his Isti'aab (Vol.1 Pg.24)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ حضرت عمر بن خطابؓ نے حضرت علی بن ابی طالبؓ سے فرمایا اے ابوالحسن! کئی مرتبہ آپ حضورؐ کی مجلس میں موجود ہوتے تھے اور ہم غائب ہوتے تھے اور کبھی ہم موجود ہوتے تھے اور آپ غیر حاضر۔ تین باتیں میں آپ سے پوچھنا چاہتا ہوں کیا آپ کو وہ معلوم ہیں؟ حضرت علیؓ نے فرمایا وہ تین باتیں کیا ہیں؟ حضرت عمرؓ نے فرمایا ایک آدمی کو ایک آدمی سے محبت ہوتی ہے، حالانکہ اس نے اس میں کوئی خیر کی بات نہیں دیکھی ہوتی اور ایک آدمی کو ایک آدمی سے دوری ہوتی ہے حالانکہ اس نے اس میں کوئی بری بات نہیں دیکھی ہوتی اس کی کیا وجہ ہے؟ حضرت علیؓ نے فرمایا ہاں اس کا جواب مجھے معلوم ہے۔ حضورؐ نے فرمایا ہے کہ انسانوں کی روحیں ازل میں ایک جگہ اکٹھی رکھی ہوئی ہیں وہاں وہ ایک دوسرے کے قریب آ کر آپس میں ملتی ہیں جن میں وہاں آپس میں تعارف ہو گیا ان میں یہاں دنیا میں الفت ہو جاتی ہے اور جن میں وہاں اجنبیت رہی وہ یہاں دنیا میں ایک دوسرے سے الگ رہتے ہیں۔ حضرت عمرؓ نے فرمایا یہ ایک بات کا جواب مل گیا۔ دوسری بات یہ ہے کہ آدمی حدیث بیان کرتا ہے کبھی اسے بھول جاتا ہے کبھی یاد آ جاتی ہے اس کی کیا وجہ ہے؟ حضرت علیؓ نے فرمایا میں نے حضورؐ کو یہ ارشاد فرماتے ہوئے سنا کہ جیسے چاند کا بادل ہوتا ہے ایسے دل کے لیے بھی بادل ہے۔ چاند خوب چمک رہا ہوتا ہے بادل اس کے سامنے آ جاتا ہے تو اندھیرا ہو جاتا ہے اور جب بادل ہٹ جاتا ہے چاند پھر چمکنے لگتا ہے۔ ایسے ہی آدمی ایک حدیث بیان کرتا ہے وہ بادل اس پر چھا جاتا ہے تو وہ حدیث بھول جاتا ہے اور جب اس سے وہ بادل ہٹ جاتا ہے تو اسے وہ حدیث یاد آ جاتی ہے۔ حضرت عمرؓ نے فرمایا دو باتوں کا جواب مل گیا تیسری بات یہ ہے کہ آدمی خواب دیکھتا ہے تو کوئی خواب سچا ہوتا ہے کوئی جھوٹا۔ اس کی کیا وجہ ہے؟ حضرت علیؓ نے فرمایا جی ہاں اس کا جواب بھی مجھے معلوم ہے۔ میں نے حضورؐ کو یہ فرماتے ہوئے سنا کہ جو بندہ یا بندی گہری نیند سو جاتا ہے تو اس کی روح کو عرش تک چڑھایا جاتا ہے جو روح عرش پر پہنچ کر جاگتی ہے اس کا خواب تو سچا ہوتا ہے اور جو اس سے پہلے جاگ جاتی ہے اس کا خواب جھوٹا ہوتا ہے۔ حضرت عمرؓ نے فرمایا میں ان تین باتوں کی تلاش میں ایک عرصہ سے لگا ہوا تھا ",""],["ٱللَّٰه","a"],[" کا شکر ہے کہ میں نے مرنے سے پہلے ان کو پا لیا۔",""],[" (11)","s"]]]],"f":[["(11)","Tabraani in his Awsat. Haythami (Vol.1 Pg.162) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابراہیم تیمیؒ","b"],[" کہتے ہیں کہ ایک دن حضرت عمر بن خطابؓ تنہائی میں بیٹھے ہوئے تھے اور اپنے دل میں کچھ سوچ رہے تھے پھر آدمی بھیج کر حضرت ابن عباسؓ کو بلایا۔ جب وہ آ گئے تو ان سے فرمایا اس امت میں کیسے اختلاف ہو سکتا ہے جب کہ ان کی کتاب ایک ہے اور ان کا نبی ایک ہے اور ان کا قبلہ ایک ہے؟ حضرت ابن عباسؓ نے کہا اے امیر المومنین! ہم پر قرآن نازل ہوا ہم نے اسے پڑھا اور ہمیں معلوم ہے کہ قرآن کی یہ آیت کس کے بارے میں نازل ہوئی ہے لیکن ہمارے بعد کے لوگ قرآن تو پڑھیں گے لیکن انہیں یہ نہیں معلوم ہوگا کہ یہ آیت کس بارے میں نازل ہوئی ہے۔ اس طرح ہر جماعت کی اس بارے میں الگ الگ رائے ہوگی۔ جب ہر جماعت کی الگ الگ رائے ہوگی تو ان میں اختلاف ہو جائے گا اور جب ان میں آپس میں اختلاف ہو جائے گا تو پھر آپس میں لڑ پڑیں گے۔ یہ سن کر حضرت عمرؓ ان پر برسے اور انہیں خوب ڈانٹا۔ حضرت ابن عباسؓ واپس چلے گئے لیکن حضرت ابن عباسؓ نے جو بات کہی تھی وہ بعد میں حضرت عمرؓ کو سمجھ آ گئی تو انہیں بلایا اور ان سے فرمایا وہ اپنی بات ذرا دوبارہ کہنا۔",""],[" (12)","s"]]]],"f":[["(12)","Sa'eed bin Mansoor, Bayhaqi and Khateeb, as quoted in Kanzul Ummaal (Vol.1 Pg.228)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ حضرت عمر بن خطابؓ نے فرمایا آج رات میں نے ایک آیت پڑھی جس کی وجہ سے مجھے ساری رات نیند نہیں آئی۔ وہ آیت یہ ہے",""]]],["q",[["أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُۥ جَنَّةٌ مِّن نَّخِيلٍ وَأَعْنَابٍ  (سورۃ بقرہ: ۲۶۶)","a"]]],["p",[["ترجمہ: \"بھلا تم میں سے کسی کو یہ بات پسند ہے کہ اس کا ایک باغ ہو کھجوروں کا اور انگوروں کا۔ اس کے (درختوں کے) نیچے نہریں چلتی ہوں اس شخص کے یہاں اس باغ میں اور بھی ہر قسم کے (مناسب) میوے ہوں اور اس شخص کا بڑھاپا آ گیا ہو اور اس کے اہل و عیال بھی ہوں جن میں (کمانے کی) قوت نہیں۔ سو اس باغ پر ایک بگولا آوے جس میں آگ (کا مادہ) ہو پھر وہ باغ جل جاوے۔\" میں ساری رات یہ سوچتا رہا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ اس آیت میں کیا کہنا چاہتے ہیں اس سے مراد کیا ہے؟ ایک آدمی نے کہا ",""],["ٱللَّٰه","a"],[" زیادہ جانتے ہیں۔ حضرت عمرؓ نے فرمایا یہ تو میں بھی جانتا ہوں کہ ",""],["ٱللَّٰه","a"],[" زیادہ جانتے ہیں لیکن میں اس لیے پوچھ رہا ہوں کہ اگر آپ لوگوں میں سے کسی کو کچھ معلوم ہے یا اس نے اس بارے میں کچھ سن رکھا ہے تو وہ بتا دے اور لوگ تو خاموش رہے لیکن میں نے دھیمی آواز سے کچھ کہا اس پر حضرت عمرؓ نے مجھ سے فرمایا کہو اے میرے بھتیجے! کہو اپنے آپ کو اتنا کم درجہ نہ سمجھو۔ میں نے کہا اس مثال سے مراد عمل ہے انھوں نے فرمایا عمل مراد لینے کی کیا دلیل ہے؟ میں نے کہا (دلیل تو کوئی نہیں ہے لیکن) میرے دل میں یہ بات آئی ہے جو میں نے کہہ دی ہے۔ اس پر حضرت عمرؓ مجھے چھوڑ کر خود تفسیر کرنے لگے اور فرمایا اے میرے بھتیجے! تم نے ٹھیک کہا واقعی اس سے عمل ہی مراد ہے۔ ابن آدم جب بوڑھا ہو جاتا ہے اور اس کے اہل و عیال زیادہ ہو جاتے ہیں تو اسے اپنے باغ کی بہت زیادہ ضرورت ہوتی ہے۔ ایسے ہی قیامت کے دن اسے عمل کی سب سے زیادہ ضرورت ہوگی۔ اے میرے بھتیجے! تم نے بالکل ٹھیک کہا۔",""],[" (13)","s"]]]],"f":[["(13)","Abd bin Humayd and Ibn Mundhir, as quoted in Kanzul Ummaal (Vol.1 Pg.234), reporting from reliable sources as confirmed by Haakim (Vol.3 Pg.542)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ حضرت عمرؓ مجھے غزوہ بدر میں شریک ہونے والے بڑے بوڑھوں کے ساتھ اپنی مجلس میں شریک فرمایا کرتے تھے۔ ایک مرتبہ ان سے حضرت عبدالرحمٰن بن عوفؓ نے کہا آپ اس نوجوان کو ہمارے ساتھ شریک کرتے ہیں حالانکہ اس جتنے تو ہمارے بیٹے ہیں؟ حضرت عمرؓ نے فرمایا یہ ان لوگوں میں سے ہے جن کو تم جانتے ہو۔ ایک دن حضرت عمرؓ نے انہیں بھی بلایا اور مجھے بھی بلایا۔ میں سمجھ گیا کہ مجھے صرف اس لیے بلایا ہے تا کہ وہ لوگ میری (علمی) حیثیت دیکھ لیں اور فرمایا آپ لوگ ",""],["ٱللَّٰه","a"],[" تعالیٰ کے اس فرمان کے بارے میں کیا کہتے ہیں اور پھر",""]]],["q",[["إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ  ...  (سورۃ نصر) سے لے کر آخر تک ساری سورت پڑھی۔ ترجمہ: \"اے محمدؐ! جب خدا کی مدد اور (مکہ کی) فتح (مع اپنے آثار کے) آپہنچے (یعنی واقع ہو جائے) اور (آثار جو اس پر متفرع ہونے والے ہیں کہ) آپ لوگوں کو اللہ کے دین (یعنی اسلام) میں جوق در جوق داخل ہوتا ہوا دیکھ لیں تو اپنے رب کی تسبیح و تحمید کیجیے اور اس سے استغفار کی درخواست کیجیے وہ بڑا توبہ قبول کرنے والا ہے۔\" ان میں سے کسی نے کہا اللہ نے ہمیں اس بات کا حکم دیا ہے کہ جب اللہ کی مدد آ جائے اور ہمیں فتح نصیب ہو جائے تو ہم اس کی تعریف کریں اور اس سے مغفرت طلب کریں اور کسی نے کہا ہمیں معلوم نہیں۔ بعضوں نے کچھ نہیں کہا بلکہ خاموش رہے پھر حضرت عمرؓ نے مجھ سے فرمایا اے ابن عباس! کیا تم بھی ایسے ہی کہتے ہو؟ میں نے کہا نہیں انھوں نے فرمایا پھر تم کیا کہتے ہو؟ میں نے کہا اس میں حضورؐ کے دنیا سے تشریف لے جانے کی طرف اشارہ ہے اللہ تعالیٰ نے حضورؐ کو بتایا ہے کہ جب اللہ کی مدد آ جائے اور مکہ فتح ہو جائے اور تم لوگوں کو دیکھ لو تو یہ آپؐ کے دنیا سے جانے کے قریب آنے کی نشانی ہے، لہٰذا آپ اپنے رب کی تسبیح و تحمید کیجیے اور اس سے مغفرت طلب کیجیے وہ بڑا توبہ قبول کرنے والا ہے پھر حضرت عمرؓ نے فرمایا مجھے بھی اس سورت کے بارے میں اتنا ہی معلوم ہے جتنا تمہیں معلوم ہے۔","a"],[" (14)","s"]]]],"f":[["(14)","Sa'eed bin Mansoor, Ibn Sa'd, Abu Ya'la, Ibn Jareer, Ibn Mundhir, Tabraani, Ibn Mardway, Abu Nu'aym and Bayhaqi both in their Dalaa'il, as quoted in Kanzul Ummaal (Vol.1 Pg.276). Abu Nu'aym has also reported the narration in his Hilya (Vol.1 Pg.317)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ میں نے حضرت عمر بن خطابؓ سے ",""],["ٱللَّٰه","a"],[" تعالیٰ کے اس فرمان کے بارے میں پوچھا",""]]],["q",[["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَسْـَٔلُوا۟ عَنْ أَشْيَآءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ  (سورۃ مائدہ: ۱۰۱)","a"]]],["p",[["ترجمہ: \"اے ایمان والو! ایسی (فضول) باتیں مت پوچھو کہ اگر تم سے ظاہر کر دی جاویں تو تمہاری ناگواری کا سبب ہوں۔\" حضرت عمرؓ نے فرمایا کچھ مہاجرین کو اپنے نسب میں کچھ شبہ تھا۔ ایک دن یہ لوگ آپس میں کہنے لگے ",""],["ٱللَّٰه","a"],[" کی قسم! ہمارا دل چاہتا ہے کہ ہمارے نسب کے بارے میں ",""],["ٱللَّٰه","a"],[" تعالیٰ کچھ قرآن نازل فرما دیں تو کیا ہی اچھا ہو۔ اس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ آیت نازل فرمائی جو تم نے ابھی پڑھی تھی پھر حضرت عمرؓ نے مجھ سے فرمایا تمہارے یہ ساتھی یعنی حضرت علی بن ابی طالبؓ اگر امیر بن گئے تو یہ زاہد تو ہوں گے لیکن مجھے خود بینی کا ڈر ہے کہ کہیں اس میں مبتلا نہ ہو جائیں۔ میں نے کہا اے امیر المومنین! ہمارے ساتھی (کے فضائل اور درجے) کو تو آپ جانتے ہیں ",""],["ٱللَّٰه","a"],[" کی قسم! آپ کیا فرما رہے ہیں؟ (حضورؐ کے دنیا سے تشریف لے جانے کے بعد) ان میں کوئی تبدیلی نہیں آئی اور جتنے دن وہ حضورؐ کے ساتھ رہے کبھی حضورؐ کو ناراض نہیں کیا۔ حضرت عمرؓ نے فرمایا حضرت فاطمہؓ کے ہوتے ہوئے حضرت علیؓ نے ابوجہل کی بیٹی کو شادی کا پیغام دینا چاہا تھا جس پر حضورؐ کو گرانی ہوئی تھی۔ میں نے کہا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضرت آدمؑ کی نافرمانی کے قصے میں فرمایا ہے",""]]],["q",[["وَلَمْ نَجِدْ لَهُۥ عَزْمًا  (سورۃ طٰہٰ: ۱۱۵)","a"]]],["p",[["ترجمہ: \"ہم نے (اس حکم کے اہتمام میں) ان میں پختگی (اور ثابت قدمی) نہ پائی۔\" ایسے ہی ہمارے ساتھی نے حضورؐ کو ناراض کرنے میں پختگی نہ دکھائی (بلکہ جونہی یہ پتہ چلا کہ یہ کام حضورؐ کو پسند نہیں ہے انہوں نے فوراً اس ارادہ کو چھوڑ دیا) اور یہ تو دل کے وہ خیالات ہیں جن کے آنے کو کوئی روک نہیں سکتا اور ",""],["ٱللَّٰه","a"],[" کے دین کی سمجھ رکھنے والے فقیہ اور ",""],["ٱللَّٰه","a"],[" کے احکام کے جاننے والے عالم سے بھی کبھی لغزش ہو جاتی ہے لیکن جب اسے اس پر متنبہ کیا جائے تو فوراً اسے چھوڑ کر ",""],["ٱللَّٰه","a"],[" کی طرف رجوع کر لیتا ہے۔ حضرت عمرؓ نے فرمایا اے ابن عباس! جو یہ چاہتا ہے کہ تمہارے (علوم کے) سمندروں میں گھس کر تمہارے ساتھ غوطہ لگائے اور گہرائی تک جا پہنچے وہ ایسا کام کرنا چاہتا ہے جو اس کے بس میں نہیں (یعنی تم نے اپنے دلائل سے مجھے لاجواب کر دیا ہے)۔",""],[" (15)","s"]]]],"f":[["(15)","Zubayr bin Bakkaar in his Muwaffaqiyaat, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.229)."]]},{"b":[["n",[["حضرت سعد بن ابی وقاصؓ","b"],[" فرماتے ہیں کہ میں حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرؓ کے پاس بیٹھا ہوا تھا کہ اتنے میں سامنے سے مقصورہ والے حضرت خبابؓ ظاہر ہوئے اور کہنے لگے اے عبد",""],["ٱللَّٰه","a"],[" بن عمر! کیا آپ نے وہ حدیث سنی ہے جو حضرت ابوہریرہؓ بیان کر رہے ہیں؟ وہ کہہ رہے ہیں کہ میں نے حضورؐ کو فرماتے ہوئے سنا کہ جو گھر سے ہی جنازہ کے ساتھ چلے اور اس کی نماز جنازہ پڑھے اور پھر دفن تک اس کے پیچھے رہے اس کو دو قیراط اجر ملے گا۔ ایک قیراط احد پہاڑ کے برابر ہوتا ہے اور جو نماز جنازہ پڑھ کر واپس آ جائے اس کو احد پہاڑ کے برابر اجر ملے گا یعنی ایک قیراط اجر ملے گا۔ حضرت ابن عمرؓ نے حضرت خبابؓ کو حضرت عائشہؓ کے پاس بھیج دیا کہ ان سے حضرت ابوہریرہؓ کی اس حدیث کے بارے میں پوچھو اور وہ جو جواب دیں وہ آ کر بتاؤ پھر حضرت ابن عمرؓ ایک مٹھی مسجد کی کنکریاں لے کر ہاتھ میں الٹ پلٹ کرتے رہے یہاں تک کہ وہ قاصد یعنی حضرت خبابؓ واپس آ گئے اور آ کر بتایا کہ حضرت عائشہؓ فرما رہی ہیں کہ حضرت ابوہریرہؓ نے ٹھیک کہا ہے تو ہاتھ میں جو کنکریاں تھیں انہیں حضرت ابن عمرؓ نے زمین پر پھینک کر کہا پھر تو ہم نے اجر و ثواب کے بہت سے قیراط کھو دیے۔ حاکم کی روایت میں اس کے بعد یہ بھی ہے کہ حضرت ابوہریرہؓ نے فرمایا کہ ہمیں نہ تو زمینداری کی مشغولی تھی اور نہ بازار کے کاروبار اور تجارت کی۔ جس کی وجہ سے ہمیں حضورؐ کو چھوڑ کر جانا پڑتا ہو۔ میری چاہت تو بس اتنی تھی کہ حضورؐ مجھے یا تو کوئی کلمہ اور بات سکھا دیں یا کھانے کا کوئی لقمہ کھلا دیں۔ اس پر حضرت ابن عمرؓ نے فرمایا اے ابوہریرہ! واقعی تم ہم سب سے زیادہ حضورؐ کو چمٹے رہتے تھے اسی وجہ سے تم ہم سب سے زیادہ حضورؐ کی حدیثوں کو جاننے والے ہو۔",""],[" (16)","s"],[" (17)","s"]]]],"f":[["(16)","Muslim, as quoted in Targheeb wat Tarheeb (Vol.5 Pg.302)."],["(17)","Haakim (Vol.3 Pg.510). Ibn Sa'd (Vol.4 Pg.332) has reported a similar narration."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ میں نے حضورؐ کے صحابہؓ سے بہتر کوئی قوم نہیں دیکھی کہ انہوں نے حضورؐ کی وفات تک حضورؐ سے صرف تیرہ مسئلے ہی پوچھے جن کا قرآن میں ان الفاظ کے ساتھ ذکر ہے",""]]],["q",[["يَسْـَٔلُونَكَ عَنِ ٱلشَّهْرِ ٱلْحَرَامِ ، وَيَسْـَٔلُونَكَ عَنِ ٱلْخَمْرِ وَٱلْمَيْسِرِ ، وَيَسْـَٔلُونَكَ عَنِ ٱلْيَتَـٰمَىٰ ، وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ ، وَيَسْـَٔلُونَكَ عَنِ ٱلْأَنفَالِ","a"]]],["p",[["(صحابہؓ آپؐ سے قابل احترام مہینے، شراب اور جوئے، یتیموں، حیض اور مال غنیمت کے بارے میں پوچھتے ہیں)",""]]],["q",[["وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ","a"]]],["p",[["(صحابہؓ آپؐ سے پوچھتے ہیں کہ وہ کیا خرچ کریں) اور وہ صرف اپنے فائدہ کی بات ہی پوچھا کرتے تھے۔ حضرت ابن عباسؓ نے یہ بھی فرمایا بیت ",""],["ٱللَّٰه","a"],[" کا سب سے پہلے فرشتوں نے طواف کیا اور حجر اسود اور رکن یمانی کے درمیان کئی نبیوں کی قبریں ہیں۔ جب کسی نبی کی قوم اسے بہت زیادہ تکلیف دینے لگتی تو وہ انہیں چھوڑ کر بیت ",""],["ٱللَّٰه","a"],[" کے پاس آ جاتا پھر وفات تک یہاں ہی ",""],["ٱللَّٰه","a"],[" کی عبادت کرتا رہتا۔",""],[" (18)","s"]]]],"f":[["(18)","Tabraani. Haythami (Vol.1 Pg.158) has commented on the chain of narrators. Bazzaar has reported a similar narration, as quoted in Al Itqaan."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ انصار کی عورتیں بہت اچھی ہیں دینی مسئلہ پوچھنے اور دین کی سمجھ حاصل کرنے میں حیا نہیں کرتی ہیں۔",""],[" (19)","s"]]]],"f":[["(19)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.88)."]]},{"b":[["n",[["حضرت ام سلیمؓ","b"],[" فرماتی ہیں کہ میں حضورؐ کی زوجہ محترمہ حضرت ام سلمہؓ کی پڑوسن تھی۔ میں نے (ان کے گھر میں جا کر) عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ذرا یہ بتائیں کہ جب کوئی عورت خواب میں یہ دیکھے کہ اس کے خاوند نے اس سے صحبت کی ہے تو کیا اسے غسل کرنا پڑے گا؟ یہ سن کر حضرت ام سلمہؓ نے کہا اے ام سلیم! تمہارے ہاتھ خاک آلود ہوں تم نے ",""],["ٱللَّٰه","a"],[" کے رسولؐ کے سامنے عورتوں کو رسوا کر دیا۔ میں نے کہا ",""],["ٱللَّٰه","a"],[" تعالیٰ حق بات بیان کرنے سے حیا نہیں کرتے۔ ہمیں جب کسی مسئلہ میں مشکل پیش آئے تو اسے نبی کریمؐ سے پوچھ لینا اس سے بہتر ہے کہ ہم ایسے ہی اندھیرے میں ہیں۔ پھر حضورؐ نے فرمایا اے ام سلیم! تمہارے ہاتھ خاک آلود ہوں اگر اس سے (کپڑوں پر یا جسم پر) پانی نظر آئے تو اسے غسل کرنا پڑے گا۔ حضرت ام سلمہؓ نے کہا کیا عورت کا بھی پانی ہوتا ہے؟ حضورؐ نے فرمایا تو پھر بچہ ماں کے کیسے مشابہ ہو جاتا ہے؟ یہ عورتیں مزاج اور طبیعت میں مردوں جیسی ہیں۔",""],[" (20)","s"]]]],"f":[["(20)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.88)."]]},{"b":[["n",[["حضرت سعدؓ","b"],[" فرماتے ہیں کہ حضورؐ کوئی بات ارشاد فرما دیتے تو بعض لوگ ایک دوسرے سے اس کے بارے میں بہت زیادہ سوالات کرتے اور پھر حضورؐ سے پوچھنے لگ جاتے جب پوچھنا شروع کرتے تو اس وقت تک وہ چیز حلال ہوتی لیکن وہ حضورؐ سے اس کے بارے میں اتنے سوالات کرتے کہ آخر وہ چیز ",""],["ٱللَّٰه","a"],[" کی طرف سے حرام کر دی جاتی۔",""],[" (21)","s"]]]],"f":[["(21)","Bazzaar. Haythami (Vol.1 Pg.158) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں کہ لعان کی آیتیں زیادہ سوالات کرنے کی وجہ سے نازل ہوئیں۔",""],[" (22)","s"]]]],"f":[["(22)","Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.158)."]]},{"b":[["n",[["ایک دن لوگوں نے حضرت ابن مسعودؓ سے بہت زیادہ سوالات کیے تو انہوں نے حضرت حارث بن قیسؓ سے فرمایا اے ابن قیس! (حارث کو \"حار\" کہہ کر پکارا) تمہارا کیا خیال ہے یہ لوگ اتنا زیادہ پوچھ کر کیا کرنا چاہتے ہیں؟ حضرت حارثؓ نے کہا یہ لوگ تو بس سیکھ کر چھوڑ دیں گے۔ حضرت ابن مسعودؓ نے فرمایا اس ذات کی قسم جس کے علاوہ کوئی معبود نہیں! تم نے ٹھیک کہا۔",""],[" (23)","s"]]]],"f":[["(23)","Tabraani in his Kabeer, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.158)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" نے فرمایا اے لوگو! جو چیز ابھی ہوئی نہیں اس کے بارے میں مت پوچھو کیونکہ حضرت عمرؓ اس آدمی پر لعنت بھیجتے تھے جو اس چیز کے بارے میں پوچھے جو ابھی ہوئی نہیں۔ ",""],["حضرت طاؤسؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ نے فرمایا کسی کے لیے یہ بات حلال نہیں ہے کہ وہ اس چیز کے بارے میں پوچھے جو ابھی ہوئی نہیں۔ کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ان تمام امور کے بارے میں فیصلہ فرما رکھا ہے جو آئندہ ہونے والے ہیں۔",""],[" (24)","s"],[" (25)","s"]]]],"f":[["(24)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.143)."],["(25)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.142)."]]},{"b":[["n",[["حضرت خارجہ بن زید بن ثابتؒ","b"],[" کہتے ہیں کہ میرے والد حضرت زید بن ثابتؓ سے جب کوئی چیز پوچھی جاتی تھی تو اس وقت تک اس کے بارے میں اپنی سمجھ سے کوئی جواب نہ دیتے تھے جب تک یہ نہ پوچھ لیتے کہ یہ بات ہو چکی ہے یا نہیں؟ اگر وہ ہوئی نہ ہوتی تو اس کا جواب نہ دیتے اور اگر ہو چکی ہوتی تو پھر اس کے بارے میں گفتگو فرماتے اور جب ان سے کوئی مسئلہ پوچھا جاتا تو پوچھتے کہ کیا یہ پیش آ چکا ہے؟ تو کوئی آدمی ان سے کہتا اے ابوسعید! ابھی پیش تو نہیں آیا لیکن ہم پہلے سے اس کا جواب تیار کر رہے ہیں۔ یہ فرماتے اسے چھوڑ دو اگر پیش آ چکا ہوتا تو اس کا جواب بتا دیتے۔",""],[" (26)","s"]]]],"f":[["(26)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.142)."]]},{"b":[["n",[["حضرت مسروقؒ","b"],[" کہتے ہیں کہ میں نے حضرت ابی بن کعبؓ سے ایک مسئلہ پوچھا تو انہوں نے فرمایا کیا یہ پیش آ چکا ہے؟ میں نے کہا نہیں تو فرمایا جب تک یہ پیش نہ آئے اس وقت تک مجھے آرام سے رہنے دو۔ ابن سعد کی روایت میں اس طرح ہے کہ حضرت ابیؓ نے فرمایا کہ جب تک یہ پیش نہ آ جائے اس وقت تک ہمیں آرام سے رہنے دو جب یہ پیش آ جائے گا تب ہم تمہارے لیے کوشش کر کے اپنی رائے بتا دیں گے۔",""],[" (27)","s"],[" (28)","s"]]]],"f":[["(27)","Ibn Sa'd (Vol.3 Pg.500)."],["(28)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.142)."]]},{"b":[["n",[["حضرت عامرؒ","b"],[" کہتے ہیں کہ حضرت عمارؓ سے ایک مسئلہ پوچھا گیا تو پوچھا کیا یہ مسئلہ پیش آ چکا ہے؟ لوگوں نے کہا نہیں تو فرمایا جب تک یہ مسئلہ پیش نہ آ جائے اس وقت تک ہمیں چھوڑے رکھو جب یہ پیش آ جائے گا تب زور لگا کر اس کا صحیح جواب نکال کر تمہیں بتائیں گے۔",""],[" (29)","s"]]]],"f":[["(29)","Ibn Sa'd (Vol.3 Pg.256)."]]}]},"77":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوامامہؓ","b"],[" فرماتے ہیں کہ ایک آدمی نے حضورؐ کی خدمت میں آ کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں نے فلاں قبیلہ کا حصہ خرید لیا تو مجھے اس میں اتنا اور اتنا نفع ہوا۔ حضورؐ نے فرمایا کیا میں تمہیں اس سے زیادہ نفع کی صورت نہ بتا دوں؟ اس نے کہا کیا اس سے زیادہ نفع ہو سکتا ہے؟ حضورؐ نے فرمایا ہاں۔ آدمی دس آیتیں سیکھ لے (تو اسے اس سے زیادہ نفع مل جائے گا) چنانچہ وہ آدمی گیا اور اس نے دس آیتیں سیکھیں اور آ کر حضورؐ کو اس کی اطلاع دی۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.7 Pg.165)."]]},{"b":[["n",[["حضرت ابی بن کعبؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا کیا میں تمہیں ایسی سورت نہ سکھاؤں کہ اس جیسی سورت تورات، انجیل، زبور اور قرآن (کسی آسمانی کتاب) میں نازل نہیں ہوئی۔ میں نے کہا ضرور سکھائیں۔ حضورؐ نے فرمایا امید ہے اس دروازے سے نکلنے سے پہلے ہی تم اس سورت کو سیکھ لو گے پھر حضورؐ کھڑے ہو گئے اور آپؐ کے ساتھ میں بھی کھڑا ہو گیا پھر آپؐ مجھ سے باتیں کرنے لگے۔ میرا ہاتھ آپؐ کے ہاتھ میں تھا اور میں اس خیال سے پیچھے ہٹنے لگا کہ حضورؐ کہیں مجھے بتانے سے پہلے باہر نہ چلے جائیں۔ جب میں دروازے کے قریب پہنچ گیا تو میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! وہ سورت جس کا آپ نے مجھ سے وعدہ کیا تھا؟ آپؐ نے فرمایا جب تم نماز کے لیے کھڑے ہوتے ہو تو کیا پڑھتے ہو؟ میں نے کہا سورت فاتحہ۔ آپؐ نے فرمایا بس یہی ہے یہی وہ سات آیتیں ہیں جن کو نماز میں بار بار پڑھا جاتا ہے جن کے بارے میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["وَلَقَدْ ءَاتَيْنَـٰكَ سَبْعًا مِّنَ ٱلْمَثَانِى وَٱلْقُرْءَانَ ٱلْعَظِيمَ  (سورۃ حجر: ۸۷)","a"]]],["p",[["ترجمہ: \"اور ہم نے آپ کو سات آیتیں دیں جو (نماز میں) مکرر پڑھی جاتی ہیں اور قرآن عظیم دیا۔\" یہی وہ چیز ہے جو مجھے خاص طور سے دی گئی ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.1 Pg.220)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ ایک دن حضرت ابوطلحہؓ سامنے سے آئے تو دیکھا کہ حضورؐ کھڑے ہوئے اصحاب صفہ کو قرآن پڑھا رہے ہیں اور آپؐ نے بھوک کی وجہ سے پیٹ مبارک پر پتھر کا ٹکڑا باندھا ہوا ہے تا کہ کمر سیدھی ہو جائے۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilya (Vol.1 Pg.342)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ ایک دن حضرت ابوموسیٰؓ اپنے گھر میں بیٹھے ہوئے تھے۔ آہستہ آہستہ بہت سے لوگ ان کے پاس جمع ہو گئے تو وہ ان کے سامنے قرآن پڑھنے لگے۔ اتنے میں ایک آدمی نے حضورؐ کی خدمت میں آ کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں آپ کو حضرت ابوموسیٰؓ کی عجیب بات نہ بتاؤں؟ وہ گھر میں بیٹھے ہوئے تھے پھران کے پاس لوگ جمع ہو گئے تو وہ ان کے سامنے قرآن پڑھنے لگے۔ حضورؐ نے فرمایا کیا تم ایسا کر سکتے ہو کہ مجھے ایسی جگہ بٹھا دو جہاں ان میں سے مجھے کوئی نہ دیکھ سکے؟ اس نے کہا جی ہاں۔ حضورؐ تشریف لے گئے اور اس آدمی نے حضورؐ کو ایسی جگہ بٹھا دیا جہاں حضورؐ کو ان میں سے کوئی نہیں دیکھ سکتا تھا اور وہاں سے حضورؐ حضرت ابوموسیٰؓ کی تلاوت کو سننے لگے پھر حضورؐ نے فرمایا یہ حضرت داؤدؑ کے لہجہ جیسی آواز میں قرآن پڑھ رہے ہیں۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Ya'la, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.360). Ibn Asaakir has reported a similar narration, as quoted in Kanzul Ummaal (Vol.7 Pg.94)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں کہ حضرت اشعریؓ نے مجھے حضرت عمرؓ کے پاس بھیجا۔ حضرت عمرؓ نے مجھ سے فرمایا اشعری بھائی کو کس حال میں چھوڑ کر آئے ہو؟ میں نے کہا میں نے ان کو اس حال میں چھوڑا کہ وہ لوگوں کو قرآن سکھا رہے تھے۔ حضرت عمرؓ نے فرمایا ذرا غور سے سنو! وہ بہت سمجھدار آدمی ہیں لیکن یہ بات انہیں نہ سنانا پھر فرمایا تم نے دیہاتیوں کو کس حال میں چھوڑا؟ میں نے کہا اشعری قبیلہ والے؟ آپ نے فرمایا نہیں بلکہ بصرہ والے۔ میں نے کہا اگر یہ بات بصرہ والے سن لیں تو انہیں بہت بری لگے گی۔ حضرت عمرؓ نے فرمایا یہ بات انہیں نہ بتانا لیکن ہیں وہ لوگ دیہاتی ہی، البتہ ان میں سے جسے ",""],["ٱللَّٰه","a"],[" جہاد فی سبیل ",""],["ٱللَّٰه","a"],[" کی توفیق دے دے (تو وہ دیہاتی نہیں رہے گا)۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Sa'd (Vol.4 Pg.162)."]]},{"b":[["n",[["حضرت ابورجاء عطاردیؒ","b"],[" کہتے ہیں کہ حضرت ابوموسیٰ اشعریؓ بصرہ کی اس مسجد میں ہمارے پاس بار بار تشریف لاتے اور ایک ایک حلقہ میں بیٹھتے اور ان کا یہ منظر اب بھی میری آنکھوں کے سامنے ہے کہ انہوں نے دو سفید چادریں پہنی ہوئی ہیں اور مجھے قرآن پڑھا رہے ہیں اور میں نے سورت اقرأ باسم ربک الذی خلق ان سے ہی سیکھی تھی اور یہ سورت حضرت محمدؐ پر سب سے پہلے نازل ہوئی تھی۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Hilya (Vol.1 Pg.256)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ جب حضورؐ کا انتقال ہو گیا تو میں نے قسم کھائی کہ دو پٹھوں کے درمیان جو قرآن ہے جب تک میں اس سارے کو جمع نہیں کر لوں گا اس وقت تک میں اپنی پیٹھ سے چادر نہیں اتاروں گا یعنی آرام نہیں کروں گا۔ چنانچہ جب تک میں نے سارا قرآن جمع نہیں کر لیا یعنی یاد نہ کر لیا اپنی پیٹھ سے چادر نہیں اتاری بالکل آرام نہیں کیا۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Nu'aym in his Hilya (Vol.1 Pg.67)."]]},{"b":[["n",[["حضرت میمونؒ","b"],[" کہتے ہیں کہ حضرت ابن عمرؓ نے چار سال میں سورت بقرہ سیکھی۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Sa'd (Vol.4 Pg.121)."]]},{"b":[["n",[["قبیلہ اجمع کے ایک صاحب بیان کرتے ہیں کہ مدائن شہر میں لوگوں نے سنا کہ حضرت سلمانؓ مسجد میں ہیں تو لوگ ان کے پاس آنے لگے یہاں تک کہ ان کے پاس ایک ہزار کے قریب آدمی جمع ہو گئے۔ حضرت سلمانؓ کھڑے ہو کر کہنے لگے بیٹھ جاؤ بیٹھ جاؤ۔ جب سب بیٹھ گئے تو انہوں نے سورت یوسف پڑھنی شروع کر دی۔ آہستہ آہستہ لوگ بکھرنے لگے اور جانے لگے اور تقریباً سو کے قریب رہ گئے تو حضرت سلمانؓ کو غصہ آ گیا اور فرمایا تم لوگ چکنی چپڑی خوشنما باتیں سننا چاہتے ہو۔ میں نے تمہیں ",""],["ٱللَّٰه","a"],[" کی کتاب سنانی شروع کی تو تم چلے گئے۔",""],[" (9)","s"]]]],"f":[["(9)","Abu Nu'aym in his Hilya (Vol.1 Pg.203)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" آدمی کو ایک آیت پڑھاتے اور فرماتے جتنی چیزوں پر سورج کی روشنی پڑتی ہے یا روئے زمین پر جتنی چیزیں ہیں یہ آیت ان سب سے بہتر ہے۔ اس طرح آپ پورا قرآن سکھاتے اور ہر آیت کے بارے میں یہ ارشاد فرماتے اور ایک روایت میں یہ ہے کہ جب صبح ہوتی تو لوگ حضرت ابن مسعودؓ کے پاس ان کے گھر آنے لگتے۔ یہ ان سے فرماتے سب اپنی اپنی جگہ بیٹھ جائیں پھر ان لوگوں کے پاس سے گزرتے جنہیں قرآن پڑھاتے ہوتے اور ان سے فرماتے اے فلانے! تم کون سی سورت تک پہنچ گئے ہو؟ وہ اس سورت کی آیت بتا دیتا تو یہ اس سے آگے والی آیت اسے پڑھاتے اور فرماتے اس آیت کو سیکھ لو یہ تمہارے لیے ان تمام چیزوں سے بہتر ہے جو زمین اور آسمان کے درمیان ہیں اور کسی کاغذ پر صرف ایک آیت لکھی ہوئی دیکھنا بھی دنیا و مافیہا سے بہتر ہے پھر دوسری آیت پڑھاتے اور یہی ارشاد فرماتے اور ان سب لوگوں کو یہی بات کہتے۔",""],[" (10)","s"]]]],"f":[["(10)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.7 Pg.167)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرمایا کرتے تھے اس قرآن کو اپنے اوپر لازم سمجھو کیونکہ یہ ",""],["ٱللَّٰه","a"],[" کا دسترخوان ہے ",""],["ٱللَّٰه","a"],[" کے اس دسترخوان سے ہر ایک کو ضرور لینا چاہیے اور علم سیکھنے سے ہی حاصل ہوتا ہے۔",""],[" (11)","s"]]]],"f":[["(11)","Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.129)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرمایا کرتے تھے اس قرآن کو اپنے اوپر لازم سمجھو کیونکہ یہ ",""],["ٱللَّٰه","a"],[" کا دسترخوان ہے جو آدمی اسے جتنا زیادہ سیکھ سکتا ہے اسے اتنا سیکھنا چاہیے۔ خیر سے سب سے زیادہ خالی گھر وہ ہے جس میں ",""],["ٱللَّٰه","a"],[" کی کتاب میں سے کچھ نہ ہو اور جس گھر میں ",""],["ٱللَّٰه","a"],[" کی کتاب میں سے کچھ نہیں ہو وہ اس اجاڑ اور ویران گھر کی طرح ہے جس میں رہنے والا کوئی نہ ہو اور جس گھر میں سورت بقرہ پڑھی جاتی ہے اس گھر سے شیطان نکل جاتا ہے۔",""],[" (12)","s"]]]],"f":[["(12)","Abu Nu'aym in his Hilya (Vol.1 Pg.130)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں کہ ایک شخص حضرت عمرؓ کے دروازے پر بہت زیادہ آیا کرتا تھا۔ حضرت عمرؓ نے اس سے فرمایا جا ",""],["ٱللَّٰه","a"],[" کی کتاب سیکھ چنانچہ وہ چلا گیا اور کئی دن تک حضرت عمرؓ کو نظر نہ آیا پھر اس سے حضرت عمرؓ کی ملاقات ہوئی تو حضرت عمرؓ نے نہ آنے پر اس پر کچھ خفگی کا اظہار کیا تو اس نے کہا مجھے ",""],["ٱللَّٰه","a"],[" کی کتاب میں وہ کچھ مل گیا ہے جس کے بعد عمر کے دروازے کی ضرورت نہیں رہی۔",""],[" (13)","s"]]]],"f":[["(13)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.217)."]]}]},"78":{"lead":[],"stories":[{"b":[["n",[["حضرت عمرؓ نے فرمایا ہر مسلمان کے لیے کم از کم چھ سورتیں سیکھنا ضروری ہے دو سورتیں فجر کی نماز کے لیے دو سورتیں مغرب کی نماز کے لیے اور دو سورتیں عشاء کی نماز کے لیے۔",""],[" (1)","s"]]]],"f":[["(1)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.1 Pg.217)."]]},{"b":[["n",[["حضرت مسور بن مخرمہؓ","b"],[" فرماتے ہیں کہ میں نے حضرت عمر بن خطابؓ کو یہ فرماتے ہوئے سنا سورت بقرہ، سورت مائدہ، سورت نساء، سورت حج اور سورت نور ضرور سیکھو کیونکہ ",""],["ٱللَّٰه","a"],[" نے جو اعمال فرض کیے ہیں وہ سب ان سورتوں میں مذکور ہیں۔ ",""],["حضرت حارثہ بن مضربؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ نے ہمیں خط میں یہ لکھا کہ سورت نساء، سورت احزاب اور سورت نور سیکھو۔ حضرت عمرؓ نے فرمایا سورت براءت سیکھو اور اپنی عورتوں کو سورت نور سکھاؤ اور انہیں چاندی کے زیور پہناؤ۔",""],[" (2)","s"],[" (3)","s"],[" (4)","s"]]]],"f":[["(2)","Haakim and Bayhaqi."],["(3)","Abu Ubayd."],["(4)","Sa'eed bin Mansoor, Abu Shaykh and Bayhaqi, as quoted in Kanzul Ummaal (Vol.1 Pg.224)."]]}]},"79":{"lead":[],"stories":[{"b":[["n",[["نبی کریمؐ کے صحابی ",""],["حضرت ابو ریحانہؓ","b"],[" نے فرمایا کہ میں حضورؐ کی خدمت میں آیا اور آپؐ کی خدمت میں یہ شکایت کی کہ قرآن میرے ہاتھ سے نکل جاتا ہے یاد نہیں رہتا اور اسے پڑھنا بھی دشوار ہے۔ حضورؐ نے فرمایا ایسے کام کی ذمہ داری مت اٹھاؤ جو تمہارے بس میں نہیں اور تم سجدے زیادہ کرو یعنی نفل نماز کثرت سے پڑھا کرو۔ ",""],["حضرت عمیرؒ","b"],[" کہتے ہیں حضرت ابو ریحانہؓ عسقلان تشریف لائے تھے اور وہ سجدے بہت زیادہ کیا کرتے تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Abdul Ghaafir bin Salaamah Himsi in his Taareekh, as quoted in Isaabah (Vol.2 Pg.156)."]]}]},"80":{"lead":[],"stories":[{"b":[["n",[["حضرت قرظہ بن کعبؓ","b"],[" فرماتے ہیں ہم عراق کے ارادے سے (مدینہ سے) نکلے تو حضرت عمر بن خطابؓ بھی ہمارے ساتھ حراء مقام تک چلے (جو مدینہ سے تین میل کے فاصلے پر ہے) پھر آپ نے وضو کر کے فرمایا کیا آپ لوگ جانتے ہیں کہ میں آپ لوگوں کے ساتھ کیوں چلا؟ ساتھیوں نے کہا جی ہاں ہم لوگ حضورؐ کے صحابہ ہیں اس لیے آپ ہمارے ساتھ چلے ہیں۔ حضرت عمرؓ نے فرمایا (یہ وجہ تو خیر ہے ہی لیکن اصل میں میں آپ لوگوں کو ایک خاص بات کہنا چاہتا تھا اور وہ یہ ہے کہ) تم لوگ ایسے علاقہ میں جا رہے ہو کہ وہاں کے لوگ شہد کی مکھی جیسی دھیمی آواز سے قرآن پڑھتے ہیں۔ ان کے سامنے احادیث بیان نہ کرنا ورنہ وہ (قرآن کو چھوڑ کر تمہارے ساتھ (احادیث میں) مشغول ہو جائیں گے بلکہ قرآن کو (احادیث سے) الگ تھلگ رکھو اور حضورؐ کی طرف سے روایت کم کرو اور اب جاؤ میں تمہارے ساتھ (اجر میں) شریک ہوں۔ جب حضرت قرظہؓ (عراق) پہنچے تو لوگوں نے کہا آپ ہمیں حدیثیں سنائیں فرمایا حضرت ابن خطابؓ نے ہمیں اس کام سے روکا ہے۔ ابن عبدالبر کی ایک روایت میں یہ ہے ان کو احادیث نہ سنانا ورنہ تم ان کو ان ہی میں مشغول کر دو گے اور قرآن عمدہ طریقہ سے پڑھنا۔ دوسری روایت میں یہ ہے کہ پھر حضرت عمرؓ نے ہم سے فرمایا کیا تم جانتے ہو میں آپ لوگوں کے ساتھ کیوں نکلا؟ ہم نے کہا آپ ہمیں رخصت کرنا چاہتے ہیں اور ہمارا اکرام کرنا چاہتے ہیں۔ انہوں نے فرمایا یہ تو ہے ہی لیکن میں ایک اور ضرورت کی وجہ سے نکلا ہوں اور وہ یہ ہے کہ تم ایسے علاقہ میں جا رہے ہو اور پھر آگے پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Haakim (Vol.1 Pg.102), reporting from reliable sources as confirmed by Dhahabi."],["(2)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.120). Ibn Sa'd (Vol.6 Pg.7) has reported a similar narration with the words \"it will prevent them from specialising in the Qur'aan\" in place of the words \"it will prevent them from mastering the Qur'aan\"."]]}]},"81":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عمرؓ","b"],[" کے ایک آزاد کردہ غلام کہتے ہیں کہ صبیغ عراقی ملک شام کے مسلمان لشکروں میں قرآن کی (ان) چیزوں کے بارے میں پوچھنے لگا (جن کی مراد ",""],["ٱللَّٰه","a"],[" کے سوا کوئی نہیں جانتا) وہ چلتے چلتے مصر پہنچ گیا تو حضرت عمرو بن عاصؓ نے اسے حضرت عمر بن خطابؓ کے پاس بھیج دیا۔ جب ان کا قاصد خط لے کر حضرت عمرؓ کے پاس آیا تو حضرت عمرؓ نے خط پڑھ کر فرمایا وہ آدمی کہاں ہے؟ قاصد نے کہا قیام گاہ میں ہے۔ حضرت عمرؓ نے فرمایا اس پر نگاہ رکھنا وہ کہیں چلانہ جائے ورنہ تمہیں سخت سزا دوں گا۔ قاصد اسے حضرت عمرؓ کے پاس لے آیا حضرت عمرؓ نے اس سے پوچھا تم کیا پوچھتے ہو؟ اس نے اپنے سوالات بتائے۔ حضرت عمرؓ نے میرے پاس پیغام بھیجا کہ کھجور کی ٹہنی لاؤ (میں نے جا کر ان کو ٹہنی لا دی) انہوں نے صبیغ کو اس ٹہنی سے اتنا مارا کہ اس کی پیٹھ زخمی ہو گئی پھر حضرت عمرؓ نے اسے چھوڑ دیا جب اس کی پیٹھ ٹھیک ہو گئی اور اسے مارنے کے لیے تیسری مرتبہ بلایا تو صبیغ نے کہا اے امیر المومنین! اگر آپ مجھے قتل کرنا چاہتے ہیں تو اچھی طرح قتل کریں اور اگر آپ میرا علاج کرنا چاہتے ہیں تو اب میں ٹھیک ہو گیا ہوں (قرآن کی متشابہ آیات کے بارے میں پوچھنے اور گفتگو کرنے سے میں نے توبہ کر لی ہے)۔ اس پر حضرت عمرؓ نے اسے اپنے علاقہ میں جانے کی اجازت دے دی اور (وہاں کے گورنر) حضرت ابوموسیٰ اشعریؓ کو لکھا کہ صبیغ کے ساتھ کوئی مسلمان نہ بیٹھا کرے۔ اس سے صبیغ بہت زیادہ پریشان ہوا پھر حضرت ابوموسیٰؓ نے حضرت عمرؓ کو لکھا کہ اب صبیغ کی حالت ٹھیک ہو گئی ہے۔ اس پر حضرت عمرؓ نے انہیں لکھا کہ اب لوگوں کو اس کے ساتھ اٹھنے بیٹھنے کی اجازت دے دو۔",""],[" (1)","s"]]]],"f":[["(1)","Daarimi, Ibn Abdil Hakam and Ibn Asaakir."]]},{"b":[["n",[["حضرت سلیمان بن یسارؒ","b"],[" کہتے ہیں کہ بنوتمیم کے ایک آدمی کو صبیغ بن عسل کہا جاتا تھا۔ وہ مدینہ منورہ آیا۔ اس کے پاس چند کتابیں تھیں اور وہ قرآن کی متشابہ آیات کے بارے میں پوچھا کرتا تھا (جن کی مراد ",""],["ٱللَّٰه","a"],[" کے سوا کوئی نہیں جانتا) حضرت عمرؓ کو اس کی اطلاع ملی تو اس کے لیے کھجور کی ٹہنیاں تیار کروائیں اور آدمی بھیج کر اسے بلایا۔ جب وہ حضرت عمرؓ کے پاس آیا تو اس سے پوچھا تو کون ہے؟ اس نے کہا میں ",""],["ٱللَّٰه","a"],[" کا بندہ صبیغ ہوں۔ حضرت عمرؓ نے فرمایا میں ",""],["ٱللَّٰه","a"],[" کا بندہ عمر ہوں۔ پھر حضرت عمرؓ نے اشارہ کر کے اسے ٹہنیوں سے مارنا شروع کر دیا اور اتنا مارا کہ اس کا سر زخمی ہو گیا اور خون اس کے چہرے پر بہنے لگا تو صبیغ نے کہا اے امیر المومنین! اب بس کر دیں ",""],["ٱللَّٰه","a"],[" کی قسم! میرے دماغ میں جو (شیطان) گھسا ہوا تھا وہ اب جاتا رہا۔ ابوعثمان کی روایت میں یہ ہے کہ حضرت عمرؓ نے ہمیں لکھا کہ اس کے ساتھ نہ بیٹھو۔ چنانچہ جب وہ آتا اور ہم سو آدمی بھی ہوتے تو ہم بکھر جاتے۔ ",""],["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں کہ صبیغ تمیمی حضرت عمرؓ کے پاس آیا اور اس نے سورت ذاریات کے بارے میں ان سے پوچھا آگے اور حدیث ذکر کی ہے۔ ابن انباری کی روایت میں یہ ہے کہ پہلے تو صبیغ اپنی قوم کا سردار تھا لیکن اس واقعہ کے بعد اس کی قوم میں اس کی کوئی حیثیت نہ رہی۔",""],[" (2)","s"],[" (3)","s"],[" (4)","s"]]]],"f":[["(2)","Daarimi, as quoted in Kanzul Ummaal (Vol.1 Pg.228)."],["(3)","Khateeb and Ibn Asaakir. Daaraqutni has reported a similar narration."],["(4)","Ibn Ambaari. Ismaa'eeli has reported a similar narration. The narrations above have been quoted in Isaabah (Vol.2 Pg.198)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں کہ کچھ لوگ مصر میں حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرؓ سے ملے اور ان سے کہا ہمیں ",""],["ٱللَّٰه","a"],[" کی کتاب میں ایسی چیزیں نظر آ رہی ہیں جن پر عمل کرنے کا ",""],["ٱللَّٰه","a"],[" نے حکم دیا ہے لیکن ان پر عمل نہیں ہو رہا ہے اس لیے ہم اس بارے میں امیر المومنین سے ملنا چاہتے ہیں چنانچہ حضرت ابن عمرؓ مدینہ آئے اور یہ لوگ بھی ان کے ساتھ مدینہ آئے۔ حضرت ابن عمرؓ نے حضرت عمرؓ سے ملاقات کی اور عرض کیا اے امیر المومنین! کچھ لوگ مجھ سے مصر میں ملے تھے اور انہوں نے کہا تھا کہ ہمیں ",""],["ٱللَّٰه","a"],[" کی کتاب میں ایسی چیزیں نظر آ رہی ہیں جن پر عمل کرنے کا ",""],["ٱللَّٰه","a"],[" نے حکم دیا ہے لیکن ان پر عمل نہیں ہو رہا، اس لیے اس بارے میں وہ آپ سے ملنا چاہتے ہیں۔ حضرت عمرؓ نے فرمایا انہیں اکٹھا کر کے میرے پاس لے آؤ۔ چنانچہ حضرت ابن عمرؓ انہیں اکٹھا کر کے حضرت عمرؓ کے پاس لے آئے ان میں سے جو حضرت عمرؓ کے سب سے زیادہ قریب تھا اسے حضرت عمرؓ نے بلایا اور فرمایا میں تمہیں ",""],["ٱللَّٰه","a"],[" اور اسلام کا واسطہ دے کر پوچھتا ہوں کیا تم نے سارا قرآن پڑھا ہے؟ اس نے کہا جی ہاں۔ حضرت عمرؓ نے فرمایا کیا تم نے سارا دل میں جما لیا ہے؟ اس نے کہا نہیں۔ حضرت عمرؓ نے فرمایا کیا تم نے سارا قرآن یاد کر لیا ہے؟ کیا تم نے سارے پر عمل کر لیا ہے؟ پھر ان میں سے ایک ایک کو بلا کر ہر ایک سے یہی سوالات کیے پھر فرمایا عمر کو اس کی ماں گم کرے کیا تم عمر کو اس بات کا مکلف بناتے ہو کہ وہ تمام لوگوں کو قرآن پر عمل کرنے کے لیے کھڑا کر دے۔ ہمارے رب کو پہلے سے معلوم ہے کہ ہم سے خطائیں سرزد ہوں گی پھر یہ آیت پڑھی",""]]],["q",[["إِن تَجْتَنِبُوا۟ كَبَآئِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنكُمْ سَيِّـَٔاتِكُمْ وَنُدْخِلْكُم مُّدْخَلًا كَرِيمًا  (سورۃ نساء: ۳۱)","a"]]],["p",[["ترجمہ: \"جن کاموں سے تم کو منع کیا جاتا ہے ان میں جو بھاری کام ہیں اگر تم ان سے بچتے رہے تو ہم تمہاری خفیف برائیاں تم سے دور فرما دیں گے اور ہم تم کو ایک معزز جگہ میں داخل کر دیں گے۔\" پھر حضرت عمرؓ نے فرمایا کیا مدینہ والوں کو معلوم ہے کہ تم لوگ کس وجہ سے آئے ہو؟ انہوں نے کہا نہیں۔ حضرت عمرؓ نے فرمایا اگر انہیں معلوم ہوتا تو میں تمہارے اوپر کر کے ان کو بھی یہی نصیحت کرتا۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.1 Pg.228)."]]}]},"82":{"lead":[],"stories":[{"b":[["n",[["حضرت عبادہ بن صامتؓ","b"],[" فرماتے ہیں کہ خود تو حضورؐ (اجتماعی کاموں میں) زیادہ مشغول رہتے تھے، اس لیے جب کوئی آدمی آپؐ کے پاس ہجرت کر کے آتا تو آپؐ اسے قرآن سکھانے کے لیے ہم میں سے کسی کے حوالے فرما دیتے چنانچہ حضورؐ نے ایک آدمی میرے حوالے کیا وہ گھر میں میرے ساتھ رہتا تھا۔ میں اسے رات کا کھانا گھر میں کھلاتا اور اسے قرآن پڑھاتا۔ وہ اپنے گھر واپس چلا گیا۔ اسے یہ خیال ہوا کہ اس پر (میرا) کچھ حق ہے، اس لیے اس نے مجھے ایک ایسی کمان ہدیے میں دی کہ میں نے اس سے عمدہ لکڑی والی اور اس سے اچھی مڑنے والی کمان کبھی دیکھی نہ تھی۔ میں نے حضورؐ کی خدمت میں آ کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ کا (اس کمان کے بارے میں) کیا خیال ہے؟ آپؐ نے فرمایا اگر تم اسے گلے میں لٹکاؤ گے تو یہ تمہارے دونوں کندھوں کے درمیان ایک چنگاری ہوگی۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani and Bayhaqi, as quoted in Kanzul Ummaal (Vol.1 Pg.231). Haakim (Vol.3 Pg.356) has also reported the narration from reliable sources as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت ابی بن کعبؓ","b"],[" نے ایک آدمی کو قرآن کی ایک سورت سکھائی اس نے حضرت ابیؓ کو ایک کپڑا یا چادر ہدیہ میں دی۔ حضرت ابیؓ نے حضورؐ سے اس کا تذکرہ کیا تو حضورؐ نے فرمایا اگر تم اسے لو گے تو تمہیں آگ کا کپڑا پہنایا جائے گا۔",""],[" (2)","s"],[" (3)","s"]]]],"f":[["(2)","Abd bin Humayd, as quoted in Kanzul Ummaal (Vol.1 Pg.231). Ibn Maajah, Rooyaani and Bayhaqi have reported a similar narration."],["(3)","Sa'eed bin Mansoor, as quoted in Kanzul Ummaal (Vol.1 Pg.230)."]]},{"b":[["n",[["حضرت طفیل بن عمروؓ","b"],[" فرماتے ہیں کہ مجھے حضرت ابی بن کعبؓ نے قرآن پڑھایا۔ میں نے انہیں ہدیے میں ایک کمان دی۔ وہ اس کو گلے میں لٹکا کر نبی کریمؐ کی خدمت میں گئے۔ حضورؐ نے فرمایا اے ابی! یہ کمان تمہیں کس نے دی؟ انہوں نے کہا حضرت طفیل بن عمروؓ نے۔ میں نے انہیں قرآن پڑھایا تھا۔ حضورؐ نے فرمایا تم اسے گلے میں ڈال لو لیکن یہ جہنم کا ایک ٹکڑا ہے۔ حضرت ابیؓ نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! ہم ان کا کھانا بھی کھاتے ہیں۔ حضورؐ نے فرمایا جو کھانا کسی اور کے لیے پکایا گیا ہو لیکن موقع پر تم بھی پہنچ گئے تو اس کے کھانے میں حرج نہیں ہے اور جو تمہارے لیے ہی پکایا گیا ہو تو اگر تم اسے کھاؤ گے تو آخرت میں تمہارا اتنا حصہ کم ہو جائے گا۔",""],[" (4)","s"]]]],"f":[["(4)","Baghawi and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.231). Tabraani has reported a similar narration but Haythami (Vol.4 Pg.95) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عوف بن مالکؓ","b"],[" فرماتے ہیں کہ میرے ساتھ ایک آدمی تھا جسے میں قرآن سکھایا کرتا تھا اس نے مجھے ایک کمان ہدیہ میں دی۔ میں نے نبی کریمؐ سے اس کا تذکرہ کیا۔ حضورؐ نے فرمایا اے عوف! کیا تم یہ چاہتے ہو کہ ",""],["ٱللَّٰه","a"],[" سے اس حال میں ملو کہ تمہارے دونوں کندھوں کے درمیان جہنم کی ایک چنگاری ہو؟",""],[" (5)","s"]]]],"f":[["(5)","Tabraani in his Kabeer, as quoted in Kanzul Ummaal (Vol.1 Pg.232). Haythami (Vol.4 Pg.96) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت مثنیٰ بن وائلؒ","b"],[" کہتے ہیں کہ میں حضرت عبد",""],["ٱللَّٰه","a"],[" بن بسرؓ کی خدمت میں حاضر ہوا۔ انہوں نے میرے سر پر ہاتھ پھیرا اور میں نے ان کے بازو پر اپنا ہاتھ رکھا۔ ان سے ایک آدمی نے (قرآن) سکھانے والے کی تنخواہ کے بارے میں پوچھا۔ انہوں نے فرمایا حضورؐ کے پاس ایک آدمی اندر آیا جس نے اپنے کندھے پر کمان ڈالی ہوئی تھی وہ کمان حضورؐ کو بہت پسند آئی۔ حضورؐ نے فرمایا تمہاری کمان بہت عمدہ ہے کیا تم نے یہ خریدی ہے؟ اس آدمی نے کہا نہیں، میں نے ایک آدمی کے بیٹے کو قرآن پڑھایا تھا اس نے مجھے یہ ہدیہ میں دی ہے۔ حضورؐ نے فرمایا کیا تم یہ چاہتے ہو کہ ",""],["ٱللَّٰه","a"],[" آگ کی کمان تمہارے گلے میں ڈالے؟ اس نے کہا نہیں۔ حضورؐ نے فرمایا تو پھر اسے واپس کر دو۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani in his Kabeer. Haythami (Vol.4 Pg.96) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت اسیر بن عمروؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ کو خبر ملی کہ حضرت سعدؓ نے کہا ہے کہ جو قرآن سارا پڑھ لے گا اسے میں دو ہزار وظیفہ لینے والوں میں شامل کر دوں گا۔ حضرت عمرؓ نے فرمایا اوہ! کیا ",""],["ٱللَّٰه","a"],[" کی کتاب پر وظیفہ دیا جائے گا؟",""]]]],"f":[]},{"b":[["n",[["حضرت سعد بن ابراہیمؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ نے اپنے ایک گورنر کو خط لکھا کہ لوگوں کو قرآن سیکھنے پر کچھ وظیفہ دو۔ اس طرح تو وہ بھی قرآن سیکھنے لگے گا جو صرف وظیفہ کے رجسٹر میں اندراج کروانا چاہتا ہو۔ اس پر حضرت عمرؓ نے انہیں لکھا کہ اچھا لوگوں کو (حضورؐ کی) صحبت اور (حضورؐ کی) دوستی کی بنیاد پر دو۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Ubayd, as quoted in Kanzul Ummaal (Vol.1 Pg.229)."]]},{"b":[["n",[["حضرت مجاہدؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ نے فرمایا اے علم اور قرآن والو! علم اور قرآن پر قیمت مت لو ورنہ زنا کار لوگ تم سے پہلے جنت میں چلے جائیں گے۔ (چونکہ دوسری احادیث میں قرآن پڑھانے پر اجرت لینے کی اجازت بھی آئی ہے، اس لیے بہتر یہ ہے کہ اجرت نہ لے اور اگر لے تو پڑھانے میں جو وقت خرچ ہوا ہے اجرت کو اس کا بدل سمجھے، پڑھانے کے عمل کا بدل نہ سمجھے۔)",""],[" (8)","s"]]]],"f":[["(8)","Khateeb, as quoted in Kanzul Ummaal (Vol.1 Pg.229)."]]}]},"83":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ میں حضرت عمر بن خطابؓ کے پاس بیٹھا ہوا تھا کہ اتنے میں ان کے پاس ایک خط آیا جس میں لکھا ہوا تھا کوفہ والوں میں سے بہت سے لوگوں نے اتنا قرآن پڑھ لیا۔ یہ پڑھ کر (خوشی کی وجہ سے) حضرت عمرؓ نے ",""],["ٱللَّٰه","a"],[" اکبر کہا ",""],["ٱللَّٰه","a"],[" ان پر رحم فرمائے میں نے کہا ان میں اختلاف ہو جائے گا۔ انہوں نے فرمایا اوہ ہو! تمہیں یہ کہاں سے پتہ چل گیا؟ اور حضرت عمرؓ کو غصہ آ گیا تو میں اپنے گھر چلا گیا۔ اس کے بعد انہوں نے میرے پاس بلانے کے لیے آدمی بھیجا۔ میں نے انہیں کوئی عذر کہلا بھیجا پھر انہوں نے یہ کہلا کر بھیجا کہ میں تمہیں قسم دے کر کہتا ہوں کہ تمہیں ضرور آنا ہوگا۔ چنانچہ میں ان کی خدمت میں حاضر ہوا۔ انہوں نے فرمایا تم نے کوئی بات کہی تھی؟ میں نے کہا استغفر ",""],["ٱللَّٰه","a"],["! اب وہ بات دوبارہ نہیں کہوں گا۔ فرمایا میں تمہیں قسم دے کر کہتا ہوں کہ تم نے جو بات کہی تھی وہ دوبارہ کہنی ہوگی۔ میں نے کہا آپ نے فرمایا تھا کہ میرے پاس خط میں یہ لکھا ہوا آیا ہے کہ کوفہ والوں میں سے بہت سے لوگوں نے اتنا اتنا قرآن پڑھ لیا ہے اس پر میں نے کہا تھا کہ ان میں اختلاف ہو جائے گا۔ حضرت عمرؓ نے فرمایا تمہیں یہ کہاں سے پتہ چلا؟ میں نے کہا میں نے یہ آیت پڑھی",""]]],["q",[["وَمِنَ ٱلنَّاسِ مَن يُعْجِبُكَ قَوْلُهُۥ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيُشْهِدُ ٱللَّهَ عَلَىٰ مَا فِى قَلْبِهِۦ وَهُوَ أَلَدُّ ٱلْخِصَامِ ۝ وَإِذَا تَوَلَّىٰ سَعَىٰ فِى ٱلْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ٱلْحَرْثَ وَٱلنَّسْلَ ۗ وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ  (سورۃ بقرہ: ۲۰۴–۲۰۵)","a"]]],["p",[["ترجمہ: \"اور بعض آدمی ایسے بھی ہیں کہ آپ کو اس کی گفتگو جو محض دنیوی غرض سے ہوتی ہے مزہ دار معلوم ہوتی ہے اور وہ ",""],["ٱللَّٰه","a"],[" کو حاضر و ناظر بتاتا ہے اپنے مافی الضمیر پر حالانکہ وہ (آپ کی مخالفت میں) نہایت شدید ہے اور جب پیٹھ پھیرتا ہے تو اس دوڑ دھوپ میں پھرتا رہتا ہے کہ شہر میں فساد کر دے اور (کسی کے) کھیت یا مواشی کو تلف کر دے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ فساد کو پسند نہیں فرماتے۔\" جب لوگ اس طرح کریں گے تو قرآن والا صبر نہیں کر سکے گا پھر میں نے یہ آیت پڑھی",""]]],["q",[["وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ ۚ فَحَسْبُهُۥ جَهَنَّمُ ۚ وَلَبِئْسَ ٱلْمِهَادُ ۝ وَمِنَ ٱلنَّاسِ مَن يَشْرِى نَفْسَهُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ ۗ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ  (سورۃ بقرہ: ۲۰۶–۲۰۷)","a"]]],["p",[["ترجمہ: \"اور جب اس سے کوئی کہتا ہے کہ خدا کا خوف کر تو نخوت اس کو اس گناہ پر (دونا) آمادہ کر دیتی ہے سو ایسے شخص کی کافی سزا جہنم ہے اور وہ بری ہی آرام گاہ ہے اور بعض آدمی ایسے بھی ہیں کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ کی رضا جوئی میں اپنی جان تک صرف کر ڈالتے ہیں اور ",""],["ٱللَّٰه","a"],[" تعالیٰ ایسے بندوں کے حال پر نہایت مہربان ہیں۔\" حضرت عمرؓ نے فرمایا اس ذات کی قسم جس کے قبضہ میں میری جان ہے! تم نے ٹھیک کہا۔",""],[" (1)","s"]]]],"f":[["(1)","Haakim (Vol.3 Pg.540), reporting from reliable sources as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عبید بن عمیرؒ","b"],[" کہتے ہیں کہ حضرت ابن عباسؓ نے فرمایا ایک دفعہ میں حضرت عمرؓ کے ساتھ تھا اور میں نے ان کا ہاتھ پکڑ رکھا تھا۔ حضرت عمرؓ نے فرمایا میرا خیال یہ ہے کہ قرآن لوگوں میں بہت زیادہ پھیل گیا ہے۔ میں نے کہا اے امیر المومنین! مجھے تو یہ بات بالکل پسند نہیں ہے۔ حضرت عمرؓ نے میرے ہاتھ میں سے اپنا ہاتھ کھینچ کر فرمایا کیوں؟ میں نے کہا اس لیے کہ جب سب لوگ قرآن پڑھیں گے (اور صحیح مطلب سمجھنے کی استعداد نہیں ہوگی) تو اپنے طور سے معنی اور مطلب تلاش کرنے لگیں گے اور جب معنی و مطلب تلاش کرنے لگیں گے تو ان میں اختلاف ہو جائے گا اور جب ان میں اختلاف ہو جائے گا تو ایک دوسرے کو قتل کرنے لگیں گے۔ یہ سن کر حضرت عمرؓ نے مجھے چھوڑ دیا اور الگ بیٹھ گئے۔ بس وہ دن میں نے جس پریشانی میں گزارا یہ ",""],["ٱللَّٰه","a"],[" ہی جانتا ہے پھر ظہر کے وقت ان کا قاصد میرے پاس آیا اور اس نے کہا امیر المومنین بلا رہے ہیں چلو۔ میں ان کے پاس گیا تو انہوں نے فرمایا تم نے کیا بات کہی تھی؟ میں نے اپنی ساری بات دہرا دی۔ حضرت عمرؓ نے فرمایا (سمجھتا تو میں بھی اسے تھا لیکن) میں لوگوں سے یہ بات چھپاتا تھا۔",""],[" (2)","s"]]]],"f":[["(2)","Haakim (Vol.3 Pg.540)."]]}]},"84":{"lead":[],"stories":[{"b":[["n",[["حضرت کنانہ عدویؒ","b"],[" کہتے ہیں کہ ملک شام میں مسلمانوں کے جو لشکر تھے ان کے امراء کو حضرت عمر بن خطابؓ نے خط میں یہ لکھا کہ قرآن کے تمام حافظوں کی فہرست میرے پاس بھیج دو تا کہ میں ان کا وظیفہ بڑھاؤں اور انہیں اطراف عالم میں لوگوں کو قرآن سکھانے کے لیے بھیج دوں۔ اس پر حضرت (ابوموسیٰ) اشعریؓ نے لکھا کہ ہمارے ہاں حافظوں کی تعداد تین سو سے زیادہ ہو گئی ہے۔ جواب میں حضرت عمرؓ نے ان حافظوں کو یہ نصیحتیں لکھیں: \"بسم ",""],["ٱللَّٰه","a"],[" الرحمٰن الرحیم۔ یہ خط ",""],["ٱللَّٰه","a"],[" کے بندے عمرؓ کی طرف سے حضرت عبد",""],["ٱللَّٰه","a"],[" بن قیس (ابوموسیٰ اشعری) اور ان کے ساتھ جتنے حافظ قرآن ہیں ان سب کے نام ہے۔ سلام علیکم! امابعد! یہ قرآن تمہارے لیے باعث اجر، سبب شرف و عزت اور (آخرت میں کام آنے والا) ذخیرہ ہے، اس لیے تم اس کے پیچھے چلو (اپنی خواہشات کو قربان کر کے اس پر عمل کرو) قرآن تمہارے پیچھے نہ چلے (یعنی قرآن کو اپنی خواہشات کے تابع نہ بناؤ) کیونکہ قرآن جس کے پیچھے چلے گا تو قرآن اسے گدی کے بل گرا دے گا پھر اسے آگ میں پھینک دے گا اور جو قرآن کے پیچھے چلے گا قرآن اسے جنت الفردوس میں لے جائے گا۔ تم اس بات کی پوری کوشش کرو کہ قرآن تمہارا سفارشی بنے اور تم سے جھگڑا نہ کرے کیونکہ قرآن جس کی سفارش کرے گا وہ جنت میں داخل ہوگا اور جس سے قرآن جھگڑا کرے گا وہ آگ میں داخل ہوگا اور یہ جان لو کہ قرآن ہدایت کا چشمہ اور علم کی رونق ہے اور یہ رحمٰن کے پاس سے آنے والی سب سے آخری کتاب ہے۔ اس کے ذریعہ سے ",""],["ٱللَّٰه","a"],[" تعالیٰ اندھی آنکھوں کو، بہرے کانوں کو اور پردہ پڑے ہوئے دلوں کو کھول دیتے ہیں اور جان لو کہ بندہ جب رات کو کھڑا ہوتا ہے اور مسواک کر کے وضو کرتا ہے پھر تکبیر کہہ کر (نماز میں) قرآن پڑھتا ہے تو فرشتہ اس کے منہ پر اپنا منہ رکھ کر کہتا ہے اور پڑھ۔ اور پڑھ۔ تم خود پاکیزہ ہو قرآن تمہارے لیے پاکیزہ ہے اور اگر وہ وضو کرے لیکن مسواک نہ کرے تو فرشتہ اس کی حفاظت کرتا ہے اور اسی تک محدود رہتا ہے اس سے آگے کچھ نہیں کرتا۔ غور سے سنو! نماز میں قرآن کا پڑھنا محفوظ خزانہ اور ",""],["ٱللَّٰه","a"],[" کا مقرر کردہ بہترین عمل ہے، لہٰذا جتنا ہو سکے زیادہ سے زیادہ قرآن پڑھو۔ نماز نور ہے اور زکوٰۃ دلیل ہے اور صبر روشن اور چمکدار عمل ہے اور روزہ ڈھال ہے اور قرآن تمہارے لیے حجت ہوگا یا تمہارے خلاف۔ لہٰذا قرآن کا اکرام کرو اور اس کی توہین نہ کرو کیونکہ جو قرآن کا اکرام کرے گا ",""],["ٱللَّٰه","a"],[" اس کا اکرام کرے گا اور جو اس کی توہین کرے گا ",""],["ٱللَّٰه","a"],[" اس کی توہین کرے گا اور جان لو کہ جو قرآن پڑھے گا اور اسے یاد کرے گا اور اس پر عمل کرے گا اور جو اس میں ہے اس کا اتباع کرے گا تو اس کی دعا ",""],["ٱللَّٰه","a"],[" کے ہاں قبول ہوگی۔ اگر ",""],["ٱللَّٰه","a"],[" چاہے گا تو اس کی دعا دنیا میں پوری کر دے گا ورنہ وہ دعا آخرت میں اس کے لیے ذخیرہ ہوگی اور جان لو کہ جو کچھ ",""],["ٱللَّٰه","a"],[" کے پاس ہے وہ ان لوگوں کے لیے بہتر اور ہمیشہ رہنے والا ہے جو ایمان والے ہیں اور اپنے رب پر توکل کرنے والے ہیں۔\"",""],[" (1)","s"]]]],"f":[["(1)","Ibn Zanjway, as quoted in Kanzul Ummaal (Vol.1 Pg.217)."]]},{"b":[["n",[["حضرت ابوکنانہؒ","b"],[" کہتے ہیں کہ حضرت ابوموسیٰؓ نے قرآن کے حافظوں کو جمع کیا۔ ان کی تعداد تقریباً تین سو تھی پھر حضرت ابوموسیٰؓ نے قرآن کی عظمت بیان کی اور فرمایا یہ قرآن تمہارے لیے باعث اجر ہوگا اور یہ بھی ہو سکتا ہے کہ تمہارے لیے بوجھ اور وبال بن جائے، لہٰذا تم قرآن کا اتباع کرو (اپنی خواہشات کو قربان کر کے اس پر عمل کرو) قرآن کو اپنے تابع نہ کرو کیونکہ جو قرآن کے تابع ہوگا اسے قرآن جنت کے باغوں میں لے جائے گا اور جو قرآن کو اپنے تابع کرے گا تو قرآن اسے گدی کے بل گرا کر آگ میں پھینک دے گا۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilya (Vol.1 Pg.257)."]]},{"b":[["n",[["حضرت ابواسود دیلیؒ","b"],[" کہتے ہیں کہ حضرت ابوموسیٰؓ نے قرآن کے حافظوں کو جمع کیا اور فرمایا میرے پاس اندر صرف قرآن کے حافظوں کو ہی لاؤ، چنانچہ ہم تقریباً تین سو حافظ ان کی خدمت میں اندر گئے پھر انہوں نے ہمیں نصیحت کی اور فرمایا تم لوگ شہر والوں کے حافظ ہو۔ کہیں ایسے نہ ہو کہ لمبی مدت گزر جانے پر تمہارے دلوں میں سختی آ جائے جیسے کہ اہل کتاب کے دل سخت ہو گئے تھے پھر فرمایا ایک سورت نازل ہوئی تھی جو سورت براءت جتنی لمبی تھی اور سورت براءت کی طرح اس میں سختی اور ڈانٹ ڈپٹ تھی۔ اس وجہ سے ہم کہتے تھے کہ یہ سورت براءت کے مشابہ ہے۔ اس کی ایک آیت مجھے یاد ہے جس کا ترجمہ یہ ہے کہ اگر ابن آدم کو سونے کی دو وادیاں مل جائیں تو وہ تیسری وادی کی تمنا کرنے لگے گا اور ابن آدم کے پیٹ کو صرف (قبر کی) مٹی ہی بھر سکتی ہے اور ایک اور سورت بھی نازل ہوئی تھی جس کے بارے میں ہم کہتے تھے کہ یہ سورت مسبحات کے مشابہ ہے کیونکہ وہ بھی سبح للہ سے شروع ہوئی تھی۔ اس کی ایک آیت مجھے یاد ہے",""]]],["q",[["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ  (سورۃ صف: ۲)","a"]]],["p",[["ترجمہ: \"اے ایمان والو! ایسی بات کیوں کہتے ہو جو کرتے نہیں ہو۔\" ہر بات گواہی بنا کر تمہاری گردنوں میں ڈالی جائے گی پھر قیامت کے دن اس کے بارے میں تم سے پوچھ ہوگی۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilya (Vol.1 Pg.257)."]]},{"b":[["n",[["حضرت ابن مسعودؓ کے پاس کوفہ کے کچھ لوگ آئے۔ حضرت ابن مسعودؓ نے انہیں سلام کیا اور انہیں اس بات کی تاکید کی کہ وہ ",""],["ٱللَّٰه","a"],[" سے ڈریں اور قرآن کے بارے میں آپس میں جھگڑا نہ کریں کیونکہ قرآن میں اختلاف نہیں ہے اور نہ اسے چھوڑا جا سکتا ہے نہ اسے زیادہ پڑھنے سے دل اکتاتا ہے۔ کیا آپ دیکھتے نہیں ہیں کہ شریعت اسلام کے حدود، فرائض اور اوامر سب ایک ہی ہیں۔ اگر قرآن میں ایک جگہ کسی کام کا حکم ہوتا اور دوسری جگہ اس کی ممانعت ہوتی تو پھر تو قرآن میں اختلاف ہوتا۔ قرآن میں تمام مضامین ایک دوسرے کی تائید کرنے والے ہیں اور مجھے یقین ہے کہ تم لوگوں میں علم اور دین کی سمجھ اور لوگوں سے زیادہ ہے اور اگر مجھے کسی آدمی کے بارے میں یہ معلوم ہو جائے کہ وہ حضرت محمدؐ پر نازل ہونے والے علوم کو مجھ سے زیادہ جاننے والا ہے اور اونٹ مجھے اس تک پہنچا سکتے ہیں تو میں (اس سے علم حاصل کرنے کے لیے) ضرور اس کے پاس جاتا تا کہ میرے علم میں اضافہ ہو جائے۔ مجھے خوب معلوم ہے کہ حضورؐ پر ہر سال قرآن ایک مرتبہ پیش کیا جاتا تھا اور جس سال آپؐ کا انتقال ہوا اس سال آپؐ پر دو مرتبہ پیش کیا گیا تھا (رمضان میں حضرت جبرائیلؑ حضورؐ کو سارا قرآن سناتے تھے اور حضورؐ حضرت جبرائیلؑ کو) اور میں جب بھی حضورؐ کو قرآن پڑھ کر سناتا تو حضورؐ ہمیشہ فرماتے کہ میں نے قرآن بہت اچھا پڑھا ہے، لہٰذا جو میری طرح قرآن پڑھتا ہے وہ میری طرح پڑھتا رہے اور اسے غلط سمجھ کر چھوڑے نہیں۔ اور حضورؐ سے اور بھی کئی طرح قرآن پڑھنا ثابت ہے جو ان میں سے کسی ایک طرح قرآن پڑھتا ہو وہ اسے نہ چھوڑے کیونکہ جو ان میں سے کسی ایک طرح کا انکار کرے گا وہ باقی تمام کا انکار کرنے والا شمار ہوگا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.232)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" کے ساتھیوں میں سے ہمدان کے رہنے والے ایک صاحب بیان کرتے ہیں کہ جب حضرت عبد",""],["ٱللَّٰه","a"],["ؓ کا مدینہ منورہ جانے کا ارادہ ہوا تو انہوں نے اپنے ساتھیوں کو جمع کر کے فرمایا مجھے امید ہے کہ اب آپ لوگوں میں دین، دینی سمجھ اور قرآن کا علم مسلمانوں کے باقی تمام لشکروں سے زیادہ ہو چکا ہے۔ اس کے بعد آگے لمبی حدیث ذکر کی ہے جس میں یہ بھی ہے کہ اس قرآن میں کسی قسم کا اختلاف نہیں اور نہ یہ زیادہ پڑھنے سے پرانا ہوتا ہے اور نہ اس کی عظمت دل میں کم ہوتی ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Ahmad. Haythami (Vol.1 Pg.450) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا کہ قرآن کے حافظ میں مندرجہ ذیل نشانیاں ہونی چاہئیں جن سے وہ پہچانا جائے (اس زمانے میں ہر حافظ قرآن کا عالم بھی ہوتا تھا) رات کو لوگ جب سو رہے ہوں تو وہ ",""],["ٱللَّٰه","a"],[" کی عبادت کر رہا ہو۔ دن کو لوگ بغیر روزہ کے ہوں تو وہ روزہ دار ہو اور جب لوگ خوش ہو رہے ہوں تو وہ (امت کے غم میں) غمگین ہو اور جب لوگ ہنس رہے ہوں تو وہ (",""],["ٱللَّٰه","a"],[" کے سامنے) رو رہا ہو اور جب لوگ آپس میں مل کر ادھر ادھر کی باتیں کر رہے ہوں تو وہ خاموش ہو اور جب لوگ اکڑ رہے ہوں تو وہ عاجز اور مسکین بنا ہوا ہو۔ اور اسی طرح حافظ قرآن کو رونے والا، غمگین، حکمت والا، بردبار، علم والا اور خاموش رہنے والا ہونا چاہیے۔ اور ایک روایت میں یہ ہے کہ تم اس کی پوری کوشش کرو کہ تم سننے والے بنو (یعنی سنانے سے زیادہ اچھے لوگوں کی سنا کرو) اور جب تم سنو کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرما رہے ہیں اے ایمان والو! تو اپنے کان اس کے حوالے کر دو (یعنی پورے غور سے اسے سنو) کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ خیر کے کام کا حکم دے رہے ہوں گے یا کسی برے کام سے روک رہے ہوں گے۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Hilya (Vol.1 Pg.130)."]]}]},"85":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ حضورؐ ایک مجلس میں لوگوں سے بات فرما رہے تھے اتنے میں ایک دیہاتی نے آ کر کہا قیامت کب ہوگی؟ حضورؐ (نے اسے کوئی جواب نہ دیا بلکہ) بات فرماتے رہے (کیونکہ حدیث کے درس کا ادب یہ ہے کہ بیچ میں سوال نہ کرنا چاہیے اور نہ جواب دینا چاہیے) بعض لوگوں نے کہا حضورؐ نے اس کی بات تو سن لی ہے لیکن حضورؐ کو پسند نہیں آئی ہے اور بعض لوگوں نے کہا حضورؐ نے اس کی بات سنی ہی نہیں۔ جب آپؐ نے بات پوری فرما لی تو فرمایا قیامت کے بارے میں پوچھنے والا کہاں ہے؟ اس نے کہا میں یہاں ہوں یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ نے فرمایا جب امانت کو ضائع کر دیا جائے تو تم قیامت کا انتظار کرو۔ اس دیہاتی نے پوچھا امانت کا ضائع کرنا کس طرح ہوگا؟ آپؐ نے فرمایا جب کام نااہل کے سپرد کر دیا جائے تو تم قیامت کا انتظار کرو۔",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari (Vol.1 Pg.14)."]]},{"b":[["n",[["حضرت وابصہؓ","b"],[" رقہ شہر کی سب سے بڑی مسجد میں عیدالفطر اور عیدالاضحیٰ کے دن کھڑے ہو کر ارشاد فرماتے جب حضورؐ نے حجۃ الوداع میں لوگوں کو خطبہ دیا تھا اس وقت میں بھی وہاں موجود تھا۔ آپؐ نے فرمایا اے لوگو! کونسا مہینہ سب سے زیادہ قابل احترام ہے؟ لوگوں نے کہا یہی (حج والا مہینہ)۔ پھر آپؐ نے فرمایا کونسا شہر سب سے زیادہ قابل احترام ہے؟ لوگوں نے کہا یہی (مکہ شہر)۔ پھر آپؐ نے فرمایا تمہارا خون، تمہارا مال اور تمہاری عزتیں ایسے ہی قابل احترام ہیں جیسے کہ تمہارا یہ (حج کا) دن، تمہارا یہ (حج والا) مہینہ اور تمہارا یہ شہر (مکہ مکرمہ) قابل احترام ہے اور یہ اس دن تک قابل احترام ہیں جس دن تم اپنے رب سے ملاقات کرو گے۔ کیا میں نے (",""],["ٱللَّٰه","a"],[" کا پیغام سارا) پہنچا دیا؟ لوگوں نے کہا جی ہاں! پھر آپؐ نے اپنے دونوں ہاتھ آسمان کی طرف اٹھا کر فرمایا اے ",""],["ٱللَّٰه","a"],["! تو گواہ رہنا۔ پھر فرمایا اے لوگو! تم میں سے جو یہاں موجود ہے وہ غائبین تک پہنچائے (اس کے بعد حضرت وابصہؓ نے کہا اے لوگو! تم بھی میرے قریب آ جاؤ تا کہ ہم (حضورؐ کا دین) تم تک پہنچائیں جیسا کہ حضورؐ نے ہم سے فرمایا تھا۔",""],[" (2)","s"]]]],"f":[["(2)","Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.139)."]]},{"b":[["n",[["حضرت مکحولؒ","b"],[" کہتے ہیں کہ حمص میں، میں، حضرت ابن ابی زکریاؒ اور حضرت سلیمان بن ابی حبیبؒ، ہم تینوں حضرت ابوامامہؓ کی خدمت میں حاضر ہوئے اور انہیں سلام کیا۔ انہوں نے فرمایا یہ (ہمارے ساتھ) بیٹھنا ",""],["ٱللَّٰه","a"],[" کی طرف سے تم تک دین کے پہنچنے کا ذریعہ ہے اور ",""],["ٱللَّٰه","a"],[" کی تم پر حجت ہے اور حضورؐ نے خود (",""],["ٱللَّٰه","a"],[" کا دین) پہنچایا، لہٰذا تم دوسروں تک پہنچاؤ۔ ایک روایت میں ",""],["حضرت سلیم بن عامرؒ","b"],[" کہتے ہیں کہ ہم لوگ حضرت ابوامامہؓ کے پاس بیٹھا کرتے وہ ہمیں حضورؐ کی طرف سے بہت سی حدیثیں سنایا کرتے۔ جب خاموش ہونے لگتے تو فرماتے کیا تم لوگ سمجھ گئے؟ جیسے تم تک یہ حدیثیں پہنچائی گئی ہیں ایسے ہی تم بھی آگے دوسروں تک پہنچاؤ۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani in his Kabeer, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.140)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ نبی کریمؐ نے فرمایا اے ",""],["ٱللَّٰه","a"],["! میرے خلفاء و نائبین پر رحم فرما۔ ہم نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ کے خلفاء کون ہیں؟ آپؐ نے فرمایا یہ وہ لوگ ہیں جو میرے بعد آئیں گے اور میری احادیث کی روایت کریں گے اور لوگوں کو حدیثیں سکھائیں گے۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.74). Ibn Najjaar, Khateeb in Sharfus Sahabah and others, as quoted in Kanzul Ummaal (Vol.5 Pg.240)."]]},{"b":[["n",[["حضرت عاصم بن محمدؒ","b"],[" اپنے والد حضرت محمدؒ سے نقل کرتے ہیں کہ میں نے حضرت ابوہریرہؓ کو دیکھا کہ وہ جمعہ کے دن باہر تشریف لاتے اور منبر کے دونوں ہتھوں کو پکڑ کر کھڑے ہو جاتے اور فرماتے ہمیں ابوالقاسم رسول ",""],["ٱللَّٰه","a"],[" الصادق المصدوقؐ نے یہ حدیث بیان کی اور پھر مسلسل احادیث بیان کرتے رہتے۔ جب امام کے نماز کے لیے باہر آنے پر حجرہ کے دروازے کے کھلنے کی آواز سنتے تو پھر بیٹھ جاتے۔",""],[" (5)","s"]]]],"f":[["(5)","Haakim, reporting from reliable sources as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت اسلمؒ","b"],[" کہتے ہیں کہ جب ہم حضرت عمرؓ کی خدمت میں عرض کیا کرتے کہ آپ ہمیں حضورؐ کی طرف سے حدیث بیان فرما دیں تو وہ فرماتے مجھے اس بات کا ڈر ہے کہ میں کہیں کوئی حرف گھٹا بڑھا نہ دوں اور حضورؐ نے فرمایا ہے جو جان بوجھ کر میرے بارے میں جھوٹ بولے گا وہ آگ میں جائے گا۔",""],[" (6)","s"]]]],"f":[["(6)","Ahmad, Ibn Adi, Uqayli and Abu Nu'aym in his Ma'rifah, as quoted in Kanzul Ummaal (Vol.5 Pg.239)."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن حاطبؒ","b"],[" کہتے ہیں کہ میں نے حضورؐ کے کسی صحابی کو حضرت عثمانؓ سے زیادہ مکمل اور زیادہ عمدہ طریقہ سے حدیث بیان کرنے والا نہیں دیکھا لیکن پھر بھی وہ حدیث بیان کرنے سے ڈرتے تھے۔ حضرت عثمانؓ فرماتے تھے کہ حضورؐ کی طرف سے حدیث بیان نہ کرنے کی وجہ یہ نہیں ہے کہ میں آپؐ کے صحابہ میں (آپؐ کی حدیثوں کا) سب سے زیادہ حافظ نہیں ہوں بلکہ اس کی وجہ یہ ہے کہ میں اس بات کی گواہی دیتا ہوں کہ میں نے حضورؐ کو یہ فرماتے ہوئے سنا ہے کہ جو میرے بارے میں ایسی بات کہے جو میں نے نہیں کہی ہے تو وہ اپنا ٹھکانہ آگ میں بنا لے اور ایک روایت میں یہ ہے کہ جو میرے بارے میں جھوٹی بات کہے تو وہ اپنا گھر آگ میں بنا لے۔",""],[" (7)","s"],[" (8)","s"]]]],"f":[["(7)","Ibn Sa'd and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.9)."],["(8)","Ahmad, Abu Ya'la and Bazzaar. Haythami (Vol.1 Pg.143) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت علیؓ","b"],[" نے فرمایا کہ میں جب تمہیں حضورؐ کی طرف سے حدیث بیان کرتا ہوں تو (کمال احتیاط کی وجہ سے) میری یہ کیفیت ہو جاتی ہے کہ آسمان سے زمین پر گر جانا مجھے اس سے زیادہ محبوب ہو جاتا ہے کہ میں حضورؐ کی طرف سے ایسی بات کہہ دوں جو آپؐ نے نہ فرمائی ہو اور جب میں تم سے آپس کے معاملات کے بارے میں بات کرتا ہوں تو پھر یہ کیفیت نہیں ہوتی (اور اس میں اتنی احتیاط کی ضرورت نہیں ہوتی) کیونکہ انسانوں سے جنگ تو تدبیر و حکمت اور داؤ سے ہی جیتی جا سکتی ہے۔",""],[" (9)","s"]]]],"f":[["(9)","Bukhaari, Muslim and others, as quoted in Kanzul Ummaal (Vol.5 Pg.240)."]]},{"b":[["n",[["حضرت عمرو بن میمونؒ","b"],[" کہتے ہیں کہ بعض دفعہ پورا سال گزر جاتا لیکن حضرت عبد",""],["ٱللَّٰه","a"],["ؓ حضورؐ کی طرف سے کوئی حدیث بیان نہ کرتے، چنانچہ ایک سال ایسا ہی گزرا اس کے بعد ایک حدیث بیان کی تو ایک دم پریشان ہو گئے اور پیشانی پر پسینہ بہنے لگا اور فرمانے لگے یہی الفاظ حضورؐ نے فرمائے تھے یا ان جیسے یا ان کے قریب الفاظ تھے۔",""],[" (10)","s"]]]],"f":[["(10)","Haakim (Vol.3 Pg.314), reporting from reliable sources as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت مسروقؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],["ؓ ایک دن حدیث بیان کرنے لگے اور فرمایا میں نے حضورؐ کو فرماتے ہوئے سنا (پھر حدیث بیان کی) تو کانپنے لگے اور کپکپی کی وجہ سے کپڑے ہلنے لگے اور فرمایا حضورؐ نے یہی الفاظ فرمائے تھے یا ان جیسے یا ان کے مشابہ الفاظ تھے۔",""],[" (11)","s"]]]],"f":[["(11)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.79). Isaabah (Vol.3 Pg.156) has reported a similar narration."]]},{"b":[["n",[["حضرت ابوادریس خولانیؒ","b"],[" کہتے ہیں میں نے دیکھا کہ حضرت ابوالدرداءؓ جب حضورؐ کی طرف سے حدیث بیان کرنے سے فارغ ہو جاتے تو فرماتے کہ حضورؐ نے یا تو یہی الفاظ فرمائے تھے یا ان جیسے یا ان سے ملتے جلتے الفاظ تھے۔ ابن عبدالبر کی روایت میں یہ ہے کہ آپ نے فرمایا اے ",""],["ٱللَّٰه","a"],["! اگر یہ الفاظ نہیں ہیں تو ان جیسے الفاظ تھے۔",""],[" (12)","s"]]]],"f":[["(12)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.141). Abu Ya'la, Rooyaani and Ibn Asaakir have reported a similar narration, as quoted in Kanzul Ummaal (Vol.3 Pg.156)."]]},{"b":[["n",[["حضرت محمد بن سیرینؒ","b"],[" کہتے ہیں کہ جب حضرت انس بن مالکؓ حضورؐ کی طرف سے حدیث بیان کر لیتے تو فرمایا کرتے کہ یا تو حضورؐ نے یہی الفاظ فرمائے تھے یا پھر جیسے آپؐ نے ارشاد فرمایا۔ حضرت ابن سیرینؒ کہتے ہیں کہ حضرت انسؓ حضورؐ کی طرف سے بہت کم حدیث بیان کیا کرتے اور جب بیان کرتے۔ آگے پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (13)","s"],[" (14)","s"]]]],"f":[["(13)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.79)."],["(14)","Ahmad, Abu Ya'la and Haakim, as quoted in Kanzul Ummaal (Vol.5 Pg.240)."]]},{"b":[["n",[["حضرت ابوجعفر محمد بن علیؒ","b"],[" کہتے ہیں کہ حضورؐ کے کوئی صحابی حضورؐ سے حدیث سن کر اس کے بیان کرنے میں حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرؓ سے زیادہ احتیاط برتنے والا نہیں تھا۔ یہ حدیث کے الفاظ نہ بڑھاتے تھے اور نہ گھٹاتے تھے اور نہ ان میں کچھ تبدیلی کرتے تھے۔ ",""],["حضرت شعبیؒ","b"],[" کہتے ہیں ایک سال تک حضرت ابن عمرؓ کے ساتھ میری نشست رہی۔ میں نے انہیں اس عرصہ میں حضورؐ کی طرف سے ایک بھی حدیث بیان کرتے ہوئے نہیں سنا۔",""],[" (15)","s"],[" (16)","s"]]]],"f":[["(15)","Ibn Sa'd (Vol.4 Pg.144)."],["(16)","Ibn Sa'd (Vol.4 Pg.145)."]]},{"b":[["n",[["حضرت عمران بن حصینؓ","b"],[" نے فرمایا میں نے حضورؐ سے بہت سی حدیثیں سنی ہیں جو مجھے یاد بھی ہیں لیکن میں انہیں صرف اس وجہ سے بیان نہیں کرتا کہ میرے ساتھ کے صحابہؓ ان حدیثوں میں میری مخالفت کریں گے۔ ",""],["حضرت مطرفؒ","b"],[" کہتے ہیں کہ مجھ سے حضرت عمران بن حصینؓ نے فرمایا اے مطرف! (مجھے بہت زیادہ حدیثیں یاد ہیں) ",""],["ٱللَّٰه","a"],[" کی قسم! مجھے اس کا یقین ہے کہ اگر میں چاہوں تو دو دن مسلسل حضور کریمؐ کی طرف سے حدیثیں اس طرح بیان کر سکتا ہوں کہ کوئی حدیث دو دفعہ بیان نہ ہو لیکن مجھے زیادہ حدیثیں بیان کرنا پسند بھی نہیں اور میں زیادہ بیان بھی نہیں کرتا اور اس کی وجہ یہ ہے کہ حضرت محمدؐ کے بعض صحابہؓ بھی اسی طرح (حضورؐ کی مجلس میں) حاضر ہوا کرتے تھے جس طرح میں حاضر ہوا کرتا تھا اور انہوں نے بھی (حضورؐ سے) اسی طرح سنا جس طرح میں نے سنا لیکن وہ کچھ حدیثیں ایسی بیان کرتے ہیں جن کے الفاظ کچھ آگے پیچھے ہو گئے ہیں، چنانچہ حضرت عمرانؓ بعض دفعہ تو یوں فرماتے کہ اگر آپ لوگوں میں یہ حدیث بیان کروں کہ میں نے نبی کریمؐ کو اس طرح فرماتے ہوئے سنا ہے تو مجھے یقین ہے کہ میں ان الفاظ میں بالکل سچا ہوں گا اور بھی پورے وثوق سے کہتے کہ میں نے نبی کریمؐ کو اس طرح فرماتے ہوئے سنا۔",""],[" (17)","s"],[" (18)","s"]]]],"f":[["(17)","Tabraani in his Kabeer, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.141)."],["(18)","Tabraani. Haythami (Vol.1 Pg.141) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت سلیمان بن ابی عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں کہ میں نے حضرت صہیبؓ کو فرماتے ہوئے سنا ",""],["ٱللَّٰه","a"],[" کی قسم! میں جان بوجھ کر آپ لوگوں کو حدیثیں نہیں سناتا اور یوں نہیں کہتا کہ حضورؐ نے فرمایا ہے ہاں اگر آپ لوگ کہیں تو میں حضورؐ کے غزوات میں شریک ہوا ہوں اور ان میں بہت کچھ دیکھا ہے۔ یہ سب کچھ سنانے کو تیار ہوں لیکن یوں کہوں کہ حضورؐ نے فرمایا ہے اس کے لیے تیار نہیں ہوں۔",""],[" (19)","s"]]]],"f":[["(19)","Ibn Sa'd (Vol.3 Pg.229), as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.203)."]]},{"b":[["n",[["حضرت مکحولؒ","b"],[" کہتے ہیں کہ ایک دن میں اور حضرت ابوالازہرؒ دونوں حضرت واثلہ بن اسقعؓ کی خدمت میں حاضر ہوئے اور عرض کیا اے ابوالاسقع! ہمیں ایسی حدیث سنائیں جو آپ نے حضورؐ سے سنی ہو جس میں نہ تو وہم ہو نہ کمی زیادتی ہو۔ انہوں نے فرمایا کیا تم میں سے کسی نے آج رات کچھ قرآن پڑھا ہے؟ ہم نے کہا جی ہاں لیکن ہمیں قرآن اچھی طرح یاد نہیں ہے۔ الف یا واؤ کی زیادتی ہو جاتی ہے تو فرمایا یہ قرآن کتنے عرصہ سے تمہارے درمیان ہے اور تم لوگ اب تک اسے اچھی طرح یاد نہیں کر سکے ہو اور سمجھتے ہو کہ تم لوگوں سے قرآن میں کمی زیادتی ہو جاتی ہے تو پھر تمہارا ان حدیثوں کے بارے میں کیا خیال ہے جنہیں ہم نے حضورؐ سے سنا ہے کیونکہ ہو سکتا ہے ہم نے حضورؐ سے وہ حدیث ایک دفعہ ہی سنی ہو، اس لیے حضورؐ والے الفاظ بعینہ بیان کرنا تو ہمارے لیے بہت مشکل ہے، البتہ ان کا معنی اور مطلب ہم بیان کر سکتے ہیں تم اسی کو کافی سمجھو۔",""],[" (20)","s"]]]],"f":[["(20)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.79)."]]},{"b":[["n",[["حضرت ابراہیم بن عبدالرحمٰن بن عوفؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ نے انتقال سے پہلے حضورؐ کے جن صحابہؓ کے پاس آدمی بھیج کر انہیں اطراف عالم سے (مدینہ منورہ میں) جمع کیا وہ یہ ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن حذافہؓ، حضرت ابوالدرداءؓ، حضرت ابوذرؓ اور حضرت عقبہ بن عامرؓ۔ جب یہ حضرات آ گئے تو ان سے حضرت عمرؓ نے فرمایا آپ لوگوں نے اطراف عالم میں حضورؐ کی طرف سے یہ کیا حدیثیں پھیلا دی ہیں؟ انہوں نے کہا کیا آپ ہمیں (حدیثیں بیان کرنے سے) روکنا چاہتے ہیں؟ آپؓ نے فرمایا نہیں بلکہ آپ لوگ میرے پاس رہیں۔ ",""],["ٱللَّٰه","a"],[" کی قسم! جب تک میں زندہ ہوں آپ لوگ مجھ سے جدا نہیں ہو سکتے (یہاں رہ کر حدیثیں بیان کریں) اور اس کی وجہ یہ ہے کہ ہم بھی حدیثیں خوب جانتے ہیں، اس لیے آپ لوگوں کی حدیثوں کو دیکھیں گے کہ کونسی لینی چاہیے اور کونسی چھوڑنی چاہیے۔ چنانچہ یہ حضرات حضرت عمرؓ کے انتقال تک ان کے پاس ہی (مدینہ منورہ میں) رہے۔ ان سے جدا نہ ہوئے۔",""],[" (21)","s"]]]],"f":[["(21)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.5 Pg.239)."]]},{"b":[["n",[["حضرت ابراہیم بن عبدالرحمٰنؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ نے حضرت ابن مسعودؓ، حضرت ابومسعود انصاریؓ اور حضرت ابوالدرداءؓ کے پاس پیغام بھیج کر انہیں بلایا اور ان سے فرمایا آپ لوگ حضورؐ کی طرف سے حدیثیں کثرت سے کیوں بیان کر رہے ہیں؟ پھر شہید ہونے تک حضرت عمرؓ نے انہیں (وہیں مدینہ میں) روک رکھا۔",""],[" (22)","s"]]]],"f":[["(22)","Tabraani. Haythami (Vol.1 Pg.149) has commented on the chain of narrators. Ibn Sa'd (Vol.4 Pg.153) has reported a similar narration which states the name of Hadhrat Abu Dharr in place of Hadhrat Abdullaah bin Mas'ood."]]},{"b":[["n",[["حضرت ابن ابی اوفیؒ","b"],[" کہتے ہیں ہم لوگ حضرت زید بن ارقمؓ کی خدمت میں حاضر ہو کر عرض کیا کرتے کہ ہمیں حضورؐ کی طرف سے حدیث بیان فرما دیں وہ فرماتے اب ہم زیادہ بوڑھے ہو گئے ہیں اور بھولنے لگ گئے ہیں اور حضورؐ کی طرف سے حدیث بیان کرنا بڑی ذمہ داری کا کام ہے (اگر اس میں غلطی ہو گئی تو سخت پکڑ ہوگی)۔",""],[" (23)","s"]]]],"f":[["(23)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.5 Pg.239)."]]}]},"86":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا تم جو چاہے سیکھو لیکن ",""],["ٱللَّٰه","a"],[" کی طرف سے فائدہ تب ہی ہوگا جب تم سیکھے ہوئے پر عمل کرو گے۔ ",""],["حضرت انسؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا تم جتنا چاہو علم حاصل کرو تمہیں علم حاصل کرنے کا ثواب تب ملے گا جب اس پر عمل کرو گے۔",""],[" (1)","s"],[" (2)","s"],[" (3)","s"]]]],"f":[["(1)","Ibn Adi and Khateeb."],["(2)","Ibn Asaakir."],["(3)","Abul Hasan bin Akhram in his Amaali, as quoted in Jaami'us Sagheer."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن غنمؒ","b"],[" کہتے ہیں کہ مجھے حضورؐ کے دس صحابہؓ نے یہ واقعہ بیان کیا کہ ہم مسجد قبا میں علم سیکھ سکھا رہے تھے کہ اتنے میں حضورؐ ہمارے پاس تشریف لائے اور فرمایا تم جتنا چاہو علم حاصل کر لو۔ اس کے بعد پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.6)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" نے فرمایا کہ ایک آدمی نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! کون سی چیز میری جہالت کو ختم کرے گی؟ آپؐ نے فرمایا علم۔ پھر اس نے پوچھا کون سی چیز علم کی حجت کو ختم کرے گی؟ آپؐ نے فرمایا عمل۔",""],[" (5)","s"]]]],"f":[["(5)","Khateeb, as quoted in Kanzul Ummaal (Vol.5 Pg.229)."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" نے فرمایا ",""],["ٱللَّٰه","a"],[" کی کتاب (قرآن) سیکھو۔ اس کی وجہ سے تمہاری پہچان ہوگی اور اس پر عمل کرو اس سے تم ",""],["ٱللَّٰه","a"],[" کی کتاب والے ہو جاؤ گے۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.5 Pg.229)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" نے فرمایا علم حاصل کرو اس سے تمہاری پہچان ہوگی اور جو علم حاصل کیا ہے اس پر عمل کرو اس سے تم علم والے ہو جاؤ گے کیونکہ تمہارے بعد ایسا زمانہ آئے گا جس میں حق کے دس حصوں میں سے نو کا انکار کر دیا جائے گا اور اس زمانے میں صرف وہ نجات پا سکے گا جو گمنام اور لوگوں سے الگ تھلگ رہنے والا ہوگا۔ یہی لوگ ہدایت کے امام اور علم کے چراغ ہوں گے۔ یہ لوگ جلد باز، بری بات پھیلانے والے اور باتونی نہیں ہوں گے۔ ",""],["حضرت علیؓ","b"],[" نے فرمایا اے حاملین علم! (اے علماء!) علم پر عمل کرو کیونکہ عالم وہ ہے جو علم حاصل کرے پھر اس پر عمل کرے اور اس کا عمل اس کے علم کے مطابق ہو۔ عنقریب ایسے لوگ ہوں گے جو علم حاصل کریں گے لیکن ان کا علم ان کی ہنسلی کی ہڈی سے آگے نہیں جائے گا (اور ",""],["ٱللَّٰه","a"],[" کے ہاں نہیں پہنچے گا) ان کا باطن ظاہر کے خلاف ہوگا اور ان کا عمل ان کے علم کے خلاف ہوگا وہ اپنے اپنے حلقے میں بیٹھیں گے اور ایک دوسرے پر فخر کریں گے اور ان کے حلقہ میں بیٹھنے والا انہیں چھوڑ کر دوسرے کے پاس اگر بیٹھے گا تو یہ اس پر ناراض ہوں گے۔ ان کی مجلسوں میں ان کے جو اعمال ہوں گے وہ ",""],["ٱللَّٰه","a"],[" کی طرف اور نہیں جائیں گے۔",""],[" (7)","s"],[" (8)","s"]]]],"f":[["(7)","Ahmad in his Zuhd, Abu Ubayd, Deenowri in his Ghareeb and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.5 Pg.229)."],["(8)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.7), as quoted in Kanzul Ummaal (Vol.5 Pg.233)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" نے فرمایا اے لوگو! علم حاصل کرو اور آدمی جو علم حاصل کرے اس پر عمل بھی کرے۔",""],[" (9)","s"]]]],"f":[["(9)","Tabraani. Haythami (Vol.1 Pg.164) has commented on the chain of narrators. Abu Nu'aym has also reported the narration in his Hilya (Vol.1 Pg.131) from Hadhrat Alqama."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن حکیمؒ","b"],[" کہتے ہیں کہ میں نے اس مسجد میں حضرت ابن مسعودؓ کو سنا کہ انہوں نے گفتگو سے پہلے قسم کھا کر فرمایا تم میں سے ہر آدمی اپنے رب سے تنہائی میں اکیلے ملے گا جیسے کہ تم میں سے ہر ایک چودھویں کا چاند تنہائی میں الگ دیکھتا ہے۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ فرمائیں گے اے ابن آدم! تجھے کس چیز نے میرے بارے میں دھوکے میں ڈال دیا؟ (کہ میری نافرمانی کرتا رہا) اے ابن آدم! تو نے رسولوں کو (ان کی دعوت کا) کیا جواب دیا؟ اے ابن آدم! تو نے جو علم حاصل کیا تھا اس پر کیا عمل کیا؟ ",""],["حضرت عدی بن عدیؒ","b"],[" کہتے ہیں حضرت ابن مسعودؓ نے فرمایا جو علم حاصل نہ کرے اس کے لیے ایک مرتبہ ہلاکت ہے اور اگر ",""],["ٱللَّٰه","a"],[" تعالیٰ چاہتے تو اسے علم عطا فرما دیتے اور جو علم حاصل کرے اور اس پر عمل نہ کرے اس کے لیے سات مرتبہ ہلاکت ہے۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.2)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا باتیں تو تمام لوگ بہت اچھی کرتے ہیں لیکن جس کا عمل اس کے قول کے مطابق ہوگا وہی کامیاب ہوگا اور جس کا فعل اس کے قول کے خلاف ہوگا وہ (قیامت کے دن) اپنے آپ کو ملامت کرے گا۔ حضرت ابن مسعودؓ نے فرمایا جو (لوگوں سے مستغنی ہو کر) ",""],["ٱللَّٰه","a"],[" (کے کام) میں مشغول ہو جائے گا تمام لوگ اس کے محتاج ہو جائیں گے اور جو اس علم پر عمل کرے گا جو ",""],["ٱللَّٰه","a"],[" نے اسے دیا ہے تو تمام لوگ اس علم کے محتاج ہو جائیں گے جو اس کے پاس ہے۔",""],[" (11)","s"],[" (12)","s"]]]],"f":[["(11)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.6)."],["(12)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.10), as quoted in Kanzul Ummaal (Vol.5 Pg.243)."]]},{"b":[["n",[["حضرت لقمان بن عامرؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ فرمایا کرتے تھے میں اپنے رب سے اس بات سے ڈرتا ہوں کہ قیامت کے دن مجھے تمام مخلوق کے سامنے بلا کر فرمائے اے عویمر! میں کہوں لبیک اے میرے رب! پھر وہ فرمائے تم نے جو علم حاصل کیا تھا اس پر کیا عمل کیا تھا؟ حضرت ابوالدرداءؓ نے فرمایا مجھے سب سے زیادہ ڈر اس بات کا ہے کہ قیامت کے دن مجھ سے یہ کہا جائے اے عویمر! کیا تم نے علم حاصل کیا تھا یا جاہل ہی رہے تھے؟ اگر میں کہوں گا کہ میں نے علم حاصل کیا تھا تو نیک کام کا حکم دینے والی ہر آیت اور برے کام سے روکنے والی ہر آیت اپنے حق کا مطالبہ کرے گی۔ حکم دینے والی آیت کہے گی کیا تو نے میرا حکم مانا تھا؟ اور روکنے والی آیت کہے گی کیا تو اس برے کام سے رک گیا تھا؟ میں ",""],["ٱللَّٰه","a"],[" کی پناہ چاہتا ہوں اس علم سے جو نفع نہ دے اور اس نفس سے جو سیر نہ ہو اور اس دعا سے جو سنی نہ جائے۔ حضرت ابوالدرداءؓ نے فرمایا انسان اس وقت تک متقی نہیں بن سکتا جب تک علم حاصل نہ کرے اور علم کے ذریعہ سے حسن و جمال تب حاصل ہو سکتا ہے جب اس پر عمل کرے۔ حضرت ابوالدرداءؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کے نزدیک قیامت کے دن لوگوں میں سب سے برے مرتبے والا وہ عالم ہوگا جس نے اپنے علم سے فائدہ نہ اٹھایا ہو (یعنی اس پر عمل نہ کیا ہو)۔",""],[" (13)","s"],[" (14)","s"],[" (15)","s"],[" (16)","s"]]]],"f":[["(13)","Bayhaqi, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.90). Abu Nu'aym has also reported a similar narration in his Hilya (Vol.1 Pg.214)."],["(14)","Abu Nu'aym in his Hilya (Vol.1 Pg.214)."],["(15)","Abu Nu'aym in his Hilya (Vol.1 Pg.213). Abu Nu'aym in his Hilya (Vol.1 Pg.211) has also reported from Hadhrat Abu Dardaa a narration similar to the one Hadhrat Adi reported from Hadhrat Abdullaah bin Mas'ood."],["(16)","Abu Nu'aym in his Hilya (Vol.1 Pg.223)."]]},{"b":[["n",[["حضرت معاذؓ","b"],[" فرماتے ہیں کہ قیامت کے دن کسی بندے کے دونوں قدم اس وقت تک اپنی جگہ سے نہیں ہل سکیں گے جب تک اس سے چار باتیں نہ پوچھ لی جائیں۔ اس نے اپنے جسم کو کن کاموں میں استعمال کیا؟ اپنی عمر کہاں لگائی؟ اور مال کہاں سے کمایا اور کہاں خرچ کیا؟ اور اپنے علم پر کیا عمل کیا؟ حضرت معاذؓ نے فرمایا تم علم تو جو چاہے سیکھ لو لیکن ",""],["ٱللَّٰه","a"],[" تمہیں علم پر اجر تب دیں گے جب تم اس پر عمل کرو گے۔",""],[" (17)","s"],[" (18)","s"]]]],"f":[["(17)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.3)."],["(18)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.6). Abu Nu'aym has reported a similar narration in his Hilya (Vol.1 Pg.236)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" نے فرمایا تم علم تو جو چاہے سیکھ لو لیکن ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہیں علم پر اجر تب دیں گے جب تم اس پر عمل کرو گے۔ علماء کا اصل مقصد تو علم کی حفاظت کرنا ہے (کہ اسے یاد رکھا جائے اور اس پر عمل کیا جائے) اور نادان لوگوں کا مقصد تو خالی آگے بیان کر دینا ہے۔",""],[" (19)","s"]]]],"f":[["(19)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.6)."]]}]},"87":{"lead":[],"stories":[{"b":[["n",[["حضرت ابی بن کعبؓ","b"],[" فرماتے ہیں کہ تم لوگ (",""],["ٱللَّٰه","a"],[" والے) صحیح راستہ اور سنت کو لازم پکڑ لو کیونکہ روئے زمین پر جو بندہ بھی صحیح راستہ اور سنت پر ہوگا پھر وہ ",""],["ٱللَّٰه","a"],[" کا ذکر کرے گا اور اس کے ڈر سے اس کی آنکھوں میں آنسو آ جائیں گے تو اسے ",""],["ٱللَّٰه","a"],[" تعالیٰ ہرگز عذاب نہیں دیں گے اور روئے زمین پر جو بندہ بھی صحیح راستہ اور سنت پر ہوگا پھر وہ اپنے دل میں ",""],["ٱللَّٰه","a"],[" کو یاد کرے گا اور ",""],["ٱللَّٰه","a"],[" کے ڈر سے اس کے رونگٹے کھڑے ہو جائیں گے تو اس کی مثال اس درخت جیسی ہو جائے گی جس کے پتے سوکھ گئے ہوں اور تیز ہوا چلنے سے اس کے پتے بہت زیادہ گرنے لگیں تو ایسے ہی اس کے گناہوں کو ",""],["ٱللَّٰه","a"],[" تعالیٰ بہت زیادہ گرانے لگ جائیں گے اور ",""],["ٱللَّٰه","a"],[" کے راستے اور سنت پر درمیانی رفتار سے چلنا اس سے بہتر ہے کہ انسان ",""],["ٱللَّٰه","a"],[" کے راستے کے خلاف اور سنت کے خلاف بہت زیادہ محنت کرے، اس لیے تم دیکھ لو جو چاہے تم زیادہ محنت کرو چاہے درمیانی رفتار سے چلو لیکن تمہارا ہر عمل انبیاء علیہم السلام کے طریقے اور سنت کے مطابق ہونا چاہیے۔",""],[" (1)","s"]]]],"f":[["(1)","Laalkaa'ee, as quoted in Kanzul Ummaal (Vol.1 Pg.97). Abu Nu'aym has reported a similar narration in his Hilya (Vol.1 Pg.253)."]]},{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ جب مدینہ تشریف لائے تو بیان کے لیے کھڑے ہوئے اور ",""],["ٱللَّٰه","a"],[" کی حمد و ثنا کے بعد فرمایا اے لوگو! تمہارے لیے سنتیں جاری ہو چکی ہیں اور فرائض مقرر ہو چکے ہیں اور تمہیں ایک صاف اور واضح راستہ دے دیا گیا ہے۔ اب تم لوگ ہی اس راستہ میں دائیں بائیں ہٹ کر لوگوں کو گمراہ کر دو تو یہ الگ بات ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.187)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" جمرات کے دن کھڑے ہو کر فرماتے اصل چیزیں دو ہیں۔ ایک زندگی گزارنے کا طریقہ اور دوسرا کلام۔ سب سے افضل اور سب سے زیادہ سچا کلام ",""],["ٱللَّٰه","a"],[" تعالیٰ کا ہے اور سب سے عمدہ طریقہ حضرت محمدؐ کا ہے اور تمام کاموں میں سب سے برے کام وہ ہیں جو نئے ایجاد کیے جائیں اور ہر نیا کام (جو قرآن و حدیث سے نہ نکالا گیا ہو وہ) بدعت ہے۔ غور سے سنو! ایسا نہ ہو کہ مدت لمبی ہو جائے اور اس سے تمہارے دل سخت ہو جائیں اور لمبی امیدیں تمہیں (آخرت سے) غافل کر دیں کیونکہ جو چیز آنے والی ہے وہ قریب ہے اور جو آنے والی نہیں ہے وہ دور ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.181)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا سنت پر میانہ روی سے چلنا بدعت پر زیادہ محنت کرنے سے اچھا ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Haakim (Vol.1 Pg.103), reporting from reliable sources as confirmed by Dhahabi. Abu Nu'aym has reported a similar narration in his Hilya (Vol.1 Pg.173)."]]},{"b":[["n",[["حضرت عمران بن حصینؓ","b"],[" نے فرمایا قرآن بھی نازل ہوا اور حضورؐ نے بھی سنتیں مقرر فرمائیں پھر حضرت عمرانؓ نے فرمایا تم لوگ ہمارا اتباع کرو (کیونکہ ہم نے قرآن و سنت کو پورا اختیار کیا ہوا ہے) اگر ایسا نہیں کرو گے تو گمراہ ہو جاؤ گے۔",""],[" (5)","s"]]]],"f":[["(5)","Ahmad. Haythami (Vol.1 Pg.191) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عمران بن حصینؓ","b"],[" نے ایک آدمی سے کہا تم احمق ہو کیا تمہیں ",""],["ٱللَّٰه","a"],[" کی کتاب میں یہ صاف طور سے لکھا ہوا ملتا ہے کہ ظہر کی نماز میں چار رکعتیں ہیں اور اس میں قراءت اونچی آواز سے نہ کرو؟ پھر حضرت عمرانؓ نے باقی نمازوں اور زکوٰۃ وغیرہ کا نام لیا (کہ کیا ان کے تفصیلی احکام قرآن میں ہیں؟) کیا تمہیں ان اعمال کی تفصیل ",""],["ٱللَّٰه","a"],[" کی کتاب میں ملتی ہے؟ ",""],["ٱللَّٰه","a"],[" کی کتاب میں یہ تمام چیزیں اجمالاً ذکر ہوئی ہیں اور سنت رسولؐ نے ان سب کو کھول کر تفصیل سے بیان کیا ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.191)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا تم میں سے جو کسی کی اقتداء کرنا چاہتا ہے تو اسے چاہیے کہ وہ حضرت محمدؐ کے صحابہؓ کی اقتداء کرے کیونکہ وہ اس امت میں سب سے زیادہ نیک دل، سب سے زیادہ گہرے علم والے، سب سے کم تکلف والے، سب سے زیادہ سیدھے طور طریقے والے اور سب سے زیادہ اچھی حالت والے تھے۔ ان لوگوں کو ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اپنے نبی کریمؐ کی صحبت کے لیے اور اپنے دین کو قائم کرنے کے لیے چنا تھا۔ لہٰذا تم ان کے فضائل و درجات کا اعتراف کرو اور ان کے نقش قدم پر چلو کیونکہ وہ سیدھی راہ پر تھے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.97). Abu Nu'aym has reported a similar narration from Hadhrat Abdullaah bin Umar in his Hilya (Vol.1 Pg.305), as has been quoted in the chapter describing the qualities of the Sahabah."]]},{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرمایا کرتے تھے اے جماعت علماء! ",""],["ٱللَّٰه","a"],[" سے ڈرو اور اپنے سے پہلے لوگوں کے راستہ کو پکڑے رکھو میری زندگی کی قسم! اگر تم اس راستہ پر چلو گے تو تم دوسروں سے بہت آگے نکل جاؤ گے اور اگر تم اسے چھوڑ کر دائیں بائیں چلے جاؤ گے تو تم بہت زیادہ بھٹک جاؤ گے۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.97). Ibn Abi Shaybah and Ibn Asaakir have reported a similar narration, as quoted in Kanzul Ummaal (Vol.5 Pg.233)."]]},{"b":[["n",[["حضرت مصعب بن سعدؒ","b"],[" کہتے ہیں میرے والد جب مسجد میں نماز پڑھتے تو مختصر پڑھتے، البتہ رکوع اور سجدہ پورا کرتے اور گھر میں جب نماز پڑھتے تو نماز، رکوع اور سجدہ سب کچھ لمبا کیا کرتے۔ میں نے کہا ابا جان! جب آپ مسجد میں نماز پڑھتے ہیں تو مختصر پڑھتے ہیں اور جب گھر میں نماز پڑھتے ہیں تو لمبی پڑھتے ہیں؟ انھوں نے کہا اے میرے بیٹے! ہم امام ہیں لوگ ہمارے پیچھے چلتے ہیں، ہماری اقتداء کرتے ہیں۔",""],[" (9)","s"]]]],"f":[["(9)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.182)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" نے فرمایا تم اپنے سے پہلے لوگوں کے پیچھے چلو، اپنی طرف سے نئے طریقے مت چلاؤ (تمہیں عقل لڑانے کی ضرورت نہیں ہے) ",""],["ٱللَّٰه","a"],[" کے رسولؐ اور صحابہؓ تمہیں سب کچھ کر کے دے گئے ہیں۔ ",""],["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" نے فرمایا حضرت ابوبکرؓ اور حضرت عمرؓ سے محبت کرنا اور ان کی فضیلت کا اعتراف کرنا دونوں سنت میں سے ہیں۔",""],[" (10)","s"],[" (11)","s"]]]],"f":[["(10)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.181)."],["(11)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.187)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" نے فرمایا اپنے زمانہ کے لوگوں کے نقش قدم پر چلنے سے بچو کیونکہ ایک آدمی جنت والوں کے عمل کرتا ہے پھر ",""],["ٱللَّٰه","a"],[" کے علم کے مطابق وہ پلٹا کھا جاتا ہے اور دوزخ والوں کے عمل کرنے لگ جاتا ہے اور وہ دوزخی بن کر مرتا ہے اور ایک آدمی دوزخ والوں کے عمل کر رہا ہوتا ہے پھر وہ ",""],["ٱللَّٰه","a"],[" کے علم کے مطابق پلٹا کھا جاتا ہے اور جنت والوں کے عمل کرنے لگ جاتا ہے اور جنتی بن کر مرتا ہے۔ اگر تم نے ضرور ہی کسی کے پیچھے چلنا ہے تو پھر تم ان لوگوں کے پیچھے چلو جن کا خاتمہ ایمان و اعمال صالحہ پر ہو چکا ہے اور وہ دنیا سے جا چکے ہیں۔ جو ابھی زندہ ہیں ان کے پیچھے مت چلو! کیونکہ کسی زندہ انسان کے بارے میں اطمینان نہیں کیا جا سکتا نہ معلوم کب گمراہ ہو جائے۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.114)."]]},{"b":[["n",[["حضرت ابوالبختریؒ","b"],[" کہتے ہیں کہ ایک آدمی نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ کو بتایا کہ کچھ لوگ مغرب کے بعد سے مسجد میں بیٹھے ہوئے ہیں اور ان میں ایک آدمی ہے جو کہہ رہا ہے اتنی مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر اتنی مرتبہ سبحان ",""],["ٱللَّٰه","a"],[" اور اتنی مرتبہ الحمد للہ کہو اور وہ لوگ کہہ رہے ہیں؟ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے پوچھا پھر کیا وہ لوگ کہہ رہے ہیں؟ اس آدمی نے کہا جی ہاں۔ فرمایا جب تم انہیں ایسا کرتے ہوئے دیکھو تو مجھے آ کر بتانا (چنانچہ اس نے آ کر بتایا تو) حضرت عبد",""],["ٱللَّٰه","a"],["ؓ ان کے پاس گئے اور انھوں نے ٹوپی والا جبہ پہن رکھا تھا اور ان کے پاس جا کر بیٹھ گئے۔ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ ذرا تیز مزاج آدمی تھے۔ جب انھوں نے ان لوگوں کو وہ کلمات اس ترتیب سے کہتے ہوئے سنا تو کھڑے ہو کر فرمایا میں عبد",""],["ٱللَّٰه","a"],[" بن مسعود ہوں۔ اس ",""],["ٱللَّٰه","a"],[" کی قسم جس کے سوا کوئی معبود نہیں تم نے اس بدعت کو لا کر بڑا ظلم کیا ہے اور تم اس طرح تو حضرت محمدؐ کے صحابہؓ سے علم میں آگے نکل گئے ہو (وہ تو اس طرح ذکر نہیں کیا کرتے تھے) حضرت معقدؓ نے کہا ہم تو کوئی بدعت لا کر ظلم نہیں کرنا چاہتے اور نہ ہم علم میں حضورؐ کے صحابہؓ سے آگے نکل گئے ہیں۔ پھر حضرت عمرو بن عتبہؓ نے کہا اے ابو عبدالرحمٰن! ہم ",""],["ٱللَّٰه","a"],[" سے معافی مانگتے ہیں۔ حضرت ابن مسعودؓ نے فرمایا تم صحیح راستہ پر چلتے رہو بلکہ اسی سے ہی چمٹے رہو ",""],["ٱللَّٰه","a"],[" کی قسم! اگر تم ایسا کرو گے تو تم بہت آگے نکل جاؤ گے اور راستہ سے ہٹ کر دائیں بائیں ہو جاؤ گے تو بہت زیادہ بھٹک جاؤ گے۔ ",""],["حضرت ابوالبختریؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ کو خبر ملی کہ کچھ لوگ مغرب اور عشاء کے درمیان بیٹھتے ہیں۔ آگے پچھلی حدیث جیسا مضمون ذکر کیا اور بعد میں یہ ہے کہ حضرت ابن مسعودؓ نے فرمایا تم نے اس بدعت کو شروع کر کے بڑا ظلم کیا ہے کیونکہ اگر یہ بدعت نہیں ہے تو پھر ہمیں حضرت محمدؐ کے صحابہؓ کو (نعوذ ب",""],["ٱللَّٰه","a"],[" من ذلک) گمراہ قرار دینا پڑے گا۔ اس پر حضرت عمرو بن عتبہ بن فرقدؓ نے کہا میں ",""],["ٱللَّٰه","a"],[" سے معافی مانگتا ہوں اے ابن مسعود اور اس کام سے توبہ کرتا ہوں پھر آپ نے انہیں بکھر جانے کا حکم دیا۔",""],[" (13)","s"],[" (14)","s"]]]],"f":[["(13)","Abu Nu'aym in his Hilya (Vol.4 Pg.381). Abu Nu'aym has reported a similar narration from Abu Za'raa, stating that it was Musayyib bin Nujbah that reported the gathering to Hadhrat Abdullaah bin Mas'ood."],["(14)","Tabraani."]]},{"b":[["n",[["حضرت ابوالبختریؒ","b"],[" کہتے ہیں کہ حضرت ابن مسعودؓ نے کوفہ کی مسجد میں دو حلقے دیکھے تو ان دونوں کے درمیان کھڑے ہو گئے اور فرمایا کون سا حلقہ پہلے شروع ہوا تھا؟ ایک حلقہ والوں نے کہا ہمارا (شروع ہوا تھا) تو دوسرے حلقے والوں سے فرمایا تم لوگ اٹھ کر اسی میں آ جاؤ اور یوں دو حلقوں کو ایک کر دیا۔ طبرانی کی ایک صحیح اور مختصر روایت میں یہ ہے کہ پھر حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ کپڑا اوڑھے ہوئے آئے اور فرمایا جو مجھے جانتا ہے وہ تو مجھے جانتا ہی ہے اور جو نہیں جانتا تو میں تعارف کرا دیتا ہوں کہ میں عبد",""],["ٱللَّٰه","a"],[" بن مسعود ہوں کیا تم لوگ حضرت محمدؐ اور ان کے صحابہؓ سے بھی زیادہ ہدایت یافتہ ہو یا تم نے گمراہی کی دم پکڑ رکھی ہے؟",""],[" (15)","s"],[" (16)","s"]]]],"f":[["(15)","Tabraani. Haythami (Vol.1 Pg.181) has commented on the chain of narrators."],["(16)","Tabraani."]]},{"b":[["n",[["حضرت عمرو بن سلمہؒ","b"],[" کہتے ہیں کہ ہم لوگ مغرب اور عشاء کے درمیان حضرت ابن مسعودؓ کے دروازے پر بیٹھے ہوئے تھے کہ اتنے میں حضرت ابوموسیٰؓ آئے اور فرمایا اے ابوعبدالرحمٰن! ذرا ہمارے پاس باہر آئیں۔ چنانچہ حضرت ابن مسعودؓ باہر آئے اور فرمایا اے ابوموسیٰ! آپ اس وقت کیوں آئے؟ حضرت ابوموسیٰؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! میں نے ایک ایسا کام دیکھا ہے جو ہے تو خیر لیکن اسے دیکھ کر میں پریشان ہو گیا ہوں، ہے تو وہ خیر لیکن اس نے مجھے چونکا دیا ہے۔ کچھ لوگ مسجد میں بیٹھے ہوئے ہیں اور ایک آدمی کہہ رہا ہے اتنی دفعہ سبحان ",""],["ٱللَّٰه","a"],[" کہو، اتنی دفعہ الحمد للہ کہو، چنانچہ حضرت ابن مسعودؓ اسی وقت چل پڑے اور ہم بھی ان کے ساتھ گئے یہاں تک کہ ان لوگوں کے پاس پہنچ گئے اور فرمایا تم لوگ کتنی جلدی بدل گئے ہو، حالانکہ حضورؐ کے صحابہؓ ابھی زندہ ہیں اور حضورؐ کی بیویاں ابھی جوان ہیں اور حضورؐ کے کپڑے اور برتن ابھی اپنی اصلی حالت پر ہیں ان میں کوئی تبدیلی نہیں آئی۔ تم اپنی برائیاں گنو، میں اس بات کا ضامن ہوں کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہاری نیکیاں گننے لگیں گے۔",""],[" (17)","s"]]]],"f":[["(17)","Tabraani in his Kabeer. Haythami (Vol.1 Pg.181) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عامر بن عبد","b"],["ٱللَّٰه","a"],[" بن زبیرؒ","b"],[" کہتے ہیں میں اپنے والد (حضرت عبد",""],["ٱللَّٰه","a"],[" بن زبیرؓ) کی خدمت میں حاضر ہوا۔ انھوں نے پوچھا تم کہاں تھے؟ میں نے کہا کچھ لوگ ملے تھے، میں نے ان سے بہتر آدمی کبھی نہیں دیکھے وہ لوگ ",""],["ٱللَّٰه","a"],[" کا ذکر کر رہے تھے۔ پھر ان میں سے ایک آدمی کانپنے لگا اور تھوڑی دیر میں ",""],["ٱللَّٰه","a"],[" کے ڈر سے بے ہوش ہو گیا۔ اس لیے میں ان کے ساتھ بیٹھ گیا تھا۔ اس کے بعد ان کے ساتھ کبھی نہ بیٹھا۔ جب انھوں نے دیکھا کہ ان کی اس بات کا میں نے اثر نہیں لیا تو فرمایا میں نے حضورؐ کو قرآن پڑھتے ہوئے دیکھا ہے۔ اور میں نے حضرت ابوبکرؓ اور حضرت عمرؓ کو بھی قرآن پڑھتے ہوئے دیکھا ہے ان حضرات پر تو ایسی حالت طاری نہیں ہوتی تھی تو تمہارا کیا خیال ہے یہ لوگ حضرت ابوبکرؓ حضرت عمرؓ سے بھی زیادہ ",""],["ٱللَّٰه","a"],[" سے ڈرنے والے ہیں؟ اس پر مجھے بات سمجھ میں آ گئی کہ بات یونہی ہے اور میں نے ان لوگوں کو چھوڑ دیا۔",""],[" (18)","s"]]]],"f":[["(18)","Abu Nu'aym in his Hilya (Vol.3 Pg.167)."]]},{"b":[["n",[["حضرت ابوصالح سعید بن عبدالرحمٰنؒ","b"],[" کہتے ہیں کہ ابن عتر تجیبی کھڑے ہو کر لوگوں میں قصہ گوئی کر رہا تھا تو اس سے حضورؐ کے صحابی حضرت صلہ بن حارث غفاریؓ نے فرمایا ہم نے حضورؐ کے عہد کو چھوڑا نہیں ہے اور کوئی قطع رحمی نہیں کی ہے تو پھر تم اور تمہارے ساتھی کہاں سے ہمارے درمیان (قصہ گوئی کے لیے) کھڑے ہو گئے ہو (اور اپنی بڑائی کے اظہار کے لیے یہ قصہ گوئی کر رہے ہو۔)",""],[" (19)","s"]]]],"f":[["(19)","Tabraani in his Kabeer, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.189). Bukhaari, Baghawi, Muhammad bin Rabee and Ibn Sakan have reported a similar narration, as quoted in Isaabah (Vol.2 Pg.193)."]]},{"b":[["n",[["حضرت عمرو بن زرارہؒ","b"],[" کہتے ہیں میں بیان کر رہا تھا کہ اتنے میں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ آ کر کھڑے ہو گئے اور فرمایا تم نے گمراہی والی بدعت ایجاد کی ہے یا تم حضرت محمدؐ اور ان کے صحابہؓ سے زیادہ ہدایت والے ہو گئے ہو؟ میں نے دیکھا کہ یہ بات سنتے ہی تمام لوگ اٹھ کر ادھر ادھر چلے گئے اور میری جگہ پر ایک آدمی بھی نہ رہا۔",""],[" (20)","s"]]]],"f":[["(20)","Tabraani. Haythami (Vol.1 Pg.189) has commented on the chain of narrators."]]}]},"88":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن شہابؒ","b"],[" کہتے ہیں کہ ایک دفعہ حضرت عمر بن خطابؓ نے منبر پر فرمایا اے لوگو! حتمی اور درست رائے تو صرف حضورؐ کی ہی تھی کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ ہی انہیں یہ رائے سمجھاتا تھا اور ہماری رائے تو بس گمان اور تکلف ہی ہے۔ (اس کا صحیح ہونا ضروری نہیں۔)",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.134)."]]},{"b":[["n",[["حضرت صدقہ بن ابی عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ فرمایا کرتے تھے اپنی رائے پر چلنے والے سنتوں کے دشمن ہیں۔ سستی کی وجہ سے سنتیں یاد نہیں کیں اور جتنی یاد تھیں انہیں محفوظ نہیں رکھا۔ اور جب ان سے ایسی بات پوچھی گئی جس کا جواب نہیں آتا تھا تو شرم کے مارے یہ نہیں کہا کہ ہم نہیں جانتے اس لیے سنتوں کے مقابلہ میں اپنی رائے لے آئے۔ ایسے لوگوں سے بالکل بچ کر رہنا۔ حضرت عمرؓ نے فرمایا سنت تو وہ ہے جسے ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ نے مقرر فرمایا۔ تم اپنی غلط رائے کو امت کے لیے سنت مت بناؤ۔ کنز کی روایت میں اس کے بعد یہ بھی ہے",""]]],["q",[["إِنَّ ٱلظَّنَّ لَا يُغْنِى مِنَ ٱلْحَقِّ شَيْـًٔا  (سورۃ نجم: ۲۸)","a"]]],["p",[["ترجمہ: \"اور یقیناً بے اصل خیالات امر حق (کے اثبات) میں ذرا بھی مفید نہیں ہوتے۔\"",""],[" (2)","s"],[" (3)","s"],[" (4)","s"]]]],"f":[["(2)","Ibn Abi Haatim and Bayhaqi, as quoted in Kanzul Ummaal (Vol.5 Pg.241)."],["(3)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.135)."],["(4)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.135)."]]},{"b":[["n",[["حضرت عمرو بن دینارؒ","b"],[" کہتے ہیں کہ ایک آدمی نے حضرت عمرؓ سے کہا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے آپ کو جو کچھ سمجھایا ہے آپ اس کے مطابق فیصلہ کریں۔ حضرت عمرؓ نے فرمایا ایسی بات نہ کہو کیونکہ یہ تو حضورؐ کی خصوصیت تھی (کہ ان کی ہر بات ",""],["ٱللَّٰه","a"],[" کی طرف سے ہوتی تھی۔ ہمارے دل میں جو بات آتی ہے وہ شیطان کی طرف سے بھی ہو سکتی ہے یہ حضرت عمرؓ کی تواضع ہے۔)",""],[" (5)","s"]]]],"f":[["(5)","Ibn Mundhir, as quoted in Kanzul Ummaal (Vol.5 Pg.241)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا یوں مت کہا کرو کہ بتائیں آپ کی کیا رائے ہے؟ کیونکہ تم سے پہلے والے اس طرح کہنے کی وجہ سے ہلاک ہوئے اور ایک چیز پر دوسری چیز کا قیاس نہ کیا کرو ورنہ تمہارے قدم جمنے کے بعد پھسل جائیں گے اور جب تم میں سے کسی سے ایسی بات پوچھی جائے جو وہ نہ جانتا ہو تو کہہ دے کہ ",""],["ٱللَّٰه","a"],[" ہی جانتے ہیں کیونکہ یہ (کہنا) بھی ایک تہائی علم ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani. Haythami (Vol.1 Pg.180) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں ہر آنے والا سال پہلے سال سے برا ہوگا (اپنی ذات کے اعتبار سے تو) کوئی سال کسی سال سے بہتر نہیں۔ کوئی جماعت کسی جماعت سے بہتر نہیں لیکن ہوگا یوں کہ تمہارے علماء اور تمہارے بھلے اور بہترین لوگ چلے جائیں گے اور پھر ایسے لوگ آ جائیں گے جو اپنی رائے سے تمام کاموں میں قیاس کرنے لگ جائیں گے۔ اس طرح اسلام میں شگاف پڑ جائے گا اور وہ گر جائے گا۔ ",""],["حضرت ابن عباسؓ","b"],[" فرماتے ہیں (دین میں) اصل تو ",""],["ٱللَّٰه","a"],[" کی کتاب اور رسول ",""],["ٱللَّٰه","a"],["ؐ کی سنت ہے اس کے بعد جو اپنی رائے سے کچھ کہے گا تو مجھے معلوم نہیں کہ اسے وہ اپنی نیکیوں میں پائے گا یا برائیوں میں۔",""],[" (7)","s"],[" (8)","s"]]]],"f":[["(7)","Tabraani in his Kabeer. Haythami (Vol.1 Pg.180) has commented on the chain of narrators. Ibn Abdul Birr has reported a similar narration in his Jaami (Vol.2 Pg.135)."],["(8)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.136)."]]},{"b":[["n",[["حضرت عطاءؒ","b"],[" اپنے والد سے نقل کرتے ہیں کہ نبی کریمؐ کے ایک صحابیؓ سے کسی چیز کے بارے میں پوچھا گیا۔ انھوں نے فرمایا مجھے اپنے رب سے اس بات سے حیا آتی ہے کہ حضرت محمدؐ کی امت کے بارے میں اپنی رائے سے کچھ کہوں۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.136)."]]}]},"89":{"lead":[],"stories":[{"b":[["n",[["حضرت معاذ بن جبلؓ","b"],[" فرماتے ہیں کہ جب نبی کریمؐ نے مجھے یمن بھیجا تو فرمایا جب تمہارے سامنے کوئی مقدمہ پیش ہوگا تو تم کس طرح فیصلہ کرو گے؟ میں نے کہا ",""],["ٱللَّٰه","a"],[" کی کتاب کے مطابق۔ حضورؐ نے فرمایا اگر تم اسے ",""],["ٱللَّٰه","a"],[" کی کتاب میں نہ پاؤ تو پھر؟ میں نے کہا رسول ",""],["ٱللَّٰه","a"],["ؐ کی سنت کے مطابق۔ حضورؐ نے فرمایا اگر تم اسے رسول ",""],["ٱللَّٰه","a"],["ؐ کی سنت میں نہ پاؤ تو پھر؟ میں نے کہا تو پھر میں اپنی رائے سے اجتہاد کروں گا اور (کوئی کمی نہیں کروں گا) (سوچ بچار میں)۔ اس پر حضورؐ نے میرے سینے پر ہاتھ مار کر فرمایا تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے رسول ",""],["ٱللَّٰه","a"],["ؐ کے قاصد کو اس چیز کی توفیق عطا فرمائی جس سے ",""],["ٱللَّٰه","a"],[" کے رسولؐ خوش ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Dawood, Tirmidhi and Daarimi, as quoted in Mishkaatul Masaabeeh (Pg.316)."]]},{"b":[["n",[["حضرت محمد بن سیرینؒ","b"],[" کہتے ہیں کہ نبی کریمؐ کے بعد کوئی آدمی حضرت ابوبکرؓ سے زیادہ اس چیز سے ڈرنے والا نہیں تھا جسے وہ نہ جانتا ہو اور حضرت ابوبکرؓ کے بعد کوئی آدمی حضرت عمرؓ سے زیادہ ڈرنے والا نہیں تھا۔ ایک مرتبہ حضرت ابوبکرؓ کے سامنے ایک مسئلہ پیش ہوا۔ انھوں نے اس کے لیے ",""],["ٱللَّٰه","a"],[" کی کتاب میں کوئی اصل نہ پائی اور نہ ہی سنت میں کوئی نشان پایا تو فرمایا اب میں اپنی رائے سے اجتہاد کروں گا۔ اگر ٹھیک فیصلہ ہوا تو ",""],["ٱللَّٰه","a"],[" کی طرف سے اور اگر غلط فیصلہ ہوا تو میری طرف سے اور میں ",""],["ٱللَّٰه","a"],[" سے استغفار کرتا ہوں۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd and Ibn Abdul Birr in his Jaami, as quoted in Kanzul Ummaal (Vol.5 Pg.241)."]]},{"b":[["n",[["حضرت شریحؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ نے انہیں یہ خط لکھا کہ جب تمہارے پاس کوئی مقدمہ آئے تو اس میں ",""],["ٱللَّٰه","a"],[" کی کتاب کے مطابق فیصلہ کرو اور اگر تمہارے پاس ایسا مقدمہ آئے جو کتاب ",""],["ٱللَّٰه","a"],[" میں نہیں ہے تو پھر اس میں سنت رسول ",""],["ٱللَّٰه","a"],["ؐ کے مطابق فیصلہ کرو اور اگر ایسا مقدمہ آئے جو نہ کتاب ",""],["ٱللَّٰه","a"],[" میں ہے اور نہ سنت رسولؐ میں تو پھر وہ فیصلہ کرو جس پر علماء کا اجماع و اتفاق ہو اور اگر ایسا مقدمہ آئے جو نہ کتاب ",""],["ٱللَّٰه","a"],[" میں ہے اور نہ سنت رسولؐ میں اور نہ اس میں کسی عالم نے کوئی بات کی ہے تو پھر دو باتوں میں سے ایک بات اختیار کر لو چاہو تو آگے بڑھ کر اپنی رائے سے اجتہاد کر کے فیصلہ کر لو اور چاہو تو پیچھے ہٹ جاؤ (اور کوئی فیصلہ نہ کرو) اور میرے خیال میں پیچھے ہٹنا تمہارے لیے بہتر ہی ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.56)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا جسے کسی معاملہ میں فیصلہ کرنے کی ضرورت پیش آ جائے تو اسے چاہیے کہ کتاب ",""],["ٱللَّٰه","a"],[" کے مطابق فیصلہ کرے اور اگر ایسا معاملہ ہو جو کتاب ",""],["ٱللَّٰه","a"],[" میں نہیں ہے تو پھر اس میں وہ فیصلہ کرے جو ",""],["ٱللَّٰه","a"],[" کے نبی کریمؐ نے کیا اور اگر ایسا معاملہ پیش آ جائے جو نہ کتاب ",""],["ٱللَّٰه","a"],[" میں ہو اور نہ اس کے بارے میں ",""],["ٱللَّٰه","a"],[" کے نبیؐ نے کوئی فیصلہ کیا ہو تو پھر اس میں وہ فیصلہ کرے جو نیک لوگوں نے کیا ہو اور اگر ایسا معاملہ پیش آ جائے جو نہ کتاب ",""],["ٱللَّٰه","a"],[" میں ہو اور نہ ",""],["ٱللَّٰه","a"],[" کے نبیؐ اور نیک بندوں نے اس کے بارے میں کوئی فیصلہ کیا ہو تو پھر اپنی رائے سے اجتہاد کرے اور اپنی اس بات پر پکا رہے اور شرمائے نہیں۔ دوسری روایت میں یہ ہے کہ پھر اپنی رائے سے اجتہاد کرے اور یہ ہرگز نہ کہے کہ میرا خیال تو ایسا ہے، البتہ میں ڈرتا بھی ہوں کیونکہ حلال بھی واضح ہے اور حرام بھی واضح ہے، البتہ ان دونوں کے درمیان بہت سے مشتبہ امور ہیں (جن کا حلال یا حرام ہونا واضح نہیں ہے) اس لیے وہ کام چھوڑ دو جن میں کسی قسم کا شک ہے اور وہ کام اختیار کرو جن میں کوئی شک نہیں ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.57)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن ابی یزیدؒ","b"],[" کہتے ہیں کہ میں نے حضرت ابن عباسؓ کا یہ معمول دیکھا کہ جب ان سے کوئی چیز پوچھی جاتی اور وہ ",""],["ٱللَّٰه","a"],[" کی کتاب میں ہوتی تو وہ فرما دیتے اور وہ ",""],["ٱللَّٰه","a"],[" کی کتاب میں نہ ہوتی لیکن اس کے بارے میں حضورؐ سے کچھ منقول ہوتا تو وہ فرما دیتے اور اگر وہ ",""],["ٱللَّٰه","a"],[" کی کتاب میں نہ ہوتی اور حضورؐ سے بھی کچھ منقول نہ ہوتا لیکن حضرت ابوبکرؓ اور حضرت عمرؓ کی طرف سے کچھ منقول ہوتا تو وہ فرما دیتے اور اگر وہ ",""],["ٱللَّٰه","a"],[" کی کتاب میں نہ ہوتی اور حضورؐ سے اور حضرت ابوبکرؓ اور حضرت عمرؓ سے بھی کچھ منقول نہ ہوتا تو پھر اپنی رائے سے اجتہاد کرتے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.57). Ibn Sa'd (Vol.4 Pg.181) has reported a similar narration."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں جب ہمارے پاس حضرت علیؓ کی طرف سے کوئی مضبوط دلیل آ جاتی تو ہم اس کے برابر کسی کو نہ سمجھتے (بلکہ اسی کو اختیار کر لیتے)۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.57)."]]},{"b":[["n",[["حضرت مسروقؒ","b"],[" کہتے ہیں میں نے حضرت ابی بن کعبؓ سے کسی چیز کے بارے میں پوچھا تو فرمایا کیا یہ چیز پیش ہو چکی ہے؟ میں نے کہا نہیں تو فرمایا جب تک یہ پیش نہ آ جائے اس وقت تک ہمیں آرام کرنے دو۔ جب پیش آ جائے گی تو پھر ہم کوشش کر کے اپنی رائے بتا دیں گے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.58)."]]}]},"90":{"lead":[],"stories":[{"b":[["n",[["حضرت عبدالرحمٰن بن ابی لیلیٰؒ","b"],[" کہتے ہیں کہ میں نے حضورؐ کے ایک سو بیس صحابہؓ کو مسجد میں پایا کہ ان میں جو حدیث بیان کرنے والے تھے وہ یہ چاہتے تھے کہ ان کا بھائی حدیث بیان کر دے اور انہیں حدیث بیان نہ کرنی پڑے اور ان میں جو بھی مفتی تھے وہ یہ چاہتے تھے کہ ان کا بھائی فتویٰ دے دے اور خود انہیں فتویٰ نہ دینا پڑے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.163). Ibn Sa'd (Vol.6 Pg.110) has reported a similar narration adding that the Sahabah Hadhrat Abdur Rahmaan bin Abu Layla met were from the Ansaar."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا وہ آدمی پاگل ہے کہ اس سے جو بھی فتویٰ پوچھا جائے وہ فوراً فتویٰ دے دے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.165). Tabraani has reported a similar narration from Hadhrat Abdullaah bin Mas'ood, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.183)."]]},{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرماتے ہیں لوگوں کو فتویٰ دینے والے آدمی تین طرح کے ہیں۔ ایک تو وہ آدمی جو قرآن کے ناسخ و منسوخ کو جانتا ہے، دوسرا وہ امیر جماعت جسے فتویٰ دیے بغیر چارہ نہیں اور تیسرا احمق ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.166)."]]},{"b":[["n",[["حضرت ابن سیرینؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ نے حضرت ابومسعودؓ سے فرمایا کیا مجھے یہ خبر نہیں ملی کہ تم امیر نہیں ہو پھر بھی تم لوگوں کو فتویٰ دیتے ہو؟ جسے امارت کی راحت ملی ہے اسے ہی امارت کی مشقت بھی اٹھانے دو یعنی جو امیر ہے اسے ہی فتویٰ کی ذمہ داری اٹھانے دو تم فتویٰ نہ دو۔",""],[" (4)","s"],[" (5)","s"]]]],"f":[["(4)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.166)."],["(5)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.143)."]]},{"b":[["n",[["حضرت ابومنہالؒ","b"],[" کہتے ہیں میں نے حضرت زید بن ارقمؓ اور حضرت براء بن عازبؓ سے سونے چاندی کی خرید و فروخت کے بارے میں پوچھا تو میں نے جس سے بھی پوچھا اس نے یہی کہا تم دوسرے سے پوچھ لو کیونکہ وہ مجھ سے بہتر اور مجھ سے زیادہ جاننے والا ہے۔ اس کے بعد سونے چاندی کی خرید و فروخت کے بارے میں حدیث ذکر کی۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abdul Birr in his Jaami Bayaanil Ilm (Vol.2 Pg.166)."]]},{"b":[["n",[["حضرت ابوحسینؓ","b"],[" نے فرمایا اب تو ہر آدمی اس مسئلہ میں فتویٰ دے رہا ہے حالانکہ اگر یہ مسئلہ حضرت عمر بن خطابؓ کے سامنے پیش ہوتا تو اس کے لیے وہ تمام بدری صحابہؓ کو جمع کر لیتے (اور پھر ان کے مشورہ سے فتویٰ دیتے)۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.5 Pg.241)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" سے پوچھا گیا کہ حضورؐ کے زمانے میں کون فتویٰ دیا کرتا تھا؟ انھوں نے فرمایا حضرت ابوبکرؓ اور حضرت عمرؓ اور میرے علم میں ان دو کے علاوہ اور کوئی نہیں ہے۔ ",""],["حضرت قاسم بن محمدؒ","b"],[" کہتے ہیں حضرت ابوبکرؓ، حضرت عمرؓ، حضرت عثمانؓ اور حضرت علیؓ حضورؐ کے زمانے میں فتویٰ دیا کرتے تھے۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Sa'd (Vol.4 Pg.151)."]]},{"b":[["n",[["حضرت فضیل بن ابی عبد","b"],["ٱللَّٰه","a"],[" بن دیناراؒ","b"],[" اپنے والد سے نقل کرتے ہیں کہ حضرت عبدالرحمٰن بن عوفؓ ان صحابہؓ میں سے تھے جو حضورؐ کے زمانے میں اور حضرت ابوبکرؓ، حضرت عمرؓ اور حضرت عثمانؓ کے زمانے میں حضورؐ سے سنی ہوئی احادیث کے مطابق فتویٰ دیا کرتے تھے۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Sa'd (Vol.4 Pg.157). Ibn Asaakir has reported a similar narration, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.77)."]]},{"b":[["n",[["حضرت ابوعطیہ ہمدانیؒ","b"],[" کہتے ہیں کہ ایک مرتبہ میں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ کے پاس بیٹھا ہوا تھا کہ اتنے میں ایک آدمی آیا اور اس نے ایک مسئلہ پوچھا۔ حضرت ابن مسعودؓ نے فرمایا کیا تم نے یہ مسئلہ میرے علاوہ کسی اور سے بھی پوچھا ہے؟ اس آدمی نے کہا ہاں میں نے حضرت ابوموسیٰؓ سے بھی پوچھا اور انھوں نے اس کا یہ جواب دیا تھا۔ جواب سن کر حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے اس کی مخالفت کی۔ اس پر حضرت ابوموسیٰؓ کھڑے ہوئے اور فرمایا جب تک یہ بڑے عالم تم میں ہیں مجھ سے کچھ نہ پوچھا کرو۔ ",""],["حضرت ابوعمرو شیبانیؒ","b"],[" کہتے ہیں کہ حضرت ابوموسیٰ اشعریؓ نے فرمایا جب تک یہ بڑے عالم حضرت ابن مسعودؓ تم میں ہیں مجھ سے کچھ نہ پوچھا کرو۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Sa'd (Vol.4 Pg.160). Abu Nu'aym has reported a similar narration in his Hilya (Vol.1 Pg.129)."]]},{"b":[["n",[["حضرت سہل بن ابی حثمہؓ","b"],[" فرماتے ہیں کہ حضورؐ کے زمانے میں فتویٰ دینے والے حضرات تین مہاجرین میں سے تھے اور تین انصار میں سے تھے حضرت عمرؓ، حضرت عثمانؓ، حضرت علیؓ، حضرت ابی بن کعبؓ، حضرت معاذ بن جبلؓ اور حضرت زید بن ثابتؓ۔",""],[" (11)","s"]]]],"f":[["(11)","Ibn Sa'd (Vol.4 Pg.167)."]]},{"b":[["n",[["حضرت مسروقؒ","b"],[" کہتے ہیں حضورؐ کے صحابہؓ میں سے فتویٰ دینے والے حضرات یہ تھے حضرت عمرؓ، حضرت علیؓ، حضرت ابن مسعودؓ، حضرت زیدؓ، حضرت ابی بن کعبؓ اور حضرت ابوموسیٰ اشعریؓ۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Sa'd (Vol.4 Pg.168)."]]},{"b":[["n",[["حضرت قبیصہ بن ذویب بن حلحلہؓ","b"],[" فرماتے ہیں کہ حضرت زید بن ثابتؓ، حضرت عمرؓ، حضرت عثمانؓ کے زمانے میں اور جب تک حضرت علیؓ مدینہ میں رہے اس وقت تک وہ مدینہ میں قضاء، فتویٰ، قراءت اور فرائض و میراث میں امام تھے اور حضرت علیؓ کے مدینہ سے چلے جانے کے بعد بھی وہ پانچ سال مزید امام رہے پھر سنہ چالیس میں حضرت معاویہؓ خلیفہ بنے تو بھی یہی امام تھے یہاں تک کہ سنہ پینتالیس میں حضرت زیدؓ کا انتقال ہو گیا۔",""],[" (13)","s"]]]],"f":[["(13)","Ibn Sa'd (Vol.4 Pg.175)."]]},{"b":[["n",[["حضرت عطاء بن یسارؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ اور حضرت عثمانؓ حضرت ابن عباسؓ کو بلایا کرتے تھے اور وہ بھی بدری صحابہؓ کے ساتھ مشورہ دیا کرتے تھے اور حضرت ابن عباسؓ، حضرت عمرؓ اور حضرت عثمانؓ کے زمانے میں فتویٰ دیا کرتے تھے اور انتقال تک حضرت ابن عباسؓ کا یہی مشغلہ رہا۔",""],[" (14)","s"]]]],"f":[["(14)","Ibn Sa'd (Vol.4 Pg.181)."]]},{"b":[["n",[["حضرت زیاد بن میناءؒ","b"],[" کہتے ہیں کہ حضرت ابن عباسؓ، حضرت ابن عمرؓ، حضرت ابوسعید خدریؓ، حضرت ابوہریرہؓ، حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرو بن عاصؓ، حضرت جابر بن عبد",""],["ٱللَّٰه","a"],["ؓ، حضرت رافع بن خدیجؓ، حضرت سلمہ بن اکوعؓ، حضرت ابوواقد لیثیؓ اور حضرت عبد",""],["ٱللَّٰه","a"],[" بن بحینہؓ اور ان جیسے اور صحابہؓ مدینہ میں فتویٰ دیا کرتے تھے اور حضورؐ کی طرف سے حدیثیں بیان کیا کرتے تھے۔ حضرت عثمانؓ کے انتقال پر یہ دونوں دینی خدمتیں ان حضرات کو میسر ہوئیں اور یہ سب اپنے انتقال تک ان میں ہی لگے رہے اور پھر ان میں سے فتویٰ میں زیادہ قابل اعتماد حضرت ابن عباسؓ، حضرت ابن عمرؓ، حضرت ابوسعید خدریؓ، حضرت ابوہریرہؓ اور حضرت جابر بن عبد",""],["ٱللَّٰه","a"],["ؓ تھے۔",""],[" (15)","s"]]]],"f":[["(15)","Ibn Sa'd (Vol.4 Pg.187)."]]},{"b":[["n",[["حضرت قاسمؒ","b"],[" کہتے ہیں حضرت عائشہؓ حضرت ابوبکرؓ، حضرت عمرؓ اور حضرت عثمانؓ کے زمانے میں مستقل فتویٰ دیا کرتی تھیں اور پھر انتقال تک ان کا یہی مشغلہ رہا۔ ",""],["ٱللَّٰه","a"],[" ان پر رحمت نازل فرمائے۔ میں ہر وقت ان کے ساتھ رہا کرتا تھا اور وہ میرے ساتھ بہت اچھا سلوک فرمایا کرتی تھیں (حضرت قاسمؒ حضرت عائشہؓ کے بھتیجے تھے) آگے اور حدیث ذکر کی۔",""],[" (16)","s"]]]],"f":[["(16)","Ibn Sa'd (Vol.4 Pg.189)."]]}]},"91":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوذرؓ","b"],[" فرماتے ہیں کہ حضورؐ ہمیں اس حال میں چھوڑ کر گئے کہ آسمان میں جو بھی پرندہ اپنے دونوں پروں کو ہلاتا ہے اس سے ہمیں (حضورؐ کا سکھایا ہوا) کوئی نہ کوئی علم یاد آ جاتا ہے۔ طبرانی کی روایت میں اس کے بعد یہ ہے کہ حضورؐ نے فرمایا جو چیز بھی جنت کے قریب کرنے والی اور دوزخ کی آگ سے دور کرنے والی ہے وہ تمہارے لیے بیان کر دی گئی ہے۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Ahmad."],["(2)","Tabraani. Tabraani has reported a narration similar to that of Ahmad from Hadhrat Abu Dardaa, which is reported from reliable sources, as confirmed by Haythami (Vol.8 Pg.264). Ibn Sa'd (Vol.4 Pg.170) has also reported a similar narration."]]},{"b":[["n",[["حضرت عمرو بن عاصؓ","b"],[" فرماتے ہیں کہ میں نے حضورؐ سے ایک ہزار مثالیں (کہاوتیں) سیکھی ہیں۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.8 Pg.264)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" نے ایک حدیث ذکر کی جس میں یہ بھی فرمایا کہ (حضورؐ کی وفات کے موقع پر) جس چیز کے بارے میں صحابہ کرامؓ میں اختلاف ہوتا تو میرے والد (حضرت ابوبکرؓ) ایسی حدیث سناتے جسے سن کر سب مطمئن ہو جاتے اور فیصلہ کن بات سامنے آ جاتی۔ صحابہؓ نے یہ سوال کیا کہ حضورؐ کو کہاں دفن کیا جائے؟ تو اس بارے میں ہمیں کسی کے پاس کوئی علم (قرآن یا حدیث کا) نہ مل سکا لیکن حضرت ابوبکرؓ نے فرمایا میں نے حضورؐ کو فرماتے ہوئے سنا کہ نبی کی جس جگہ روح قبض کی جاتی ہے اسی جگہ اسے دفن کیا جاتا ہے۔ ایسے ہی حضورؐ کی میراث کے بارے میں صحابہؓ میں اختلاف ہوا تو ہمیں اس بارے میں کسی کے پاس کوئی علم نہ مل سکا لیکن حضرت ابوبکرؓ نے فرمایا میں نے حضورؐ کو فرماتے ہوئے سنا کہ ہم انبیاء کی جماعت کسی کو وارث نہیں بناتے اور جو کچھ ہم چھوڑتے ہیں وہ صدقہ ہوا کرتا ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Baghawi, Ibn Asaakir and others, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.346)."]]},{"b":[["n",[["حضرت ابو وائلؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا کہ اگر حضرت عمرؓ کے علم کو ترازو کے ایک پلڑے میں رکھا جائے اور تمام زمین والوں کے علم کو دوسرے پلڑے میں رکھا جائے تو حضرت عمرؓ کے علم والا پلڑا جھک جائے گا۔ ",""],["حضرت اعمشؒ","b"],[" کہتے ہیں میرے دل نے اس بات کو قبول نہ کیا۔ میں نے جا کر حضرت ابراہیمؒ سے اس کا ذکر کیا تو انہوں نے کہا تم اسے نہیں مان رہے ہو اور ",""],["ٱللَّٰه","a"],[" کی قسم! حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے تو اس سے آگے کی بھی بات کہہ رکھی ہے۔ انہوں نے فرمایا ہے کہ جس دن حضرت عمرؓ دنیا سے گئے اس دن علم کے دس حصوں میں سے نو حصے چلے گئے۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani. Haythami (Vol.9 Pg.69) has commented on the chain of narrators. Ibn Sa'd (Vol.4 Pg.153) has reported a similar narration."]]},{"b":[["n",[["حضرت عمرؓ کی وفات کے بارے میں ایک لمبی حدیث میں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ کا یہ ارشاد منقول ہے کہ حضرت عمرؓ ہم میں ",""],["ٱللَّٰه","a"],[" کو سب سے زیادہ جاننے والے، ",""],["ٱللَّٰه","a"],[" کی کتاب کو ہم سب سے زیادہ پڑھنے والے اور ",""],["ٱللَّٰه","a"],[" کے دین کی ہم سب سے زیادہ سمجھ رکھنے والے تھے۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani, as quoted in Majma'uz Zawaa'id (Vol.9 Pg.69)."]]},{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرماتے ہیں حضرت عمرؓ کا علم اتنا زیادہ تھا کہ اس کے سامنے تمام لوگوں کا علم اتنا کم لگتا تھا کہ جیسے وہ کسی سوراخ میں چھپا کر رکھا ہوا ہو۔ مدینہ کے ایک صاحب کہتے ہیں میں حضرت عمرؓ کے پاس گیا تو مجھے ان کے سامنے فقہاء بچوں کی طرح نظر آئے۔ وہ دینی سمجھ اور علم کی وجہ سے تمام فقہاء پر حاوی تھے۔",""],[" (7)","s"],[" (8)","s"]]]],"f":[["(7)","Ibn Sa'd (Vol.4 Pg.153)."],["(8)","Ibn Sa'd (Vol.4 Pg.153)."]]},{"b":[["n",[["حضرت ابواسحاقؒ","b"],[" کہتے ہیں کہ جب حضرت علیؓ نے حضرت فاطمہؓ سے شادی کی تو حضرت فاطمہؓ نے نبی کریمؐ کی خدمت میں عرض کیا کہ آپؐ نے میری ان سے شادی کر دی ہے ان کی آنکھیں کمزور ہیں پیٹ بڑا ہے (شکل و صورت اچھی نہیں)۔ حضورؐ نے فرمایا میں نے تمہاری جن سے شادی کی ہے ان کے فضائل یہ ہیں کہ میرے صحابہؓ میں سب سے پہلے اسلام لائے اور ان کا علم ان سب سے زیادہ ہے اور یہ ان میں سب سے زیادہ بردبار ہیں (اے فاطمہ! صورت نہ دیکھو سیرت دیکھو)۔ ",""],["حضرت معقل بن یسارؓ","b"],[" کی روایت میں یہ ہے کہ حضورؐ نے فرمایا (اے فاطمہ!) کیا تم اس پر راضی نہیں ہو کہ میں نے تمہاری شادی ایسے آدمی سے کی ہے جو میری امت میں سب سے پرانے اسلام لانے والے، سب سے زیادہ علم والے اور سب سے زیادہ بردبار ہیں۔",""],[" (9)","s"],[" (10)","s"]]]],"f":[["(9)","Tabraani. Haythami (Vol.9 Pg.102) has commented on the chain of narrators."],["(10)","Tabraani and Ahmad. Haythami (Vol.9 Pg.101) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ ",""],["ٱللَّٰه","a"],[" کی قسم! جو آیت بھی نازل ہوئی اس کے بارے میں مجھے معلوم ہے کہ کس معاملہ میں نازل ہوئی؟ اور کہاں نازل ہوئی؟ اور کن لوگوں کے بارے میں نازل ہوئی؟ میرے رب نے مجھے سمجھدار دل اور خوب بولنے والی فصیح زبان دی ہے۔ ",""],["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں کہ حضرت عمرؓ اس مشکل مسئلہ سے ",""],["ٱللَّٰه","a"],[" کی پناہ مانگتے تھے جس کے حل کے لیے حضرت ابوالحسن یعنی حضرت علیؓ موجود نہ ہوں۔",""],[" (11)","s"],[" (12)","s"]]]],"f":[["(11)","Ibn Sa'd (Vol.4 Pg.154)."],["(12)","Ibn Sa'd (Vol.4 Pg.156)."]]},{"b":[["n",[["حضرت مسروقؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا جو سورت بھی نازل ہوئی مجھے معلوم ہے کہ وہ کس بارے میں نازل ہوئی؟ اگر مجھے معلوم ہو جائے کہ کوئی آدمی مجھ سے زیادہ ",""],["ٱللَّٰه","a"],[" کی کتاب کو جاننے والا ہے اور اونٹ اور سواریاں مجھے اس تک پہنچا سکتی ہیں تو میں اس کے پاس ضرور جاؤں گا۔",""]]]],"f":[]},{"b":[["n",[["حضرت مسروقؒ","b"],[" کہتے ہیں کہ میں حضرت محمدؐ کے صحابہؓ کی مجلسوں میں بہت بیٹھا ہوں۔ میں نے انہیں (دینی فیضان میں) تالاب کی طرح پایا کسی تالاب سے ایک آدمی سیراب ہوتا ہے اور کسی تالاب سے دو آدمی اور کسی سے دس اور کسی سے سو آدمی سیراب ہوتے ہیں اور بعض تالاب اتنے بڑے ہوتے ہیں کہ ساری زمین والے اس سے سیراب ہو جائیں۔ میں نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ کو اسی بڑے تالاب کی طرح پایا (ان سے ساری دنیا سیراب ہوتی تھی)۔",""],[" (13)","s"]]]],"f":[["(13)","Ibn Sa'd (Vol.4 Pg.169)."]]},{"b":[["n",[["حضرت زید بن وہبؒ","b"],[" کہتے ہیں کہ ایک دن حضرت عمرؓ بیٹھے ہوئے تھے کہ سامنے سے حضرت عبد",""],["ٱللَّٰه","a"],["ؓ آئے۔ جب حضرت عمرؓ نے انہیں آتے ہوئے دیکھا تو فرمایا یہ دینی سمجھ اور علم سے بھری ہوئی کوٹھی ہیں۔ ",""],["حضرت اسد بن وداعہؒ","b"],[" کہتے ہیں کہ ایک مرتبہ حضرت عمرؓ نے حضرت ابن مسعودؓ کا ذکر فرمایا اور فرمایا یہ تو علم سے بھری ہوئی کوٹھی ہیں اور انہیں قادسیہ بھیج کر میں نے قادسیہ والوں کو اپنے پر ترجیح دی ہے۔",""],[" (14)","s"]]]],"f":[["(14)","Ibn Sa'd (Vol.4 Pg.161)."]]},{"b":[["n",[["حضرت ابوالبختریؒ","b"],[" کہتے ہیں کہ ہم لوگ حضرت علیؓ کی خدمت میں گئے اور ہم ان سے حضرت محمدؐ کے صحابہؓ کے بارے میں پوچھنے لگے۔ انہوں نے فرمایا کس صحابی کے بارے میں پوچھتے ہو؟ ہم نے کہا حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ کے بارے میں ہمیں کچھ بتا دیں۔ انہوں نے فرمایا انہوں نے قرآن و حدیث کا علم حاصل کیا اور علم کی انتہا کو پہنچ گئے اور یہی بات ان کے زیادہ علم والا ہونے کے لیے کافی ہے۔ پھر ہم نے عرض کیا حضرت ابوموسیٰؓ کے بارے میں کچھ فرما دیں۔ فرمایا انہیں علم میں اچھی طرح رنگا گیا پھر اچھی طرح رنگ کر باہر نکلے۔ پھر ہم نے عرض کیا حضرت عمار بن یاسرؓ کے بارے میں کچھ بتا دیں۔ فرمایا وہ ایسے مومن ہیں جو بھول گئے تھے اور جب انہیں یاد دلایا گیا تو انہیں یاد آ گیا تھا۔ پھر ہم نے عرض کیا ہمیں حضرت حذیفہؓ کے بارے میں کچھ فرما دیں۔ فرمایا وہ حضرت محمدؐ کے صحابہؓ میں منافقوں کو سب سے زیادہ جاننے والے تھے۔ پھر ہم نے عرض کیا حضرت ابوذرؓ کے بارے میں کچھ بتا دیں۔ فرمایا انہوں نے علم تو خوب اچھی طرح حاصل کیا تھا اور خوب یاد بھی تھا لیکن پھر اس کے پھیلانے میں وہ کامیاب نہ ہو سکے (آخر میں طبیعت میں سختی زیادہ ہو گئی تھی)۔ پھر ہم نے عرض کیا حضرت سلمان فارسیؓ کے بارے میں کچھ بتائیں۔ فرمایا انہوں نے پہلا علم بھی حاصل کیا تھا (جو پہلے نبی لے کر آئے تھے) اور بعد والا علم بھی حاصل کیا (جو حضورؐ لے کر آئے تھے) وہ علم کا ایسا سمندر ہیں جس کی گہرائی کا اندازہ نہیں لگایا جا سکتا اور وہ ہمارے گھر انے میں سے ہیں۔ پھر ہم نے عرض کیا اے امیر المومنین! اب آپ اپنے بارے میں کچھ بتا دیں۔ فرمایا تم لوگ اصل میں یہ بات پوچھنا چاہتے تھے۔ میں جب حضورؐ سے کچھ پوچھتا تو آپؐ اس کا جواب ارشاد فرما دیتے اور جب میں خاموش ہوتا تو آپؐ از خود گفتگو کی ابتداء فرماتے۔",""],[" (15)","s"]]]],"f":[["(15)","Ibn Sa'd (Vol.4 Pg.162)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا حضرت معاذ بن جبلؓ مقتدا تھے اور ",""],["ٱللَّٰه","a"],[" کے فرمانبردار تھے اور سب طرف سے یکسو ہو کر ایک ",""],["ٱللَّٰه","a"],[" کے ہو گئے تھے اور وہ مشرکوں میں سے نہیں تھے (حضرت فروہ بن نوفل اشجعیؒ کہتے ہیں) میں نے عرض کیا ابوعبدالرحمٰن یعنی ابن مسعودؓ سے غلطی ہو گئی ہے۔ یہ الفاظ تو ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضرت ابراہیمؑ کے بارے میں استعمال فرمائے ہیں",""]]],["q",[["إِنَّ إِبْرَٰهِيمَ كَانَ أُمَّةً قَانِتًا لِّلَّهِ حَنِيفًا وَلَمْ يَكُ مِنَ ٱلْمُشْرِكِينَ  (سورۃ نحل: ۱۲۰)","a"]]],["p",[["ترجمہ: \"بے شک ابراہیم علیہ السلام بڑے مقتدا تھے ",""],["ٱللَّٰه","a"],[" تعالیٰ کے فرمانبردار تھے بالکل ایک طرف کے ہو رہے تھے اور وہ شرک کرنے والوں میں سے نہ تھے۔\" حضرت ابن مسعودؓ نے دوبارہ ارشاد فرمایا حضرت معاذ بن جبلؓ مقتدا تھے اور ",""],["ٱللَّٰه","a"],[" کے فرمانبردار تھے اور سب طرف سے یکسو ہو کر ایک ",""],["ٱللَّٰه","a"],[" کے ہو گئے تھے اور وہ مشرکوں میں سے نہیں تھے۔ اس پر میں سمجھا کہ وہ حضرت معاذؓ کے بارے میں یہ الفاظ جان بوجھ کر استعمال کر رہے ہیں۔ اس پر میں خاموش ہو گیا۔ پھر انھوں نے فرمایا کیا تم جانتے ہو لفظ امت کا کیا مطلب ہے؟ لفظ قانت کا کیا مطلب ہے؟ میں نے کہا ",""],["ٱللَّٰه","a"],[" ہی جانتے ہیں (میں نہیں جانتا) فرمایا امت وہ انسان ہے جو لوگوں کو بھلائی اور خیر سکھائے اور قانت وہ ہے جو ",""],["ٱللَّٰه","a"],[" و رسولؐ کا فرمانبردار ہو تو حضرت معاذؓ لوگوں کو خیر سکھایا کرتے تھے اور ",""],["ٱللَّٰه","a"],[" و رسولؐ کے فرمانبردار تھے۔",""],[" (16)","s"]]]],"f":[["(16)","Ibn Sa'd (Vol.4 Pg.165)."]]},{"b":[["n",[["حضرت مسروقؒ","b"],[" کہتے ہیں کہ میں نے حضورؐ کے صحابہؓ کو غور سے دیکھا تو میں نے دیکھا کہ صحابہؓ کا علم چھ حضرات پر پہنچ کر ختم ہو گیا حضرت عمرؓ، حضرت علیؓ، حضرت عبد",""],["ٱللَّٰه","a"],["ؓ، حضرت معاذؓ، حضرت ابوالدرداءؓ اور حضرت زید بن ثابتؓ۔ پھر میں نے ان چھ حضرات کو غور سے دیکھا تو ان کا علم حضرت علیؓ اور حضرت عبد",""],["ٱللَّٰه","a"],["ؓ پر پہنچ کر ختم ہو گیا۔",""],[" (17)","s"]]]],"f":[["(17)","Ibn Sa'd (Vol.4 Pg.167)."]]},{"b":[["n",[["حضرت مسروقؒ","b"],[" کہتے ہیں میں مدینہ گیا اور نبی کریمؐ کے صحابہؓ کے بارے میں پوچھا تو مجھے حضرت زید بن ثابتؓ مضبوط علم والوں میں سے نظر آئے۔",""],[" (18)","s"]]]],"f":[["(18)","Ibn Sa'd (Vol.4 Pg.176)."]]},{"b":[["n",[["حضرت مسروقؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا اگر حضرت ابن عباسؓ (چھوٹی عمر کے نہ ہوتے اور) ہماری عمر کو پا لیتے تو ہم میں سے کوئی آدمی ان کے (علم کے) دسویں حصے کو نہ پا سکتا۔ اس روایت میں حضرت نضرؒ راوی نے یہ بھی بڑھایا ہے کہ حضرت ابن عباسؓ قرآن کے بہترین ترجمان تھے۔",""],[" (19)","s"]]]],"f":[["(19)","Ibn Sa'd (Vol.4 Pg.181)."]]},{"b":[["n",[["حضرت مجاہدؒ","b"],[" کہتے ہیں کہ زیادہ علم کی وجہ سے حضرت ابن عباسؓ کو سمندر کہا جاتا تھا۔",""],[" (20)","s"]]]],"f":[["(20)","Ibn Sa'd (Vol.4 Pg.181)."]]},{"b":[["n",[["حضرت لیث بن ابی سلیمؒ","b"],[" کہتے ہیں میں نے حضرت طاؤسؒ سے کہا اس کی کیا وجہ ہے کہ آپ حضورؐ کے اکابر صحابہؓ کو چھوڑ کر ان نوعمر (صحابی) یعنی حضرت ابن عباسؓ کے ساتھ ہر وقت رہتے ہیں؟ انھوں نے کہا میں نے حضورؐ کے ستر صحابہؓ کو دیکھا کہ جب ان میں کسی چیز کے بارے میں اختلاف ہو جاتا تو وہ حضرت ابن عباسؓ کے قول کی طرف رجوع کرتے۔",""],[" (21)","s"]]]],"f":[["(21)","Ibn Sa'd (Vol.4 Pg.181)."]]},{"b":[["n",[["حضرت عامر بن سعد بن ابی وقاصؒ","b"],[" کہتے ہیں میں نے اپنے والد (حضرت سعد بن ابی وقاصؓ) کو فرماتے ہوئے سنا کہ میں نے حضرت ابن عباسؓ سے زیادہ حاضر دماغ، زیادہ سمجھدار، زیادہ علم والا اور زیادہ بردبار کوئی نہیں دیکھا اور میں نے دیکھا ہے کہ حضرت عمرؓ انہیں مشکل مسائل کے لیے بلایا کرتے اور ان سے فرماتے تیار ہو جاؤ یہ مشکل مسئلہ تمہارے پاس آیا ہے (اور ان کے سامنے وہ مشکل مسئلہ رکھتے) پھر حضرت عمرؓ ان ہی کے قول کے مطابق فیصلہ کر دیتے حالانکہ ان کے ارد گرد بہت سے بدری مہاجر اور انصاری صحابہؓ بیٹھے ہوئے ہوتے۔",""],[" (22)","s"]]]],"f":[["(22)","Ibn Sa'd (Vol.4 Pg.183)."]]},{"b":[["n",[["حضرت ابوزنادؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت ابن عباسؓ کو بخار ہو گیا تو حضرت عمر بن خطابؓ ان کے پاس عیادت کے لیے تشریف لے گئے اور فرمایا تمہاری بیماری کی وجہ سے ہمارا بڑا نقصان ہو رہا ہے ",""],["ٱللَّٰه","a"],[" ہی سے مدد طلب کرتا ہوں۔",""],[" (23)","s"]]]],"f":[["(23)","Ibn Sa'd (Vol.4 Pg.185)."]]},{"b":[["n",[["حضرت طلحہ بن عبید","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں کہ حضرت ابن عباسؓ کو (",""],["ٱللَّٰه","a"],[" کی طرف سے) بڑی سمجھ، عقل اور بہت علم دیا گیا تھا۔ میں نے کبھی نہیں دیکھا کہ حضرت عمر بن خطابؓ نے کسی (کی رائے) کو ان (کی رائے) پر ترجیح دی ہو۔",""],[" (24)","s"]]]],"f":[["(24)","Ibn Sa'd (Vol.4 Pg.185)."]]},{"b":[["n",[["حضرت محمد بن ابی بن کعبؒ","b"],[" کہتے ہیں کہ حضرت ابن عباسؓ حضرت ابی بن کعبؓ کے پاس بیٹھے ہوئے تھے پھر حضرت ابن عباسؓ اٹھ کر چلے گئے تو میں نے حضرت ابی بن کعبؓ کو فرماتے ہوئے سنا کہ یہ اس امت کے بہت بڑے عالم بن جائیں گے کیونکہ انہیں (",""],["ٱللَّٰه","a"],[" کی طرف سے) عقل اور سمجھ بھی خوب ملی ہے اور حضورؐ نے ان کے لیے یہ دعا فرمائی ہے کہ ",""],["ٱللَّٰه","a"],[" انہیں دین کی سمجھ عطا فرمائے۔",""],[" (25)","s"]]]],"f":[["(25)","Ibn Sa'd (Vol.4 Pg.185)."]]},{"b":[["n",[["حضرت طاؤسؒ","b"],[" کہتے ہیں کہ حضرت ابن عباسؓ تمام لوگوں میں علم کے اعتبار سے ایسے اونچے تھے جیسے کھجور کے چھوٹے درختوں میں لمبا درخت ہوتا ہے۔",""],[" (26)","s"]]]],"f":[["(26)","Ibn Sa'd (Vol.4 Pg.185)."]]},{"b":[["n",[["حضرت ابو وائلؒ","b"],[" کہتے ہیں کہ میں اور میرا ایک ساتھی حج پر گئے۔ حضرت ابن عباسؓ حج کے امیر تھے وہ سورت نور پڑھنے لگے اور ساتھ کے ساتھ اس کی تفسیر کرنے لگے جسے سن کر میرے ساتھی نے کہا سبحان ",""],["ٱللَّٰه","a"],["! اس آدمی کے سر سے کیا کچھ نکل رہا ہے؟ اگر ترک لوگ اسے سن لیں مسلمان ہو جائیں۔ دوسری روایت میں یہ ہے کہ حضرت ابو وائلؒ کہتے ہیں (تفسیر سن کر) میں نے کہا ایسی جیسی باتیں نہ تو میں نے کسی آدمی سے سنی ہیں اور نہ کہیں دیکھی ہیں۔ اگر فارس اور روم والے یہ سن لیتے تو مسلمان ہو جاتے۔",""],[" (27)","s"]]]],"f":[["(27)","Haakim (Vol.3 Pg.537)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ ایک دن میں حضرت عمر بن خطابؓ کی خدمت میں حاضر ہوا۔ انھوں نے مجھ سے ایک مسئلہ پوچھا جو انہیں یمن سے حضرت یعلیٰ بن امیہؓ نے لکھا تھا۔ میں نے انہیں اس کا جواب دیا تو فرمایا میں اس بات کی گواہی دیتا ہوں کہ تم نبوت کے گھرانے سے بولتے ہو۔",""],[" (28)","s"]]]],"f":[["(28)","Ibn Sa'd (Vol.4 Pg.184)."]]},{"b":[["n",[["حضرت عطاءؒ","b"],[" کہتے ہیں کچھ لوگ حضرت ابن عباسؓ کے پاس اشعار کے لیے آتے کچھ لوگ نسب اور کچھ لوگ عرب کے واقعات معلوم کرنے آتے وہ ہر طرح کے لوگوں کی طرف متوجہ ہوتے اور جس طرح چاہتے خوب گفتگو کرتے۔",""],[" (29)","s"]]]],"f":[["(29)","Ibn Sa'd (Vol.4 Pg.182)."]]},{"b":[["n",[["حضرت عبید","b"],["ٱللَّٰه","a"],[" بن عبد","b"],["ٱللَّٰه","a"],[" بن عتبہؒ","b"],[" کہتے ہیں کہ کئی عمدہ صفات کی وجہ سے حضرت ابن عباسؓ تمام لوگوں پر فوقیت رکھتے تھے وہ گزشتہ علوم خوب جانتے تھے اور جب ان کے مشورے کی ضرورت ہوتی تو بہت سمجھداری کا مشورہ دیتے اور بردباری اور جود و سخا ان میں کوٹ کوٹ کر بھری ہوئی تھی۔ میں نے کوئی آدمی ایسا نہیں دیکھا جو ان سے زیادہ حضورؐ کی حدیثوں کو اور حضرت ابوبکرؓ، حضرت عمرؓ اور حضرت عثمانؓ کے فیصلوں کو جاننے والا ہو اور ان سے زیادہ سمجھداری کی رائے والا ہو اور اشعار کو، عربی لغت کو، قرآن کی تفسیر کو، حساب اور میراث کو اور گزشتہ واقعات کو ان سے زیادہ جاننے والا ہو اور ان سے زیادہ درست رائے والا ہو۔ کسی دن وہ اپنی مجلس میں بیٹھتے تو صرف دین کی سمجھ کے بارے میں بات کرتے اور کسی دن صرف قرآن کی تفسیر کے بارے میں بات کرتے اور کسی دن صرف حضورؐ کے غزوات کے بارے میں بات کرتے اور کسی دن اشعار کے بارے میں اور کسی دن عرب کی لڑائیوں کے بارے میں بات کرتے اور میں نے یہی دیکھا کہ جو عالم بھی ان کی مجلس میں آیا وہ آخر کار ان (کی علمی عظمت) کے سامنے ضرور جھک گیا اور جو بھی ان سے کچھ پوچھنے آیا اسے اپنے سوال کا جواب ضرور ملا۔",""],[" (30)","s"]]]],"f":[["(30)","Ibn Sa'd (Vol.4 Pg.183)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ میں حضورؐ کے مہاجر اور انصاری بڑے بڑے صحابہؓ کے ساتھ ہر وقت رہا کرتا تھا اور میں ان سے حضورؐ کے غزوات کے بارے میں اور ان غزوات کے متعلق اترنے والے قرآن کے بارے میں خوب سوالات کیا کرتا تھا اور میں ان میں سے جس کے پاس جاتا وہ میرے آنے سے بہت خوش ہوتا کیونکہ (میں) حضورؐ کا رشتہ دار (چچازاد بھائی) تھا۔ حضرت ابی بن کعبؓ مضبوط اور پختہ علم والوں میں سے تھے۔ میں نے ان سے ایک دن مدینہ میں نازل ہونے والی سورتوں کے بارے میں پوچھا تو انھوں نے فرمایا مدینہ میں ستائیس سورتیں نازل ہوئیں اور باقی مکہ میں۔",""],[" (31)","s"]]]],"f":[["(31)","Ibn Sa'd (Vol.4 Pg.186)."]]},{"b":[["n",[["حضرت عکرمہؒ","b"],[" کہتے ہیں کہ میں نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرو بن عاصؓ کو فرماتے ہوئے سنا کہ حضرت ابن عباسؓ گزرے ہوئے علوم اور واقعات کو ہم سب سے زیادہ جاننے والے ہیں اور جو نیا مسئلہ پیش آ جائے اور اس کے بارے میں قرآن و حدیث میں کچھ نہ آیا ہو اس کے متعلق وہ سب سے زیادہ دینی سمجھ رکھنے والے ہیں۔ حضرت عکرمہؒ کہتے ہیں میں نے یہ بات حضرت ابن عباسؓ کو بتائی تو انھوں نے فرمایا حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمروؓ کے پاس بہت علم ہے کیونکہ وہ حضورؐ سے حلال و حرام کے بارے میں خوب پوچھا کرتے تھے (یعنی حضرت ابن عباسؓ ان کے فضائل کا اعتراف فرما رہے ہیں)۔",""],[" (32)","s"]]]],"f":[["(32)","Ibn Sa'd (Vol.4 Pg.186)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" نے حج کی راتوں میں دیکھا کہ حضرت ابن عباسؓ کے ارد گرد بہت سے حلقے ہیں اور ان سے مناسک حج کے بارے میں لوگ خوب پوچھ رہے ہیں تو حضرت عائشہؓ نے فرمایا اب جتنے صحابہؓ باقی رہ گئے ہیں۔ یہ ان میں سب سے زیادہ مناسک حج کو جاننے والے ہیں۔",""],[" (33)","s"]]]],"f":[["(33)","Ibn Sa'd (Vol.4 Pg.184)."]]},{"b":[["n",[["حضرت یعقوب بن زیدؒ","b"],[" اپنے والد سے نقل کرتے ہیں کہ جب حضرت جابر بن عبد",""],["ٱللَّٰه","a"],["ؓ کو حضرت ابن عباسؓ کے انتقال کی خبر ملی تو انھوں نے ایک ہاتھ دوسرے ہاتھ پر مارا اور فرمایا لوگوں میں سب سے زیادہ علم والے اور سب سے زیادہ بردبار انسان کا انتقال ہو گیا ہے اور ان کے انتقال سے اس امت کا ایسا نقصان ہوا ہے جس کی تلافی کبھی نہیں ہو سکے گی۔",""],[" (34)","s"]]]],"f":[["(34)","Ibn Sa'd (Vol.4 Pg.187)."]]},{"b":[["n",[["حضرت ابوبکر بن محمد بن عمرو بن حزمؒ","b"],[" کہتے ہیں جب حضرت ابن عباسؓ کا انتقال ہوا تو حضرت رافع بن خدیجؓ نے فرمایا آج اس شخصیت کا انتقال ہو گیا جس کے علم کے مشرق سے لے کر مغرب تک کے تمام لوگ محتاج تھے۔",""],[" (35)","s"]]]],"f":[["(35)","Ibn Sa'd (Vol.4 Pg.183)."]]},{"b":[["n",[["حضرت ابوکلثومؒ","b"],[" کہتے ہیں حضرت ابن عباسؓ دفن ہو گئے تو حضرت ابن حنفیہؒ نے کہا اس امت کے عالم ربانی کا انتقال ہو گیا۔",""],[" (36)","s"]]]],"f":[["(36)","Ibn Sa'd (Vol.4 Pg.183)."]]},{"b":[["n",[["حضرت عمرو بن دینارؒ","b"],[" کہتے ہیں حضرت ابن عمرؓ نوعمر فقہاء میں شمار کیے جاتے تھے۔",""],[" (37)","s"]]]],"f":[["(37)","Ibn Sa'd (Vol.4 Pg.187)."]]},{"b":[["n",[["حضرت خالد بن معدانؒ","b"],[" کہتے ہیں اب ملک شام میں حضورؐ کے صحابہؓ میں سے کوئی صحابی حضرت عبادہ بن صامتؓ اور حضرت شداد بن اوسؓ سے زیادہ قابل اعتماد، زیادہ دینی سمجھ رکھنے والا اور ان سے زیادہ پسندیدہ باقی نہیں رہا۔",""],[" (38)","s"]]]],"f":[["(38)","Ibn Sa'd (Vol.4 Pg.188)."]]},{"b":[["n",[["حضرت حنظلہ بن ابی سفیانؒ","b"],[" اپنے اساتذہ سے یہ نقل کرتے ہیں کہ حضورؐ کے نوعمر صحابہؓ میں سے کوئی صحابی حضرت ابوسعید خدریؓ سے زیادہ دین کی سمجھ رکھنے والا نہیں ہے۔",""],[" (39)","s"]]]],"f":[["(39)","Ibn Sa'd (Vol.4 Pg.188)."]]},{"b":[["n",[["مروان بن حکم کے منشی ",""],["ابوعزیزہؒ","b"],[" کہتے ہیں کہ مروان نے حضرت ابوہریرہؓ کو بلایا اور مجھے تخت کے پیچھے بٹھا دیا۔ مروان ان سے پوچھنے لگا اور میں ان کے جواب لکھنے لگا۔ جب ایک سال ہو گیا تو مروان نے انہیں بلا کر پردے کے پیچھے بٹھایا اور ان سے وہی پچھلے سال والے سوالات کیے۔ انھوں نے بعینہ وہی پچھلے سال والے جواب دیے نہ کوئی حرف کم کیا اور نہ زیادہ نہ آگے کیا اور نہ پیچھے۔",""],[" (40)","s"]]]],"f":[["(40)","Haakim (Vol.3 Pg.510), reporting from reliable sources as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت ابوموسیٰؓ","b"],[" فرماتے ہیں کہ جب بھی حضورؐ کے صحابہؓ کو کسی چیز میں شک ہوا اور انہوں نے اس کے بارے میں حضرت عائشہؓ سے پوچھا تو انہیں ان کے پاس اس چیز کا علم ضرور ملا۔",""],[" (41)","s"]]]],"f":[["(41)","Ibn Sa'd (Vol.4 Pg.189)."]]},{"b":[["n",[["حضرت قبیصہ بن ذویبؒ","b"],[" فرماتے ہیں حضرت عائشہؓ تمام لوگوں میں سب سے زیادہ جاننے والی تھیں۔ حضورؐ کے اکابر صحابہؓ ان سے مسائل پوچھا کرتے تھے۔ ",""],["حضرت ابوسلمہؒ","b"],[" فرماتے ہیں میں نے حضرت عائشہؓ سے زیادہ حضورؐ کی سنتوں کو جاننے والا اور بوقت ضرورت ان سے زیادہ سمجھداری کی رائے والا، آیت کی شان نزول کو اور میراث کو ان سے زیادہ جاننے والا نہیں دیکھا۔",""],[" (42)","s"],[" (43)","s"]]]],"f":[["(42)","Ibn Sa'd (Vol.4 Pg.189)."],["(43)","Ibn Sa'd (Vol.4 Pg.189)."]]},{"b":[["n",[["حضرت مسروقؒ","b"],[" سے پوچھا گیا کیا حضرت عائشہؓ علم میراث کو اچھی طرح جانتی تھیں؟ انہوں نے کہا جی ہاں۔ اس ذات کی قسم جس کے قبضہ میں میری جان ہے! میں نے حضورؐ کے بزرگ اکابر صحابہؓ کو دیکھا کہ وہ حضرت عائشہؓ سے میراث کے بارے میں پوچھا کرتے تھے۔",""],[" (44)","s"]]]],"f":[["(44)","Ibn Sa'd (Vol.4 Pg.189). Tabraani has reported a similar narration from reliable sources as confirmed by Haythami (Vol.9 Pg.242)."]]},{"b":[["n",[["حضرت محمود بن لبیدؒ","b"],[" کہتے ہیں نبی کریمؐ کی تمام ازواج مطہراتؓ کو حضورؐ کی بہت سی حدیثیں یاد تھیں لیکن حضرت عائشہؓ اور ام سلمہؓ جیسی کوئی نہ تھی اور حضرت عائشہؓ حضرت عمرؓ اور حضرت عثمانؓ کے زمانے میں فتویٰ دیا کرتی تھیں اور پھر انتقال تک ان کا یہ مشغلہ رہا۔ ",""],["ٱللَّٰه","a"],[" ان پر رحمت نازل فرمائے اور حضورؐ کے اکابر صحابہؓ حضرت عمرؓ اور حضرت عثمانؓ حضورؐ کے بعد ان کے پاس آدمی بھیج کر سنتیں پوچھا کرتے تھے۔",""],[" (45)","s"]]]],"f":[["(45)","Ibn Sa'd (Vol.4 Pg.189)."]]},{"b":[["n",[["حضرت معاویہؓ","b"],[" فرماتے ہیں ",""],["ٱللَّٰه","a"],[" کی قسم! میں نے حضرت عائشہؓ سے زیادہ فصیح بلیغ اور ان سے زیادہ عقلمند کوئی خطیب نہیں دیکھا۔",""],[" (46)","s"]]]],"f":[["(46)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.243)."]]},{"b":[["n",[["حضرت عروہؓ","b"],[" فرماتے ہیں میں نے کوئی عورت ایسی نہیں دیکھی جو حضرت عائشہؓ سے زیادہ طب، فقہ اور اشعار کو جاننے والی ہو۔",""],[" (47)","s"]]]],"f":[["(47)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.9 Pg.242)."]]},{"b":[["n",[["حضرت عروہؓ","b"],[" فرماتے ہیں میں نے حضرت عائشہؓ کی خدمت میں عرض کیا میں آپ کے معاملہ میں جتنا سوچتا ہوں اتنا ہی مجھے تعجب ہوتا ہے۔ آپ مجھے تمام لوگوں میں سب سے زیادہ دین کی سمجھ رکھنے والی نظر آتی ہیں تو میں کہتا ہوں اس میں کیا بات ہے۔ آپ حضورؐ کی زوجہ محترمہ ہیں اور حضرت ابوبکرؓ کی صاحبزادی ہیں (آپ کو دین کی سب سے زیادہ سمجھ والا ہونا ہی چاہیے) آپ مجھے عرب کی لڑائیوں کو، ان کے نسب ناموں کو اور ان کے اشعار کو جاننے والی نظر آتی ہیں تو میں کہتا ہوں اس میں کیا بات ہے؟ آپ کے والد (حضرت ابوبکرؓ) قریش کے بہت بڑے عالم تھے (لہٰذا ان کی بیٹی کو ایسا ہونا ہی چاہیے) لیکن مجھے اس بات پر تعجب ہے کہ آپ طب بھی جانتی ہیں آپ نے کہاں سے سیکھی؟ انہوں نے میرا ہاتھ پکڑ کر (پیار سے نام بدل کر) کہا اے عرویہ! جب حضورؐ کی بیماریاں زیادہ ہو گئیں تو عرب و عجم کے اطباء ان کے پاس دوائیاں بھیجنے لگے۔ اس طرح میں نے علم طب سیکھ لیا۔ احمد کی روایت میں یہ ہے کہ میں ان دوائیوں سے حضورؐ کا علاج کیا کرتی تھی، یہاں سے میں نے طب سیکھی (حضرت عروہؓ حضرت عائشہؓ کے بھانجے تھے)۔",""],[" (48)","s"],[" (49)","s"]]]],"f":[["(48)","Bazzaar, Ahmad and Tabraani in his Kabeer and Awsat."],["(49)","Ahmad. Haythami (Vol.9 Pg.242) has commented on the chain of narrators."]]}]},"92":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" نے اپنے ساتھیوں سے فرمایا تم علم کے چشمے، ہدایت کے چراغ، اکثر گھروں میں رہنے والے، رات کے چراغ، نئے دل والے اور پرانے کپڑوں والے بنو۔ آسمان میں پہچانے جاؤ گے اور زمین والوں پر پوشیدہ رہو گے۔ ابونعیم میں حضرت علیؓ کی روایت میں زمین والوں پر پوشیدہ رہنے کے بجائے یہ الفاظ ہیں کہ ان صفات کی وجہ سے تمہارا زمین پر بھی ذکر خیر ہوگا۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.126)."],["(2)","Abu Nu'aym in his Hilya (Vol.1 Pg.77)."]]},{"b":[["n",[["حضرت وہب بن منبہؒ","b"],[" کہتے ہیں کہ حضرت ابن عباسؓ کو خبر ملی کہ باب بنی سہم کے پاس کچھ لوگ تقدیر کے بارے میں جھگڑ رہے ہیں وہ اٹھ کر ان کی طرف چلے اور (اپنی) چھڑی حضرت عکرمہؒ کو دی اور اپنا ایک ہاتھ اس چھڑی پر رکھا اور دوسرا ہاتھ حضرت طاؤسؒ پر رکھا۔ جب ان کے پاس پہنچے تو ان لوگوں نے خوش آمدید کہا اور اپنی مجلس میں ان کے بیٹھنے کے لیے جگہ بنائی لیکن وہ بیٹھے نہیں بلکہ ان سے فرمایا میں تمہیں اپنا نسب نامہ بیان کر دوں کہ میں تمہیں پہچان لوں۔ ان سب نے یا ان میں سے کچھ نے اپنا نسب نامہ بیان کیا تو فرمایا کیا تمہیں معلوم نہیں کہ ",""],["ٱللَّٰه","a"],[" کے کچھ بندے ایسے ہیں جو گونگے اور بولنے سے عاجز نہیں ہیں بلکہ ",""],["ٱللَّٰه","a"],[" کے ڈر سے خاموش رہتے ہیں۔ یہی لوگ فصاحت والے، فضیلت والے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ کی قدرت کے واقعات کو جاننے والے علماء ہیں۔ جب انہیں ",""],["ٱللَّٰه","a"],[" کی عظمت کا دھیان آتا ہے تو ان کی عقلیں اڑ جاتی ہیں ان کے دل شکستہ ہو جاتے ہیں اور ان کی زبانیں بند ہو جاتی ہیں۔ جب ان کو اس کیفیت سے افاقہ ہوتا ہے تو وہ پاکیزہ اعمال کے ذریعے ",""],["ٱللَّٰه","a"],[" کی طرف تیزی سے چلتے ہیں حالانکہ وہ عقلمند اور طاقتور ہوں گے لیکن پھر بھی وہ اپنے آپ کو تباہی کرنے والوں میں شمار کریں گے اور اسی طرح وہ نیک اور خطاؤں سے پاک ہوں گے لیکن اپنے آپ کو ظالم اور خطا کار لوگوں میں شمار کریں گے اور ",""],["ٱللَّٰه","a"],[" کے لیے زیادہ (اعمال اور قربانی) کو زیادہ نہیں سمجھیں گے اور ",""],["ٱللَّٰه","a"],[" کے لیے کم پر وہ راضی نہیں ہوں گے اور اعمال میں ",""],["ٱللَّٰه","a"],[" کے سامنے نخرے نہیں کریں گے۔ تم انہیں جہاں بھی ملو گے وہ اہتمام اور فکر سے چلنے والے، ڈرنے والے اور کپکپانے والے ہوں گے۔ حضرت وہبؒ فرماتے ہیں یہ باتیں ارشاد فرما کر حضرت ابن عباسؓ وہاں سے اٹھے اور اپنی مجلس میں واپس تشریف لے آئے۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilya (Vol.1 Pg.325)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا اگر علم والے علم کی حفاظت کرتے اور جو علم کے اہل ہیں ان ہی کو علم دیتے تو اپنے زمانے والوں کے سردار ہوتے لیکن انہوں نے دنیا والوں کے سامنے اپنا علم رکھ دیا تا کہ ان کی دنیا میں سے کچھ حاصل کر لیں اس وجہ سے علم والے دنیا والوں کی نگاہ میں بے قیمت ہو گئے۔ میں نے تمہارے نبی کریمؐ کو فرماتے ہوئے سنا کہ جو تمام فکروں کو ایک فکر یعنی آخرت کی فکر بنا دے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کی تمام فکروں کی کفایت فرمائیں گے اور جسے دنیاوی افکار نے پراگندہ کر دیا تو ",""],["ٱللَّٰه","a"],[" کو بھی اس بات کی پروا نہیں ہوگی کہ وہ دنیا کی کس وادی میں ہلاک ہو گیا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.5 Pg.243). Ibn Abdul Birr has reported a similar narration in his Jaami (Vol.1 Pg.187)."]]},{"b":[["n",[["حضرت سفیان بن عیینہؒ","b"],[" کہتے ہیں ہمیں حضرت ابن عباسؓ کی طرف سے ان کا یہ ارشاد پہنچا کہ اگر حاملین علم علم کو اس کے حق کے ساتھ لیتے اور اس کے مناسب جو آداب ہیں انہیں اختیار کرتے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ، اس کے فرشتے اور نیک لوگ ان سے محبت کرتے اور لوگوں کے دلوں میں ان کی ہیبت ہوتی لیکن انہوں نے علم کے ذریعے دنیا حاصل کرنے کی کوشش کی جس کی وجہ سے وہ ",""],["ٱللَّٰه","a"],[" کے ہاں مبغوض بن گئے اور لوگوں کی نگاہ میں بھی بے حیثیت ہو گئے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.188)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا تمہارا اس وقت کیا حال ہوگا جب تم میں ایک زبردست فتنہ اٹھے گا جس میں کم عمر تو بڑھ جائے گا اور زیادہ عمر والا بوڑھا ہو جائے گا اور نئے طریقے ایجاد کر کے اختیار کر لیے جائیں گے اور اگر کسی دن انہیں بدلنے (اور صحیح اور مسنون طریقہ لانے) کی کوشش کی جائے گی تو لوگ کہنے لگیں گے یہ تو بالکل اجنبی اور اوپرا طریقہ ہے۔ اس پر لوگوں نے پوچھا ایسا فتنہ کب ہوگا؟ حضرت ابن مسعودؓ نے فرمایا جب تمہارے امین لوگ کم ہو جائیں گے اور تمہارے امراء و حکام زیادہ ہو جائیں گے اور تمہارے دین کی سمجھ رکھنے والے کم ہو جائیں گے اور تمہارے قرآن پڑھنے والے زیادہ ہو جائیں گے اور دین کے غیر یعنی دنیا کے لیے دینی علم حاصل کیا جائے گا اور آخرت والے عمل سے دنیا طلب کی جائے گی۔ اور ایک روایت میں یہ ہے کہ نئے طریقے گھڑے جائیں گے جس پر لوگ چلنے لگیں گے اور جب اس میں کچھ تبدیلی کی جانے لگے گی تو وہ لوگ کہیں گے ہمارا معروف طریقہ بدلا جا رہا ہے اور یہ بھی ہے کہ تمہارے دین کی سمجھ رکھنے والے کم ہو جائیں گے اور تمہارے امراء و حکام خزانے بھرنے لگیں گے۔",""],[" (6)","s"]]]],"f":[["(6)","Abdur Razzaaq, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.82). Ibn Abdul Birr has reported a similar narration in his Jaami (Vol.1 Pg.188)."]]},{"b":[["n",[["حضرت ابوذرؓ","b"],[" فرماتے ہیں یہ بات اچھی طرح جان لو کہ یہ احادیث جن میں اصل یہ ہے کہ ان کے ذریعہ سے ",""],["ٱللَّٰه","a"],[" کی رضا مندی حاصل کی جائے اگر انہیں دنیا کا سامان حاصل کرنے کے لیے سیکھے گا تو وہ بھی جنت کی خوشبو نہیں پا سکے گا۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.187)."]]},{"b":[["n",[["حضرت عمرؓ نے ",""],["حضرت کعبؓ","b"],[" (جو کہ تورات کے بھی بڑے عالم تھے) سے پوچھا جب علماء علم کو یاد کر لیں گے اور اچھی طرح سمجھ لیں گے تو پھر کون سی چیز ان کے دلوں سے علم لے جائے گی؟ حضرت کعبؓ نے کہا دو چیزیں ایک تو دنیا کی لالچ دوسرے لوگوں کے سامنے اپنی حاجتیں لے جانا۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.6)."]]},{"b":[["n",[["ایک مرتبہ حضرت علیؓ نے ان فتنوں کا ذکر کیا جو آخری زمانہ میں ہوں گے تو حضرت عمرؓ نے ان سے پوچھا اے علی! یہ فتنے کب ہوں گے؟ فرمایا جب غیر دین یعنی دنیا کے لیے دینی علم حاصل کیا جائے گا اور عمل کے غیر یعنی عزت اور مال کے لیے علم سکھایا جائے گا اور آخرت کے عمل سے دنیا طلب کی جائے گی۔",""],[" (9)","s"]]]],"f":[["(9)","Abdur Razzaaq, as quoted in Targheeb wat Tarheeb (Vol.1 Pg.82)."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" نے فرمایا میں تمہارے بارے میں دو آدمیوں سے ڈرتا ہوں ایک تو وہ آدمی جو قرآن کی غلط تفسیر کرے گا اور دوسرا وہ آدمی جو ملک کے بارے میں اپنے بھائی سے آگے بڑھنے کی کوشش کرے گا۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Abdul Birr in his Jaami (Vol.2 Pg.194). Ibn Abi Shaybah has reported a similar narration, as quoted in Kanzul Ummaal (Vol.5 Pg.233)."]]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں بصرہ کا وفد حضرت عمرؓ کے پاس آیا ان میں احنف بن قیس بھی تھے اور سب کو تو حضرت عمرؓ نے جانے دیا لیکن حضرت احنف بن قیس کو روک لیا اور انہیں ایک سال روک رکھا اس کے بعد فرمایا تمہیں معلوم ہے میں نے تمہیں کیوں روکا تھا؟ میں نے اس وجہ سے روکا تھا کہ ہمیں حضورؐ نے ہر اس منافق سے ڈرایا جو عالمانہ زبان والا ہو مجھے ڈر ہوا کہ شاید تم بھی ان میں سے ہو لیکن (میں نے ایک سال رکھ کر دیکھ لیا کہ) ان شاء ",""],["ٱللَّٰه","a"],[" تم ان میں سے نہیں ہو۔",""],[" (11)","s"]]]],"f":[["(11)","Ibn Sa'd and Abu Ya'la."]]},{"b":[["n",[["حضرت ابوعثمان نہدیؒ","b"],[" کہتے ہیں میں نے حضرت عمر بن خطابؓ کو منبر پر فرماتے ہوئے سنا کہ اس منافق سے بچو جو عالم ہو۔ لوگوں نے پوچھا منافق کیسے عالم ہو سکتا ہے؟ فرمایا بات تو حق کہے گا لیکن عمل منکرات پر کرے گا۔ حضرت عمرؓ نے فرمایا ہم یہ بات کہا کرتے تھے کہ اس امت کو وہ منافق ہلاک کرے گا جو زبان کا عالم ہوگا۔",""],[" (12)","s"],[" (13)","s"]]]],"f":[["(12)","Bayhaqi and Ibn Najjaar."],["(13)","Firyaabi, Abu Ya'la, Nasr and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.5 Pg.232)."]]},{"b":[["n",[["حضرت ابوعثمان نہدیؒ","b"],[" کہتے ہیں میں نے حضرت عمر بن خطابؓ کو منبر پر یہ فرماتے ہوئے سنا کہ اس امت پر سب سے زیادہ ڈر اس منافق سے ہے جو عالم ہو۔ لوگوں نے پوچھا اے امیر المومنین! منافق کیسے عالم ہو سکتا ہے؟ فرمایا وہ زبان کا تو عالم ہوگا لیکن دل اور عمل کا جاہل ہوگا۔",""],[" (14)","s"]]]],"f":[["(14)","Musaddad and Firyaabi, as quoted in Kanzul Ummaal (Vol.5 Pg.233)."]]},{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرماتے ہیں ایسی جگہوں سے بچو جہاں کھڑے ہونے سے انسان فتنوں میں مبتلا ہو جاتا ہے۔ کسی نے پوچھا اے ابوعبد",""],["ٱللَّٰه","a"],["! فتنوں کی یہ جگہیں کونسی ہیں؟ فرمایا امراء اور حکام کے دروازے۔ آدمی کسی حاکم یا گورنر کے پاس جاتا ہے اور غلط بات میں اس کی تصدیق کرتا ہے اور اس کی تعریف میں ایسی خوبیاں ذکر کرتا ہے جو اس میں نہیں ہیں۔",""],[" (15)","s"]]]],"f":[["(15)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.167)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں جیسے اونٹوں کے بیٹھنے کی جگہ میں اونٹ ہوتے ہیں ایسے سلاطین کے دروازوں پر فتنے ہوتے ہیں۔ اس ذات کی قسم جس کے قبضہ میں میری جان ہے! تم ان سلاطین سے جتنی دنیا حاصل کرلو گے وہ سلاطین تمہارے دین میں اتنی کمی کر دیں گے یا اس سے دوگنی کمی کر دیں گے۔",""],[" (16)","s"]]]],"f":[["(16)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.167)."]]}]},"93":{"lead":[],"stories":[{"b":[["n",[["حضرت عوف بن مالک اشجعیؓ","b"],[" فرماتے ہیں ایک دن حضورؐ نے آسمان کی طرف دیکھا اور فرمایا اس وقت مجھے وہ وقت بتایا گیا ہے جس میں علم اٹھا لیا جائے گا۔ ابن لبیدؓ نامی ایک انصاری صحابی نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! جب علم کتابوں میں لکھ دیا جائے گا اور دل اسے سمجھ لیں گے اور محفوظ کر لیں گے تو علم کیسے اٹھا لیا جائے گا؟ حضورؐ نے فرمایا میں تو تمہیں مدینہ والوں میں سب سے زیادہ سمجھدار آدمی سمجھتا تھا پھر حضورؐ نے اس بات کا ذکر کیا کہ یہود و نصاریٰ کے پاس ",""],["ٱللَّٰه","a"],[" کی کتاب ہے لیکن پھر بھی گمراہ ہیں۔ راوی کہتے ہیں پھر میری حضرت شداد بن اوسؓ سے ملاقات ہوئی تو میں نے حضرت عوف بن مالکؓ والی حدیث انہیں سنائی۔ حضرت شدادؓ نے فرمایا حضرت عوفؓ نے ٹھیک کہا کیا میں تمہیں وہ چیز نہ بتاؤں جو علم میں سب سے پہلے اٹھائی جائے گی؟ میں نے کہا ضرور فرمایا خشوع۔ یہاں تک کہ تمہیں کوئی خشوع والا نظر نہ آئے گا۔ ابن عبدالبر کی روایت میں یہ ہے کہ ایک انصاری صحابی نے جنہیں زیاد بن لبید کہا جاتا تھا عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! علم ہم میں سے اٹھا لیا جائے گا جبکہ ہم میں ",""],["ٱللَّٰه","a"],[" کی کتاب ہوگی اور ہم اسے اپنے بیٹوں اور عورتوں کو سکھائیں گے۔ ایک روایت میں یہ ہے کہ حضرت شدادؓ نے فرمایا کیا تم جانتے ہو کہ علم کے اٹھائے جانے کی کیا صورت ہوگی؟ میں نے کہا میں نہیں جانتا فرمایا علم کے برتن یعنی علماء اٹھ جائیں گے اور کیا تم جانتے ہو کہ علم کی کونسی صفت اٹھا لی جائے گی؟ میں نے کہا نہیں جانتا۔ فرمایا خشوع۔ کوئی خشوع والا نظر نہیں آئے گا۔ حضرت ابوالدرداءؓ کی روایت میں ہے کہ حضورؐ نے فرمایا یہ تورات اور انجیل یہود و نصاریٰ کے پاس ہے لیکن ان کے کس کام آ رہی ہے؟ حضرت وحشیؓ کی روایت میں ہے کہ وہ یہود و نصاریٰ تورات و انجیل کی طرف بالکل توجہ نہیں کرتے ہیں اور حضرت ابن لبیدؓ کی روایت میں ہے کہ ان یہود و نصاریٰ کو تورات و انجیل سے کوئی فائدہ نہیں ہو رہا۔",""],[" (1)","s"],[" (2)","s"],[" (3)","s"],[" (4)","s"],[" (5)","s"],[" (6)","s"]]]],"f":[["(1)","Haakim (Vol.1 Pg.99). Bazzaar and Tabraani have reported a similar narration, as quoted in Majma'uz Zawaa'id (Vol.1 Pg.200)."],["(2)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.152)."],["(3)","Ibn Abdul Birr in his Jaami (Vol.1 Pg.152). Haakim and Tabraani have reported a similar narration, as quoted in Majma'uz Zawaa'id."],["(4)","Haakim."],["(5)","Tabraani."],["(6)","Haakim."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" نے پوچھا تم جانتے ہو کہ اسلام کیسے کم ہوگا؟ لوگوں نے کہا جیسے کپڑے کا رنگ اور جانور کا موٹاپا کم ہو جاتا ہے اور زیادہ چھپائے اور دبائے رکھنے سے درہم کم ہو جاتا ہے۔ حضرت ابن مسعودؓ نے فرمایا اسلام کم ہونے کی بھی یہی صورت ہوگی لیکن اس کے کم ہونے کی اس سے زیادہ بڑی وجہ علماء کا انتقال کر جانا اور دنیا سے چلے جانا ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani in his Kabeer, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.202)."]]},{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں میں حضرت زید بن ثابتؓ کے جنازہ میں شریک تھا۔ جب ان کو قبر میں دفن کر دیا گیا تو حضرت ابن عباسؓ نے فرمایا اے لوگو! جو یہ جاننا چاہتا ہے کہ علم کیسے چلا جائے گا تو یہ علم اس طرح جائے گا ",""],["ٱللَّٰه","a"],[" کی قسم! آج بہت زیادہ علم چلا گیا۔ ",""],["حضرت عمار بن ابی عمارؒ","b"],[" کہتے ہیں جب حضرت زید بن ثابتؓ کا انتقال ہوا تو ہم جھونپڑی کے سائے میں حضرت ابن عباسؓ کی خدمت میں جا کر بیٹھ گئے۔ انہوں نے فرمایا اس طرح علم چلا جاتا ہے آج بہت زیادہ علم دفن ہو گیا۔ حضرت ابن عباسؓ نے حضرت زید بن ثابتؓ کی قبر کی طرف اشارہ کرتے ہوئے فرمایا یوں علم چلا جاتا ہے ایک آدمی ایک چیز کو جانتا ہے اس چیز کو اور کوئی نہیں جانتا۔ جب یہ آدمی مر جاتا ہے تو جو علم اس کے پاس تھا وہ بھی چلا جاتا ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Tabraani. Haythami (Vol.1 Pg.202) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" نے فرمایا تم جانتے ہو علم کیسے جاتا ہے؟ اس کے جانے کی صورت یہ ہے کہ علماء زمین سے چلے جائیں۔",""],[" (9)","s"]]]],"f":[["(9)","Majma'uz Zawaa'id (Vol.1 Pg.202)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں میں یہ سمجھتا ہوں کہ آدمی علم سیکھ کر بھول جاتا ہے اس کی وجہ گناہوں میں مبتلا ہونا ہے۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Nu'aym in his Hilya (Vol.1 Pg.131). The narration also appears in Majma'uz Zawaa'id (Vol.1 Pg.199) and Targheeb wat Tarheeb (Vol.1 Pg.92)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" نے فرمایا علم کی آفت اسے بھول جانا ہے۔",""],[" (11)","s"]]]],"f":[["(11)","Ibn Abi Shaybah, as quoted in Jaami'ul Ilm (Vol.1 Pg.108)."]]}]},"94":{"lead":[],"stories":[{"b":[["n",[["حضرت جابر بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں حضرت حذیفہؓ نے ہم سے فرمایا ہمیں یہ علم دیا گیا ہے۔ اب ہم یہ علم تم تک پہنچا رہے ہیں اگرچہ ہم اس پر خود عمل نہ کر رہے ہوں۔",""],[" (1)","s"]]]],"f":[["(1)","Bayhaqi and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.7 Pg.24)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ یہ دعا فرمایا کرتے تھے",""]]],["q",[["اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْأَرْبَعِ: مِنْ عِلْمٍ لَا يَنفَعُ، وَقَلْبٍ لَا يَخْشَعُ، وَنَفْسٍ لَا تَشْبَعُ، وَدُعَاءٍ لَا يُسْمَعُ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں چار چیزوں سے تیری پناہ چاہتا ہوں اس علم سے جو نفع نہ دے اور اس دل سے جس میں خشوع نہ ہو اور اس نفس سے جو سیر نہ ہو اور اس دعا سے جو سنی نہ جائے۔\"",""],[" (2)","s"]]]],"f":[["(2)","Haakim (Vol.1 Pg.104), reporting from reliable sources as confirmed by Dhahabi."]]}]}}});
